def es_modo_emision():
    """Retorna True si el sistema debe emitir las reservas de forma real.
    Por defecto retorna False (Modo Seguro / Pruebas sin emitir).
    La llave de config.json abre SOLO con el booleano true: cualquier otro valor
    (texto, número, "true" entre comillas, null) deja el candado cerrado y se avisa."""
    if os.environ.get("AQUASHIELD_EMITIR", "").strip().lower() in ("1", "true", "si", "yes"):
        return True
    if any(a.lower() in ("emitir", "--emitir", "produccion", "--produccion") for a in sys.argv):
        return True
    try:
        cfg = cargar_config()
        valor = cfg.get("opciones", {}).get("emitir_reservas", False)
        if valor is True:
            return True
        if valor is not False:
            _avisar_llave_config(valor)
    except Exception:
        pass
    return False


def _avisar_llave_config(valor):
    """Avisa en pantalla y en el log que emitir_reservas no es un booleano (_avisar_en_pantalla_y_log)."""
    texto = (f"⚠ Candado de emisión: en config.json, «emitir_reservas» vale "
             f"{json.dumps(valor, ensure_ascii=False)} y solo se abre con true (sin comillas). "
             f"Lo dejé cerrado: no se emite ninguna reserva. Si quieres emitir, escribe true; si no, false.")
    _avisar_en_pantalla_y_log(texto)


_AVISOS_SIN_CORRIDA = set()


def _avisar_en_pantalla_y_log(texto, una_vez=None):
    """Si hay una corrida en curso, avisa por su Registro (su log.txt, su consola y la pantalla que la muestre); si
    no, por la consola y el registro del panel web. Con 'una_vez', ese aviso sale una sola vez por corrida, y una
    sola vez sin corrida: el del peso y la temperatura de config.json se pide en cada reserva."""
    abiertos = list(_REGISTROS_ABIERTOS)
    if abiertos:
        for reg in abiertos:
            avisados = reg.__dict__.setdefault("avisos_una_vez", set())
            if una_vez is not None and una_vez in avisados:
                continue
            avisados.add(una_vez)
            reg.paso(texto)
        return
    if una_vez is not None and una_vez in _AVISOS_SIN_CORRIDA:
        return
    _AVISOS_SIN_CORRIDA.add(una_vez)
    try:
        print(texto, flush=True)
    except Exception:
        pass
    try:
        _wlog(texto)
    except Exception:
        pass


# Forma del número en la pantalla de confirmación, medida en las capturas de logs/
# (CICLO-numero-booking.md; HYUNDAI y MAERSK, CICLO-estado-tras-envio.md): la etiqueta de esa
# pantalla y, junto a ella, el número. Una naviera sin forma medida nunca llega a EMITIDA.
FORMA_BOOKING = {
    "one": r"(?i:Booking\s+Reference\s+No\.?)\s*:?\s*(SCLG\d{8})\b",   # 5 de 5 capturas
    "msc": r"(?i:Your\s+eBooking\s+number\s+is)\s*:?\s*(EBKG\d{8})\b",  # 5 de 5 capturas
    "hyundai": r"(?i:Created\s+tentative\s+booking\s+number)\s*:?\s*(SCLA\d{8})\b",  # 5 de 5 capturas
    "maersk": r"(?i:Booking\s+number)\s*:?\s*(\d{9})\b",  # 5 de 5 capturas
}
# Segundos que se reintenta la lectura: la confirmación puede tardar en pintarse.
BKG_ESPERA_SEG = 15

# Texto visible de la página y de las raíces shadow abiertas (innerText no entra en ellas).
_JS_TEXTO_VISIBLE = """() => {
    const textos = [document.body ? document.body.innerText : ''];
    const visitar = (raiz) => {
        for (const e of raiz.querySelectorAll('*')) {
            if (e.shadowRoot) {
                for (const c of e.shadowRoot.children) textos.push(c.innerText || c.textContent || '');
                visitar(e.shadowRoot);
            }
        }
    };
    visitar(document);
    return textos.join('\\n');
}"""


def numero_tras_envio(page, naviera, espera=None):
    """Número de reserva de la pantalla de confirmación, SOLO si calza con la forma medida
    de la naviera (FORMA_BOOKING); si no, ''. Lee la página y cada uno de sus marcos, con las
    raíces shadow, y reintenta cada segundo hasta 'espera' s. Sin clics ni navegación."""
    import re
    patron = FORMA_BOOKING.get(naviera)
    if not patron:
        return ""
    espera = BKG_ESPERA_SEG if espera is None else espera
    for intento in range(espera + 1):
        for alcance in [page] + [f for f in (getattr(page, "frames", None) or []) if f is not page]:
            try:
                texto = alcance.evaluate(_JS_TEXTO_VISIBLE) or ""
            except Exception:
                continue                   # un marco que no se deja leer no tapa a los demás
            m = re.search(patron, str(texto))
            if m:
                return m.group(1)
        if intento < espera:
            page.wait_for_timeout(1000)
    return ""


