# ============================================================
#  REGISTRO
# ============================================================
# Registros abiertos (corridas en curso): por ahí sale el aviso de la llave de config.
_REGISTROS_ABIERTOS = weakref.WeakSet()


class Registro:
    def __init__(self, ruta_log, on_log=None):
        self.ruta = Path(ruta_log)
        self.ruta.parent.mkdir(parents=True, exist_ok=True)
        self.on_log = on_log
        self.t0 = time.time()
        self._f = open(self.ruta, "a", encoding="utf-8")
        self.dir_capturas = self.ruta.parent
        _REGISTROS_ABIERTOS.add(self)

    def _emit(self, linea):
        stamp = datetime.datetime.now().strftime("%H:%M:%S")
        elapsed = time.time() - self.t0
        texto = f"[{stamp} +{elapsed:6.1f}s] {linea}"
        try:
            self._f.write(texto + "\n"); self._f.flush()
        except Exception:
            pass
        try:
            print(texto, flush=True)
        except Exception:
            pass
        if self.on_log:
            try:
                self.on_log(texto)
            except Exception:
                pass

    def paso(self, msg): self._emit("· " + msg)
    def info(self, msg): self._emit("    " + msg)

    def url(self, page):
        try: self._emit("    URL: " + page.url)
        except Exception: pass

    def captura(self, page, nombre, full=False, pagina_entera=False):
        """Guarda una captura. Por defecto SOLO la ventana visible: la captura de
        pagina completa cuesta entre 1 y 4 s en portales largos (medido) y no
        aporta para el seguimiento normal. Se activa con AQUASHIELD_CAPTURA_FULL
        o en modo descubrir; 'pagina_entera' la pide siempre (la evidencia de la
        guarda del candado). Devuelve True si la guardó."""
        try:
            completa = bool(full) and bool(os.environ.get("AQUASHIELD_CAPTURA_FULL")
                                           or os.environ.get("AQUASHIELD_DESCUBRIR"))
            ruta = self.dir_capturas / f"{nombre}.png"
            page.screenshot(path=str(ruta), full_page=completa or bool(pagina_entera))
            self._emit(f"    captura: {ruta.name}")
            return True
        except Exception as e:
            self._emit(f"    (no pude capturar {nombre}: {e})")
            return False

    def cerrar(self):
        _REGISTROS_ABIERTOS.discard(self)
        try: self._f.close()
        except Exception: pass


# ============================================================
#  UTILIDADES
# ============================================================
def _cosco_esperar_contenido(page, patron, seg, reg=None, motivo="", minimo=2.0):
    """El formulario de COSCO vive dentro de un iframe: esperar a que el iframe
    exista no dice nada. Esto espera a que su CONTENIDO muestre lo que buscamos.
    'minimo' es un piso obligatorio: al cambiar de paso el texto del paso ANTERIOR
    sigue en pantalla unos instantes y la coincidencia seria falsa (medido: los
    campos de carga quedaron sin llenar por avanzar demasiado rapido)."""
    import time as _t, re as _r
    rx = _r.compile(patron, _r.I)
    t0 = _t.time()
    if minimo:
        try: page.wait_for_timeout(int(minimo * 1000))
        except Exception: pass
    while _t.time() - t0 < seg:
        try:
            for fr in page.frames:
                try:
                    txt = fr.evaluate("()=>document.body?document.body.innerText.slice(0,4000):''") or ""
                except Exception:
                    continue
                if rx.search(txt):
                    if reg and motivo:
                        reg.info(f"esperando {_t.time()-t0:.1f}s ({motivo})")
                    return True
        except Exception:
            pass
        try:
            page.wait_for_timeout(400)
        except Exception:
            break
    if reg and motivo:
        reg.info(f"esperando {_t.time()-t0:.1f}s ({motivo}) [sin señal]")
    return False


def _args_chrome():
    """Argumentos de Chrome. El zoom reducido (factor de escala < 1) hace que
    quepa mas pagina en la ventana: menos scroll antes de cada accion y capturas
    mas rapidas. Se ajusta con AQUASHIELD_ZOOM (1 = 100%)."""
    try:
        zoom = float(os.environ.get("AQUASHIELD_ZOOM", "0.65"))
    except Exception:
        zoom = 0.65
    zoom = min(max(zoom, 0.5), 1.0)
    args = ["--start-maximized", "--disable-blink-features=AutomationControlled"]
    if zoom < 0.999:
        args.append(f"--force-device-scale-factor={zoom}")
        args.append("--high-dpi-support=1")
    return args


def esperar(page, seg, reg=None, motivo=""):
    if reg and motivo:
        reg.info(f"esperando {seg:.1f}s ({motivo})")
    page.wait_for_timeout(int(seg * 1000))


def esperar_hasta(page, selector, seg=8, reg=None, motivo="", minimo=0.4, asentar=0.0):
    """Espera hasta que aparezca 'selector' (o hasta 'seg'), en vez de dormir un
    tiempo fijo. 'asentar' agrega un margen DESPUES de encontrarlo: en portales
    hechos con componentes web el campo se ve antes de que la aplicacion quede
    lista para responder (autocompletados, validaciones). Si el selector no
    llega, no falla: se comporta como la espera fija anterior."""
    import time as _t
    t0 = _t.time()
    if minimo:
        page.wait_for_timeout(int(minimo * 1000))
    try:
        page.wait_for_selector(selector, timeout=int(max(seg - minimo, 0.5) * 1000),
                               state="visible")
        listo = True
    except Exception:
        listo = False
    if listo and asentar:
        page.wait_for_timeout(int(asentar * 1000))
    dt = _t.time() - t0
    if reg and motivo:
        reg.info(f"esperando {dt:.1f}s ({motivo})" + ("" if listo else " [sin señal]"))
    return dt


def _css_simple(selector):
    """True si el selector es CSS puro (se puede consultar con querySelector)."""
    s = selector or ""
    return not any(x in s for x in ("role=", ":has-text", ">>", "text="))


def click_si_existe(page, selector, timeout_ms=2500, reg=None):
    """Clic sobre algo OPCIONAL. Antes de esperar, comprueba de forma instantanea
    si el elemento siquiera existe: en algunos portales la espera de Playwright
    se estira mucho mas alla del tiempo pedido cuando la pagina esta ocupada
    (medido: 30 s en MSC para un elemento que no existia)."""
    t = time.time()
    _JS_ESTADO = """(s)=>{
                const e=document.querySelector(s);
                if(!e) return 0;
                const r=e.getBoundingClientRect();
                return (e.offsetParent!==null && r.width>0 && r.height>0) ? 2 : 1;
            }"""
    if _css_simple(selector):
        estado, err = None, ""
        for intento in range(2):
            try:
                estado = int(page.evaluate(_JS_ESTADO, selector)); err = ""; break
            except Exception as e:
                err = str(e)[:40]
                try: page.wait_for_timeout(600)
                except Exception: break
        if estado is None:
            # No se pudo consultar la pagina (suele ser una navegacion en curso).
            # Como el clic es OPCIONAL, se omite: esperar aqui puede costar 30 s.
            if reg: reg.info(f"clic NO (pagina ocupada) '{selector[:40]}' [{err}]")
            return False
        if estado == 0:
            if reg: reg.info(f"clic NO (no existe) '{selector[:50]}' ({(time.time()-t):.1f}s)")
            return False
        if estado == 1:
            if reg: reg.info(f"clic NO (oculto) '{selector[:50]}' ({(time.time()-t):.1f}s)")
            return False
    try:
        loc = page.locator(selector).first
        loc.wait_for(state="visible", timeout=timeout_ms)
        loc.click()
        if reg: reg.info(f"clic OK '{selector[:50]}' ({(time.time()-t):.1f}s)")
        return True
    except PWTimeout:
        if reg: reg.info(f"clic NO (no apareció) '{selector[:50]}' ({(time.time()-t):.1f}s)")
        return False
    except Exception as e:
        if reg: reg.info(f"clic ERROR '{selector[:50]}': {e}")
        return False


def rellenar(page, selector, valor, timeout_ms=15000, reg=None):
    t = time.time()
    try:
        loc = page.locator(selector).first
        loc.wait_for(state="visible", timeout=timeout_ms)
        loc.click(timeout=timeout_ms)
        loc.fill(valor, timeout=timeout_ms)
        if reg: reg.info(f"campo OK '{selector[:50]}' ({(time.time()-t):.1f}s)")
        return True
    except Exception as e:
        if reg: reg.info(f"campo ERROR '{selector[:50]}': {str(e)[:90]} ({(time.time()-t):.1f}s)")
        return False


def texto_pagina(page):
    try:
        return (page.evaluate("() => document.body ? document.body.innerText : ''") or "").lower()
    except Exception:
        return ""


def pausa_manual(reg, on_pausa, mensaje):
    reg.paso("PAUSA: esperando acción manual del operador...")
    if on_pausa:
        on_pausa(mensaje); return
    # Sin panel: si hay consola interactiva, esperar ENTER; si no, esperar un lapso y seguir
    try:
        interactiva = sys.stdin is not None and sys.stdin.isatty()
    except Exception:
        interactiva = False
    if interactiva:
        try:
            print("\n" + mensaje); input(">> ENTER cuando lo hayas resuelto... ")
            return
        except Exception:
            pass
    seg = int(os.environ.get("AQUASHIELD_PAUSA_SEG", "25"))
    reg.info(f"sin panel/consola: espero {seg}s para resolver manualmente y continúo")
    time.sleep(seg)


# ============================================================
#  LOGIN · ONE
# ============================================================
# La dirección a la que ONE vuelve después del login (decisión de Marcelo, CICLO-cierre-de-frenos.md): así terminaron
# los 4 logins nuevos de logs/, del 2026-09-24 al 26, en www.one-line.com/one-ecom/booking/quick-booking. Hasta 4948e16
# esperaba ecomm.one-line.com/one-ecom, que después del login ya no aparece: la espera vencía siempre a los 25 s («no
# confirmé redirect en 25s») y la sesión quedaba igual, así que cada login tardaba unos 32 s (CICLO-inicio-de-todas.md).
ONE_TRAS_LOGIN = "**://www.one-line.com/one-ecom/**"


def login_one(page, creds, reg, on_pausa=None):
    marc = ["one-ecom/booking", "one-ecom/home", "one-ecom/dashboard"]
    reg.paso("Abriendo ONE...")
    page.goto("https://ecomm.one-line.com/one-ecom/booking/quick-booking", wait_until="domcontentloaded")
    esperar(page, 3, reg, "carga inicial"); reg.url(page)

    if "auth.one-line.com" not in page.url.lower():
        if any(m in page.url.lower() for m in marc):
            reg.paso("Ya había una sesión activa."); return True

    reg.paso("Ingresando credenciales...")
    rellenar(page, "input[placeholder='User ID'], input[type='text']", creds["usuario"], reg=reg)
    rellenar(page, "input[type='password']", creds["clave"], reg=reg)
    if not click_si_existe(page, "role=button[name='Sign In']", 5000, reg):
        click_si_existe(page, "button[type='submit']", 5000, reg)

    try: page.wait_for_url(ONE_TRAS_LOGIN, timeout=25000)
    except Exception: reg.info("no confirmé redirect en 25s")
    esperar(page, 2, reg, "asentar sesión"); reg.url(page); reg.captura(page, "one_final")

    ok = "auth.one-line.com" not in page.url.lower()
    reg.paso("Sesión iniciada." if ok else "No confirmé la sesión.")
    return ok


# ============================================================
#  LOGIN · MSC
# ============================================================
_JS_MSC_LOGIN = """() => {
    const cands = [...document.querySelectorAll('a,button')];
    let el = cands.find(e => /log in to mymsc/i.test(e.textContent||''));
    if (!el) el = cands.find(e => /mymsc/i.test(e.getAttribute('aria-label')||''));
    if (!el) el = cands.find(e => /^\\s*mymsc\\s*$/i.test(e.textContent||''));
    if (!el) el = cands.find(e => /identityserver|mymsc|signin|login/i.test(e.getAttribute('href')||''));
    if (el) { el.click(); return true; }
    return false;
}"""


def _msc_cookies(page, reg):
    """Rechaza cookies no esenciales (OneTrust) si aparece el banner. Rápido si ya se hizo."""
    try:
        if page.evaluate("() => window.__aqua_cookies_ok === true"):
            return True
    except Exception:
        pass
    # ¿está el banner visible?
    try:
        visible = page.locator("#onetrust-reject-all-handler").first.is_visible(timeout=1200)
    except Exception:
        visible = False
    if not visible:
        return False
    for sel in ["#onetrust-reject-all-handler",
                "button:has-text('Reject All')", "button:has-text('Rechazar todo')"]:
        if click_si_existe(page, sel, 1500, reg):
            reg.info("cookies: rechazadas")
            try: page.evaluate("() => { window.__aqua_cookies_ok = true; }")
            except Exception: pass
            esperar(page, 0.8); return True
    return False


# La sesión de myMSC se reconoce por su página (decisión de Marcelo, encargo 45, CICLO-login-msc-y-maersk.md): las 53
# vueltas a myMSC (OidcLoginCallBack) del historial del perfil del programa, del 2026-08-24 al 2026-10-01, terminan en
# /myMSC/welcome; con la sesión ya iniciada, www.mymsc.com lleva ahí (medido el 2026-08-24); y /myMSC/booking/main es
# la página desde la que sigue el programa (MSC_EBOOKING). Hasta el encargo 45 bastaba que no se viera el formulario
# de login y que la dirección fuera de mymsc.com (_msc_logueado): el 2026-10-01 a las 16:06 dio por iniciada la sesión
# en la página de error del propio MSC, en www.mymsc.com/mymsc/, y el historial dice que no la había.
MSC_PAGINAS_CON_SESION = ("/mymsc/welcome", "/mymsc/booking/main")
# La página del portal desde la que sigue el programa después del login: la de eBooking, que reservar_msc abre primero.
MSC_EBOOKING = "https://www.mymsc.com/myMSC/booking/main"
# Los textos del error del portal de MSC en el texto a la vista: los de la página de error de Chrome cuando MSC responde
# 502 («502» y «no puede procesar»; medidos con OCR en msc_final y msc_paso_email: CICLO-inicio-de-todas.md y
# CICLO-cierre-de-frenos.md; en logs/, las 3 capturas con esa página nombran a www.mymsc.com), y el de la página de
# error del propio MSC («We are unable to complete your request at this time»; medido con OCR en las 2 capturas del
# 2026-10-01 a las 16:05 y 16:06, encargo 45).
MSC_TEXTOS_DE_ERROR = ("502", "no puede procesar", "unable to complete your request")
# Lo que dice la página cuando MSC pide una validación (captcha o código): el login pausa para el operador.
MSC_VALIDACION = ("captcha", "verify", "verificación", "robot", "code")
# Cada espera del login de MSC mira la página cada MSC_SONDEO s, hasta MSC_SONDEOS veces: unos 30 s. Hipótesis: 3 veces
# lo más largo medido en el historial del perfil, de las credenciales aceptadas en b2clogin a la vuelta a myMSC (de 2 a
# 10 s en 48 pasadas; sin pasar por b2clogin, de 3 a 5 s en 4; encargo 45).
MSC_SONDEO = 0.5
MSC_SONDEOS = 60
# Cuántos segundos espera el login de MSC, con la página de error que sale tras el «Next» (el 502 de TriggerOidcLogin),
# antes de recargarla una sola vez (_msc_recargar; decisión de Marcelo, encargo 47,
# CICLO-msc-recarga-y-corrida-02-10.md).
# Hipótesis: lo que tardaba la recarga del código de antes del encargo 45, medida en las 9 de logs/ (del 21-09 al
# 01-10): avisaba 18 o 19 s después del «Next» y recargaba 3 s más tarde. El historial del perfil guarda 8 de esas 9.
# Las 7 de TriggerOidcLogin siguieron solas, 5 hasta la página de la clave y 2 por identityserver sin pedirla, y 4
# terminaron en la sesión sin otro intento (3 con la clave escrita por primera vez después de la recarga). La otra, el
# 01-10, terminó en la página de error de MSC. Ninguna volvió al campo del usuario.
MSC_PAUSA_RECARGA = 20
# El motivo de la fila de MSC cuando el login no deja la sesión iniciada y no hubo otro intento: queda NO ENVIADA
# (decisión de Marcelo, encargo 45: el portal podría bloquear la cuenta). Desde el encargo 50, el login hace un segundo
# intento solo tras el error del portal después de la clave (MSC_INTENTOS), y su motivo es MSC_SIN_SESION_TRAS_DOS.
MSC_SIN_SESION = ("no quedó iniciada la sesión de MSC: la reserva no se envió, y el inicio de sesión no se reintentó, "
                  "para no arriesgar la cuenta (el detalle, en log.txt)")
# El motivo de la fila de MSC cuando el portal dio el error después de aceptar el usuario y la clave, al volver a myMSC,
# y el único intento más, desde el principio, tampoco dejó la sesión (decisión de Marcelo, encargo 50,
# CICLO-msc-segundo-intento.md).
MSC_SIN_SESION_TRAS_DOS = ("no quedó iniciada la sesión de MSC: el portal dio un error al volver a myMSC después de "
                           "aceptar el usuario y la clave, y el único intento más, desde el principio, tampoco dejó la "
                           "sesión. La reserva no se envió (el detalle, en log.txt)")
# Las navieras cuyas filas quedan NO ENVIADA, con su motivo, si su login no deja la sesión iniciada: solo MSC (decisión
# de Marcelo, encargo 45). Con las otras, la fila queda sin estado, como antes. El motivo lo da _motivo_sin_sesion.
SIN_SESION = {"msc": MSC_SIN_SESION}
# Cuántos inicios de sesión completos hace el login de MSC, a lo más: el segundo, desde el principio, solo si el
# primero terminó con el error del portal después de la clave (MSC_ERROR_TRAS_LA_CLAVE); nunca un tercero. Así la
# clave se escribe a lo más dos veces, una por intento (decisión de Marcelo, encargo 50, CICLO-msc-segundo-intento.md:
# el 502 llega después de que b2clogin e identityserver aceptaron el usuario y la clave, la ida a eBooking del encargo
# 45 no rescató la sesión en ninguno de los 4 casos medidos, y lo único medido que la recupera es otro inicio de
# sesión). Hasta el encargo 50, ante ese error iba una sola vez a eBooking y no reintentaba.
MSC_INTENTOS = 2
# Lo que devuelve _msc_entrar cuando el error del portal llega después del botón de entrar, con la clave ya escrita.
MSC_ERROR_TRAS_LA_CLAVE = "error tras la clave"
# Las cabeceras de la respuesta que trajo la página de error del login de MSC cuyo valor va a log.txt: las que nombran
# el servidor o una protección contra robots (decisión de Marcelo, encargo 50). De las demás va solo el nombre: nunca
# cookies, tokens ni valores de sesión. Las cookies del perfil en .mymsc.com son de Akamai y de Citrix NetScaler
# (CICLO-login-msc-y-maersk.md); un identificador de petición o de cliente (cf-ray, x-azure-ref, x-datadome-cid…) no
# está en la lista: su nombre ya dice de quién es.
MSC_CABECERAS_CON_VALOR = ("server", "via", "x-powered-by", "x-cache", "x-cdn", "x-served-by", "cf-cache-status",
                           "cf-mitigated", "x-datadome", "akamai-cache-status")
# Cuántas respuestas o fallas de documentos guarda, a lo más, la escucha del login de MSC (_msc_escuchar).
MSC_ESCUCHA = 20


def _msc_sesion(page):
    """True si la página es de myMSC con la sesión iniciada: www.mymsc.com con una ruta de MSC_PAGINAS_CON_SESION, sin
    distinguir mayúsculas. Si no puede leer la dirección, False."""
    try:
        u = urlsplit(str(page.url))
    except Exception:
        return False
    return u.netloc.lower() == "www.mymsc.com" and u.path.lower().rstrip("/") in MSC_PAGINAS_CON_SESION


def _msc_error(page):
    """True si la página es el error del portal de MSC: la página de error de Chrome (su dirección empieza con
    «chrome-error://», como al terminar los 2 logins de logs/ que quedaron sin sesión, el 2026-09-21 y el 26) o una
    cuyo texto a la vista trae uno de MSC_TEXTOS_DE_ERROR. Si no puede leer la página, False. Hasta el encargo 45 era
    _msc_error_502, que no reconocía la página de error del propio MSC ni miraba la dirección."""
    try:
        if str(page.url).lower().startswith("chrome-error://"):
            return True
    except Exception:
        pass
    txt = texto_pagina(page)
    return any(t in txt for t in MSC_TEXTOS_DE_ERROR)


def _msc_a_la_vista(page, selector):
    try:
        return bool(page.locator(selector).first.is_visible())
    except Exception:
        return False


def _msc_esperar(page, reg, que, campo="", on_pausa=None, validar=False, sufijo=""):
    """Espera lo primero que llegue, mirando la página cada MSC_SONDEO s, hasta MSC_SONDEOS veces: la sesión
    (_msc_sesion), el error del portal (_msc_error) o, con 'campo', ese campo a la vista. Devuelve "sesión", "error",
    "campo" o "" si no llegó nada (decisión de Marcelo, encargo 45: la espera termina con el éxito o con el error, lo
    que llegue primero). Con 'validar', si la página pide una validación (MSC_VALIDACION), deja msc_validador (con
    'sufijo' en el segundo intento, _msc_sufijo), pausa una vez para el operador y vuelve a esperar desde ahí. Hasta el
    encargo 45, tras el «Next» esperaba 3 s fijos y hasta 15 s el campo de la contraseña, y tras el botón de entrar
    hasta 5 s y tres vueltas de 3 s, sin mirar si la sesión ya estaba: el 2026-10-01 llegó a las 16:09:06, y el
    programa esperó la contraseña y el botón hasta las 16:09:46."""
    pauso, n = False, 0
    while True:
        if _msc_sesion(page):
            return "sesión"
        if _msc_error(page):
            return "error"
        if campo and _msc_a_la_vista(page, campo):
            return "campo"
        if validar and not pauso and any(k in texto_pagina(page) for k in MSC_VALIDACION):
            reg.captura(page, f"msc_validador{sufijo}")
            pausa_manual(reg, on_pausa, "MSC pide una validación (captcha/código). Resuélvela en el navegador "
                                        "y pulsa '✔ Ya lo resolví (continuar)'.")
            pauso, n = True, 0
            continue
        if n >= MSC_SONDEOS:
            reg.info(f"esperé {MSC_SONDEO * MSC_SONDEOS:.0f} s {que}, y no llegó")
            return ""
        n += 1
        esperar(page, MSC_SONDEO)


def _msc_abrir(page, reg):
    """Abre myMSC y rechaza las cookies no esenciales si aparece el banner."""
    try:
        page.goto("https://www.mymsc.com/", wait_until="domcontentloaded")
    except Exception:
        pass
    esperar_hasta(page, "input[type='email'], input[name*='ser'], input[type='text']", 6, reg, "carga myMSC", asentar=0.6)
    _msc_url(page, reg)
    _msc_cookies(page, reg)


def _msc_sufijo(intento):
    """Lo que llevan al final las capturas y los HTML del login de MSC en el intento 'intento': nada en el primero (los
    nombres de siempre) y «_2» en el segundo, para no pisar los del primero (encargo 50)."""
    return "" if intento == 1 else f"_{intento}"


def _msc_sin_consulta(url):
    """La dirección con su servidor y su ruta, sin usuario ni clave, consulta ni fragmento: la del login de MSC puede
    traer el usuario (usernameLoginHint en TriggerOidcLogin, login_hint en identityserver y b2clogin; medido en el
    historial del perfil del programa, encargo 50)."""
    try:
        s = urlsplit(str(url))
        return f"{s.scheme}://{s.hostname or ''}{f':{s.port}' if s.port else ''}{s.path}"
    except Exception:
        return "(no pude leer la dirección)"


def _msc_url(page, reg):
    """La dirección de la página en log.txt, como reg.url, pero sin su consulta (_msc_sin_consulta): lo dice si la
    quitó. La usa el login de MSC desde el encargo 50, que anota direcciones en cada intento y en cada error."""
    try:
        u = str(page.url)
    except Exception:
        return
    reg.info(f"URL: {_msc_sin_consulta(u)}{' (sin su consulta)' if urlsplit(u).query else ''}")


def _msc_escuchar(page):
    """Escucha, sin tocar la página, las respuestas y las fallas de red de los documentos de su marco principal, para
    decir en log.txt cuál trajo la página de error del login de MSC (_msc_respuesta_del_error; decisión de Marcelo,
    encargo 50: solo se escucha lo que ya pasa). Devuelve un dict: 'vistas', las últimas MSC_ESCUCHA, en orden;
    'nuevas', cuántas de ellas no se informaron todavía; 'activa', si la página dejó escuchar; y 'quitar', que deja de
    escuchar.
    Medido sin red, en Chrome y con datos inventados (encargo 50): un 502 sin cuerpo trae la respuesta, con su código y
    sus cabeceras, y después la falla de red «net::ERR_HTTP_RESPONSE_CODE_FAILURE», y la página queda en
    chrome-error://chromewebdata/; con cuerpo, solo la respuesta."""
    escucha = {"vistas": [], "nuevas": 0, "activa": False}

    def del_marco_principal(peticion):
        try:
            return peticion.resource_type == "document" and peticion.frame == page.main_frame
        except Exception:
            return False

    def anotar(vista):
        escucha["vistas"] = (escucha["vistas"] + [vista])[-MSC_ESCUCHA:]
        escucha["nuevas"] = min(escucha["nuevas"] + 1, MSC_ESCUCHA)

    def al_responder(respuesta):
        try:
            if del_marco_principal(respuesta.request):
                anotar({"respuesta": respuesta, "metodo": respuesta.request.method, "url": respuesta.url,
                        "estado": respuesta.status})
        except Exception:
            pass

    def al_fallar(peticion):
        try:
            if del_marco_principal(peticion):
                anotar({"metodo": peticion.method, "url": peticion.url, "falla": str(peticion.failure or "")})
        except Exception:
            pass

    oyentes = (("response", al_responder), ("requestfailed", al_fallar))
    try:
        for evento, oyente in oyentes:
            page.on(evento, oyente)
        escucha["activa"] = True
    except Exception:
        pass

    def quitar():
        for evento, oyente in oyentes:
            try:
                page.remove_listener(evento, oyente)
            except Exception:
                pass
    escucha["quitar"] = quitar
    return escucha


def _msc_cabeceras(respuesta):
    """Las cabeceras de una respuesta para log.txt: el nombre de todas (all_headers; si no se pueden leer, headers, que
    no trae las de cookies, y lo dice) y el valor solo de las de MSC_CABECERAS_CON_VALOR, recortado. Nunca el valor de
    otra: ni cookies, ni tokens, ni valores de sesión (decisión de Marcelo, encargo 50)."""
    try:
        cab, aviso = dict(respuesta.all_headers()), ""
    except Exception:
        try:
            cab, aviso = dict(respuesta.headers), ", sin las de cookies: no pude leerlas todas"
        except Exception:
            return "no pude leer sus cabeceras"
    cab = {str(k).lower(): v for k, v in cab.items()}
    nombres = sorted(cab)
    valores = [f"{k}: {' '.join(str(cab[k]).split())[:80]}" for k in nombres if k in MSC_CABECERAS_CON_VALOR]
    return f"cabeceras ({len(nombres)}{aviso}): {', '.join(nombres) or '—'}" + "".join(f" · {v}" for v in valores)


def _msc_respuesta_del_error(escucha):
    """La línea de log.txt sobre la respuesta que trajo la página de error del login de MSC, de lo que la escucha vio
    desde la línea anterior (_msc_escuchar): la última respuesta con un código HTTP de 400 o más, con la falla de red de
    su misma dirección, si la hubo; si ninguna trae uno, la última falla de red; y si no hay ninguna de las dos, la
    última respuesta, diciendo que ninguna falló. De cada una: el método, la dirección sin consulta (_msc_sin_consulta),
    el código HTTP y sus cabeceras (_msc_cabeceras). Sin escucha (None), lo dice. Decisión de Marcelo, encargo 50."""
    escucha = {} if escucha is None else escucha
    nuevas = escucha["vistas"][-escucha["nuevas"]:] if escucha.get("nuevas") else []
    escucha["nuevas"] = 0
    if not escucha.get("activa"):
        return "no pude escuchar la red de la página: no sé qué respuesta trajo la página de error"
    respuestas = [v for v in nuevas if "respuesta" in v]
    fallidas = [v for v in respuestas if (v.get("estado") or 0) >= 400]
    fallas = [v for v in nuevas if "falla" in v]
    if fallidas or (respuestas and not fallas):
        r = (fallidas or respuestas)[-1]
        red = [q["falla"] for q in fallas if q["url"] == r["url"]][-1:]
        return (f"{'respuesta que trajo la página de error' if fallidas else 'ninguna respuesta falló; la última'}: "
                f"{r['metodo']} {_msc_sin_consulta(r['url'])} · HTTP {r['estado']}"
                + "".join(f" · falla de red: {x}" for x in red) + f" · {_msc_cabeceras(r['respuesta'])}")
    if fallas:
        q = fallas[-1]
        return (f"petición que falló, sin respuesta HTTP: {q['metodo']} {_msc_sin_consulta(q['url'])} · falla de red: "
                f"{q['falla']}")
    return "no vi ninguna respuesta nueva de la página: no sé cuál trajo la página de error"


def _msc_evidencia_del_error(page, reg, escucha, nombre, creds):
    """El error del portal en el login de MSC, para entender por qué pasa (decisión de Marcelo, encargo 50): log.txt
    anota la respuesta que trajo la página de error (_msc_respuesta_del_error) y la dirección de la página sin su
    consulta (_msc_url), y se guardan la captura de la ventana y el HTML de la página y de cada marco, salvo el que
    traiga el usuario o la clave de la cuenta (_textos_de_la_cuenta): medido sin red, en Chrome y con datos inventados,
    la página de error de Chrome tras un GET repite la dirección entera, y la de TriggerOidcLogin trae el usuario en
    usernameLoginHint; tras el POST de la vuelta a myMSC, no la trae. Solo lee: ni clics, ni navegación, ni esperas."""
    reg.info(_msc_respuesta_del_error(escucha))
    _msc_url(page, reg)
    png = reg.captura(page, nombre)
    guardados, total, _ = _guardar_html_completo(page, reg, nombre, "con el error del login de MSC",
                                                 sin=_textos_de_la_cuenta(creds))
    reg.info(f"evidencia del error de MSC: {f'{nombre}.png' if png else 'sin la captura'} y {guardados} de {total} "
             f"HTML (la página y {total - 1} marco(s))")


# El login de MSC pulsa el «Next» y el botón de entrar solo por su texto: click_si_existe toma el primero, en el orden de
# la página, entre las alternativas de su selector. Si no encuentra uno, lo anota y no pulsa nada: la espera que sigue
# dice si llegó la sesión (decisiones de Marcelo, CICLO-inicio-de-todas.md y CICLO-cierre-de-frenos.md). Hasta c4df3ab
# caía a _JS_CLICK_BTN, que pulsaba el primer botón, enlace o input submit de la página, fuera del encabezado y de la
# navegación, cuyo texto calzara, visible o no; hasta 4948e16, el de entrar también podía ser el primer
# button[type=submit] de la página. Medido en los 7 logins de MSC de logs/ (del 2026-09-21 al 26): el «Next» lo
# encontró su selector las 7 veces, y el de entrar, 6; la vez que no (2026-09-21), el clic genérico tampoco dio la sesión.
def _msc_entrar(page, creds, reg, on_pausa=None, escucha=None, intento=1):
    """Escribe el usuario, pulsa «Next» y espera lo primero que llegue: el campo de la contraseña, la sesión (la de
    identityserver seguía abierta: así pasó el 2026-09-27, el 29 y el 01-10, al volver a entrar) o el error
    (_msc_esperar). Si tras el «Next» llega el error, recarga esa página una sola vez y vuelve a esperar (_msc_recargar;
    decisión de Marcelo, encargo 47). Con el campo, escribe la clave, una sola vez, pulsa el botón de entrar y espera la
    sesión o el error, con la pausa si MSC pide una validación. Devuelve "sesión", "error" (antes de la clave),
    MSC_ERROR_TRAS_LA_CLAVE (después del botón de entrar, con su evidencia: _msc_evidencia_del_error, encargo 50) o ""
    (no llegó ninguna); sin nada tras el «Next», deja msc_paso_email. En el segundo intento ('intento' 2), las
    capturas y los HTML llevan «_2» (_msc_sufijo)."""
    suf = _msc_sufijo(intento)
    reg.paso("Ingresando credenciales..." if intento == 1 else "Ingresando credenciales (segundo intento)...")
    rellenar(page, "#UserName, input[type=email]", creds["usuario"], 12000, reg)
    if not click_si_existe(page, "button:has-text('Next'), button:has-text('Siguiente')", 5000, reg):
        reg.info("no encontré el botón «Next» ni «Siguiente» del login de MSC; no pulsé nada")
    _msc_cookies(page, reg)
    paso = _msc_esperar(page, reg, "la contraseña, la sesión o el error tras el «Next»", campo="input[type=password]")
    if paso == "error":
        paso = _msc_recargar(page, reg, escucha, intento, creds)
    if paso != "campo":
        if not paso:
            reg.info("no vi el campo de contraseña"); reg.captura(page, f"msc_paso_email{suf}")
        return paso
    rellenar(page, "input[type=password]", creds["clave"], 12000, reg)
    if not click_si_existe(page,
            "button:has-text('Login'), button:has-text('Sign In'), button:has-text('Next'), "
            "button:has-text('Iniciar')", 5000, reg):
        reg.info("no encontré el botón para entrar a MSC (Login, Sign In, Next o Iniciar); no pulsé nada")
    paso = _msc_esperar(page, reg, "la sesión o el error tras el botón de entrar", on_pausa=on_pausa, validar=True,
                        sufijo=suf)
    if paso != "error":
        return paso
    reg.paso("⚠ MSC mostró una página de error después de la clave, al pulsar el botón de entrar.")
    _msc_evidencia_del_error(page, reg, escucha, f"msc_error_clave{suf}", creds)
    return MSC_ERROR_TRAS_LA_CLAVE


def _msc_recargar(page, reg, escucha=None, intento=1, creds=None):
    """El error del portal tras el «Next» del login de MSC (el 502 de TriggerOidcLogin, como el 2026-10-02): deja su
    evidencia (_msc_evidencia_del_error: msc_error_next, encargo 50), espera MSC_PAUSA_RECARGA s, recarga esa página una
    sola vez, como hasta el encargo 45, y espera lo primero que llegue: el campo de la contraseña, la sesión o el error
    (_msc_esperar); si sigue el error, deja también msc_error_recarga. Decisión de Marcelo, encargo 47
    (CICLO-msc-recarga-y-corrida-02-10.md): la recarga vuelve, sin reenviar la clave ni otro intento de inicio de
    sesión. No escribe ni pulsa nada: la clave, si aparece su campo, la escribe _msc_entrar por primera vez; si vuelve
    el campo del usuario, no lo escribe (sería otro intento), y la espera termina sin nada. Espera solo el campo de la
    contraseña, como el código de antes del encargo 45: en las 3 recargas de logs/ que dejaron la sesión con la clave,
    la encontró en 0,1 s o menos al buscarla, y el del usuario no apareció en 12 s. Un selector con los dos miraría
    solo el primero en la página (.first). Devuelve "campo", "sesión", "error" o ""."""
    suf = _msc_sufijo(intento)
    reg.paso(f"⚠ MSC mostró una página de error al pulsar «Next». Espero {MSC_PAUSA_RECARGA} s y recargo esa página "
             f"una sola vez, como antes del encargo 45, sin volver a escribir el usuario.")
    _msc_evidencia_del_error(page, reg, escucha, f"msc_error_next{suf}", creds)
    esperar(page, MSC_PAUSA_RECARGA)
    try:
        page.reload(wait_until="domcontentloaded")
    except Exception as e:
        reg.info(f"no pude recargar la página: {str(e)[:70]}")
    paso = _msc_esperar(page, reg, "la contraseña, la sesión o el error tras la recarga", campo="input[type=password]")
    _msc_url(page, reg)
    if paso == "error":
        reg.paso("⚠ Después de la recarga, MSC sigue mostrando la página de error.")
        _msc_evidencia_del_error(page, reg, escucha, f"msc_error_recarga{suf}", creds)
    return paso


def _msc_intento(page, creds, reg, on_pausa, escucha, intento):
    """Un inicio de sesión completo de MSC, desde su página (_msc_abrir, www.mymsc.com), nunca desde una dirección
    guardada: si ya hay sesión, no escribe nada; si la portada ya muestra el error, deja su evidencia
    (msc_error_portada) y no escribe nada; si no, _msc_entrar. Devuelve "sesión", MSC_ERROR_TRAS_LA_CLAVE, "error" o
    "" (no llegó nada)."""
    reg.paso("Abriendo myMSC..." if intento == 1 else "Abriendo myMSC otra vez, desde el principio...")
    _msc_abrir(page, reg)
    if _msc_sesion(page):
        reg.paso("Ya había una sesión activa.")
        return "sesión"
    if _msc_error(page):
        reg.paso("⚠ MSC mostró una página de error al abrir su portada; no escribo el usuario ni la clave.")
        _msc_evidencia_del_error(page, reg, escucha, f"msc_error_portada{_msc_sufijo(intento)}", creds)
        return "error"
    return _msc_entrar(page, creds, reg, on_pausa, escucha, intento)


def login_msc(page, creds, reg, on_pausa=None):
    """Inicia sesión en myMSC desde su página, con el «Next» y el botón de entrar por su texto (_msc_intento,
    _msc_entrar); cada espera termina con lo primero que llegue, la sesión o el error del portal (_msc_esperar).
    Decisiones de Marcelo, encargo 45 (CICLO-login-msc-y-maersk.md), y desde el encargo 50
    (CICLO-msc-segundo-intento.md):
    - Si el error del portal llega después de la clave (MSC_ERROR_TRAS_LA_CLAVE: b2clogin e identityserver ya aceptaron
      el usuario y la clave, y falla la vuelta a myMSC), hace un solo intento más, completo y desde el principio; nunca
      un tercero (MSC_INTENTOS). Si también falla, las filas de MSC quedan NO ENVIADA con MSC_SIN_SESION_TRAS_DOS, que
      deja en el Registro (_motivo_sin_sesion).
    - Con cualquier otro error (en la portada, o tras el «Next» aunque la recarga del encargo 47 no lo arregle) no
      reintenta, y las filas quedan NO ENVIADA con MSC_SIN_SESION.
    - Escucha la red de la página mientras dura (_msc_escuchar), y cada error deja en log.txt la respuesta que lo trajo,
      con su captura y su HTML (_msc_evidencia_del_error). Sin clics nuevos.
    Hasta el encargo 50, ante cualquier error iba una sola vez a eBooking (MSC_EBOOKING) y comprobaba la sesión, sin
    otro intento: en los 4 casos medidos, del 2026-10-02, llevó a la portada sin la sesión. Hasta el encargo 45
    repetía el login entero hasta 2 veces tras un 502 (MSC_REINTENTOS_502, CICLO-cierre-de-frenos.md) y recargaba la
    página si el 502 salía tras el «Next»: el 2026-10-01 a las 16:02 tardó 214 s y dio por iniciada una sesión que no
    existía."""
    vars(reg).setdefault("sin_sesion", {}).pop("msc", None)
    escucha = _msc_escuchar(page)
    intento = 1
    try:
        desenlace = _msc_intento(page, creds, reg, on_pausa, escucha, intento)
        while desenlace == MSC_ERROR_TRAS_LA_CLAVE and intento < MSC_INTENTOS:
            intento += 1
            reg.paso("⚠ El usuario y la clave pasaron, y MSC dio el error al volver a myMSC. Hago un solo intento "
                     "más de inicio de sesión, desde el principio; si también falla, no hay un tercero.")
            desenlace = _msc_intento(page, creds, reg, on_pausa, escucha, intento)
    finally:
        escucha["quitar"]()
    _msc_url(page, reg); reg.captura(page, "msc_final")
    if desenlace == "sesión":
        reg.paso("Sesión iniciada.")
        return True
    if intento > 1:
        reg.sin_sesion["msc"] = MSC_SIN_SESION_TRAS_DOS
        reg.paso("⚠ El segundo intento de inicio de sesión de MSC tampoco dejó la sesión; no hay un tercero.")
    elif desenlace == "error":
        reg.paso("⚠ MSC mostró una página de error antes de la clave; no reintento el inicio de sesión, para no "
                 "arriesgar la cuenta.")
    else:
        reg.paso("No confirmé la sesión.")
    return False


def _motivo_sin_sesion(reg, nav):
    """El motivo de las filas de 'nav' (una naviera de SIN_SESION) cuando su login no dejó la sesión iniciada: el que el
    login dejó en el Registro, si dejó uno (MSC, tras su segundo intento: MSC_SIN_SESION_TRAS_DOS, encargo 50), o el de
    SIN_SESION."""
    return (getattr(reg, "sin_sesion", None) or {}).get(nav) or SIN_SESION[nav]


# ============================================================
#  LOGIN · CMA-CGM
# ============================================================
_JS_CMA_MENU = """() => {
    const el = [...document.querySelectorAll('a,button,span,div')]
        .find(e => /My CMA ?CGM/i.test(e.textContent) && e.textContent.trim().length < 25);
    if (el) { el.click(); return true; } return false; }"""
_JS_CMA_LOGIN = """() => {
    const re = /^(log in|iniciar sesi[oó]n|acceder|connexion)$/i;
    const el = [...document.querySelectorAll('a,button,span,div')]
        .find(e => re.test(e.textContent.trim()));
    if (el) { el.click(); return true; } return false; }"""


def _cma_es_robotcheck(page):
    """Detecta el captcha o verificación anti-bot (DataDome / captcha-delivery) en CMA CGM."""
    try:
        # 1. Chequear URLs, títulos y texto de frames (DataDome usa geo.captcha-delivery.com)
        for fr in page.frames:
            u = (fr.url or "").lower()
            if "captcha-delivery.com" in u or "datadome" in u:
                return True
            try:
                ftit = (fr.title() or "").lower()
                if any(k in ftit for k in ["bloqueado", "blocked", "captcha", "verification"]):
                    return True
                ftxt = (fr.evaluate("() => document.body ? document.body.innerText : ''") or "").lower()
                if any(k in ftxt for k in ["no a un robot", "not a robot", "desliza", "slide", "restring", "restricted", "temporarily restricted"]):
                    return True
            except Exception:
                pass

        # 2. Chequear elementos iframe en el documento principal
        hay_ifr = bool(page.evaluate("""() => {
            return !!document.querySelector('iframe[src*="captcha-delivery"], iframe[src*="datadome"], iframe[src*="challenge"], iframe[src*="captcha"]');
        }"""))
        if hay_ifr:
            return True

        # 3. Chequear texto o título del documento principal
        tit = (page.title() or "").lower()
        if any(k in tit for k in ["bloqueado", "blocked", "verificaci", "verification"]):
            return True
        t = (page.evaluate("() => document.body ? document.body.innerText : ''") or "").lower()
        if any(k in t for k in ["no a un robot", "not a robot", "desliza", "slide", "restring", "restricted"]):
            return True
    except Exception:
        pass
    return False


def resolver_cma_slider(page, reg=None):
    """Intenta arrastrar automáticamente el deslizador de DataDome de CMA CGM hacia la derecha
    con una curva de movimiento humano (aceleración, desaceleración, micro-jitter)."""
    import math, random
    for fr in page.frames:
        try:
            coords = fr.evaluate("""() => {
                const handle = document.querySelector('#slider, .slider, div[class*="slider-btn"], div[class*="sliderBtn"], div[class*="slider-button"], div[class*="handle"], div[role="slider"], div[class*="slider"]');
                const track = document.querySelector('#slider-container, .sliderContainer, .slider-track, div[class*="track"], div[class*="slider-bg"], div[class*="sliderBar"]');
                if (handle) {
                    const hr = handle.getBoundingClientRect();
                    const tr = track ? track.getBoundingClientRect() : (handle.parentElement ? handle.parentElement.getBoundingClientRect() : null);
                    if (hr.width > 0 && hr.height > 0 && tr && tr.width > hr.width) {
                        return {
                            hx: hr.x + hr.width / 2,
                            hy: hr.y + hr.height / 2,
                            distancia: tr.width - hr.width - 2
                        };
                    }
                }
                const arrows = [...document.querySelectorAll('div, button, span')].filter(e => {
                    const r = e.getBoundingClientRect();
                    const t = (e.textContent || '').trim();
                    return (t === '→' || t === '->' || /fa-arrow|icon-arrow|arrow/i.test(e.className || '')) 
                           && r.width > 15 && r.width < 80 && r.height > 15 && r.height < 80;
                });
                if (arrows.length >= 1) {
                    const h = arrows[0];
                    const hr = h.getBoundingClientRect();
                    const parent = h.closest('[class*="slider"], [class*="container"], div') || h.parentElement;
                    const pr = parent ? parent.getBoundingClientRect() : null;
                    const dist = (pr && pr.width > 120) ? (pr.width - hr.width - 4) : 220;
                    return {
                        hx: hr.x + hr.width / 2,
                        hy: hr.y + hr.height / 2,
                        distancia: dist
                    };
                }
                return null;
            }""")
            
            if not coords or coords.get("distancia", 0) <= 20:
                continue

            ifr_offset = page.evaluate("""(frameUrl) => {
                const ifr = [...document.querySelectorAll('iframe')].find(f => (f.src || '').includes(frameUrl) || f.contentWindow === window);
                if (ifr) {
                    const r = ifr.getBoundingClientRect();
                    return { ox: r.x, oy: r.y };
                }
                return { ox: 0, oy: 0 };
            }""", fr.url) or {"ox": 0, "oy": 0}

            start_x = ifr_offset["ox"] + coords["hx"]
            start_y = ifr_offset["oy"] + coords["hy"]
            distancia = coords["distancia"]

            if reg: reg.info(f"CMA slider detectado en ({start_x:.1f}, {start_y:.1f}), arrastre={distancia:.1f}px. Moviendo...")

            page.mouse.move(start_x, start_y)
            esperar(page, 0.25)
            page.mouse.down()
            esperar(page, 0.12)

            pasos = random.randint(32, 45)
            for i in range(pasos):
                t = (i + 1) / pasos
                prog = (1 - math.cos(t * math.pi)) / 2
                cur_x = start_x + distancia * prog
                cur_y = start_y + random.uniform(-1.2, 1.2)
                page.mouse.move(cur_x, cur_y)
                page.wait_for_timeout(random.randint(16, 26))

            esperar(page, 0.25)
            page.mouse.up()
            esperar(page, 2.5)

            if not _cma_es_robotcheck(page):
                if reg: reg.paso("CMA CGM: deslizador resuelto automáticamente con éxito ✓")
                return True
        except Exception as e:
            if reg: reg.info(f"error en auto-deslizador CMA: {e}")
            continue

    return not _cma_es_robotcheck(page)


def _cma_esperar_desafio(page, reg, on_pausa=None, segundos=180):
    """Si CMA CGM muestra la verificación de DataDome (deslizar flecha a la derecha),
    alerta al operador y espera de forma reactiva a que deslice la flecha con el mouse.
    (No se debe arrastrar con eventos sintéticos porque DataDome bloquea temporalmente la IP)."""
    if not _cma_es_robotcheck(page):
        return True

    reg.paso("CMA CGM muestra verificación de seguridad (DataDome: 'Desliza hacia la derecha').")
    reg.captura(page, "cma_robot_desafio")
    try:
        page.bring_to_front()
    except Exception:
        pass

    try:
        import winsound
        winsound.MessageBeep(winsound.MB_ICONEXCLAMATION)
    except Exception:
        pass

    aviso_msg = (
        "\n============================================================\n"
        "  [ATENCIÓN OPERADOR] CMA CGM requiere deslizar la flecha\n"
        "  En la ventana de Chrome, desliza la flecha hacia la derecha.\n"
        "  El robot detectará el desbloqueo y continuará automáticamente.\n"
        "============================================================\n"
    )
    if on_pausa:
        on_pausa("CMA CGM: desliza la flecha hacia la derecha en el navegador para continuar.")
    else:
        print(aviso_msg)

    import time as _t
    t0 = _t.time()
    ultimo_aviso = 0
    while _t.time() - t0 < segundos:
        esperar(page, 1.0)
        if not _cma_es_robotcheck(page):
            reg.paso("Verificación de CMA CGM superada ✓; continúo automáticamente.")
            esperar(page, 1.5)
            return True
        seg_transcurridos = int(_t.time() - t0)
        if seg_transcurridos - ultimo_aviso >= 5:
            ultimo_aviso = seg_transcurridos
            reg.info(f"esperando que deslices la flecha en Chrome... ({seg_transcurridos}s)")

    reg.paso("Tiempo de espera agotado para la verificación de CMA CGM.")
    return False


def login_cma(page, creds, reg, on_pausa=None):
    marc = ["customer-hub", "/ebusiness/"]
    reg.paso("Abriendo cma-cgm.com...")
    page.goto("https://www.cma-cgm.com/", wait_until="domcontentloaded")

    # Esperar verificación de dispositivo
    for i in range(20):
        try: titulo = (page.title() or "").lower()
        except Exception: titulo = ""
        if "verificaci" not in titulo and "verification" not in titulo:
            if i: reg.info(f"home lista tras ~{i}s")
            break
        esperar(page, 1)
    esperar(page, 2, reg, "estabilizar home"); reg.url(page)

    # ¿Verificación de robot (deslizador)?
    if _cma_es_robotcheck(page):
        if not _cma_esperar_desafio(page, reg, on_pausa):
            return False

    if any(m in page.url.lower() for m in marc):
        reg.paso("Ya había una sesión activa."); return True

    reg.paso("Abriendo menú de acceso...")
    llego = False
    for intento in range(4):
        if _cma_es_robotcheck(page):
            if not _cma_esperar_desafio(page, reg, on_pausa):
                return False

        try:
            ab = page.evaluate(_JS_CMA_MENU); reg.info(f"intento {intento+1}: menú {'abierto' if ab else 'no encontrado'}")
        except Exception as e:
            reg.info(f"intento {intento+1}: error menú: {e}")
        esperar(page, 1.3)
        try:
            cl = page.evaluate(_JS_CMA_LOGIN); reg.info(f"intento {intento+1}: login {'pulsado' if cl else 'no encontrado'}")
        except Exception as e:
            reg.info(f"intento {intento+1}: error login: {e}")

        # Comprobar si tras pulsar login apareció el desafío
        if _cma_es_robotcheck(page):
            if not _cma_esperar_desafio(page, reg, on_pausa):
                return False

        import time as _t
        _t0 = _t.time()
        while _t.time() - _t0 < 9:
            if "auth.cma-cgm.com" in page.url.lower():
                break
            if _cma_es_robotcheck(page):
                break
            esperar(page, 0.4)

        if _cma_es_robotcheck(page):
            if not _cma_esperar_desafio(page, reg, on_pausa):
                return False

        if "auth.cma-cgm.com" in page.url.lower():
            reg.info(f"llegué a auth en intento {intento+1} ({_t.time() - _t0:.1f}s)")
            llego = True; break

    if not llego and "auth.cma-cgm.com" not in page.url.lower():
        if _cma_es_robotcheck(page):
            if not _cma_esperar_desafio(page, reg, on_pausa):
                pass
        if any(m in page.url.lower() for m in marc):
            reg.paso("Ya había una sesión activa."); return True
        if not llego and "auth.cma-cgm.com" not in page.url.lower():
            reg.paso("No llegué a la página de autenticación."); reg.captura(page, "cma_sin_login"); return False

    try:
        page.wait_for_selector("input[placeholder='Enter your email'], input[type='email']",
                               timeout=20000, state="visible"); reg.info("formulario visible")
    except Exception:
        reg.info("no vi el formulario en 20s")

    reg.paso("Ingresando credenciales...")
    rellenar(page, "input[placeholder='Enter your email'], input[type='email']", creds["usuario"], 15000, reg)
    rellenar(page, "input[placeholder='Enter your password'], input[type='password']", creds["clave"], 15000, reg)
    if not click_si_existe(page, "role=button[name='Log in']", 5000, reg):
        click_si_existe(page, "button[type='submit']", 5000, reg)

    try: page.wait_for_url("**cma-cgm.com/ebusiness/**", timeout=30000)
    except Exception: reg.info("no confirmé redirect en 30s")
    esperar(page, 2, reg, "asentar sesión"); reg.url(page); reg.captura(page, "cma_final")

    ok = any(m in page.url.lower() for m in marc)
    reg.paso("Sesión iniciada." if ok else "No confirmé la sesión.")
    return ok


# ============================================================
#  AUTO-RESOLUCIÓN DE PUZZLE · COSCO (AJ-Captcha / Vision)
# ============================================================
def _calcular_offset_cosco(bg_bytes, block_bytes):
    """Calcula la coordenada X exacta del hueco en COSCO usando template matching de OpenCV con máscara."""
    import cv2
    import numpy as np

    nparr_bg = np.frombuffer(bg_bytes, np.uint8)
    bg = cv2.imdecode(nparr_bg, cv2.IMREAD_COLOR)

    nparr_block = np.frombuffer(block_bytes, np.uint8)
    block = cv2.imdecode(nparr_block, cv2.IMREAD_UNCHANGED)

    orig_gw = bg.shape[1]
    alpha = block[:, :, 3]

    y_indices, x_indices = np.where(alpha > 80)
    if not len(y_indices):
        return 150, 0, orig_gw

    y0, y1 = y_indices.min(), y_indices.max() + 1
    x0, x1 = x_indices.min(), x_indices.max() + 1

    crop_block = block[y0:y1, x0:x1]
    crop_bgr = crop_block[:, :, :3]
    crop_mask = crop_block[:, :, 3]

    bg_gray = cv2.cvtColor(bg, cv2.COLOR_BGR2GRAY)
    block_gray = cv2.cvtColor(crop_bgr, cv2.COLOR_BGR2GRAY)

    res = cv2.matchTemplate(bg_gray, block_gray, cv2.TM_CCOEFF_NORMED, mask=crop_mask)
    _, _, _, max_loc = cv2.minMaxLoc(res)

    best_x = max_loc[0]
    return best_x, x0, orig_gw


def resolver_cosco_puzzle(page, reg=None):
    """Auto-resuelve el puzzle de COSCO calculando la posición exacta del hueco por visión de bordes."""
    import base64, math, random
    try:
        page.wait_for_selector(".verifybox, .verify-img-panel", timeout=6000, state="visible")
    except Exception:
        return False

    data = page.evaluate("""() => {
        const bg = document.querySelector('img.backImg');
        const block = document.querySelector('img.bock-backImg, img.block-backImg');
        const slider = document.querySelector('.verify-move-block');
        const bar = document.querySelector('.verify-bar-area');
        if (!bg || !block || !slider) return null;
        return {
            bg_b64: bg.src,
            block_b64: block.src,
            slider: slider.getBoundingClientRect(),
            bar: bar ? bar.getBoundingClientRect() : null,
            bg: bg.getBoundingClientRect()
        };
    }""")

    if not data or not data.get("bg_b64") or not data.get("block_b64"):
        if reg: reg.info("puzzle: no se pudieron extraer las imágenes base64")
        return False

    try:
        bg_bytes = base64.b64decode(data["bg_b64"].split(",", 1)[1])
        block_bytes = base64.b64decode(data["block_b64"].split(",", 1)[1])
        target_x, bx0, orig_gw = _calcular_offset_cosco(bg_bytes, block_bytes)

        delta_x_orig = target_x - bx0
        scale = data["bg"]["width"] / float(orig_gw)
        distancia_web = delta_x_orig * scale

        if reg: reg.info(f"puzzle auto-solver: hueco en X={target_x} (desplazamiento={distancia_web:.1f}px)")

        slider = data["slider"]
        start_x = slider["x"] + slider["width"] / 2
        start_y = slider["y"] + slider["height"] / 2

        page.mouse.move(start_x, start_y)
        esperar(page, 0.25)
        page.mouse.down()
        esperar(page, 0.12)

        total_pasos = random.randint(28, 38)
        for i in range(total_pasos):
            t = (i + 1) / total_pasos
            prog = (1 - math.cos(t * math.pi)) / 2
            jy = random.uniform(-1.0, 1.0)
            page.mouse.move(start_x + distancia_web * prog, start_y + jy)
            page.wait_for_timeout(random.randint(18, 30))

        esperar(page, 0.2)
        page.mouse.up()
        esperar(page, 2.5)

        exito = not bool(page.locator(".verifybox, .verify-img-panel").first.is_visible())
        if reg: reg.info(f"puzzle resultado: {'SUPERADO' if exito else 'FALLÓ'}")
        return exito
    except Exception as e:
        if reg: reg.info(f"error en auto-solver: {e}")
        return False


# ============================================================
#  LOGIN · COSCO  (URL directa de Keycloak + login_hint)
# ============================================================
def _cosco_sesion_activa(url, leer_texto, nombre=""):
    """¿La página de COSCO muestra una sesión iniciada? En el tablero, sí; en las páginas de acceso, no. En
    cualquier otra página /ebusiness/, si su texto trae el nombre con que el portal muestra al operador
    («nombre_en_pantalla» de sus credenciales de COSCO en config.json) o «aquachile», junto con «logout» o
    «message center». El texto se lee (leer_texto) solo en ese último caso. Hasta 9710ae2 ese nombre estaba escrito
    aquí (CICLO-cola-cuatro-items.md)."""
    u = (url or "").lower()
    if "/ebusiness/dashboard" in u:
        return True
    if "b2clogin" in u or "/auth/" in u or "exiamfw" in u or "re-login" in u:
        return False
    if "/ebusiness/" in u:
        t = (leer_texto() or "").lower()
        n = str(nombre or "").strip().lower()
        return bool((n and n in t) or "aquachile" in t) and ("logout" in t or "message center" in t)
    return False


def login_cosco(page, creds, reg, on_pausa=None):
    """Login COSCO por el flujo de la app (modal E-LINES): Login -> usuario -> Next step
       -> validador (auto o manual) -> Dashboard. Este flujo SÍ establece la sesión de la app."""
    usuario = creds.get("usuario", ""); clave = creds.get("clave", "")

    def logueado():
        try:
            return _cosco_sesion_activa(
                page.url, lambda: page.evaluate("()=>document.body?document.body.innerText:''"),
                creds.get("nombre_en_pantalla", ""))
        except Exception:
            return False

    reg.paso("Abriendo COSCO e-business...")
    try:
        page.goto("https://elines.coscoshipping.com/ebusiness/Dashboard", wait_until="domcontentloaded")
    except Exception:
        pass
    esperar_hasta(page, "a, button", 5, reg, "carga e-business", asentar=0.8)
    if logueado():
        reg.paso("Ya había una sesión activa."); reg.captura(page, "cosco_final"); return True

    # Home + cerrar tour si aparece
    try:
        page.goto("https://elines.coscoshipping.com/ebusiness/", wait_until="domcontentloaded")
    except Exception:
        pass
    esperar(page, 3)
    try:
        page.evaluate("""()=>{const b=[...document.querySelectorAll('button,span,a')]
            .find(e=>/^\\s*skip\\s*$/i.test((e.textContent||'').trim()));if(b)b.click();}""")
    except Exception:
        pass

    reg.paso("Abriendo modal de login (E-LINES)...")
    try:
        page.get_by_text("Login", exact=False).first.click(timeout=6000)
    except Exception:
        page.evaluate("""()=>{const b=[...document.querySelectorAll('a,button,span,div')]
            .find(e=>e.offsetParent && /^\\s*log ?in\\s*$/i.test((e.textContent||'').trim()));if(b)b.click();}""")
    esperar(page, 2)
    rellenar(page, "input[placeholder*='User' i], input[placeholder*='Email' i]", usuario, 8000, reg)
    esperar(page, 0.5)
    # Next step: secuencia realista de eventos (más fiable con el modal Vue)
    try:
        page.evaluate("""()=>{const b=[...document.querySelectorAll('button,[role=button],a')]
            .find(e=>/next step/i.test((e.textContent||e.value||'').trim()));
            if(b){['pointerdown','mousedown','pointerup','mouseup','click']
                .forEach(t=>b.dispatchEvent(new MouseEvent(t,{bubbles:true,cancelable:true,view:window})));}}""")
    except Exception:
        pass
    # El paso a Keycloak es una NAVEGACIÓN: hay que esperar la URL nueva, no
    # "algún input". El selector anterior incluía input[type=text], que también
    # existe en la página de e-business, así que la espera se cumplía al instante,
    # la URL todavía era la vieja y la contraseña no se escribía nunca.
    try:
        page.wait_for_url("**/auth/realms/**", timeout=12000)
        reg.info("llegué al formulario de contraseña")
    except Exception:
        if any(x in page.url.lower() for x in ("exiamfw", "/auth/", "re-login")):
            reg.info("ya estaba en autenticación")
        else:
            reg.info("no llegué a la pantalla de contraseña")
    esperar_hasta(page, "#password, input[type='password']", 5, reg,
                  "campo de contraseña", minimo=0.3, asentar=0.4)
    reg.url(page)

    # Si cae en Keycloak, rellenar contraseña
    u = page.url.lower()
    if "exiamfw" in u or "/auth/" in u or "re-login" in u:
        rellenar(page, "#password, input[name='password'], input[type='password']", clave, 6000, reg)
        click_si_existe(page, "#kc-login, button[type='submit'], input[type='submit']", 5000, reg)
        esperar(page, 3); reg.url(page)

    # Intento de auto-resolución del puzzle de COSCO
    for intento_p in range(3):
        if logueado():
            break
        try:
            if page.locator(".verifybox, .verify-img-panel").first.is_visible():
                reg.paso(f"COSCO: detectado puzzle de verificación (intento {intento_p+1}/3). Resolviendo automáticamente...")
                resuelto = resolver_cosco_puzzle(page, reg)
                if resuelto:
                    reg.paso("COSCO: puzzle resuelto automáticamente con éxito. Esperando redirección a Dashboard...")
                    for _ in range(15):
                        if logueado():
                            break
                        esperar(page, 1)
                    break
                esperar(page, 1.5)
        except Exception as e:
            reg.info(f"auto-puzzle err: {e}")

    # Pausa + sondeo: si no se resolvió solo, el operador puede resolverlo a mano
    if not logueado():
        reg.captura(page, "cosco_pre_validacion")
        pausa_manual(reg, on_pausa,
                     "COSCO: completa el login/validador en el navegador (Login → usuario → "
                     "Next step → validador). Sigo solo apenas llegues al portal.")
    espera_max = int(os.environ.get("AQUASHIELD_LOGIN_MAX", "240"))
    reg.info(f"esperando sesión (hasta {espera_max}s, avanza al detectarla)...")
    for _ in range(int(espera_max / 3)):
        if logueado():
            break
        esperar(page, 3)
    reg.url(page); reg.captura(page, "cosco_final")
    ok = logueado()
    reg.paso("Sesión iniciada." if ok else "No confirmé la sesión.")
    return ok


