def _maersk_cookies(page, reg):
    """Cierra el aviso de cookies de MAERSK (iframe cookieinformation) eligiendo
    la opción más privada (solo necesarias). El overlay de consentimiento bloquea
    los clics del formulario, así que hay que quitarlo antes de pulsar Log in."""
    # El banner de cookieinformation (elementos 'coi-banner*') inyecta un overlay
    # que intercepta los clics. En vez de pelear con su shadow DOM, se elimina el
    # overlay del DOM para que los botones del formulario queden accionables.
    try:
        quitados = page.evaluate(r"""()=>{
          let n=0;
          const sels=['[id^=coi-banner]','[class^=coi-banner]','[class*=coi-banner]',
                      '[id*=coiOverlay]','[id*=coiConsent]','#coiConsentBanner',
                      'coi-consent-banner','[id*=CybotCookiebot]'];
          sels.forEach(s=>document.querySelectorAll(s).forEach(e=>{e.remove();n++;}));
          // overlays fijos de z-index alto a nivel body
          document.querySelectorAll('body > *').forEach(e=>{
            const cs=getComputedStyle(e);
            if((cs.position==='fixed'||cs.position==='absolute') && (parseInt(cs.zIndex)||0)>=1000
               && /coi|cookie|consent/i.test((e.id||'')+' '+(e.className||''))){e.remove();n++;}});
          document.documentElement.style.overflow=''; document.body.style.overflow='';
          return n;}""")
        if quitados:
            reg.info(f"cookies MAERSK: overlay eliminado ({quitados})")
            return True
    except Exception as e:
        reg.info(f"cookies MAERSK: {str(e)[:50]}")
    return False


def login_maersk(page, creds, reg, on_pausa=None):
    """Login MAERSK (accounts.maersk.com, OIDC). Formulario con componentes web
    (shadow DOM): se usan localizadores de Playwright por placeholder/rol.
    Sin captcha. Si aparece verificación adicional (OTP), se pide al usuario."""
    # Se navega directo a la página protegida de reserva: si ya hay sesión,
    # carga; si no, MAERSK redirige a accounts.maersk.com/login.
    destino = "https://www.maersk.com/book/"

    def en_login():
        return "accounts.maersk.com" in page.url.lower()

    def dentro():
        u = page.url.lower()
        return "maersk.com" in u and "accounts.maersk.com" not in u

    reg.paso("Abriendo MAERSK (book)...")
    try:
        page.goto(destino, wait_until="domcontentloaded")
    except Exception:
        pass
    esperar_hasta(page, "input[placeholder='Username'], #mc-input-origin, button", 7, reg, "carga", asentar=1.2)
    # esperar breve por si redirige a login
    for _ in range(5):
        if en_login() or dentro():
            break
        esperar(page, 1)
    if dentro() and not en_login():
        reg.paso("Ya había una sesión activa."); reg.captura(page, "maersk_final"); return True

    _maersk_cookies(page, reg)
    esperar(page, 1)

    def _navego():
        try:
            return not en_login()
        except Exception:
            return False

    # Dos escenarios en accounts.maersk.com:
    #  (a) pantalla "You are authenticated / Continue as <usuario>" (sesión viva)
    #  (b) formulario Username / Password
    escena = ""
    for _ in range(12):
        try:
            if page.get_by_placeholder("Username").first.is_visible():
                escena = "form"; break
        except Exception:
            pass
        try:
            cont = page.get_by_role("button", name="Continue", exact=True).first
            if cont.is_visible():
                escena = "continue"; break
        except Exception:
            pass
        esperar(page, 1)

    if escena == "continue":
        reg.info("MAERSK: sesión existente -> Continue")
        _maersk_cookies(page, reg)  # quitar overlay que intercepta el clic
        for forzar in (False, True):
            try:
                page.get_by_role("button", name="Continue", exact=True).first.click(
                    timeout=4000, force=forzar)
                break
            except Exception:
                continue
        esperar(page, 3)
    else:
        pwd_loc = None
        try:
            user_loc = page.get_by_placeholder("Username").first
            user_loc.wait_for(state="visible", timeout=10000)
            user_loc.fill(creds.get("usuario", ""), timeout=6000)
            pwd_loc = page.get_by_placeholder("Password").first
            pwd_loc.fill(creds.get("clave", ""), timeout=6000)
            reg.info("campos usuario/clave completados")
        except Exception as e:
            reg.info(f"campos login err: {str(e)[:70]}")
        # Enviar: Enter en la contraseña es lo más fiable con estos componentes web.
        if pwd_loc is not None:
            try:
                pwd_loc.press("Enter"); reg.info("Log in vía Enter")
            except Exception:
                pass
        esperar(page, 3)
        if not _navego():
            for forzar in (False, True):
                try:
                    page.get_by_role("button", name="Log in", exact=False).first.click(
                        timeout=3500, force=forzar)
                    reg.info("clic Log in" + (" (forzado)" if forzar else ""))
                    esperar(page, 2)
                    if _navego():
                        break
                except Exception:
                    continue
    esperar(page, 5, reg, "post-login")

    # Si el portal pide verificación adicional (OTP / 2FA), lo resuelve el usuario.
    for _ in range(8):
        if dentro():
            break
        esperar(page, 2)
    if not dentro():
        u = page.url.lower()
        # ojo: la URL OIDC trae 'code_challenge'; no confundir con 2FA real.
        es_2fa = any(k in u for k in ("/otp", "verify", "mfa", "two-factor", "authenticator", "onetime"))
        if es_2fa:
            reg.paso("MAERSK pide verificación adicional.")
            pausa_manual(reg, on_pausa,
                         "MAERSK: completa la verificación (código/2FA) y pulsa '✔ Ya lo resolví'.")
            for _ in range(6):
                if dentro():
                    break
                esperar(page, 2)
    reg.url(page); reg.captura(page, "maersk_final")
    ok = dentro()
    reg.paso("Sesión iniciada." if ok else "No confirmé la sesión (revisa credenciales/verificación).")
    return ok


def _login_portal(nombre, url_default):
    """Login genérico de portal (aún sin automatizar): abre el portal y espera login manual.
       Sirve de andamiaje para navieras nuevas hasta construir su flujo real."""
    def _login(page, creds, reg, on_pausa=None):
        url = creds.get("url") or url_default
        reg.paso(f"Abriendo portal de {nombre}...")
        try:
            page.goto(url, wait_until="domcontentloaded")
        except Exception as e:
            reg.info(f"goto: {str(e)[:60]}")
        esperar(page, 4, reg, "carga portal")
        reg.captura(page, f"{nombre.lower()}_portal")
        reg.paso(f"{nombre}: inicia sesión manualmente (el flujo automático aún no está construido).")
        pausa_manual(reg, on_pausa,
                     f"{nombre}: completa el login en el navegador y pulsa '✔ Ya lo resolví'.")
        esperar(page, 3)
        reg.url(page); reg.captura(page, f"{nombre.lower()}_final")
        reg.paso(f"{nombre}: continúo (login manual).")
        return True
    return _login


