HOJA_ALIAS = {
    "one":     ["ONE"],
    "msc":     ["MSC"],
    "cma":     ["CMA-CGM", "CMA CGM", "CMA"],
    "cosco":   ["COSCO"],
    "hyundai": ["HYUNDAI", "HMM"],
    "hmm":     ["HYUNDAI", "HMM"],
    "maersk":  ["MAERSK"],
}
HOJA = {k: v[0] for k, v in HOJA_ALIAS.items()}


def _s(v):
    return "" if v is None else str(v).strip()


# El día de carga de la fila, en las formas en que puede llegar (CICLO-cola-cuatro-items.md). Excel entrega una fecha
# como datetime, con hora o sin ella: el lector del panel la escribe «AAAA-MM-DD» y el de consola, «AAAA-MM-DD hh:mm:ss».
# Si la celda no tiene formato de fecha, llega su número de serie (días desde el 30-12-1899), y si es texto, como se
# escribió. Los textos d/m/a se leen con el día primero, como siempre en este programa.
_FECHA_AMD = _re_mk.compile(r"(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?:[ T]\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?)?")
_FECHA_DMA = _re_mk.compile(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4}|\d{2})(?: \d{1,2}:\d{2}(?::\d{2})?)?")
_FECHA_SERIAL = _re_mk.compile(r"\d{5}(?:\.\d+)?")
_DIA_CERO_EXCEL = datetime.date(1899, 12, 30)


def _fecha_planilla(valor):
    """El valor de una celda de fecha como datetime.date, o None si no trae una fecha que se entienda: vacío, un texto que
    no es fecha o una fecha que no existe, como el 31 de febrero. Lo lee todo el programa (_mk_fecha_txt, _cma_fecha_txt,
    _desde y _hmm_fecha; COSCO y MSC, por _desde). Hasta ecbdfaa cada naviera tenía su lector, y ninguno entendía la hora
    ni el número de serie."""
    if isinstance(valor, datetime.datetime):
        return valor.date()
    if isinstance(valor, datetime.date):
        return valor
    if isinstance(valor, bool):                 # true y false no son fechas
        return None
    s = "" if valor is None else str(valor).strip()
    try:
        m = _FECHA_AMD.fullmatch(s)
        if m:
            return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        m = _FECHA_DMA.fullmatch(s)
        if m:
            a = int(m.group(3))
            a = 2000 + a if a < 100 else a
            return datetime.date(a, int(m.group(2)), int(m.group(1)))
        if _FECHA_SERIAL.fullmatch(s):
            return _DIA_CERO_EXCEL + datetime.timedelta(days=int(float(s)))
    except ValueError:
        return None
    return None


def _fecha_ilegible(valor):
    """True si la celda trae algo, pero no una fecha que se entienda (_fecha_planilla)."""
    return bool("" if valor is None else str(valor).strip()) and _fecha_planilla(valor) is None


def _avisar_dia_carga(reserva, reg):
    """Si la fila trae en el día de carga algo que no se entiende como fecha, lo avisa en pantalla y en log.txt. La
    naviera sigue como si la fila no trajera fecha (CICLO-cola-cuatro-items.md)."""
    valor = (reserva or {}).get("dia_carga")
    if _fecha_ilegible(valor):
        reg.paso(f"⚠ El día de carga de la fila {(reserva or {}).get('fila')} («{' '.join(str(valor).split())[:40]}») "
                 f"no se entiende como fecha: sigo como si la fila no lo trajera. Escríbelo como fecha de Excel o como "
                 f"DD-MM-AAAA.")


def _desde(reserva, campos=("dia_carga",)):
    """El día desde el que se busca y se elige la salida. Las reservas se emiten el día en que se corre el programa, así
    que es hoy, o la primera fecha que se entienda de 'campos' (el día de carga; MSC también el de retiro) si es
    posterior (CICLO-proxima-salida.md). Marcelo confirmó esa lectura, para las cuatro navieras que aplican la regla,
    ONE incluida (CICLO-cola-siete-items.md)."""
    hoy = datetime.date.today()
    d = next((f for f in (_fecha_planilla((reserva or {}).get(c)) for c in campos) if f), None)
    return max(hoy, d) if d else hoy


# Los meses en inglés, como los escriben los portales en sus fechas de salida (COSCO, MSC).
_MESES_EN = ("JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC")


def _proxima_salida(salidas, desde, transito=None):
    """Entre varias salidas de la nave de la fila, la próxima a partir de 'desde' (decisión de Marcelo,
    CICLO-proxima-salida.md). 'salidas' es una lista de (fecha de salida, opción), con la fecha como datetime.date, o
    None si no se pudo leer. Entre las que salen el mismo día, la de menor tiempo de tránsito (_menor_transito):
    'transito' da el de cada opción, como datetime.timedelta, o None si no se puede leer. Los transbordos no cuentan
    (decisión de Marcelo, CICLO-cola-tres-items.md). Devuelve (opción, "") si queda una sola; si no, (None, motivo):
    - "ninguna": no hay salidas, o todas salen antes de 'desde';
    - "sin-fecha": hay más de una y alguna no trae una fecha legible, así que no se pueden ordenar;
    - "empate": más de una sale el día de la próxima salida, y el tránsito no deja una sola.
    Una salida sola sin fecha legible se elige: no hay otra con qué compararla. Nunca se elige a ciegas."""
    if len(salidas) == 1 and salidas[0][0] is None:
        return salidas[0][1], ""
    if any(f is None for f, _ in salidas):
        return None, "sin-fecha"
    futuras = [(f, o) for f, o in salidas if f >= desde]
    if not futuras:
        return None, "ninguna"
    primera = min(f for f, _ in futuras)
    del_dia = [o for f, o in futuras if f == primera]
    if len(del_dia) > 1 and transito:
        return _menor_transito(del_dia, transito)
    return (del_dia[0], "") if len(del_dia) == 1 else (None, "empate")


def _transito_legible(tiempo):
    """Si un tiempo de tránsito sirve para desempatar: que se haya leído y sea mayor que cero."""
    return tiempo is not None and tiempo > datetime.timedelta(0)


def _menor_transito(opciones, transito):
    """Entre salidas del mismo día, (la de menor tiempo de tránsito, "") si es una sola y todas lo traen legible (leído y
    mayor que cero, _transito_legible); si no, (None, "empate"): nunca se elige a ciegas (decisión de Marcelo,
    CICLO-cola-tres-items.md)."""
    tiempos = [transito(o) for o in opciones]
    if not all(_transito_legible(x) for x in tiempos):
        return None, "empate"
    menor = min(tiempos)
    las_menores = [o for o, x in zip(opciones, tiempos) if x == menor]
    return (las_menores[0], "") if len(las_menores) == 1 else (None, "empate")


def _directas_primero(tarjetas, desde, reg, lector):
    """Entre las tarjetas de la próxima salida desde 'desde' (las que salen ese mismo día), si alguna es directa, quedan
    solo las directas: las con transbordo de ese día se descartan, y queda anotado en log.txt. Decisiones de Marcelo:
    HYUNDAI (CICLO-ampliar-msc-y-cma.md) y ONE (CICLO-one-y-maersk-eligen-la-nave.md). 'lector' es el de la naviera
    (_hmm_salidas, _one_salidas): [(fecha de salida o None, tarjeta)]. Si todas tienen transbordo, si todas son
    directas o si hay una sola, quedan todas, y _proxima_salida decide por el tránsito. Una tarjeta que no dice si es
    directa (directa None) cuenta como con transbordo. Con alguna fecha que no se lee, no toca nada: _proxima_salida no
    elige. Las otras salidas, intactas: la directa solo desempata el mismo día. Hasta el encargo 34 era
    _hmm_directas_primero, solo de HYUNDAI."""
    salidas = lector(tarjetas)
    if any(f is None for f, _ in salidas):
        return tarjetas
    futuras = [(f, t) for f, t in salidas if f >= desde]
    if not futuras:
        return tarjetas
    dia = min(f for f, _ in futuras)
    del_dia = [t for f, t in futuras if f == dia]
    directas = [t for t in del_dia if t.get("directa") is True]
    if not directas or len(directas) == len(del_dia):
        return tarjetas
    descartadas = [t for t in del_dia if t.get("directa") is not True]
    preferidas = "la directa" if len(directas) == 1 else f"las {len(directas)} directas"
    reg.info(f"{len(del_dia)} salidas de la nave salen el {dia:%d-%m-%Y}: prefiero "
             f"{preferidas}; descarto {len(descartadas)} con transbordo")
    return [t for t in tarjetas if t not in descartadas]


def _por_que_sin_salida(motivo, salidas, desde, transito=None):
    """En palabras, por qué _proxima_salida no dejó una sola salida, para el motivo de la reserva NO ENVIADA. Con
    'transito', en un empate dice también por qué el tiempo de tránsito no desempató (_y_el_transito). Con «sin-viaje»,
    que la fila trae un viaje que ninguna salida de la nave trae (MAERSK y COSCO, CICLO-cierre-de-frenos.md). Con
    «no-reservable», que la salida pedida está, pero el portal ya no deja reservarla (SALIDA_NO_RESERVABLE, MAERSK)."""
    if motivo == "empate" and transito:
        return _por_que_sin_salida(motivo, salidas, desde) + _y_el_transito(salidas, desde, transito)
    n = len(salidas)
    if motivo == "no-reservable":
        return SALIDA_NO_RESERVABLE
    if motivo == "sin-viaje":
        return (f"ninguna de las {n} opciones de la nave trae el viaje de la fila" if n > 1
                else "la única opción de la nave no trae el viaje de la fila")
    if motivo == "sin-fecha":
        return f"no pude leer la fecha de salida de {sum(1 for f, _ in salidas if f is None)} de las {n} opciones"
    if motivo == "ninguna":
        if n < 2:
            return f"la única opción sale antes del {desde:%d-%m-%Y}" if n else "no hay opciones"
        return f"las {n} opciones salen antes del {desde:%d-%m-%Y}"
    primera = min(f for f, _ in salidas if f >= desde)
    return (f"{sum(1 for f, _ in salidas if f == primera)} de las {n} opciones salen el {primera:%d-%m-%Y}, la próxima "
            f"salida desde el {desde:%d-%m-%Y}")


# La salida pedida está en la lista, pero el portal ya no deja reservarla (decisión de Marcelo para MAERSK,
# CICLO-ampliar-la-busqueda.md).
SALIDA_NO_RESERVABLE = "la salida pedida ya no se puede reservar"

# Ampliar la búsqueda (decisiones de Marcelo, CICLO-ampliar-la-busqueda.md y CICLO-ampliar-msc-y-cma.md): si la nave de
# la fila no está en lo que el portal muestra de entrada, la naviera amplía su lista como su portal lo permite (una
# opción o un enlace, por su texto; MSC, bajando por la lista, sin pulsar nada) y vuelve a leerla, hasta encontrarla o
# hasta que el portal no deje ampliar más. Entonces la reserva queda REVISAR, y el motivo dice hasta qué fecha buscó
# (_hasta_donde_busque). AMPLIAR_MAX es el tope de seguridad de las que amplían por tandas (MAERSK, MSC y CMA), por si
# el portal no deja nunca de ofrecer más: es una hipótesis, no está medido. Lo medido: el 2026-09-26, tres tandas de
# MAERSK llegaron a 50 días desde la corrida y el botón desapareció.
AMPLIAR_MAX = 12
NO_AMPLIA_MAS = "el portal no deja ampliar más la búsqueda"


def _hasta_donde_busque(fechas, por_que):
    """Hasta qué fecha buscó la naviera que no encontró la nave de la fila, en palabras, para el motivo del REVISAR: la
    última salida que mostró el portal (la mayor de 'fechas', datetime.date o None) y por qué dejó de ampliar."""
    legibles = [f for f in fechas if f]
    hasta = (f"busqué hasta el {max(legibles):%d-%m-%Y}, la última salida que mostró el portal" if legibles
             else "el portal no mostró ninguna salida con fecha")
    return f"{hasta}, y {por_que}"


def _texto_transito(tiempo):
    """Un tiempo de tránsito en palabras: «40 días», «1 día», «44 días y 6 horas»."""
    dias, horas = tiempo.days, tiempo.seconds // 3600
    texto = f"{dias} día" + ("" if dias == 1 else "s")
    return texto + (f" y {horas} hora" + ("" if horas == 1 else "s") if horas else "")


def _y_el_transito(salidas, desde, transito):
    """Por qué el tiempo de tránsito no desempató las salidas del mismo día: alguna no lo trae legible, o el menor se
    repite."""
    fechas = [f for f, _ in salidas if f >= desde]
    tiempos = [transito(o) for f, o in salidas if f == min(fechas)]
    ilegibles = sum(1 for x in tiempos if not _transito_legible(x))
    if ilegibles:
        return f", y no pude leer el tiempo de tránsito de {ilegibles} de ellas"
    return f", y {tiempos.count(min(tiempos))} de ellas tienen el menor tiempo de tránsito, {_texto_transito(min(tiempos))}"


def _anotar_desempate(reg, salidas, desde, transito):
    """Si el tiempo de tránsito decidió entre salidas del mismo día, lo anota en log.txt: cuántas salían ese día, el
    tiempo de la elegida y el de las otras. Sin esto, el log no dejaría rastro de las que se descartaron
    (CICLO-cola-tres-items.md)."""
    fechas = [f for f, _ in salidas if f is not None and f >= desde]
    if not fechas:
        return
    tiempos = [transito(o) for f, o in salidas if f == min(fechas)]
    if len(tiempos) < 2 or not all(_transito_legible(x) for x in tiempos):
        return
    tiempos = sorted(tiempos)
    reg.info(f"{len(tiempos)} salidas de la nave salen el {min(fechas):%d-%m-%Y}: elijo la de menor tiempo de tránsito, "
             f"{_texto_transito(tiempos[0])} (las otras: {', '.join(_texto_transito(x) for x in tiempos[1:])})")


# Los comodines de la nave: una celda que trae solo esto no pide ninguna nave (decisión de Marcelo,
# CICLO-solo-la-nave-pedida.md). Es una sola lista para las seis navieras. Junta los que ya reconocían CMA, en la celda
# entera (AUTO, CUALQUIERA, LIBRE, N/A, NINGUNA, NONE y «-»), y HYUNDAI, que apartaba todo texto con «completar» y
# quitaba de la nave, antes de calzar, AUTO, PRIMERA, DISPONIBLE, CUALQUIERA y las palabras de una letra. «N/A» y «-»
# no van en la lista: los cubre la regla de las palabras de _fila_sin_nave. Los prefijos de naviera, que también son
# comodines, van aparte, en NAVES_PREFIJO; y MANUAL, como palabra entera, en _fila_manual.
NAVES_COMODIN = ("AUTO", "CUALQUIERA", "LIBRE", "NINGUNA", "NONE", "PRIMERA", "DISPONIBLE")
# Los prefijos de naviera también son comodines: una celda con solo el prefijo de una naviera, o con él y comodines, no
# pide ninguna nave (decisión de Marcelo, CICLO-cola-seis-items.md). Son los que se miden en el código: la lista con que
# CMA calzaba sin ellos hasta 9051f43 (MSC, CMA, CGM, HMM, ONE, COSCO y MV, que es «motor vessel» y no es de una
# naviera) y los nombres de hoja de HOJA_ALIAS que no estaban en ella (HYUNDAI y MAERSK). Van aparte de NAVES_COMODIN
# porque son también los nombres de las navieras, que otras funciones escriben como texto (los reservadores, el panel de
# escritorio y el lector de la consola); ninguna trae como texto una palabra de NAVES_COMODIN. CSCL y SHIPPING no
# vienen del código: son prefijos por decisión de Marcelo, que nombró «CSCL» y «COSCO SHIPPING» (CICLO-inicio-de-todas.md).
# COSCO SHIPPING entra como sus dos palabras, igual que CMA CGM: COSCO ya estaba, así que se suma SHIPPING, y tampoco
# piden una nave «SHIPPING» sola ni «SHIPPING COSCO», que calzarían con toda nave COSCO SHIPPING (salvo en MAERSK, que
# exige el orden). Hasta c4df3ab,
# una celda con solo CSCL o COSCO SHIPPING pedía una nave, y la naviera calzaba con toda tarjeta que la trajera (en las
# listas guardadas de COSCO, 2 de 16 textos de nave empiezan con CSCL y 0 con COSCO SHIPPING).
NAVES_PREFIJO = ("MSC", "CMA", "CGM", "HMM", "ONE", "COSCO", "MV", "HYUNDAI", "MAERSK", "CSCL", "SHIPPING")
FILA_SIN_NAVE = "la fila no trae una nave para reservar"
FILA_MANUAL = "la fila está marcada para hacerse a mano"
# Los motivos de la fila con nave que no trae su puerto de carga o su destino (_falta_en_la_fila; decisión de Marcelo,
# encargo 42, CICLO-maersk-y-fila-sin-ruta.md).
FILA_SIN_PUERTO = "a la fila le falta el puerto de carga"
FILA_SIN_DESTINO = "a la fila le falta el destino"


def _fila_manual(nave):
    """Si la nave de la fila dice MANUAL como palabra entera (_palabra_en: sin una letra o un número pegado antes ni
    después) y sin distinguir mayúsculas: el operador la hace a mano, y la fila es un comodín con su propio motivo
    (decisiones de Marcelo, CICLO-cola-seis-items.md y CICLO-inicio-de-todas.md). «MANUALMENTE» o «SEMIMANUAL» no son
    MANUAL: hasta c4df3ab bastaba que fuera parte del texto. El panel web la recibe de /api/filas para dejarla sin
    marcar; hasta f68ce6c tenía la regla en su JavaScript (marcadaPorDefecto)."""
    return _palabra_en(str(nave or "").upper(), "MANUAL") >= 0


def _fila_sin_nave(nave):
    """Si la nave de la fila no pide ninguna: trae «completar» o MANUAL (_fila_manual, un comodín con su propio motivo),
    o no trae una palabra de dos letras o números o más que no sea comodín (NAVES_COMODIN) ni prefijo de naviera
    (NAVES_PREFIJO), sin distinguir mayúsculas. Las palabras se separan por cualquier signo, y las de una letra no
    cuentan: ninguna naviera las busca. Así, «», «-», «N/A», «(AUTO)», «PRIMERA/DISPONIBLE», «AUTO X», «MSC», «HMM»,
    «CMA-CGM», «CSCL», «COSCO SHIPPING» y «NAVE UNO MANUAL» no piden una nave. Con una palabra que no es comodín ni
    prefijo, y sin «completar» ni MANUAL, sí pide una, y cada naviera la busca con todas sus palabras (_trae_la_nave)."""
    t = str(nave or "").upper()
    palabras = _re_mk.findall(r"[0-9A-ZÑÁÉÍÓÚÜ]{2,}", t)
    return "COMPLETAR" in t or _fila_manual(t) or all(p in NAVES_COMODIN or p in NAVES_PREFIJO for p in palabras)


def _sin_nave(reg, fila, nave=""):
    """La fila no pide una nave (_fila_sin_nave): no se entra al portal por ella. Lo deja en pantalla y en log.txt, y
    devuelve NO ENVIADA con el motivo, que quien la llama deja en la planilla: FILA_MANUAL si la fila dice MANUAL
    (_fila_manual), y si no, FILA_SIN_NAVE."""
    if _fila_manual(nave):
        reg.paso(f"✗ fila {fila}: {NO_ENVIADA} · {FILA_MANUAL}. No entro al portal por ella: hazla a mano en el "
                 f"portal, o escribe en la celda solo la nave, sin MANUAL, si quieres que la arme yo.")
        return (NO_ENVIADA, FILA_MANUAL)
    reg.paso(f"✗ fila {fila}: {NO_ENVIADA} · {FILA_SIN_NAVE}. No entro al portal por ella: escribe la nave en la "
             f"planilla y vuelve a armar la reserva.")
    return (NO_ENVIADA, FILA_SIN_NAVE)


def _ciudad_de(celda):
    """La parte de una celda de puerto o de destino antes de la primera coma, sin los espacios de los extremos: con
    ella buscan las navieras su sugerencia (HYUNDAI escribe la celda entera, y el origen de COSCO, el puerto
    normalizado). Da "" si no trae dos letras o números seguidos, de cualquier alfabeto, porque «-», «?» o «X»
    calzarían con cualquier sugerencia que los trajera (revisión de código del encargo 42). Una sola regla para
    _falta_en_la_fila, los topes de los ayudantes de la ruta y los motivos de sus cortes (encargo 42,
    CICLO-maersk-y-fila-sin-ruta.md)."""
    texto = str(celda or "").split(",")[0].strip()
    return texto if _re_mk.search(r"[^\W_]{2,}", texto) else ""


# Lo que buscaba el ayudante de origen, de destino o del lugar de entrega que recibió un texto sin una palabra antes
# de la primera coma (_ciudad_de): no escribe ni pulsa nada y corta, porque el texto vacío calza con cualquier
# sugerencia a la vista, y «-» o «X», con cualquiera que los traiga (medido en el encargo 42,
# CICLO-maersk-y-fila-sin-ruta.md). Los dos orquestadores ya apartan la fila sin puerto de carga o sin destino
# (_falta_en_la_fila); esto cuida cualquier otro camino, como el destino original de CMA, que ella no mira. El
# ayudante de COSCO sirve también al contrato: corta solo con el texto vacío, y quien le pasa el origen y el destino
# los toma con _ciudad_de.
_TEXTO_DE_LA_FILA = "en la celda de la planilla, antes de su primera coma, el texto para buscar en la lista"


def _sugerencia_que_elegir(celda):
    """Lo que buscaba el ayudante de origen, de destino o del lugar de entrega que no eligió ninguna sugerencia, para el
    motivo de la NO ENVIADA (ObjetivoNoEncontrado): ninguna naviera sigue sin ese campo (decisión de Marcelo, encargo
    42, CICLO-maersk-y-fila-sin-ruta.md). log.txt dice antes por qué no la eligió."""
    return f"una sugerencia que elegir para «{_ciudad_de(celda)}»"


# El país del puerto de carga, como puede venir en su celda: su nombre y su sigla. «CL» cuenta como el país, igual que
# «CHILE» (decisión de Marcelo, encargo 43, CICLO-maersk-elige-exacto.md): hasta ahí, «CL» solo pasaba como un puerto,
# COSCO buscaba «CL» y, en CMA, calzaba con el código de cualquier puerto de Chile. Desde el encargo 46, COSCO también
# lo quita al final del puerto, como «CHILE» (_cosco_puerto_de_la_celda; decisión de Marcelo,
# CICLO-maersk-pulsa-el-book.md).
PAIS_DEL_PUERTO = ("CHILE", "CL")


def _puerto_de_carga(celda):
    """El puerto de carga de una celda, como lo busca COSCO (_cosco_puerto_de_la_celda: antes de la primera coma, en
    mayúsculas, sin tildes y sin el país al final), si trae una palabra que no sea el país; si no, "". La palabra se
    mide con _ciudad_de en la celda tal como viene (así «№» no la inventa al normalizarse: daría «NO») y en el puerto
    sin el país (PAIS_DEL_PUERTO: «CHILE» o «CL») en ninguna posición: «X CHILE», «CHILE X», «Chile - X», «CHILE 1»,
    «CL» o «X CL» no traen el puerto. Las letras se cuentan después de normalizar: A-Z sin tildes y números (el puerto
    de carga es de Chile). Una sola regla para _falta_en_la_fila y _cosco_puerto_de_carga (revisiones del encargo 42,
    CICLO-maersk-y-fila-sin-ruta.md: hasta ahí, «X CHILE» pasaba y COSCO buscaba «X», y después «CHILE X» pasaba y
    «№» también; «CL», desde el encargo 43). Con otra palabra, COSCO busca lo que quedó: al final quita el país, «CHILE»
    o, desde el encargo 46, «CL»; en medio del nombre, los dos quedan (_cosco_puerto_de_la_celda)."""
    puerto = _cosco_puerto_de_la_celda(celda)
    sin_pais = " ".join(p for p in puerto.split() if p not in PAIS_DEL_PUERTO)
    return puerto if _ciudad_de(celda) and _ciudad_de(sin_pais) else ""


def _destino_final_de(celda):
    """La celda del destino final como la leen los dos lectores de la planilla (leer_filas y leer_reservas): «-», sin
    otra cosa, cuenta como la celda vacía, y el destino pasa a ser el original, como con la celda vacía (decisión de
    Marcelo, encargo 43, CICLO-maersk-elige-exacto.md). Hasta ahí, esa fila quedaba NO ENVIADA con «a la fila le falta
    el destino» (encargo 42), y antes las navieras buscaban «-». Otro texto, como «--» o «N/A», queda como viene."""
    return "" if str(celda or "").strip() == "-" else celda


def _falta_en_la_fila(reserva):
    """Lo que le falta a una fila para buscar su ruta en el portal: FILA_SIN_PUERTO si el puerto de carga no trae una
    palabra que no sea el país (_puerto_de_carga); FILA_SIN_DESTINO si el destino (el final o, si viene vacío, el
    original) no trae una palabra antes de la primera coma (_ciudad_de); o "" si trae los dos. Con esa parte buscan las
    navieras su sugerencia, así que «, CHILE», «CHILE», «X CHILE», «CL», «-» o «X» no son un puerto. Con el texto
    vacío, los siete ayudantes de origen, destino y lugar de entrega pulsaban una sugerencia a la vista (medido en un
    Chromium local, sin portales), y MAERSK, HYUNDAI, el destino de COSCO y el lugar de entrega de CMA no miraban si
    eligieron.
    leer_filas salta solo la fila sin puerto de carga ni nave: esta regla la aplican, después de leer, el panel web, la
    consola y el decorador de cada reservador (decisión de Marcelo, encargo 42, CICLO-maersk-y-fila-sin-ruta.md: la fila
    con nave y sin puerto de carga o sin destino queda NO ENVIADA sin entrar al portal, como la fila sin nave). Los
    lectores leen «-» en el destino final como la celda vacía (_destino_final_de; encargo 43): aquí, una fila armada
    de otra forma con «-» en el final no trae destino."""
    pol = (reserva or {}).get("pol")
    destino = (reserva or {}).get("destino_final") or (reserva or {}).get("destino_orig")
    if not _puerto_de_carga(pol):
        return FILA_SIN_PUERTO
    if not _ciudad_de(destino):
        return FILA_SIN_DESTINO
    return ""


def _sin_ruta(reg, fila, falta):
    """La fila trae nave, pero no su puerto de carga o su destino ('falta', de _falta_en_la_fila): no se entra al
    portal por ella. Como _sin_nave, lo deja en pantalla y en log.txt y devuelve NO ENVIADA con el motivo, que quien la
    llama deja en la planilla (decisión de Marcelo, encargo 42, CICLO-maersk-y-fila-sin-ruta.md)."""
    que = "el puerto de carga" if falta == FILA_SIN_PUERTO else "el destino"
    reg.paso(f"✗ fila {fila}: {NO_ENVIADA} · {falta}. No entro al portal por ella: escribe {que} en la planilla y "
             f"vuelve a armar la reserva.")
    return (NO_ENVIADA, falta)


# Las letras (las del castellano, en mayúsculas) y los números de una palabra de nave: la misma clase con que
# _fila_sin_nave separa las palabras (test_la_misma_regla_en_javascript lo vigila). Una palabra de la fila está en el
# texto de la tarjeta como palabra entera si no tiene una de estas pegada antes ni después.
_LETRAS_DE_NAVE = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZÑÁÉÍÓÚÜ"


def _palabra_en(texto, palabra, desde=0):
    """Dónde está 'palabra' en 'texto' como palabra entera, desde la posición 'desde': sin una letra o un número
    (_LETRAS_DE_NAVE) pegado antes ni después. Los dos llegan en mayúsculas. -1 si no está, o si la palabra viene
    vacía. Hace la misma cuenta que _palabraEn de _JS_TRAE_LA_NAVE."""
    if not palabra:
        return -1
    j = texto.find(palabra, desde)
    while j >= 0:
        antes, despues = texto[j - 1:j], texto[j + len(palabra):j + len(palabra) + 1]
        if (not antes or antes not in _LETRAS_DE_NAVE) and (not despues or despues not in _LETRAS_DE_NAVE):
            return j
        j = texto.find(palabra, j + 1)
    return -1


def _con_su_marca(fila):
    """La fila como la lista el panel web (/api/filas), con las marcas de la regla del programa: «manual», si dice
    MANUAL (_fila_manual); «sin_nave», si no trae una nave para reservar (_fila_sin_nave) y no es MANUAL; y, si trae
    nave, «sin_puerto» o «sin_destino», si le falta el puerto de carga o el destino, lo que diga _falta_en_la_fila (la
    fila sin nave dice eso, aunque tampoco traiga la ruta). El panel deja sin marcar las MANUAL, y muestra y cuenta
    aparte las sin nave (CICLO-cola-seis-items.md) y, desde el encargo 43, las sin ruta (decisión de Marcelo,
    CICLO-maersk-elige-exacto.md): hasta ahí, esas quedaban NO ENVIADA recién al correr."""
    nave = fila.get("nave")
    falta = "" if _fila_sin_nave(nave) else _falta_en_la_fila(fila)
    return dict(fila, sin_nave=_fila_sin_nave(nave) and not _fila_manual(nave), manual=_fila_manual(nave),
                sin_puerto=falta == FILA_SIN_PUERTO, sin_destino=falta == FILA_SIN_DESTINO)


def _trae_la_nave(texto, palabras):
    """Si 'texto' (lo que la tarjeta muestra de la nave) trae todas las 'palabras' de la nave de la fila, cada una como
    palabra entera (_palabra_en) y sin distinguir mayúsculas: «ANNA» no calza con «SAVANNAH» (decisión de Marcelo,
    CICLO-cola-seis-items.md; hasta f68ce6c bastaba que fuera parte del texto). Sin palabras no calza nada: una fila sin
    nave no es la nave de ninguna tarjeta (CICLO-cola-tres-items.md). Lo usan MSC y COSCO; ONE, HYUNDAI, MAERSK y CMA
    calzan en su JavaScript con _JS_TRAE_LA_NAVE, que es la misma regla."""
    t = str(texto or "").upper()
    return bool(palabras) and all(_palabra_en(t, p) >= 0 for p in palabras)


# La misma regla para el JavaScript de ONE, HYUNDAI, MAERSK y CMA: cada uno la lleva al principio de su función y calza
# con _traeLaNave (MAERSK, que exige el orden, con _palabraEn). Va sin barras invertidas, porque algunos de esos
# JavaScript no son r"""…""" y las perderían. _traeLaNave pasa el texto a mayúsculas, como _trae_la_nave; las palabras
# llegan en mayúsculas, y el texto de _palabraEn también.
_JS_TRAE_LA_NAVE = """
    const _letraDeNave = c => c !== '' && '""" + _LETRAS_DE_NAVE + """'.includes(c);
    const _palabraEn = (t, x, desde) => {
        if (!x) return -1;
        for (let j = t.indexOf(x, desde); j >= 0; j = t.indexOf(x, j + 1)) {
            if (!_letraDeNave(t.charAt(j - 1)) && !_letraDeNave(t.charAt(j + x.length))) return j;
        }
        return -1;
    };
    const _traeLaNave = (t, palabras) => {
        const u = (t || '').toUpperCase();
        return palabras.length > 0 && palabras.every(x => _palabraEn(u, x, 0) >= 0);
    };
"""


def encontrar_archivo_reservas():
    """Detecta automáticamente el archivo de agendamientos/reservas presente en la carpeta."""
    for nombre in ("Reservas AQUASHIELD.xlsx", "Planilla_Estandar_AQUASHIELD.xlsx", "Agendamientos.xlsx"):
        p = BASE / nombre
        if p.exists():
            return p
    return BASE / "Reservas AQUASHIELD.xlsx"


def leer_reservas(naviera_clave):
    """Lee las filas de reserva adaptándose dinámicamente al archivo Agendamientos o Reservas AQUASHIELD."""
    import openpyxl
    ruta = encontrar_archivo_reservas()
    if not ruta.exists():
        raise FileNotFoundError(f"Falta el archivo Excel de reservas ('Agendamientos.xlsx' o 'Reservas AQUASHIELD.xlsx') junto al programa.")
    try:
        wb = openpyxl.load_workbook(ruta, data_only=True)
    except PermissionError:
        import tempfile, shutil
        tmp_copy = Path(tempfile.gettempdir()) / f"aquashield_read_{ruta.name}"
        shutil.copy(ruta, tmp_copy)
        wb = openpyxl.load_workbook(tmp_copy, data_only=True)
    aliases = HOJA_ALIAS.get(naviera_clave, [naviera_clave.upper()])
    hoja_nombre = next((a for a in aliases if a in wb.sheetnames), None)
    if not hoja_nombre:
        raise ValueError(f"La planilla no tiene la hoja para '{naviera_clave}' (buscados: {aliases}).")
    ws = wb[hoja_nombre]

    # Detectar dinámicamente la fila de encabezados (escaneando filas 1 a 8)
    h_row = None
    for r in range(1, min(ws.max_row + 1, 9)):
        vals = [_s(ws.cell(r, c).value).lower() for c in range(1, min(ws.max_column, 25) + 1)]
        if any("embarque" in v or "pol" in v or "origen" in v for v in vals):
            h_row = r
            break
    if not h_row:
        h_row = 4  # fallback estándar

    # Mapeo dinámico de columnas según su encabezado textual
    col_map = {}
    for c in range(1, min(ws.max_column, 25) + 1):
        v = _s(ws.cell(h_row, c).value).lower()
        if not v or v.startswith("http"):
            continue
        if "embarque" in v or "pol" in v or "origen" in v:
            col_map["pol"] = c
        elif "puerto descarga" in v or "pod" in v:
            col_map["pod"] = c
        elif "lugar de entrega" in v or "entrega" in v:
            col_map["entrega"] = c
        elif "reserva orig" in v:
            col_map["reserva_orig"] = c
        elif "destino orig" in v:
            col_map["dest_orig"] = c
        elif "destino final" in v:
            col_map["dest_final"] = c
        elif "nave" in v or "buque" in v or "vessel" in v:
            col_map["nave"] = c
        elif "viaje" in v or "voyage" in v:
            col_map["viaje"] = c
        elif "cotiz" in v or "contrato" in v:
            col_map["cotiz"] = c
        elif "tipo cont" in v or "contenedor" in v:
            col_map["tipo"] = c
        elif "cant" in v or "qty" in v:
            col_map["cant"] = c
        elif "retiro" in v:
            col_map["retiro"] = c
        elif "deposito" in v or "depósito" in v:
            col_map["deposito"] = c
        elif "carga" in v:
            col_map["carga"] = c
        elif "estado" in v:
            col_map["estado"] = c

    reservas = []
    for r in range(h_row + 1, ws.max_row + 1):
        pol = _s(ws.cell(r, col_map.get("pol", 1)).value)
        # Ignorar filas totalmente vacías
        if not any(_s(ws.cell(r, c).value) for c in range(1, min(ws.max_column, 16) + 1)):
            continue

        nave = _s(ws.cell(r, col_map.get("nave", 0)).value) if "nave" in col_map else ""
        dest_orig = _s(ws.cell(r, col_map.get("pod", col_map.get("dest_orig", 0))).value) if ("pod" in col_map or "dest_orig" in col_map) else ""
        dest_final = _s(ws.cell(r, col_map.get("entrega", col_map.get("dest_final", 0))).value) if ("entrega" in col_map or "dest_final" in col_map) else ""
        dest_final = _destino_final_de(dest_final)       # «-» es la celda vacía (decisión de Marcelo, encargo 43)

        # Manejo tolerante a la estructura humana de Agendamientos. Con la celda de la nave vacía (o sin columna de nave),
        # en ONE y MSC la columna F (en la planilla estándar, «Viaje») sigue decidiendo lo que decidía: si la fila es una
        # nota, si entra a la lista y, en ONE, el destino. Pero no es la nave: la fila queda sin nave (nave_de_la_f), y
        # ejecutar_reservas la deja NO ENVIADA sin entrar al portal por ella (decisión de Marcelo,
        # CICLO-cola-seis-items.md). Hasta f68ce6c iba al portal con el texto de la F como nave.
        nave_de_la_f = False
        if not nave and naviera_clave == "one":
            val_f = _s(ws.cell(r, 6).value)
            if any(w in val_f.upper() for w in ["MSC", "ONE", "FA", "JULIETTE", "LEILA", "VIVIENNE"]):
                nave = val_f
                nave_de_la_f = True
                dest_final = dest_orig  # El destino real está en Destino Original (Col D, formato Agendamientos)
            elif not dest_final:
                dest_final = dest_orig
        elif naviera_clave == "one" and not dest_final:
            dest_final = dest_orig
        elif naviera_clave == "msc":
            val_d = _s(ws.cell(r, 4).value)
            val_f = _s(ws.cell(r, 6).value)
            if not nave and any(w in val_f.upper() for w in ["MSC", "NX", "LEILA"]):
                nave = val_f
                nave_de_la_f = True
            if not dest_orig:
                dest_orig = val_d
            if not dest_final:
                dest_final = val_d
        elif naviera_clave in ("cosco", "hyundai", "maersk"):
            if not dest_orig and col_map.get("reserva_orig"):
                v = _s(ws.cell(r, col_map["reserva_orig"]).value)
                if any(p in v.upper() for p in ["SHANGHAI", "BARCELONA", "BUSAN", "ROTTERDAM"]):
                    dest_orig = v
                    dest_final = v

        # Descartar notas operativas escritas en celdas sueltas
        texto_fila = (nave + " " + pol + " " + dest_orig + " " + dest_final).lower()
        if any(pal in texto_fila for pal in ["elegir siempre", "hacer clicks", "mostrar mas", "significa directo", "no hacerla aun"]):
            continue

        if pol or (nave and len(nave) < 40 and not any(c in nave for c in [",", ";"])) or dest_orig:
            reservas.append({
                "fila": r,
                "pol": pol,
                "reserva": _s(ws.cell(r, col_map.get("reserva_orig", 2)).value) if col_map.get("reserva_orig") else "",
                "destino_orig": dest_orig,
                "destino_final": dest_final or dest_orig,
                "dia_retiro": _s(ws.cell(r, col_map.get("retiro", 0)).value) if col_map.get("retiro") else "",
                "deposito": _s(ws.cell(r, col_map.get("deposito", 0)).value) if col_map.get("deposito") else "",
                "dia_carga": _s(ws.cell(r, col_map.get("carga", 0)).value) if col_map.get("carga") else "",
                "nave": "" if nave_de_la_f else nave,
                "viaje": _s(ws.cell(r, col_map.get("viaje", 0)).value) if col_map.get("viaje") else "",
                "contenedor": _s(ws.cell(r, col_map.get("tipo", 0)).value) if col_map.get("tipo") else "40 HC REEFER",
                "cant": ws.cell(r, col_map.get("cant", 0)).value if col_map.get("cant") else 1,
                "cotizacion": _s(ws.cell(r, col_map.get("cotiz", 0)).value) if col_map.get("cotiz") else "",
            })
    return reservas


# Columna mínima donde nace «Estado (Robot)» si la hoja no tiene «Estado»: la M.
COL_ESTADO_MINIMA = 13


class ErrorEscritura(Exception):
    """No pude escribir un resultado en la planilla. El mensaje va en español, para el operador."""


def _columna_estado(ws):
    """Columna «Estado» de la hoja, ubicada por el texto de su encabezado con el mismo
    _mapear de la descarga del panel. Si la hoja no la tiene, crea «Estado (Robot)» en la
    fila de encabezados, en la columna siguiente a la última con encabezado y nunca antes
    de la M. Nada depende de ws.max_column: leer con ws.cell() crea celdas y lo corre
    (hasta d86fbca la columna nueva caía en la P en vez de la M)."""
    fila_h, cols = _mapear(ws)
    if not fila_h:
        raise ErrorEscritura(f"no encontré la fila de encabezados en la hoja «{ws.title}»")
    if "estado" in cols:
        return cols["estado"]
    ultima = max((c.column for c in ws[fila_h] if _txt(c.value)), default=0)
    col = max(ultima + 1, COL_ESTADO_MINIMA)
    ws.cell(fila_h, col, "Estado (Robot)")
    return col


def escribir_estado(naviera_clave, fila, estado):
    """Escribe el resultado en la columna Estado de la hoja de la naviera en el archivo activo.
    Si no puede, levanta ErrorEscritura con el motivo en español y ejecutar_reservas lo
    muestra en pantalla y en log.txt (hasta fba3bc3 el error se perdía en silencio)."""
    import openpyxl
    ruta = encontrar_archivo_reservas()
    try:
        wb = openpyxl.load_workbook(ruta)
        aliases = HOJA_ALIAS.get(naviera_clave, [naviera_clave.upper()])
        hoja_nombre = next((a for a in aliases if a in wb.sheetnames), None)
        if not hoja_nombre:
            raise ErrorEscritura(f"«{ruta.name}» no tiene la hoja de {naviera_clave} (busqué: {', '.join(aliases)})")
        ws = wb[hoja_nombre]
        col_estado = _columna_estado(ws)
        ws.cell(fila, col_estado, estado)
        wb.save(ruta)
    except ErrorEscritura:
        raise
    except PermissionError as e:
        raise ErrorEscritura(f"«{ruta.name}» está abierta en otro programa (¿Excel?) o es de solo lectura; "
                             f"ciérrala y vuelve a correr") from e
    except FileNotFoundError as e:
        raise ErrorEscritura(f"no encontré «{ruta.name}» junto al programa") from e
    except Exception as e:
        raise ErrorEscritura(f"error inesperado al escribir en «{ruta.name}» ({type(e).__name__}: {e})") from e


def respaldar_planilla():
    """Copia la planilla activa junto a ella, con fecha y hora en el nombre, antes de que la
    consola escriba encima (la copia queda fuera de git: *.xlsx). Devuelve su ruta; si no
    puede hacerla, levanta ErrorEscritura y no se escribe sobre la planilla sin respaldo."""
    import shutil
    ruta = encontrar_archivo_reservas()
    marca = datetime.datetime.now().strftime("%Y-%m-%d %H%M%S")
    destino = ruta.with_name(f"{ruta.stem} - respaldo {marca}{ruta.suffix}")
    n = 2
    while destino.exists():             # dos corridas en el mismo segundo no se pisan
        destino = ruta.with_name(f"{ruta.stem} - respaldo {marca} ({n}){ruta.suffix}")
        n += 1
    try:
        shutil.copyfile(ruta, destino)
    except OSError as e:
        raise ErrorEscritura(f"no pude dejar la copia de respaldo de «{ruta.name}» ({type(e).__name__}: {e}); "
                             f"sin respaldo no escribo encima") from e
    return destino


# Mientras main() corre varias navieras seguidas («todas»), la corrida es una sola y comparte
# una sola copia de respaldo; fuera de eso vale None y cada ejecutar_reservas es su corrida.
_CORRIDA_CONSOLA = None


def _respaldo_de_la_corrida(corrida, reg):
    """Hace la copia de respaldo de la corrida si todavía no existe; si ya la hizo otra naviera
    de la misma corrida, solo la anota en este log. Si la copia falla, levanta ErrorEscritura."""
    if corrida.get("respaldo") is not None:
        reg.info(f"La copia de respaldo de esta corrida ya está: {corrida['respaldo'].name}")
        return
    corrida["respaldo"] = respaldar_planilla()
    reg.info(f"Dejé una copia de respaldo de la planilla: {corrida['respaldo'].name}")
    try:
        borrados, errores = podar_respaldos(corrida["respaldo"].parent)
    except Exception as e:                  # la poda nunca impide escribir: la copia ya está
        reg.paso(f"⚠ No pude revisar las copias de respaldo antiguas ({type(e).__name__}: {e}); la corrida sigue.")
        return
    if borrados:
        reg.info(f"Borré {len(borrados)} copia(s) de respaldo antiguas "
                 f"(se conservan las {RESPALDOS_A_CONSERVAR} más recientes).")
    for error in errores:
        reg.paso(f"⚠ No pude borrar la copia de respaldo antigua {error}; bórrala a mano si sobra.")


# Copias de respaldo que se conservan; las más antiguas se borran al dejar una nueva.
RESPALDOS_A_CONSERVAR = 10
# Solo se borra lo que calza EXACTO con este nombre (decisión de Marcelo): ni las « (2)», ni las
# copias de otra planilla, ni nada fuera de la carpeta de la planilla.
PATRON_RESPALDO = r"Reservas AQUASHIELD - respaldo \d{4}-\d{2}-\d{2} \d{6}\.xlsx"


def podar_respaldos(carpeta):
    """Borra las copias de respaldo más antiguas y deja las RESPALDOS_A_CONSERVAR más recientes.
    Mira solo archivos (no carpetas ni enlaces) de ESA carpeta, sin entrar a subcarpetas, cuyo
    nombre calce exacto con PATRON_RESPALDO; la antigüedad sale de la fecha y hora del nombre,
    no de la del archivo. Devuelve (borrados, errores): lo que no se puede borrar queda."""
    import re
    entradas = list(os.scandir(carpeta))
    respaldos = sorted((e for e in entradas
                        if e.is_file(follow_symlinks=False) and re.fullmatch(PATRON_RESPALDO, e.name)),
                       key=lambda e: e.name)
    borrados, errores = [], []
    for e in respaldos[:-RESPALDOS_A_CONSERVAR]:
        try:
            os.remove(e.path)
            borrados.append(e.name)
        except OSError as err:
            errores.append(f"«{e.name}» ({type(err).__name__}: {err})")
    return borrados, errores


# ============================================================
#  RESERVA · ONE  (hasta ANTES de emitir)
# ============================================================
# Las tarjetas de itinerario de ONE (CICLO-proxima-salida.md), medidas en la corrida del 2026-09-25: la raíz de cada una
# lleva la clase ResultCard_card__<sufijo>; su salida y su llegada van en elementos con clase textStyle-h5 (AAAA-MM-DD);
# la nave y el viaje, en el enlace que sigue a la etiqueta «Vessel Voyage / Service»; y trae un solo botón de reserva.
# Una tarjeta calza solo si ese enlace trae todas las palabras de la nave de la fila, cada una como palabra entera
# (_JS_TRAE_LA_NAVE), como MSC en su campo de la nave (decisiones de Marcelo, CICLO-cola-tres-items.md y
# CICLO-cola-seis-items.md; medido en las 32 tarjetas del 2026-09-25: el enlace trae la nave entera con su viaje, en
# un solo texto). Hasta 9051f43 calzaba con la nave entera, sin su última palabra o con esa palabra sola, que se tomaba
# por el viaje, y en el texto de toda la tarjeta, que trae también los puertos; hasta f68ce6c, con que cada palabra
# fuera parte del enlace. Hasta 8927e1f se pulsaba el botón del elemento más chico que la traía, fuera cual fuera su
# salida (_JS_ONE_SELECT_NAVE). Cada tarjeta dice si es directa en un solo elemento, el de la clase
# TransshipmentInfo_transshipment-container, con «Direct» o «Transshipment» (medido en las 4 listas guardadas, del 25
# y el 27-09: uno en cada una de las 128 tarjetas; cada nave, 4 salidas del mismo día y una sola directa). directa es
# true, false, o null si no hay uno solo o dice otra cosa, como en HYUNDAI (_JS_HMM_TARJETAS). Desde el encargo 34 la
# usa _directas_primero (CICLO-one-y-maersk-eligen-la-nave.md).
_JS_ONE_TARJETAS_NAVE = """(nave) => {""" + _JS_TRAE_LA_NAVE + """
    const palabras = nave.toUpperCase().split('/').join(' ').split(/\\s+/).filter(x => x.length > 1);
    const reserva = /reserva ahora|book now|select|seleccionar/i;
    return [...document.querySelectorAll("[class*='ResultCard_card__']")].map((c, i) => {
        const etq = c.querySelector("[class*='VesselServiceInfo_info-item-label']");
        const enlace = etq && etq.parentElement ? etq.parentElement.querySelector('a') : null;
        const suNave = enlace ? (enlace.textContent||'') : '';
        const calza = _traeLaNave(suNave, palabras);
        const fechas = [...c.querySelectorAll("[class*='textStyle-h5']")].map(e => (e.textContent||'').trim())
            .filter(x => /^\\d{4}-\\d{2}-\\d{2}$/.test(x));
        const tipo = [...c.querySelectorAll("[class*='TransshipmentInfo_transshipment-container']")]
            .map(e => (e.textContent||'').trim());
        const directa = tipo.length !== 1 ? null : /^direct$/i.test(tipo[0]) ? true
            : /^transshipment$/i.test(tipo[0]) ? false : null;
        return {i: i, calza: !!calza, salida: fechas[0] || '', nave: enlace ? (enlace.textContent||'').trim() : '',
                llegada: fechas.length === 2 ? fechas[1] : '',
                botones: [...c.querySelectorAll('button,a')].filter(b => reserva.test(b.textContent||'')).length,
                directa: directa};
    }).filter(x => x.calza);
}"""

# Pulsa el botón de reserva de la tarjeta elegida, {i, nave, salida, directa}, solo si es el único de esa tarjeta y si,
# al volver a leer las tarjetas con _JS_ONE_TARJETAS_NAVE en el mismo JavaScript, la tarjeta i sigue siendo la elegida:
# calza con la nave, sale el día 'salida' y es directa o no como la elegida. Si no, no pulsa nada. Antes cierra el
# diálogo que tape la lista, como hacía _JS_ONE_SELECT_NAVE. Hasta el encargo 34 pulsaba la i-ésima sin volver a
# leerla: desde entonces, dos tarjetas de la misma nave y el mismo día pueden diferir solo en si son directas, como en
# HYUNDAI (_JS_HMM_CLIC_TARJETA; CICLO-one-y-maersk-eligen-la-nave.md).
_JS_ONE_CLIC_TARJETA = """(args) => {
    const t = (""" + _JS_ONE_TARJETAS_NAVE + """)(args.nave).find(x => x.i === args.i);
    if (!t || t.salida !== args.salida || t.directa !== args.directa) return false;
    const i = args.i;
    const dlg = document.querySelector('[class*=dialog__overlay],[id^=dialog-portal] [role=dialog],[role=dialog]');
    if (dlg) {
        // Nunca «Next»: en «Vessel Information» lleva a elegir otra nave (hasta a198645 lo pulsaba).
        const dBtn = [...dlg.querySelectorAll('button')].find(b => /^\\s*(cancel|cancelar|close|cerrar)\\s*$/i.test(b.textContent.trim()));
        if (dBtn) dBtn.click();
    }
    const c = [...document.querySelectorAll("[class*='ResultCard_card__']")][i];
    if (!c) return false;
    const btns = [...c.querySelectorAll('button,a')].filter(b => /reserva ahora|book now|select|seleccionar/i.test(b.textContent||''));
    if (btns.length !== 1) return false;
    btns[0].scrollIntoView({block:'center'}); btns[0].click(); return true;
}"""


# Enfocar un input por su placeholder (regex, bilingüe)
_JS_FOCUS_INPUT = """(rx) => {
    const re = new RegExp(rx, 'i');
    const el = [...document.querySelectorAll('input')].find(i => re.test(i.placeholder||''));
    if (el) { el.scrollIntoView({block:'center'}); el.focus(); el.click(); return true; }
    return false;
}"""

# Clic en botón cuyo texto (trim) matchee la regex (excluyendo header y navegación)
_JS_CLICK_BTN = """(rx) => {
    const re = new RegExp(rx, 'i');
    const el = [...document.querySelectorAll('button,a,input[type=submit]')]
        .filter(b => !b.closest('header, nav, [role="navigation"]'))
        .find(b => re.test((b.textContent||b.value||'').trim()));
    if (el) { el.scrollIntoView({block:'center'}); el.click(); return true; }
    return false;
}"""

# Elegir 'Reefer/Refrigerada' en el desplegable de tipo de carga
_JS_CARGO_REEFER = """() => {
    // 1) select nativo
    for (const s of document.querySelectorAll('select')) {
        for (const o of s.options) {
            if (/reefer|refriger/i.test(o.textContent)) { s.value=o.value; s.dispatchEvent(new Event('change',{bubbles:true})); return 'select'; }
        }
    }
    // 2) desplegable custom: abrir el que dice Cargo Type / Tipo de Carga y clicar la opción
    const trg = [...document.querySelectorAll('*')].find(e =>
        /dry|seco|general|cargo type|tipo de carga/i.test((e.textContent||'').trim()) && e.children.length<=2 && e.offsetParent);
    if (trg) { trg.click(); }
    return 'custom-open';
}"""


def _seleccionar_opcion_autocomplete(page, valor, reg):
    """Escribe en un autocompletado enfocado y elige la primera sugerencia."""
    try:
        page.keyboard.type(valor, delay=60)
        esperar(page, 2)
        # intentar clic en la primera opción visible de la lista
        clic = False
        try:
            clic = bool(page.evaluate("""() => {
                const cand = [...document.querySelectorAll('li,[role=option],.ant-select-item,.el-select-dropdown__item,div')]
                    .filter(e => e.offsetParent && (e.textContent||'').trim().length>2
                                 && /option|item|result|suggest|dropdown/i.test((e.className||'')+(e.getAttribute('role')||'')));
                if (cand.length) { cand[0].click(); return true; }
                return false;
            }"""))
        except Exception:
            pass
        if not clic:
            page.keyboard.press("ArrowDown"); page.keyboard.press("Enter")
        return True
    except Exception as e:
        reg.info(f"autocomplete '{valor}': {e}")
        return False


# Clic en una opción del desplegable/autocompletado que contenga el token (no el input)
_JS_CLICK_OPTION_TOKEN = """(tok) => {
    const T = tok.toUpperCase();
    const els = [...document.querySelectorAll('li,[role=option],[class*=option],[class*=item],[class*=suggest],[class*=dropdown] *,[class*=menu] *')]
        .filter(e => e.offsetParent && e.tagName !== 'INPUT'
                     && (e.textContent||'').toUpperCase().includes(T)
                     && (e.textContent||'').trim().length < 60);
    els.sort((a,b) => (a.textContent||'').length - (b.textContent||'').length);
    if (els.length) { els[0].click(); return true; }
    return false;
}"""


# Cierra la ventana emergente de ONE por su botón (texto) o su ícono de cierre (aria-label o clase «close»).
# Hasta 83067a1 pulsaba, si no, el primer botón visible del diálogo, fuera cual fuera: ahora devuelve
# 'sin-cierre' sin pulsar nada, solo en el caso en que antes habría pulsado a ciegas (CICLO-clics-a-ciegas.md).
_JS_ONE_CERRAR_MODAL = """() => {
    const dlg = document.querySelector('[class*=dialog__overlay],[id^=dialog-portal] [role=dialog],[role=dialog]');
    if (!dlg) return false;
    const text = (dlg.textContent || '').trim();
    // Si es 'Vessel Information' ("passed the cut-off date... click Next to select a new vessel"), la nave de la fila
    // pasó su cut-off y ONE ofrece elegir otra: no pulsa nada en él, y antes de la guarda la reserva corta
    // (_cerrar_modal_one). Hasta a198645 lo cerraba con su primer botón, «Next» incluido, y seguía
    // (CICLO-solo-la-nave-pedida.md).
    if (/passed the cut-off date|select a new vessel/i.test(text)) return 'vessel-info';
    let b = [...dlg.querySelectorAll('button')]
        .find(x => /^\\s*(cancel|cancelar|close|cerrar|dismiss|ok|accept|aceptar)\\s*$/i.test((x.textContent||'').trim()));
    if (b) { b.click(); return 'button-close'; }
    const x = [...dlg.querySelectorAll('[aria-label*=close i],[class*=close i]')]
        .find(e => e.offsetParent);
    if (x) { x.click(); return 'icon-close'; }
    if ([...dlg.querySelectorAll('button')].some(e => e.offsetParent)) return 'sin-cierre';
    return false;
}"""


def _cerrar_modal_one(page, reg, antes_de_la_guarda=True):
    """Cierra los diálogos emergentes si aparecen. Si hay uno con botones y ninguno se reconoce como su cierre, no
    pulsa nada: antes de la guarda corta la reserva (ObjetivoNoEncontrado); después, solo lo anota, porque el envío pudo
    haber salido. «Vessel Information» (la nave pasó su cut-off y ONE ofrece elegir otra) no se toca y corta igual: el
    programa nunca reserva una nave que la fila no pidió (CICLO-solo-la-nave-pedida.md)."""
    try:
        cerrado = page.evaluate(_JS_ONE_CERRAR_MODAL)
        if cerrado == "vessel-info":
            buscaba = ("una salida de la nave con su cut-off vigente: ONE avisa que la elegida lo pasó y ofrece elegir "
                       "otra nave")
            if antes_de_la_guarda:
                raise ObjetivoNoEncontrado("«Vessel Information» de ONE", buscaba)
            reg.info("ONE muestra «Vessel Information»: la nave pasó su cut-off y ofrece elegir otra; no pulsé nada")
            return False
        if cerrado == "sin-cierre":
            buscaba = ("el botón que cierra la ventana emergente («Cancel», «Close», «OK» o «Aceptar») ni su "
                       "ícono de cierre")
            if antes_de_la_guarda:
                raise ObjetivoNoEncontrado("Cerrar la ventana emergente de ONE", buscaba)
            reg.info(f"hay una ventana emergente y no encontré {buscaba}; no pulsé nada")
            return False
        if cerrado:
            reg.info(f"cerré un modal emergente ({cerrado})"); esperar(page, 1)
        return bool(cerrado)
    except Exception:
        return False


# Diagnóstico + clic de la sugerencia real (excluye tarjetas frecuentes/patrón). Pulsa solo con [texto, true] (o con
# el texto solo, como antes); con [texto, false] solo lee y devuelve la que pulsaría ('' si ninguna), sin pulsarla, para
# dejar antes la evidencia de la lista (CICLO-origen-y-destino.md). La describe con su etiqueta, su clase, su posición y
# su texto.
_JS_PICK_SUGGESTION = """(a) => {
    const [tok, pulsar] = Array.isArray(a) ? [a[0], a[1] === true] : [a, true];
    const T = tok.toUpperCase();
    // candidatos en la zona del formulario/desplegable (arriba), excluyendo tarjetas frecuentes
    const all = [...document.querySelectorAll('li,[role=option],[class*=option],[class*=item],[class*=menu] *,[class*=list] *,[class*=autocomplete] *,div,span,td,p')]
        .filter(e => {
            if (!e.offsetParent || e.tagName === 'INPUT') return false;
            const t = (e.textContent||'').toUpperCase();
            if (!t.includes(T) || t.trim().length > 55) return false;
            const r = e.getBoundingClientRect();
            return r.height > 8 && r.height < 70;
        });
    const dump = all.slice(0,8).map(e => {
        const r = e.getBoundingClientRect();
        return e.tagName + '.' + (e.className||'').toString().slice(0,24) + '#' + Math.round(r.top);
    }).join('  ');
    let cand = all.filter(e =>
        !/frequent|pattern|summaryinfo|infobox|card/i.test((e.className||'').toString())
        && !e.closest('[class*=Frequent i],[class*=pattern i]')
        && e.getBoundingClientRect().top < 850);
    cand.sort((a,b) => a.getBoundingClientRect().top - b.getBoundingClientRect().top);
    let clicked = '';
    if (cand.length) {
        const r = cand[0].getBoundingClientRect();
        if (pulsar) cand[0].click();
        clicked = cand[0].tagName + '.' + (cand[0].className||'').toString().slice(0,24) + '#' + Math.round(r.top)
            + ' «' + (cand[0].textContent||'').trim().slice(0,45) + '»';
    }
    return pulsar ? 'CLICK[' + clicked + '] CANDS[' + dump + ']' : clicked;
}"""


def _texto_de_la_sugerencia(descripcion):
    """El texto de una sugerencia (sus primeros 45 caracteres) en la descripción que da _JS_PICK_SUGGESTION,
    «ETIQUETA.clase#posición «texto»», o la descripción entera si no lo trae. Con él se compara la que pulsaría al
    dejar la evidencia con la que pulsó: la clase se lee después del clic, y la posición puede moverse mientras se
    guarda la evidencia, sin que cambie la sugerencia (revisión del informe del encargo 41, CICLO-origen-y-destino.md).
    Hasta ahí se comparaba la descripción entera."""
    i = descripcion.find(" «")
    return descripcion[i + 2:-1] if i >= 0 and descripcion.endswith("»") else descripcion


def _fill_autocomplete(page, css, keyword, reg, etiqueta, evidencia=""):
    """Escribe 'keyword' en un autocompletado (mag-list) y clica la sugerencia apenas aparece. Si no aparece, no
    pulsa nada y corta la reserva (ObjetivoNoEncontrado): hasta fb63271 elegía con el teclado (flecha abajo y Enter)
    la sugerencia que quedara primera, fuera cual fuera (CICLO-cola-nueve-items.md). Anota cuál pulsó.
    Con 'evidencia' (el origen y el destino), antes de pulsarla deja con ese nombre la captura de la ventana y el HTML
    de la página y de sus marcos, con la lista: _JS_PICK_SUGGESTION, sin pulsar, dice si hay una que pulsaría (decisión
    de Marcelo, CICLO-origen-y-destino.md); y después del clic, _avisar_lista_distinta, con solo el texto de cada una
    (_texto_de_la_sugerencia). Sin una palabra antes de la primera coma (_ciudad_de: vacío, «-», «X») no escribe ni
    pulsa nada: corta (_TEXTO_DE_LA_FILA; encargo 42), porque calzaba con cualquier sugerencia que lo trajera."""
    if not _ciudad_de(keyword):
        raise ObjetivoNoEncontrado(f"{etiqueta} de ONE", _TEXTO_DE_LA_FILA)
    try:
        _cerrar_modal_one(page, reg)
        inp = page.locator(css).first
        inp.wait_for(state="visible", timeout=8000)
        try:
            inp.click(timeout=4000)
        except Exception:
            try: page.keyboard.press("Escape")
            except Exception: pass
            esperar(page, 0.4)
            try: inp.click(force=True, timeout=4000)
            except Exception: pass
        try: inp.fill("")
        except Exception: pass
        inp.type(keyword, delay=80)
        tok = keyword.split(",")[0].strip()
        # Sondea hasta ~3.5s: avanza apenas la sugerencia es clicable
        info = ""; clic_ok = False; pendiente = bool(evidencia); vista = ""
        for _ in range(9):
            esperar(page, 0.4)
            if pendiente:
                vista = " ".join(str(_sugerencia_sin_pulsar(page, _JS_PICK_SUGGESTION, [tok])).split())
                if vista:
                    _evidencia_antes_de_la_guarda(page, reg, evidencia, f"con las sugerencias de {etiqueta}",
                                                  completa=False)
                    pendiente = False
            try:
                info = page.evaluate(_JS_PICK_SUGGESTION, [tok, True])
            except Exception as e:
                info = f"err {str(e)[:50]}"
            if ("CLICK[" in info) and ("CLICK[]" not in info):
                clic_ok = True; break
        if not clic_ok:
            reg.info(f"{etiqueta} ('{keyword}'): sin sugerencia | {info[:80]}")
            if pendiente:
                _evidencia_sin_sugerencia(page, reg, evidencia, etiqueta)
            raise ObjetivoNoEncontrado(f"{etiqueta} de ONE", f"la sugerencia «{tok}» en la lista del autocompletado")
        pulsada = " ".join(info[info.index("CLICK[") + 6:info.rfind("] CANDS[")].split())
        reg.info(f"{etiqueta} ('{keyword}'): sugerencia seleccionada: {pulsada}")
        _avisar_lista_distinta(reg, etiqueta, evidencia, _texto_de_la_sugerencia(vista),
                               _texto_de_la_sugerencia(pulsada), pendiente)
        esperar(page, 0.4)
        return True
    except Exception as e:
        reg.info(f"{etiqueta}: error {str(e)[:80]}")
        return False


def _fill_port(page, css, valor, reg, etiqueta, evidencia=""):
    """Escribe la CIUDAD del puerto para disparar el autocompletado y clica la sugerencia; con 'evidencia', antes deja
    la de la lista (_fill_autocomplete)."""
    return _fill_autocomplete(page, css, valor.split(",")[0].strip(), reg, etiqueta, evidencia=evidencia)


def _fill_texto_por_label(page, regex_label, valor, reg, etiqueta):
    """Rellena un input de texto/número ubicándolo por su etiqueta cercana o placeholder."""
    try:
        ok = page.evaluate("""(a) => {
            const [rx, val] = a;
            const re = new RegExp(rx, 'i');
            // 1) por placeholder directo
            let inp = [...document.querySelectorAll('input:not([type=checkbox]):not([type=radio])')]
                .find(i => i.offsetParent && re.test(i.placeholder||''));
            // 2) por etiqueta cercana (label -> input dentro del mismo contenedor)
            if (!inp) {
                const lab = [...document.querySelectorAll('label,span,div,p')]
                    .find(e => e.offsetParent && re.test((e.textContent||'').trim())
                               && (e.textContent||'').trim().length < 45);
                let cont = lab ? lab.parentElement : null;
                for (let k=0; k<4 && cont && !inp; k++) {
                    inp = [...cont.querySelectorAll('input:not([type=checkbox]):not([type=radio])')]
                        .find(i => i.offsetParent);
                    cont = cont.parentElement;
                }
            }
            if (!inp) return false;
            const set = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
            inp.focus(); set.call(inp, ''); inp.dispatchEvent(new Event('input', {bubbles:true}));
            set.call(inp, String(val));
            inp.dispatchEvent(new Event('input', {bubbles:true}));
            inp.dispatchEvent(new Event('change', {bubbles:true}));
            inp.dispatchEvent(new KeyboardEvent('keyup', {bubbles:true}));
            return true;
        }""", [regex_label, valor])
        reg.info(f"{etiqueta}='{valor}': {'ok' if ok else 'NO encontré el campo'}")
        return bool(ok)
    except Exception as e:
        reg.info(f"{etiqueta}: error {str(e)[:80]}")
        return False


_JS_FILL_INPUT_LABEL = """(a) => {
    const [rx, val] = a;
    const re = new RegExp(rx, 'i');
    const labels = [...document.querySelectorAll('label')]
        .filter(e => e.offsetParent && re.test((e.textContent||'').replace(/\\*/g,'').trim()));
    if (!labels.length) return 'no-label';
    const label = labels[0];
    // acotar al contenedor de ESTE campo (no al grupo)
    const scope = label.closest('[class*=number-input__base],[class*=unit-input],[class*=compact-wrapper],[class*=input__base],[class*=input-container__base]') || label.parentElement;
    let inp = scope ? scope.querySelector('input:not([type=checkbox]):not([type=radio])') : null;
    if (!inp) {
        const all = [...document.querySelectorAll('input')].filter(i => i.offsetParent);
        inp = all.find(i => (label.compareDocumentPosition(i) & Node.DOCUMENT_POSITION_FOLLOWING));
    }
    if (!inp) return 'no-input';
    const set = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    inp.scrollIntoView({block:'center'});
    inp.focus(); set.call(inp, ''); inp.dispatchEvent(new Event('input', {bubbles:true}));
    set.call(inp, String(val));
    inp.dispatchEvent(new Event('input', {bubbles:true}));
    inp.dispatchEvent(new Event('change', {bubbles:true}));
    inp.dispatchEvent(new KeyboardEvent('keyup', {bubbles:true}));
    try { inp.blur(); } catch(e){}
    return 'ok';
}"""


def _fill_input_por_label(page, regex_label, valor, reg, etiqueta):
    """Rellena el input propio de una etiqueta (acota al contenedor del campo, no al grupo)."""
    try:
        r = str(page.evaluate(_JS_FILL_INPUT_LABEL, [regex_label, valor]))
    except Exception as e:
        r = f"err {str(e)[:60]}"
    reg.info(f"{etiqueta}='{valor}': {r}")
    return r == "ok"


def _set_dropdown_por_label(page, regex_label, regex_opcion, reg, etiqueta):
    """Abre un desplegable identificado por su etiqueta y elige la opción que matchee."""
    abierto = False
    try:
        abierto = bool(page.evaluate("""(rx) => {
            const re = new RegExp(rx, 'i');
            const lab = [...document.querySelectorAll('label,span,div,p')]
                .find(e => e.offsetParent && re.test((e.textContent||'').trim())
                           && (e.textContent||'').trim().length < 45);
            let cont = lab ? lab.parentElement : null;
            for (let k=0; k<4 && cont; k++) {
                const dd = [...cont.querySelectorAll('*')].find(e => e.offsetParent &&
                    (/select|choose|seleccion|elegir/i.test((e.textContent||'').trim())
                     || e.matches('select,[class*=select i],[role=combobox]'))
                    && (e.textContent||'').trim().length < 40);
                if (dd) { (dd.closest('[class*=select i],[role=combobox]') || dd).click(); return true; }
                cont = cont.parentElement;
            }
            return false;
        }""", regex_label))
    except Exception:
        pass
    if not abierto:
        reg.info(f"{etiqueta}: no abrí el desplegable"); return False
    esperar(page, 1)
    ok = False
    try:
        ok = bool(_click_opcion(page, regex_opcion))
    except Exception as e:
        reg.info(f"{etiqueta}: {str(e)[:60]}")
    reg.info(f"{etiqueta} -> '{regex_opcion}': {'ok' if ok else 'sin opción'}")
    return ok


def _determinar_contrato_one(reserva, creds):
    """Elige el contrato USA u Otros Mercados según nota del Excel. Sin uno en la fila ni en las credenciales,
    el de config.json (_contrato_por_defecto: «one_usa» u «one_otros»)."""
    if reserva.get("cotizacion"):
        return reserva["cotizacion"]
    d = (reserva.get("destino_final") or reserva.get("destino_orig") or "").upper()
    es_usa = any(x in d for x in ["UNITED STATES", "USA", "U.S.A.", "MIAMI", "LOS ANGELES", "LONG BEACH", "NEW YORK", "SAVANNAH", "SEATTLE", "HOUSTON"])
    if es_usa:
        return creds.get("contrato_usa") or creds.get("contrato") or _contrato_por_defecto("one_usa")
    else:
        return creds.get("contrato_otros") or _contrato_por_defecto("one_otros")


def _set_weeks_one(page, semanas_txt, reg):
    """En ONE Quick Booking, cambia el rango de búsqueda a 8 semanas (Nota del Excel Agendamientos)."""
    try:
        abierto = page.evaluate("""() => {
            const dd = [...document.querySelectorAll('*')].find(e =>
                e.offsetParent && /\\b\\d+\\s*(?:semanas?|weeks?)\\b/i.test((e.textContent||'').trim())
                && (e.textContent||'').trim().length < 25);
            if (dd) {
                (dd.closest('[class*=select i],[role=combobox]') || dd).click();
                return true;
            }
            return false;
        }""")
        if abierto:
            esperar(page, 0.8)
            click_8 = page.evaluate("""() => {
                const opts = [...document.querySelectorAll('li,[role=option],div,span')].filter(e =>
                    e.offsetParent && /\\b8\\s*(?:semanas?|weeks?)\\b/i.test((e.textContent||'').trim())
                    && (e.textContent||'').trim().length < 25);
                if (opts.length) {
                    opts[0].click();
                    return true;
                }
                return false;
            }""")
            reg.info(f"ONE rango semanas: {'8 semanas seleccionado ✓' if click_8 else 'no encontró opción 8 semanas'}")
            return click_8
    except Exception as e:
        reg.info(f"ONE set_weeks error: {e}")
    return False


# Elige el contrato de ONE en la lista abierta: el de la reserva, o «Otros contratos». Si no está ninguno,
# no pulsa nada y devuelve 'sin-contrato' (CICLO-clics-a-ciegas.md).
_JS_ONE_ELEGIR_CONTRATO = """(c) => {
    const portal = document.querySelector('[class*="mag-select__portal--isOpen-true"], [class*="ContractNoSelect_custom-select-dropdown"], [data-floating-ui-portal]');
    const scope = portal || document;
    const opts = [...scope.querySelectorAll('button[class*="mag-list-item"], button[class*="mag-select-option"], button, li, [role="option"]')]
        .filter(e => e.offsetParent && (e.textContent||'').trim().length > 1
                     && !e.closest('[class*=pattern i], [class*=card i], [class*=frequent i]'));
    if (!opts.length) return false;
    let el = c ? opts.find(o => (o.textContent||'').toUpperCase().includes(c.toUpperCase())) : null;
    if (el) { el.click(); return 'match'; }
    let otros = opts.find(o => /otros contratos|other contracts/i.test((o.textContent||'').trim()));
    if (otros) { otros.click(); return 'otros'; }
    // Hasta 83067a1 elegía aquí la primera opción de la lista, fuera el contrato que fuera.
    return 'sin-contrato';
}"""


def _set_contract(page, contrato, reg):
    """Abre el desplegable 'Contract No.' y elige el contrato. Si no aparece en la lista, elige 'Otros Contratos' y digita el código."""
    abierto = False
    try:
        abierto = bool(page.evaluate("""() => {
            const lab = [...document.querySelectorAll('*')].find(e =>
                /contract no|contract|contrato/i.test((e.textContent||'').trim())
                && (e.textContent||'').trim().length < 20 && e.offsetParent);
            let cont = lab ? lab.parentElement : null;
            for (let k=0; k<4 && cont; k++) {
                const dd = [...cont.querySelectorAll('*')].find(e =>
                    /^\\s*(select|seleccionar)\\s*$/i.test((e.textContent||'').trim()) && e.offsetParent);
                if (dd) { (dd.closest('[class*=select i]') || dd).click(); return true; }
                cont = cont.parentElement;
            }
            return false;
        }"""))
    except Exception:
        pass
    if not abierto:
        reg.info("contrato: no abrí el desplegable (¿ruta aún inválida?)"); return
    esperar(page, 1.2)
    try:
        elegido = page.evaluate(_JS_ONE_ELEGIR_CONTRATO, contrato)
        if elegido == "sin-contrato":
            raise ObjetivoNoEncontrado("Contrato de ONE", f"el contrato «{contrato}» ni «Otros contratos» en la "
                                                          f"lista")
        reg.info(f"contrato ONE: resultado selección '{elegido}'")
        esperar(page, 1.0)
        if elegido == 'otros' and contrato:
            # El campo que aparece junto a 'Other Contracts' tiene name="contractNo". Hasta 83067a1, sin él,
            # escribía en el primer campo de texto del formulario.
            inp = page.locator('input[name="contractNo"]').first
            if not inp.count():
                raise ObjetivoNoEncontrado("Contrato de ONE", "el campo del contrato (name «contractNo») junto a "
                                                              "«Otros contratos»")
            try:
                inp.click(timeout=3000)
                inp.fill(contrato, timeout=3000)
                page.keyboard.press("Tab")
                reg.info(f"contrato ONE: escrito '{contrato}' en Otros Contratos ✓")
            except Exception as e:
                reg.info(f"contrato ONE: error campo texto: {e}")
    except Exception as e:
        reg.info(f"contrato: {e}")


def _abrir_dropdown_por_texto(page, regex_actual):
    """Abre un desplegable custom identificándolo por su texto actual (ej 'Dry/General', 'Select')."""
    return page.evaluate("""(rx) => {
        const re = new RegExp(rx, 'i');
        const el = [...document.querySelectorAll('div,span,input')]
            .find(e => e.offsetParent && re.test((e.textContent||e.value||'').trim())
                       && (e.textContent||e.value||'').trim().length < 20);
        if (el) { (el.closest('[class*=select i],[class*=Select]') || el).click(); return true; }
        return false;
    }""", regex_actual)


def _click_opcion(page, regex_opcion):
    """Clic en la opción visible de un desplegable abierto cuyo texto matchee."""
    return page.evaluate("""(rx) => {
        const re = new RegExp(rx, 'i');
        const sel = 'li,[role=option],.ant-select-item,.el-select-dropdown__item,.rc-virtual-list-holder-inner > div,div,span';
        const opt = [...document.querySelectorAll(sel)]
            .filter(e => e.offsetParent)
            .find(e => re.test((e.textContent||'').trim()));
        if (opt) { opt.click(); return true; }
        return false;
    }""", regex_opcion)


# Abre un mag-select de ONE: desde su <label> exacto sube hasta el botón trigger del campo
_JS_ONE_OPEN_DD = """(lab) => {
    const norm = s => (s||'').replace(/\\*/g,'').replace(/\\s+/g,' ').trim().toLowerCase();
    const L = norm(lab);
    const labels = [...document.querySelectorAll('label')]
        .filter(e => e.offsetParent && norm(e.textContent) === L);
    labels.sort((a,b) => (a.textContent||'').length - (b.textContent||'').length);
    const label = labels[0];
    if (!label) return 'no-label';
    let cont = label.parentElement;
    for (let k=0; k<5 && cont; k++) {
        const trig = cont.querySelector(
            'button.mag-select__trigger,[class*=mag-select__trigger],[role=combobox]');
        if (trig && trig.offsetParent) { trig.scrollIntoView({block:'center'}); trig.click(); return 'opened'; }
        cont = cont.parentElement;
    }
    return 'no-trigger';
}"""

# Vuelca las opciones visibles (hojas) de un desplegable abierto (diagnóstico)
_JS_DD_OPCIONES = """() => {
    const sel = '[role=option],li,[class*=option i],[class*=item i],[class*=menu i] *,[class*=list i] *,[class*=dropdown i] *';
    const set = new Set();
    [...document.querySelectorAll(sel)].forEach(e => {
        if (!e.offsetParent || e.children.length>0) return;
        const t = (e.textContent||'').trim();
        if (t.length>0 && t.length<28) set.add(t);
    });
    return [...set].slice(0,30).join(' | ');
}"""

# Clic en la opción cuyo texto (hoja) sea EXACTAMENTE el buscado (evita agarrar el contenedor)
_JS_CLICK_OPTION_EXACT = """(txt) => {
    const T = txt.replace(/\\s+/g,' ').trim().toUpperCase();
    const els = [...document.querySelectorAll('[role=option],li,[class*=option i],[class*=item i],[class*=dropdown i] *,div,span,p')]
        .filter(e => e.offsetParent && e.children.length===0
                     && (e.textContent||'').replace(/\\s+/g,' ').trim().toUpperCase() === T);
    if (!els.length) return false;
    const target = els[0].closest('li,[role=option],[class*=item i],[class*=option i]') || els[0];
    target.scrollIntoView({block:'center'}); target.click();
    return true;
}"""


# Conjunto de textos-hoja cortos visibles (para descubrir opciones por diferencia)
_JS_LEAF_SET = """() => {
    const set = new Set();
    document.querySelectorAll('*').forEach(e => {
        if (!e.offsetParent || e.children.length>0) return;
        const t = (e.textContent||'').replace(/\\s+/g,' ').trim();
        if (t.length>0 && t.length<28) set.add(t);
    });
    return [...set];
}"""


_JS_HTML_CAMPO = """(lab) => {
    const norm = s => (s||'').replace(/\\*/g,'').replace(/\\s+/g,' ').trim().toLowerCase();
    const L = norm(lab);
    const cands = [...document.querySelectorAll('label,span,div,p')].filter(e =>
        e.offsetParent && norm(e.textContent) === L);
    cands.sort((a,b) => (a.textContent||'').length - (b.textContent||'').length);
    const label = cands[0];
    if (!label) return 'no-label';
    // subir hasta un contenedor que tenga input o control select
    let cont = label.parentElement;
    for (let k=0; k<4 && cont; k++) {
        if (cont.querySelector('input,select,[class*=select i],[role=combobox]')) break;
        cont = cont.parentElement;
    }
    if (!cont) return 'no-cont';
    return cont.outerHTML.replace(/\\s+/g,' ').slice(0, 700);
}"""


def _dump_html_campo(page, etiqueta, reg):
    try:
        html = str(page.evaluate(_JS_HTML_CAMPO, etiqueta))
    except Exception as e:
        html = f"err {str(e)[:60]}"
    reg.info(f"HTML[{etiqueta}]: {html}")


def _one_descubrir(page, etiqueta_exacta, reg, nombre):
    """Abre un desplegable y registra SOLO las opciones nuevas (diferencia de textos)."""
    try:
        antes = set(page.evaluate(_JS_LEAF_SET))
    except Exception:
        antes = set()
    estado = "?"
    try:
        estado = str(page.evaluate(_JS_ONE_OPEN_DD, etiqueta_exacta))
    except Exception as e:
        estado = f"err {str(e)[:40]}"
    esperar(page, 1.3)
    try:
        despues = set(page.evaluate(_JS_LEAF_SET))
    except Exception:
        despues = set()
    nuevas = sorted(despues - antes)
    reg.info(f"DESCUBRIR {nombre} ({etiqueta_exacta}) [{estado}]: {nuevas}")
    try: page.keyboard.press("Escape")
    except Exception: pass
    esperar(page, 0.5)


def _one_dropdown(page, etiqueta_exacta, opciones_candidatas, reg, nombre):
    """Abre el desplegable de ONE por etiqueta exacta y clica la 1ª opción candidata que exista.
       'opciones_candidatas' es una lista de textos EXACTOS a probar en orden."""
    estado = "?"
    try:
        estado = str(page.evaluate(_JS_ONE_OPEN_DD, etiqueta_exacta))
    except Exception as e:
        estado = f"err {str(e)[:50]}"
    if not estado.startswith("opened"):
        reg.info(f"{nombre}: no abrí el desplegable ({estado})")
        return False
    esperar(page, 1.3)
    if os.environ.get("AQUASHIELD_DESCUBRIR"):
        try:
            reg.info(f"{nombre}: opciones=[{page.evaluate(_JS_DD_OPCIONES)}]")
        except Exception:
            pass
    elegido = None
    for cand in opciones_candidatas:
        try:
            if bool(page.evaluate(_JS_CLICK_OPTION_EXACT, cand)):
                elegido = cand; break
        except Exception:
            pass
    reg.info(f"{nombre} -> {elegido if elegido else 'NINGUNA de '+str(opciones_candidatas)}")
    esperar(page, 0.8)
    return bool(elegido)


_JS_DUMP_CARGA = """() => {
    const vis = e => { const r = e.getBoundingClientRect();
        return e.offsetParent && r.width>0 && r.height>0; };
    const out = [];
    // 1) inputs
    document.querySelectorAll('input').forEach((i,idx) => {
        if (!vis(i)) return;
        const r = i.getBoundingClientRect();
        out.push('INPUT#'+idx+' ph="'+(i.placeholder||'')+'" val="'+(i.value||'')+'" type='+(i.type||'')+' top='+Math.round(r.top));
    });
    // 2) selects nativos
    document.querySelectorAll('select').forEach((s,idx) => {
        if (!vis(s)) return;
        const ops = [...s.options].slice(0,12).map(o=>o.textContent.trim()).join(' | ');
        out.push('SELECT#'+idx+' val="'+(s.value||'')+'" ops=['+ops+']');
    });
    // 3) posibles desplegables custom (combobox / .select con texto tipo 'Select')
    document.querySelectorAll('[role=combobox],[class*=select i],[class*=dropdown i]').forEach((d,idx) => {
        if (!vis(d)) return;
        const t = (d.textContent||'').trim().slice(0,40);
        if (t.length>0 && t.length<40) out.push('DDOWN#'+idx+' txt="'+t+'"');
    });
    // 4) etiquetas cortas visibles (para mapear labels)
    const labs = [];
    document.querySelectorAll('label,span,div,p').forEach(e => {
        if (!vis(e)) return;
        const t = (e.textContent||'').trim();
        if (t.length>2 && t.length<32 && e.children.length===0) labs.push(t);
    });
    out.push('LABELS=['+[...new Set(labs)].slice(0,40).join(' ~ ')+']');
    return out.join('\\n');
}"""


def _dump_carga(page, reg):
    if not os.environ.get("AQUASHIELD_DESCUBRIR"):
        return   # diagnóstico sólo en modo afinamiento
    try:
        info = page.evaluate(_JS_DUMP_CARGA)
        reg.info("---- DOM carga ----")
        for linea in str(info).split("\n"):
            reg.info(linea)
        reg.info("---- fin DOM ----")
    except Exception as e:
        reg.info(f"dump carga error: {str(e)[:80]}")


def _one_esta_en_paso(page, paso):
    url = page.url or ""
    if f"step={paso}" in url:
        return True
    try:
        data = page.evaluate("""() => {
            const body = (document.body ? document.body.innerText : '').toLowerCase();
            return body.slice(0, 8000);
        }""")
        if paso == "booking-parties":
            return "booking requester" in data or "booking parties" in data
        elif paso == "container-cargo-details":
            return "total estimated cargo weight" in data or "commodity" in data
        elif paso == "additional-information":
            return "manual booking number" in data or "booking shipper ref. no." in data
        elif paso == "review-booking":
            return "review booking" in data and ("submit" in data or "booking details" in data or "booking submission summary" in data)
    except Exception:
        pass
    return False


def _one_esperar_sin_spinner(page, reg, seg=15):
    """Espera a que desaparezca cualquier spinner u overlay 'In progress...'."""
    import time as _t
    t0 = _t.time()
    while _t.time() - t0 < seg:
        try:
            spin = page.evaluate("""() => {
                const els = [...document.querySelectorAll('*')].filter(e => {
                    const t = (e.textContent || '').trim();
                    const cls = typeof e.className === 'string' ? e.className : '';
                    return (t === 'In progress...' || /loading-indicator|mag-loading/i.test(cls))
                           && e.offsetParent !== null;
                });
                return els.length > 0;
            }""")
            if not spin:
                return True
        except Exception:
            pass
        esperar(page, 0.4)
    return False


def _one_esperar_paso(page, paso, seg, reg, minimo=0.4):
    """Espera que el asistente de ONE llegue a 'paso', comprobando URL y DOM,
    y asegurando que los spinners hayan desaparecido."""
    import time as _t
    t0 = _t.time()
    if minimo:
        esperar(page, minimo)
    while _t.time() - t0 < seg:
        _cerrar_modal_one(page, reg)
        if _one_esta_en_paso(page, paso):
            _one_esperar_sin_spinner(page, reg, seg=8)
            reg.info(f"paso: {paso} ({_t.time() - t0:.1f}s)")
            return True
        esperar(page, 0.6)
    actual = ""
    try:
        actual = page.url.split("step=")[-1][:30]
    except Exception:
        pass
    reg.info(f"NO llegué a '{paso}' en {seg:.0f}s (URL dice '{actual}')")
    return False


def _one_click_search(page, reg):
    """Clica el botón Search del formulario de Quick Booking, evitando el Search del header global."""
    try:
        resultado = page.evaluate("""() => {
            // 1. Selector directo por data-booking-name oficial de ONE
            const btnData = document.querySelector('button[data-booking-name="SEARCH_SCHEDULE_BUTTON"]');
            if (btnData && btnData.offsetParent) {
                btnData.scrollIntoView({block: 'center'});
                btnData.click();
                return 'data-booking-name';
            }
            // 2. Buscar dentro del contenedor de acciones del formulario (SearchScheduleAction)
            const cont = document.querySelector('[class*="SearchScheduleAction"], [class*="searchScheduleAction"]');
            if (cont) {
                const btn = [...cont.querySelectorAll('button')].find(b =>
                    b.offsetParent && /^\\s*search\\s*$/i.test((b.textContent || '').trim()));
                if (btn) {
                    btn.scrollIntoView({block: 'center'});
                    btn.click();
                    return 'container-search';
                }
            }
            // 3. Buscar como hermano del botón Reset
            const resetBtn = [...document.querySelectorAll('button')].find(b =>
                b.offsetParent && /^\\s*reset\\s*$/i.test((b.textContent || '').trim()));
            if (resetBtn && resetBtn.parentElement) {
                const sBtn = [...resetBtn.parentElement.querySelectorAll('button')].find(b =>
                    /search|buscar/i.test((b.textContent || '').trim()));
                if (sBtn && sBtn.offsetParent) {
                    sBtn.scrollIntoView({block: 'center'});
                    sBtn.click();
                    return 'reset-sibling';
                }
            }
            // 4. Buscar cualquier botón con texto Search/Buscar fuera de header y nav
            const allBtns = [...document.querySelectorAll('button, input[type=submit]')].filter(b => {
                if (!b.offsetParent) return false;
                if (b.closest('header, nav, [class*="header" i], [class*="nav" i], [role="navigation"]')) return false;
                return /^\\s*(search|buscar)\\s*$/i.test((b.textContent || b.value || '').trim());
            });
            if (allBtns.length) {
                allBtns[0].scrollIntoView({block: 'center'});
                allBtns[0].click();
                return 'fallback-non-header';
            }
            return false;
        }""")
        reg.info(f"botón Search: {resultado if resultado else 'NO encontrado'}")
        return bool(resultado)
    except Exception as e:
        reg.info(f"error al clicar Search en ONE: {e}")
        return False


# Las tarjetas de itinerario de ONE: cada resultado es un div con la clase ResultCard_card__<sufijo>, 32 en la corrida
# del 2026-09-25 (CICLO-cola-cuatro-items.md). Hasta e16beb6 la espera buscaba «mag-card, [class*=schedule],
# [class*=result], [data-booking-step]», y Playwright solo mira el primer elemento que calza: era la lista vacía del
# autocompletado de puertos (SearchMenu_search-menu-result), que nunca se ve, así que vencía siempre (7 de 7 en logs/).
_ONE_TARJETAS = "[class*='ResultCard_card']"


def _one_esperar_resultados(page, reg, seg=8):
    """Espera las tarjetas de itinerario de ONE (_ONE_TARJETAS) y dice lo que pasó: cuántas llegaron a la vista o, si
    vence, si no llegó ninguna o si llegaron y la primera no se ve. Solo lee: ni clics ni teclas."""
    dt = esperar_hasta(page, _ONE_TARJETAS, seg, asentar=0.4)
    try:
        tarjetas = page.locator(_ONE_TARJETAS)
        n = tarjetas.count()
        vista = bool(n) and tarjetas.first.is_visible()
    except Exception:
        n, vista = 0, False
    if vista:
        reg.info(f"itinerarios: {n} tarjeta(s) a la vista ({dt:.1f}s)")
    elif n:
        reg.paso(f"⚠ ONE: en {dt:.0f} s llegaron {n} tarjeta(s) de itinerario, pero la primera no se ve. Busco la nave "
                 f"igual.")
    else:
        reg.paso(f"⚠ ONE: en {dt:.0f} s no apareció ninguna tarjeta de itinerario. Busco la nave igual.")
    return vista


def _one_detenida(page, reg, fila):
    """ONE se detuvo sin llegar a Review Booking (la nave no está o el asistente quedó en otro paso): deja la
    captura y el HTML de esa pantalla (one_f<fila>_detenida) con el mecanismo de la guarda, sin clics ni esperas.
    Hasta 456a758 esos REVISAR quedaban solo con capturas (CICLO-cola-nueve-items.md)."""
    _evidencia_antes_de_la_guarda(page, reg, f"one_f{fila}_detenida", "donde se detuvo", completa=False)


def _one_salidas(tarjetas):
    """[(salida como datetime.date, o None si no se puede leer, tarjeta)] de las que lee _JS_ONE_TARJETAS_NAVE."""
    out = []
    for t in tarjetas:
        try:
            d = datetime.date.fromisoformat(t.get("salida") or "")
        except ValueError:
            d = None
        out.append((d, t))
    return out


def _one_transito(tarjeta):
    """El tiempo de tránsito de una tarjeta de ONE: su llegada menos su salida, las dos fechas textStyle-h5 que lee
    _JS_ONE_TARJETAS_NAVE (CICLO-cola-tres-items.md). Medido en las 32 tarjetas del 2026-09-25: es el «N day(s)» que
    muestra la tarjeta. None si no trae las dos o si la llegada no es posterior."""
    llegada, salida = (str(tarjeta.get(k) or "") for k in ("llegada", "salida"))
    try:
        tiempo = datetime.date.fromisoformat(llegada) - datetime.date.fromisoformat(salida)
    except ValueError:
        return None
    return tiempo if tiempo.days > 0 else None


def _one_sin_una_salida(page, reg, reserva, tarjetas, motivo, desde):
    """No queda una sola tarjeta de ONE para la nave de la fila (_proxima_salida): no se elige ninguna. Deja la evidencia
    de la lista donde se detuvo (_one_detenida), sin clics ni esperas, y la reserva queda NO ENVIADA con el motivo
    (CICLO-proxima-salida.md)."""
    reg.info("tarjetas que calzan: " + " | ".join(f"{t.get('nave')} sale {t.get('salida')}" for t in tarjetas[:6])[:400])
    _one_detenida(page, reg, reserva["fila"])
    por_que = _por_que_sin_salida(motivo, _one_salidas(tarjetas), desde, _one_transito)
    return _no_enviada(reg, f"ONE: no elegí salida para esa nave ('{reserva['nave']}'): {por_que}. Revisa la fila y "
                            f"elige la salida en el portal.")


# El «Next» del asistente de ONE (Booking Parties, Container & Cargo y Additional Information): el único botón a la
# vista, fuera del encabezado y de la navegación, cuyo texto es exactamente «Next» o «Siguiente» (sin espacios en los
# extremos y sin distinguir mayúsculas). Medido con OCR, sin mirar las imágenes, en las capturas de las 5 reservas del
# 2026-09-21 que recorrieron el asistente (one_f<fila>_6_parties, _8_carga y _9_adicional): en cada paso, el único
# botón de color con etiqueta dice «Next»; en Additional Information, en las 2 capturas donde se ve el pie de la
# pantalla (en las otras 3 no se ve). No hay HTML de esas pantallas (CICLO-cola-seis-items.md). Si un «Next» está en
# una ventana emergente (el mismo selector de _JS_ONE_CERRAR_MODAL), como el de «Vessel Information», que lleva a elegir
# otra nave, no pulsa nada y devuelve -1. Si no hay uno solo, no pulsa nada y devuelve cuántos había.
_JS_ONE_SIGUIENTE = """() => {
    const vis = e => {
        const r = e.getBoundingClientRect();
        return e.offsetParent !== null && r.width > 0 && r.height > 0;
    };
    const botones = [...document.querySelectorAll('button,a,input[type=submit]')]
        .filter(b => !b.closest('header, nav, [role="navigation"]') && vis(b))
        .filter(b => /^(next|siguiente)$/i.test((b.textContent || b.value || '').trim()));
    const dialogo = '[class*=dialog__overlay],[id^=dialog-portal] [role=dialog],[role=dialog]';
    if (botones.some(b => b.closest(dialogo))) return -1;
    if (botones.length !== 1) return botones.length;
    botones[0].scrollIntoView({block: 'center'});
    botones[0].click();
    return 1;
}"""


def _one_siguiente(page, reg, pantalla, paso):
    """Pulsa el «Next» de esa pantalla del asistente de ONE (_JS_ONE_SIGUIENTE), con hasta 3 intentos mientras no hay
    ninguno a la vista. Antes comprueba que el asistente esté en ese paso (_one_esta_en_paso): medido en los 5 recorridos
    del 2026-09-21, _one_esperar_paso lo confirmó en cada paso. Si no está en el paso, si el «Next» está en una ventana
    emergente, o si no hay uno solo, levanta ObjetivoNoEncontrado sin pulsar nada: la reserva queda NO ENVIADA, con la
    captura y el HTML de esa pantalla (decisión de Marcelo, CICLO-cola-seis-items.md). Si la búsqueda misma falla, corta
    sin reintentar, porque el clic pudo haber salido: hasta f68ce6c ese error dejaba la reserva en ERROR. Hasta f68ce6c pulsaba con
    _JS_CLICK_BTN el primero, en el orden de la página, cuyo texto fuera Next, Siguiente, Continue o Continuar (en
    Additional Information, también Review o Revisar), estuviera a la vista o no, en la pantalla que fuera; y si no
    encontraba ninguno, lo anotaba y seguía."""
    objetivo = f"«Next» de {pantalla} en ONE"
    if not _one_esta_en_paso(page, paso):
        raise ObjetivoNoEncontrado(objetivo, f"la pantalla «{pantalla}»: el asistente no está en ella")
    n = 0
    for _ in range(3):
        try:
            n = int(page.evaluate(_JS_ONE_SIGUIENTE) or 0)
        except Exception as e:
            # Si la búsqueda falla, no se reintenta: el clic pudo haber salido y la pantalla, cambiado.
            raise ObjetivoNoEncontrado(objetivo,
                                       f"un solo botón «Next» a la vista (no pude buscarlo: {str(e)[:60]})")
        if n == 1:
            reg.info(f"{pantalla}: Next")
            return
        if n != 0:
            break
        esperar(page, 0.4)
    if n == -1:
        raise ObjetivoNoEncontrado(objetivo, "un «Next» fuera de una ventana emergente: la que está abierta trae el suyo")
    raise ObjetivoNoEncontrado(objetivo, f"un solo botón «Next» a la vista (había {n})")


# ONE busca solo las 8 semanas que pide la nota de la planilla, y no amplía (decisión de Marcelo,
# CICLO-ampliar-msc-y-cma.md): el REVISAR lo dice. Entre 05cfdb7 y el encargo 33 abría el selector «N weeks» y probaba
# una opción de más de 8 semanas (CICLO-ampliar-la-busqueda.md).
ONE_SOLO_8 = "no amplío más allá de las 8 semanas que pide la nota de la planilla"

# Las salidas de todas las tarjetas de ONE, para decir hasta qué fecha buscó: la primera fecha AAAA-MM-DD textStyle-h5
# de cada una, como en _JS_ONE_TARJETAS_NAVE, o '' si no la trae.
_JS_ONE_FECHAS = """() => [...document.querySelectorAll("[class*='ResultCard_card__']")].map(c =>
    [...c.querySelectorAll("[class*='textStyle-h5']")].map(e => (e.textContent||'').trim())
        .find(x => /^\\d{4}-\\d{2}-\\d{2}$/.test(x)) || '')"""


def _one_fechas(page):
    """Las salidas de todas las tarjetas de la lista (_JS_ONE_FECHAS), como datetime.date, o None si no se leen."""
    try:
        textos = page.evaluate(_JS_ONE_FECHAS) or []
    except Exception:
        textos = []
    return [d for d, _ in _one_salidas([{"salida": t} for t in textos])]


def _one_tarjetas(page, reg, nave):
    """Las tarjetas de la nave (_JS_ONE_TARJETAS_NAVE), con hasta 3 lecturas mientras no llega ninguna."""
    tarjetas = []
    for intento in range(3):
        try:
            tarjetas = page.evaluate(_JS_ONE_TARJETAS_NAVE, nave) or []
        except Exception as e:
            reg.info(f"error buscando nave: {e}")
        if tarjetas:
            break
        esperar(page, 0.8)
    return tarjetas


@_con_la_nave_de_la_fila
@_con_la_ruta_de_la_fila
@_sin_clic_a_ciegas("one")
def reservar_one(page, reserva, creds, reg, on_pausa=None):
    f = reserva["fila"]
    reg.paso(f"[fila {f}] {reserva['pol']} -> {reserva['destino_final']} | NAVE: {reserva['nave']}")
    _avisar_dia_carga(reserva, reg)

    page.goto("https://ecomm.one-line.com/one-ecom/booking/quick-booking?step=search-schedule",
              wait_until="domcontentloaded")
    esperar_hasta(page, "mag-autocomplete, input", 5, reg, "abrir Quick Booking", asentar=0.8)
    _cerrar_modal_one(page, reg)
    reg.captura(page, f"one_f{f}_1_form")

    # Origen y Destino (autocompletado con clic en la sugerencia), y antes de cada clic la evidencia de la lista
    # (decisión de Marcelo, CICLO-origen-y-destino.md)
    reg.paso("Cargando ruta...")
    # Sin una sugerencia elegida, NO ENVIADA: ninguna naviera sigue sin su origen o su destino (decisión de Marcelo,
    # encargo 42, CICLO-maersk-y-fila-sin-ruta.md). _fill_autocomplete ya cortaba si no veía ninguna; si fallaba al
    # escribir, la reserva seguía.
    if not _fill_port(page, "input[placeholder*='Origin' i], input[placeholder*='Origen' i]",
                      reserva["pol"], reg, "Origen", evidencia=f"one_f{f}_origen"):
        raise ObjetivoNoEncontrado("Origen de ONE", _sugerencia_que_elegir(reserva["pol"]))
    esperar(page, 0.3)
    dest = reserva["destino_final"] or reserva["destino_orig"]
    if not _fill_port(page, "input[placeholder*='Destination' i], input[placeholder*='Destino' i]",
                      dest, reg, "Destino", evidencia=f"one_f{f}_destino"):
        raise ObjetivoNoEncontrado("Destino de ONE", _sugerencia_que_elegir(dest))
    esperar(page, 0.3)
    reg.captura(page, f"one_f{f}_2_ruta")

    # Rango de semanas (Nota del Excel Agendamientos: 'DEBE SELECCIONAR SIEMPRE 8 SEMANAS')
    _set_weeks_one(page, "8 semanas", reg)
    esperar(page, 0.3)

    # Tipo de carga -> Reefer
    if _abrir_dropdown_por_texto(page, "dry/general|dry|seco|general"):
        esperar(page, 0.3)
        _click_opcion(page, "^reefer$|refriger")
        reg.info("tipo de carga: intento Reefer")
    else:
        reg.info("tipo de carga: no encontré el desplegable")

    # Contrato inteligente: USA u Otros Mercados (_determinar_contrato_one).
    contrato = _determinar_contrato_one(reserva, creds)
    _set_contract(page, contrato, reg)

    esperar(page, 0.3)
    _cerrar_modal_one(page, reg)
    reg.captura(page, f"one_f{f}_3_precarga")

    # Buscar (Search / Buscar)
    clic_buscar = _one_click_search(page, reg)
    reg.info(f"botón Search {'pulsado' if clic_buscar else 'NO encontrado'}")
    _one_esperar_resultados(page, reg)
    for _ in range(3):
        if _cerrar_modal_one(page, reg):
            esperar(page, 0.3)
        else:
            break
    reg.captura(page, f"one_f{f}_4_resultados")

    # Seleccionar la NAVE: entre sus tarjetas, la próxima salida (CICLO-proxima-salida.md), desde el día de carga si la
    # fila lo trae y es posterior, o desde hoy (_desde; decisión de Marcelo, CICLO-cola-siete-items.md). Hasta fc7de54,
    # ONE contaba siempre desde hoy.
    reg.paso(f"Buscando la nave '{reserva['nave']}' en los itinerarios...")
    tarjetas = _one_tarjetas(page, reg, reserva["nave"])
    # Solo las 8 semanas de la nota de la planilla: si la nave no está, el REVISAR dice hasta qué fecha buscó
    # (ONE_SOLO_8; decisión de Marcelo, CICLO-ampliar-msc-y-cma.md).
    hay_nave = bool(tarjetas)
    sin_boton = [t for t in tarjetas if t.get("botones") != 1]
    if sin_boton:
        reg.info(f"{len(sin_boton)} tarjeta(s) con la nave sin un solo botón de reserva: no cuentan")
    tarjetas = [t for t in tarjetas if t.get("botones") == 1]
    desde = _desde(reserva)
    # El día de la próxima salida, la directa; solo si ninguna lo es (o todas), el tránsito (decisión de Marcelo, la regla
    # de HYUNDAI; CICLO-one-y-maersk-eligen-la-nave.md). Hasta el encargo 34, la directa y la con transbordo del mismo
    # día y el mismo tránsito empataban, y la reserva quedaba NO ENVIADA.
    tarjetas = _directas_primero(tarjetas, desde, reg, _one_salidas)
    elegida, motivo = _proxima_salida(_one_salidas(tarjetas), desde, _one_transito) if tarjetas else (None, "")
    if tarjetas and elegida is None:
        return _one_sin_una_salida(page, reg, reserva, tarjetas, motivo, desde)
    seleccionada = False
    if elegida:
        if len(tarjetas) > 1:
            reg.info(f"{len(tarjetas)} tarjetas calzan con '{reserva['nave']}'; elijo la próxima salida desde el "
                     f"{desde:%d-%m-%Y}")
            _anotar_desempate(reg, _one_salidas(tarjetas), desde, _one_transito)
        try:
            seleccionada = bool(page.evaluate(_JS_ONE_CLIC_TARJETA, {"i": elegida["i"], "nave": reserva["nave"],
                                                                     "salida": elegida.get("salida", ""),
                                                                     "directa": elegida.get("directa")}))
            if not seleccionada:
                reg.info("no pulsé el botón de la tarjeta elegida: al volver a leer la lista, ya no estaba, no era la "
                         "misma o no traía un solo botón de reserva")
        except Exception as e:
            reg.info(f"error al seleccionar la nave: {e}")
        if seleccionada:
            reg.info(f"nave encontrada y seleccionada: {elegida.get('nave')}, sale {elegida.get('salida')}")

    esperar(page, 0.3)
    reg.url(page); reg.captura(page, f"one_f{f}_5_post_seleccion")

    if not seleccionada:
        _one_detenida(page, reg, f)
        reg.paso("NO encontré la nave por el nombre exacto. Revisa que la columna 'Nave' calce con el portal.")
        donde = "" if hay_nave else f": {_hasta_donde_busque(_one_fechas(page), ONE_SOLO_8)}"
        return ("REVISAR", f"nave '{reserva['nave']}' no encontrada{donde}")

    reg.paso("Nave seleccionada ✓. Avanzando por el asistente (sin emitir)...")
    
    # 1. Esperar a salir de search-schedule y llegar a booking-parties (o container-cargo-details)
    _one_esperar_paso(page, "booking-parties", 25, reg)
    _cerrar_modal_one(page, reg)

    # ---- Paso 2: Booking Parties (datos de AQUACHILE ya vienen precargados) ----
    if _one_esta_en_paso(page, "booking-parties"):
        reg.captura(page, f"one_f{f}_6_parties")
        esperar(page, 0.4)
        _one_siguiente(page, reg, "Booking Parties", "booking-parties")
        _one_esperar_paso(page, "container-cargo-details", 20, reg)
    else:
        reg.info("Booking Parties ya completado o saltado")

    _cerrar_modal_one(page, reg)
    reg.captura(page, f"one_f{f}_7_container", full=True)
    _dump_carga(page, reg)   # diagnóstico: estructura real del formulario

    # ---- Paso 3: Container & Cargo Detail ----
    # Datos inventados/por defecto (carga refrigerada de salmón)
    commodity = "SALMON"
    peso = _peso_reefer()
    grados = _temp_reserva(reserva)
    reg.paso("Paso 3 · Container & Cargo (datos de ejemplo, refrigerado)...")

    # Commodity (autocompletado igual que los puertos)
    _fill_autocomplete(page,
        "input[placeholder*='commodity' i], input[placeholder*='mercanc' i], "
        "input[placeholder*='Input and select' i]",
        commodity, reg, "Commodity")
    esperar(page, 0.3)

    # Peso estimado de la carga
    _fill_texto_por_label(page,
        "total estimated cargo weight|estimated cargo weight|cargo weight|peso",
        peso, reg, "Peso(KGS)")
    esperar(page, 0.2)

    # Tipo de contenedor: Type = REEFER  (esto despliega el panel Reefer)
    _one_dropdown(page, "Type", ["REEFER"], reg, "Type")
    esperar(page, 0.3)

    if os.environ.get("AQUASHIELD_DESCUBRIR"):
        # Descubrimiento: primero fijo Size (arriba), luego listo los del panel reefer
        _one_descubrir(page, "Size", reg, "Size-arriba")
        _one_dropdown(page, "Size", ["40FT High Cube", "40FT HIGH CUBE"], reg, "Size")
        esperar(page, 1.5)
        for etq, nom in [("Container Type/ Size", "ContTipoSize"),
                         ("Genset", "Genset"), ("Nature", "Nature")]:
            _one_descubrir(page, etq, reg, nom)
        reg.captura(page, f"one_f{f}_8_carga", full=True)
        return ("DESCUBRIR", "opciones listadas")

    # Tamaño (arriba): Size = 40FT High Cube  (habilita el panel reefer)
    _one_dropdown(page, "Size", ["40FT High Cube"], reg, "Size")
    esperar(page, 0.4)
    # Contenedor del panel reefer (una sola opción para REEFER + 40FT HC)
    _one_dropdown(page, "Container Type/ Size",
                  ["REEFER/ 40FT High Cube", "REEFER / 40FT High Cube"], reg, "ContTipoSize")
    esperar(page, 0.2)

    # Ventilación (input numérico obligatorio): 0  -- se llena ANTES que Degree
    _fill_input_por_label(page, "^ventilation$", "0", reg, "Ventilation")
    esperar(page, 0.15)
    # Temperatura del reefer (Degree) -- al final para que no la pise otro campo
    _fill_input_por_label(page, "^degree$", grados, reg, "Degree")
    esperar(page, 0.15)
    # Genset (obligatorio): No
    _one_dropdown(page, "Genset", ["No"], reg, "Genset")
    esperar(page, 0.15)
    # Nature (obligatorio): carga congelada
    _one_dropdown(page, "Nature", ["Frozen", "FROZEN", "Frozen Cargo", "Chilled"], reg, "Nature")
    esperar(page, 0.2)
    _cerrar_modal_one(page, reg)
    reg.captura(page, f"one_f{f}_8_carga", full=True)
    _dump_carga(page, reg)   # diagnóstico: estado tras llenar

    # ---- Paso 3 -> 4: Additional Information ----
    _one_siguiente(page, reg, "Container & Cargo", "container-cargo-details")
    _one_esperar_paso(page, "additional-information", 20, reg)
    _cerrar_modal_one(page, reg)
    reg.captura(page, f"one_f{f}_9_adicional")

    # ---- Paso 4 -> 5: Review Booking (SIN emitir) ----
    _one_siguiente(page, reg, "Additional Info", "additional-information")
    _one_esperar_paso(page, "review-booking", 20, reg)
    _cerrar_modal_one(page, reg)
    reg.captura(page, f"one_f{f}_10_review")

    reg.url(page)
    if _one_esta_en_paso(page, "review-booking"):
        _evidencia_antes_de_la_guarda(page, reg, f"one_f{f}_guarda")
        if not es_modo_emision():
            reg.paso("Me DETENGO en Review Booking (NO se pulsa Submit / Emitir).")
            return ("OK-EJEMPLO", "reserva de ejemplo armada hasta Review; SIN emitir")

        # MODO EMISIÓN REAL
        reg.paso("🔴 MODO EMISIÓN REAL: Pulsando 'Submit' en ONE...")
        pulsado, error = None, None
        try:
            page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
            esperar(page, 0.8)
            pulsado = _pulsar_boton(page, "button:has-text('Submit'), button:has-text('Enviar'), button[type='submit']",
                                    _JS_CLICK_BTN, "^(submit|enviar|submit booking)$")
            esperar(page, 4.0)
            _cerrar_modal_one(page, reg, antes_de_la_guarda=False)
        except Exception as e:
            error = e
        return _resultado_envio(page, reg, "one", "ONE", f"one_f{f}_11_confirmado", "Submit", pulsado, error)
    else:
        _one_detenida(page, reg, f)
        actual = page.url.split("step=")[-1][:30] if "step=" in (page.url or "") else page.url
        reg.paso(f"NO se completó el flujo: el asistente quedó en '{actual}' en lugar de review-booking.")
        return ("REVISAR", f"asistente ONE no llegó a review-booking (quedó en: {actual})")


