def _guardar_html(page, nombre, reg):
    try:
        html = page.content()
        with open(BASE / nombre, "w", encoding="utf-8") as fh:
            fh.write(html)
        reg.info(f"HTML guardado en {nombre} ({len(html)} chars)")
    except Exception as e:
        reg.info(f"no pude guardar {nombre}: {str(e)[:70]}")


_JS_LINKS_BOOKING = """() => {
    const out = [];
    document.querySelectorAll('a,button,[role=button]').forEach(e => {
        if (!e.offsetParent) return;
        const t = (e.textContent||'').replace(/\\s+/g,' ').trim();
        const href = e.getAttribute('href')||'';
        if (/book|booking|reserva|new booking|create/i.test(t+' '+href) && t.length<40)
            out.push(t + (href ? ' -> '+href : ''));
    });
    return [...new Set(out)].slice(0,25).join('\\n');
}"""


# Cuenta cuántos itinerarios (botones Select) hay cargados
_JS_MSC_COUNT_SCHED = """()=>[...document.querySelectorAll('button,a')]
    .filter(b=>/^\\s*select\\s*$/i.test((b.textContent||'').trim()) && b.offsetParent).length"""

# Lista los "Vessel / Voyage" visibles (diagnóstico)
_JS_MSC_LISTA_NAVES = """()=>{
    const set=new Set();
    document.querySelectorAll('*').forEach(e=>{
        if(!e.offsetParent||e.children.length>0)return;
        const t=(e.textContent||'').replace(/\\s+/g,' ').trim();
        if(/^[A-Z][A-Z0-9 .'\\-]{3,30}\\/\\s*[A-Z0-9]{3,10}$/.test(t)) set.add(t);
    });
    return [...set].slice(0,40).join(' | ');
}"""

# Selecciona el itinerario cuya "Vessel / Voyage" calce con la nave de la planilla
_JS_MSC_NAVES = """()=>{
    // Cada itinerario es un div.shipment-grid-list con su propio boton 'Select'.
    // Antes se subia por los ancestros buscando el nombre de la nave y se
    // terminaba leyendo el contenedor de TODA la lista: cualquier boton
    // "coincidia" y se elegia el primero. Ahora cada tarjeta se lee sola.
    const norm=s=>(s||'').toUpperCase().replace(/[\\/]/g,' ').replace(/\\s+/g,' ').trim();
    const cards=[...document.querySelectorAll('div.shipment-grid-list')];
    return cards.map((c,i)=>{
        const t=norm(c.textContent);
        const m=t.match(/VESSEL VOYAGE (.{3,40}?) ETD/);
        const b=[...c.querySelectorAll('button,a')]
            .find(x=>/^\\s*select\\s*$/i.test((x.textContent||'').trim()));
        const e=t.match(/ETD ([0-9]{2} [A-Z]{3} [0-9]{4})/);
        const etas=t.match(/ETA [0-9]{2} [A-Z]{3} [0-9]{4}/g) || [];
        // Sin «Vessel / Voyage» no hay nave que comparar: hasta a198645 tomaba los primeros 40 caracteres de la tarjeta
        // (CICLO-solo-la-nave-pedida.md). Las 79 tarjetas guardadas lo traen.
        return {i:i, nave:(m?m[1]:'').trim(), etd:(e?e[1]:''),
                eta:(etas.length === 1 ? etas[0].slice(4) : ''),
                sel:!!(b && b.offsetParent)};
    });
}"""

_JS_MSC_CLIC_NAVE = """(i)=>{
    const cards=[...document.querySelectorAll('div.shipment-grid-list')];
    const c=cards[i]; if(!c) return false;
    const b=[...c.querySelectorAll('button,a')]
        .find(x=>/^\\s*select\\s*$/i.test((x.textContent||'').trim()));
    if(!b) return false;
    b.scrollIntoView({block:'center'}); b.click(); return true;
}"""

# MSC no tiene botón de ampliar: las demás naves aparecen al bajar por la lista (decisión de Marcelo,
# CICLO-ampliar-msc-y-cma.md). _JS_MSC_BAJAR baja por ella, sin pulsar nada: lleva al final cada ancestro de las
# tarjetas que tenga desplazamiento, y la ventana. Devuelve cuántas tarjetas había (0: no encontró la lista). Medido en
# los log.txt del 21 al 26-09: al cargar, la lista ya traía 25 a 27 itinerarios con su «Select» a la vista, aunque en
# pantalla se vean 4 o 5; si al bajar llegan más, no está medido. MSC_ESPERA_MAS: los segundos que se esperan tarjetas
# nuevas después de bajar (hipótesis).
MSC_ESPERA_MAS = 15
_JS_MSC_BAJAR = """()=>{
    const cards=[...document.querySelectorAll('div.shipment-grid-list')];
    if(!cards.length) return 0;
    for(let e=cards[0].parentElement; e; e=e.parentElement){
        if(e.scrollHeight>e.clientHeight) e.scrollTop=e.scrollHeight;
    }
    window.scrollTo(0, document.documentElement.scrollHeight);
    return cards.length;
}"""


def _msc_bajar(page, reg, antes):
    """Baja por la lista de itinerarios de MSC (_JS_MSC_BAJAR; no es un clic) y espera hasta MSC_ESPERA_MAS s a que haya
    más de 'antes' tarjetas con su «Select» a la vista (_JS_MSC_COUNT_SCHED). Devuelve "" si llegaron; si no, por qué,
    para _hasta_donde_busque: NO_AMPLIA_MAS si no llegó ninguna, o por qué no pudo bajar."""
    try:
        if not page.evaluate(_JS_MSC_BAJAR):
            return "no pude ampliar la búsqueda: no encontré la lista de itinerarios para bajar por ella"
    except Exception as e:
        return f"no pude ampliar la búsqueda: no pude bajar por la lista ({str(e)[:50]})"
    reg.info("bajo por la lista de itinerarios para que MSC cargue más")
    for _ in range(MSC_ESPERA_MAS):
        esperar(page, 1.0)
        try:
            n = int(page.evaluate(_JS_MSC_COUNT_SCHED))
        except Exception:
            n = 0
        if n > antes:
            reg.info(f"búsqueda ampliada: {antes} -> {n} itinerarios")
            return ""
    return NO_AMPLIA_MAS


# Pasos del asistente de MSC: pestanas Bootstrap con id fijo. La URL no cambia
# entre pasos, asi que esta es la unica senal fiable de que se avanzo.
_MSC_PASOS = {"shipping-rates-tab": "Base Information",
              "shipment-details-tab": "Route Details",
              "container-cargo-tab": "Container and Cargo",
              "parties-tab": "Parties",
              "summary-tab": "Summary"}

_JS_MSC_PASO = """()=>{
    const ids=['shipping-rates-tab','shipment-details-tab','container-cargo-tab',
               'parties-tab','summary-tab'];
    for(const id of ids){ const e=document.getElementById(id);
        if(e && e.classList.contains('active')) return id; }
    return '';
}"""


def _msc_paso_actual(page):
    try:
        return str(page.evaluate(_JS_MSC_PASO) or "")
    except Exception:
        return ""


def _msc_esperar_paso(page, tab, seg, reg, motivo="", minimo=0.6):
    """Espera a que la pestana indicada quede activa. Con piso minimo: al pulsar
    Next la pestana anterior sigue marcada un instante."""
    import time as _t
    t0 = _t.time()
    esperar(page, minimo)
    while _t.time() - t0 < seg:
        if _msc_paso_actual(page) == tab:
            reg.info(f"paso: {_MSC_PASOS.get(tab, tab)} ({_t.time() - t0:.1f}s)")
            return True
        esperar(page, 0.3)
    actual = _msc_paso_actual(page)
    reg.info(f"NO llegue a {_MSC_PASOS.get(tab, tab)} en {seg:.0f}s "
             f"(sigue en '{_MSC_PASOS.get(actual, actual or '?')}')")
    return False


def _msc_puerto(page, name, ciudad, reg, etiqueta, evidencia=""):
    """Escribe la ciudad en un autocompletado de puerto de MSC y elige la sugerencia. Si ninguna dice la ciudad, no
    pulsa nada y corta la reserva (ObjetivoNoEncontrado): hasta fb63271 elegía con el teclado la que quedara
    primera (CICLO-cola-nueve-items.md).
    Con 'evidencia' (el puerto de carga y el de descarga), antes de pulsarla deja con ese nombre la captura de la
    ventana y el HTML de la página y de sus marcos, con la lista: el mismo JavaScript, sin pulsar, dice si hay una que
    pulsaría (decisión de Marcelo, CICLO-origen-y-destino.md); y después del clic, _avisar_lista_distinta.
    Sin una palabra antes de la primera coma (_ciudad_de: vacío, «-», «X») no escribe ni pulsa nada: corta
    (_TEXTO_DE_LA_FILA; encargo 42), porque calzaba con cualquier sugerencia que lo trajera."""
    if not _ciudad_de(ciudad):
        raise ObjetivoNoEncontrado(f"{etiqueta} de MSC", _TEXTO_DE_LA_FILA)
    # [ciudad, pulsar]: pulsa solo con pulsar en true; con false, solo dice cuál pulsaría ('' si ninguna).
    js = """(args)=>{
        const [city, pulsar]=args;
        const C=city.toUpperCase();
        const items=[...document.querySelectorAll('li,[role=option],[class*=autocomplete i] *,[class*=result i],[class*=suggest i],[class*=item i],ul li,a')]
          .filter(e=>e.offsetParent && (e.textContent||'').toUpperCase().includes(C)
                     && (e.textContent||'').trim().length<70 && e.children.length<=3);
        items.sort((a,b)=>(a.textContent||'').length-(b.textContent||'').length);
        if(items.length){ if(pulsar===true) items[0].click(); return (items[0].textContent||'').trim().slice(0,45);}
        return '';
    }"""
    try:
        inp = page.locator(f"input[name='{name}']").first
        inp.wait_for(state="visible", timeout=8000)
        inp.click()
        try: inp.fill("")
        except Exception: pass
        inp.type(ciudad, delay=90)
        picked, vista = "", ""
        pendiente = bool(evidencia)
        for _ in range(8):     # sondea hasta ~3.2s
            esperar(page, 0.4)
            if pendiente:
                vista = " ".join(str(_sugerencia_sin_pulsar(page, js, [ciudad])).split())
                if vista:
                    _evidencia_antes_de_la_guarda(page, reg, evidencia, f"con las sugerencias de {etiqueta}",
                                                  completa=False)
                    pendiente = False
            try:
                picked = str(page.evaluate(js, [ciudad, True]))
            except Exception:
                pass
            if picked:
                break
        if not picked:
            if pendiente:
                _evidencia_sin_sugerencia(page, reg, evidencia, etiqueta)
            raise ObjetivoNoEncontrado(f"{etiqueta} de MSC", f"la sugerencia que dice «{ciudad}» entre las que ofrece "
                                                             f"el portal")
        reg.info(f"{etiqueta} '{ciudad}': {picked}")
        _avisar_lista_distinta(reg, etiqueta, evidencia, vista, " ".join(picked.split()), pendiente)
        esperar(page, 0.6)
        return True
    except Exception as e:
        reg.info(f"{etiqueta}: {str(e)[:70]}")
        return False


def _msc_fecha(page, iso, reg):
    """Fija la fecha de Sailing Schedule usando la API del datepicker Kendo."""
    try:
        r = str(page.evaluate("""(iso)=>{
            const parts = iso.split('-').map(Number);
            const d = new Date(parts[0], parts[1]-1, parts[2]);
            try {
                if (window.jQuery) {
                    const $i = jQuery('#ScheduleCharge_Schedule_SailingDate, input[name="SailingDate-input"]').first();
                    const w = $i.data('kendoDatePicker');
                    if (w) { w.value(d); w.trigger('change'); $i.trigger('change'); return 'kendo-ok'; }
                }
            } catch(e){ return 'err:'+e.message; }
            return 'no-widget';
        }""", iso))
        reg.info(f"Sailing date '{iso}': {r}")
        return r.endswith("ok")
    except Exception as e:
        reg.info(f"fecha: {str(e)[:60]}")
        return False


def _msc_desde(reserva):
    """El día desde el que MSC busca (Sailing Schedule) y elige la salida (_desde): hoy, o el día de carga de la fila si lo
    trae y es posterior, y si no lo trae, el de retiro. Hasta 384d3ce era hoy + 18 cuando la fila no traía fecha o la
    traía pasada o a 2 días. Ese número no tenía registro, y el portal no lo exige: su campo viene con la fecha de hoy,
    sin mínimo, y la búsqueda lista salidas desde 2 días (CICLO-proxima-salida.md)."""
    return _desde(reserva, ("dia_carga", "dia_retiro"))


def _msc_fecha_etd(texto):
    """La ETD de una tarjeta de itinerario de MSC como la lee _JS_MSC_NAVES («27 SEP 2026»), como datetime.date; None si no
    se puede leer."""
    m = _re_mk.fullmatch(r"\s*(\d{1,2}) ([A-Za-z]{3}) (\d{4})\s*", str(texto or ""))
    if not m or m.group(2).upper() not in _MESES_EN:
        return None
    try:
        return datetime.date(int(m.group(3)), _MESES_EN.index(m.group(2).upper()) + 1, int(m.group(1)))
    except ValueError:
        return None


def _msc_salidas(exacta):
    return [(_msc_fecha_etd(x.get("etd")), x) for x in exacta]


def _msc_transito(x):
    """El tiempo de tránsito de una tarjeta de MSC: su ETA menos su ETD, las dos que lee _JS_MSC_NAVES
    (CICLO-cola-tres-items.md). Medido en las 27 tarjetas del 2026-09-25: es el «Est T.T» que muestra la tarjeta. None
    si no trae las dos o si la ETA no es posterior."""
    etd, eta = _msc_fecha_etd(x.get("etd")), _msc_fecha_etd(x.get("eta"))
    if not etd or not eta or eta <= etd:
        return None
    return eta - etd


def _msc_elegir_salida(exacta, desde):
    """De las tarjetas con la nave de la fila, (la que se elige, "") o, si no queda una sola, (None, motivo): la próxima
    salida desde 'desde' (_proxima_salida). Hasta 384d3ce tomaba la primera que calzaba (CICLO-proxima-salida.md)."""
    return _proxima_salida(_msc_salidas(exacta), desde, _msc_transito)


def _msc_salida_ambigua(page, reg, reserva, exacta, motivo, desde):
    """No queda una sola salida de MSC para la nave de la fila: no se elige ninguna. Deja la captura y el HTML de la lista
    (msc_f<fila>_itinerarios), sin clics ni esperas, y la reserva queda NO ENVIADA con el motivo."""
    reg.info("itinerarios que calzan: " + " | ".join(f"{x.get('nave')} ETD {x.get('etd')}" for x in exacta[:6])[:400])
    _evidencia_antes_de_la_guarda(page, reg, f"msc_f{reserva['fila']}_itinerarios", "en la lista de itinerarios",
                                  completa=False)
    por_que = _por_que_sin_salida(motivo, _msc_salidas(exacta), desde, _msc_transito)
    return _no_enviada(reg, f"MSC: no elegí salida para esa nave ('{reserva['nave']}'): {por_que}. Revisa la fila y "
                            f"elige la salida en el portal.")


def _msc_kendo_dropdown(page, wid, tokens, reg, etiqueta):
    """Selecciona en un Kendo dropdownlist la 1ª opción que contenga TODOS los tokens."""
    try:
        r = str(page.evaluate("""(a)=>{
            const [id, toks] = a;
            if(!window.jQuery) return 'no-jquery';
            const w = jQuery('#'+id).data('kendoDropDownList');
            if(!w) return 'no-widget';
            const tf = w.options.dataTextField || 'Text';
            const vf = w.options.dataValueField || 'Value';
            const data = w.dataSource.data();
            const T = toks.map(s=>s.toUpperCase());
            const opts=[]; let idx=-1;
            for(let i=0;i<data.length;i++){
                const t=((data[i][tf]!=null?data[i][tf]:data[i])+'');
                opts.push(t);
                const U=t.toUpperCase();
                if(idx<0 && T.every(x=>U.includes(x))) idx=i;
            }
            if(idx>=0){ 
                const chosen=opts[idx]; 
                const item = data[idx];
                const val = (item && item[vf] != null) ? item[vf] : (item && item.Value != null ? item.Value : idx);
                w.value(val);
                w.select(idx); 
                w.trigger('change');
                const span = w.wrapper ? w.wrapper.find('.k-input') : null;
                if(span && span.length) span.text(chosen);
                if(w.element && w.element[0]) {
                    w.element[0].value = val;
                    w.element[0].dispatchEvent(new Event('change', {bubbles:true}));
                    w.element[0].dispatchEvent(new Event('input', {bubbles:true}));
                }
                return 'ok:'+chosen+' ||opts='+opts.slice(0,18).join(' / '); 
            }
            return 'sin-match|opts='+opts.slice(0,20).join(' / ');
        }""", [wid, tokens]))
        if os.environ.get("AQUASHIELD_DESCUBRIR"):
            reg.info(f"{etiqueta}: {r[:240]}")
        else:
            reg.info(f"{etiqueta}: {r.split('||')[0][:90]}")
        return r.startswith("ok")
    except Exception as e:
        reg.info(f"{etiqueta}: err {str(e)[:60]}")
        return False


def _msc_seleccionar_tipo_contenedor(page, reg):
    """Selecciona obligatoriamente 40' HIGH CUBE REEFER en Container Type."""
    import re as _re
    seleccionado = False
    try:
        # Intento 1: Interacción de usuario directa en la interfaz
        wrap = page.locator("span.k-dropdown:has(#EquipmentTypes), span[aria-owns*='EquipmentTypes']").first
        if wrap.count() and wrap.is_visible():
            wrap.click(timeout=3000)
            esperar(page, 0.5)
            # Buscar la opción 40' HIGH CUBE REEFER
            opt = page.locator("#EquipmentTypes_listbox li, .k-animation-container:visible li").filter(
                has_text=_re.compile(r"40.*high\s*cube.*reefer|40.*hc.*reefer|high\s*cube.*reefer", _re.I)).first
            if opt.count() and opt.is_visible():
                txt = opt.inner_text().strip()
                opt.click(timeout=3000)
                reg.info(f"Container Type seleccionado (UI): '{txt}' ✓")
                seleccionado = True
                esperar(page, 0.8)
    except Exception as e:
        reg.info(f"Container Type UI click err: {e}")

    # Intento 2: Kendo API completo asegurando valor, selección y disparo de eventos
    if not seleccionado:
        res = str(page.evaluate("""() => {
            if (!window.jQuery) return 'no-jquery';
            const w = jQuery('#EquipmentTypes').data('kendoDropDownList');
            if (!w) return 'no-widget';
            const data = w.dataSource.data();
            const tf = w.options.dataTextField || 'Text';
            const vf = w.options.dataValueField || 'Value';
            let idx = -1;
            for (let i = 0; i < data.length; i++) {
                const t = ((data[i][tf] != null ? data[i][tf] : data[i]) + '').toUpperCase();
                if (t.includes('40') && (t.includes('HIGH CUBE') || t.includes('HC')) && t.includes('REEFER')) {
                    idx = i; break;
                }
            }
            if (idx < 0) {
                for (let i = 0; i < data.length; i++) {
                    const t = ((data[i][tf] != null ? data[i][tf] : data[i]) + '').toUpperCase();
                    if (t.includes('HIGH CUBE') && t.includes('REEFER')) { idx = i; break; }
                }
            }
            if (idx >= 0) {
                const item = data[idx];
                const chosen = ((item[tf] != null ? item[tf] : item) + '');
                const val = (item && item[vf] != null) ? item[vf] : (item && item.Value != null ? item.Value : idx);
                w.value(val);
                w.select(idx);
                w.trigger('change');
                const span = w.wrapper ? w.wrapper.find('.k-input') : null;
                if (span && span.length) span.text(chosen);
                if (w.element && w.element[0]) {
                    w.element[0].value = val;
                    w.element[0].dispatchEvent(new Event('change', {bubbles:true}));
                    w.element[0].dispatchEvent(new Event('input', {bubbles:true}));
                }
                return 'ok:' + chosen;
            }
            return 'sin-match';
        }"""))
        reg.info(f"Container Type (Kendo API): {res}")
        if "ok:" in res:
            seleccionado = True

    try:
        vis = page.evaluate("""() => {
            const el = document.querySelector('span.k-dropdown:has(#EquipmentTypes), span[aria-owns*="EquipmentTypes"]');
            return el ? (el.querySelector('.k-input') ? el.querySelector('.k-input').textContent.trim() : '') : '';
        }""")
        reg.info(f"Container Type en pantalla: '{vis}'")
    except Exception:
        pass
    return seleccionado


# Elige en la lista del HS Code la sugerencia del salmón. Hasta 83067a1, si no estaba, pulsaba la primera de la
# lista: ahora devuelve 'sin-salmon' sin pulsar nada (CICLO-clics-a-ciegas.md).
_JS_MSC_HS_ELEGIR = """() => {
    let items = [];
    const lb = document.querySelector('#HsCode_listbox');
    if (lb) items = [...lb.querySelectorAll('li.k-item, li[role=option], li')].filter(e => e.offsetParent);
    if (!items.length) {
        const popups = [...document.querySelectorAll('.k-animation-container, .k-list-container')].filter(e => e.offsetParent);
        for (const p of popups) {
            const li = [...p.querySelectorAll('li.k-item, li[role=option], li')].filter(e => e.offsetParent);
            if (li.length) { items = li; break; }
        }
    }
    if (items.length > 0) {
        const target = items.find(e => /atlantic salmon|salmo salar/i.test(e.textContent || ''));
        if (!target) return 'sin-salmon';
        const txt = (target.textContent || '').trim();
        target.scrollIntoView({block: 'center'});
        target.click();
        return txt;
    }
    return '';
}"""


def _msc_set_hscode(page, hscode, reg):
    """Escribe el HS Code (030313), aguarda a que carguen las sugerencias y elige la del salmón. Si ninguna es el
    salmón, o el portal no ofrece ninguna, no pulsa nada y corta la reserva (ObjetivoNoEncontrado). Hasta fb63271,
    sin sugerencias, confirmaba con el teclado la que quedara primera (CICLO-cola-nueve-items.md)."""
    try:
        inp = page.locator("#HsCode").first
        inp.wait_for(state="visible", timeout=8000)
        inp.click()
        inp.press("Control+a")
        inp.press("Backspace")
        esperar(page, 0.3)
        inp.press_sequentially(str(hscode), delay=120)
        reg.info(f"HS Code escrito '{hscode}', esperando carga de opciones...")

        # Aguardar a que cargue la lista de opciones (llamada AJAX de MSC); el salmón puede llegar después
        elegido = ""
        for seg in range(14):   # hasta 7 segundos de sondeo
            esperar(page, 0.5)
            elegido = str(page.evaluate(_JS_MSC_HS_ELEGIR))
            if elegido and elegido != "sin-salmon":
                break

        if elegido == "sin-salmon":
            raise ObjetivoNoEncontrado("HS Code de MSC", f"la sugerencia del salmón («Atlantic salmon» o «Salmo "
                                                         f"salar») entre las que ofrece el portal para '{hscode}'")
        if not elegido:
            raise ObjetivoNoEncontrado("HS Code de MSC", f"la sugerencia del salmón para '{hscode}': el portal no "
                                                         f"ofreció ninguna")
        reg.info(f"HS Code '{hscode}' seleccionado (salmón): '{elegido[:60]}' ✓")

        esperar(page, 1.0)
        return True
    except Exception as e:
        reg.info(f"HS Code err: {e}")
        return False


# Elige en un Kendo autocomplete la sugerencia que contiene el texto escrito. Hasta 83067a1, si ninguna lo
# contenía, pulsaba la primera: ahora devuelve 'sin-coincidencia' sin pulsar nada (CICLO-clics-a-ciegas.md).
_JS_MSC_KENDO_ELEGIR = """(a)=>{
    const [id,txt]=a;
    let items=[];
    const lb=document.querySelector('#'+id+'_listbox');
    if(lb) items=[...lb.querySelectorAll('li.k-item,li[role=option]')].filter(e=>e.offsetParent);
    if(!items.length){
        const conts=[...document.querySelectorAll('.k-animation-container,.k-list-container')].filter(e=>e.offsetParent);
        for(const c of conts){ const li=[...c.querySelectorAll('li.k-item,li[role=option]')].filter(e=>e.offsetParent);
            if(li.length){ items=li; break; } }
    }
    const el=items.find(e=>(e.textContent||'').toUpperCase().includes(txt.toUpperCase()));
    if(el){ el.scrollIntoView({block:'center'}); el.click(); return (el.textContent||'').trim().slice(0,45); }
    return items.length ? 'sin-coincidencia' : '';
}"""


def _msc_kendo_autocomplete(page, wid, texto, reg, etiqueta):
    """Escribe en un Kendo autocomplete y elige la sugerencia que contiene el texto. Si ninguna lo contiene, o el
    portal no ofrece ninguna, no pulsa nada y corta la reserva (ObjetivoNoEncontrado). Hasta fb63271, sin
    sugerencias, elegía con el teclado la que quedara primera (CICLO-cola-nueve-items.md)."""
    try:
        inp = page.locator(f"#{wid}").first
        inp.wait_for(state="visible", timeout=8000)
        inp.click()
        try: inp.fill("")
        except Exception: pass
        inp.type(texto, delay=90)
        picked = ""
        for _ in range(8):     # sondea hasta ~3.2s
            esperar(page, 0.4)
            try:
                picked = str(page.evaluate(_JS_MSC_KENDO_ELEGIR, [wid, texto]))
            except Exception:
                pass
            if picked and picked != "sin-coincidencia":
                break
        if picked == "sin-coincidencia":
            raise ObjetivoNoEncontrado(f"{etiqueta} de MSC", f"la sugerencia que dice «{texto}» entre las que "
                                                             f"ofrece el portal")
        if not picked:
            raise ObjetivoNoEncontrado(f"{etiqueta} de MSC", f"la sugerencia que dice «{texto}»: el portal no ofreció "
                                                             f"ninguna")
        reg.info(f"{etiqueta} '{texto}': {picked}")
        esperar(page, 0.6)
        return True
    except Exception as e:
        reg.info(f"{etiqueta}: err {str(e)[:60]}")
        return False


def _msc_fill_id(page, wid, valor, reg, etiqueta):
    """Rellena un input por id (dispara eventos para Knockout/Kendo)."""
    try:
        r = str(page.evaluate("""(a)=>{
            const [id,val]=a;
            const inp=document.getElementById(id);
            if(!inp) return 'no-input';
            const set=Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;
            inp.focus(); set.call(inp, String(val));
            inp.dispatchEvent(new Event('input',{bubbles:true}));
            inp.dispatchEvent(new Event('change',{bubbles:true}));
            inp.dispatchEvent(new KeyboardEvent('keyup',{bubbles:true}));
            try{ inp.blur(); }catch(e){}
            return 'ok';
        }""", [wid, valor]))
        reg.info(f"{etiqueta}='{valor}': {r}")
        return r == "ok"
    except Exception as e:
        reg.info(f"{etiqueta}: err {str(e)[:60]}")
        return False


def _msc_next(page, reg, motivo=""):
    """Pulsa el botón Next del asistente MSC (#nextBtn); espera a que se habilite."""
    habilitado = False
    for _ in range(10):
        try:
            habilitado = bool(page.evaluate("""()=>{
                const b=document.querySelector('#nextBtn');
                return b && !b.disabled && b.offsetParent;
            }"""))
        except Exception:
            habilitado = False
        if habilitado:
            break
        esperar(page, 1.2)
    if not habilitado:
        reg.info(f"Next DESHABILITADO {motivo}")
        return False
    ok = click_si_existe(page, "#nextBtn", 5000, reg)
    reg.info(f"Next {'ok' if ok else 'NO'} {motivo}")
    return ok


def _msc_llenar_comentarios(page, texto, reg):
    """Escribe los comentarios corporativos (Customer Comments) en myMSC (pestaña Summary)."""
    reg.paso("Comentarios corporativos (Customer Comments)...")
    try:
        # Selector preciso del campo en Summary (NUNCA usar 'textarea' genérico)
        sel = "#CustomerComments, textarea[name='CustomerComments'], [data-test-id='customer-comments'], textarea.CustomerComments"
        txt_loc = page.locator(sel).first
        try:
            txt_loc.wait_for(state="visible", timeout=8000)
        except Exception:
            pass

        # Intento vía Playwright con scroll y click previo
        if txt_loc.count() and txt_loc.is_visible():
            txt_loc.scroll_into_view_if_needed(timeout=3000)
            txt_loc.click(timeout=2000)
            txt_loc.fill(texto)
            esperar(page, 0.4)

        # Sincronización JavaScript y disparo de eventos para Knockout / Kendo
        res = page.evaluate("""(t) => {
            const el = document.getElementById('CustomerComments') || 
                       document.querySelector("[data-test-id='customer-comments']") ||
                       document.querySelector("textarea[name='CustomerComments']") ||
                       document.querySelector(".CustomerComments");
            if (el) {
                el.scrollIntoView({block: 'center'});
                el.focus();
                el.value = t;
                el.dispatchEvent(new Event('input', { bubbles: true }));
                el.dispatchEvent(new Event('change', { bubbles: true }));
                el.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true }));
                return el.value;
            }
            return '';
        }""", texto)

        esperar(page, 0.6)

        valor_final = ""
        try:
            valor_final = txt_loc.input_value()
        except Exception:
            valor_final = res or ""

        if valor_final:
            reg.info(f"Customer Comments MSC: '{valor_final}' ✓")
            return True
        else:
            reg.info("Customer Comments MSC: no se pudo escribir el comentario")
            return False
    except Exception as e:
        reg.info(f"Customer Comments MSC error: {str(e)[:60]}")
        return False


def _msc_buscar_itinerarios(page, reg):
    """Pulsa «Search Schedule» con click_si_existe: el primer botón, en el orden de la página, cuyo texto traiga «Search
    Schedule» o «Buscar». Si ese no se ve en 6 s, no pulsa nada y levanta ObjetivoNoEncontrado: la reserva queda NO
    ENVIADA, con la captura y el HTML (decisión de Marcelo, CICLO-inicio-de-todas.md). Hasta c4df3ab caía a
    _JS_CLICK_BTN, que pulsaba el primer botón, enlace o input submit de la página, fuera del encabezado y de la
    navegación, cuyo texto trajera «search schedule» o «buscar», visible o no. Medido en logs/: en las 9 búsquedas del
    2026-09-21 al 26, el botón lo encontró su selector."""
    if not click_si_existe(page, "button:has-text('Search Schedule'), button:has-text('Buscar')", 6000, reg):
        raise ObjetivoNoEncontrado("Search Schedule de MSC", "el botón «Search Schedule» o «Buscar» (por su texto)")


@_con_la_nave_de_la_fila
@_con_la_ruta_de_la_fila
@_sin_clic_a_ciegas("msc")
def reservar_msc(page, reserva, creds, reg, on_pausa=None):
    f = reserva["fila"]
    reg.paso(f"[MSC fila {f}] {reserva['pol']} -> {reserva['destino_final']} | NAVE: {reserva['nave']}")
    _avisar_dia_carga(reserva, reg)
    reg.paso("Abriendo eBooking de MSC...")
    try:
        page.goto(MSC_EBOOKING, wait_until="domcontentloaded")
    except Exception as e:
        reg.info(f"goto eBooking: {str(e)[:70]}")
    _msc_esperar_paso(page, "shipping-rates-tab", 14, reg, minimo=1.0)
    _msc_cookies(page, reg)
    reg.captura(page, f"msc_f{f}_1_base", full=True)

    # ---- Paso 1: Base Information ----
    reg.paso("Paso 1 · Base Information...")
    # Tarifa por contrato de servicio (radio S) + número de contrato
    # Radio "tarifa por contrato de servicio". Es opcional y en algunas cuentas
    # ya viene marcado. Se resuelve con una consulta directa a la pagina: la
    # espera de Playwright aqui se estiraba a 30 s (medido) sin aportar nada.
    try:
        _r = str(page.evaluate("""()=>{
            const e=document.querySelector('#scheduleCharge_S');
            if(!e) return 'ausente';
            if(e.checked) return 'ya-marcado';
            const r=e.getBoundingClientRect();
            if(e.offsetParent===null || r.width===0) { e.click(); return 'marcado-oculto'; }
            e.click(); return 'marcado';
        }"""))
    except Exception as _e:
        _r = "no-consultable"
    reg.info(f"tarifa por contrato: {_r}")
    contrato = (str(reserva.get("cotizacion") or "").strip()
                or str(creds.get("contrato") or "").strip()
                or _contrato_por_defecto("msc"))
    if contrato:
        try:
            inp_c = page.locator("input[name='serviceContract'], #serviceContract, input#ServiceContract").first
            if inp_c.count():
                inp_c.click(timeout=3000)
                inp_c.fill(contrato, timeout=3000)
                page.keyboard.press("Tab")
                reg.info(f"contrato MSC: escrito '{contrato}' ✓")
            else:
                rellenar(page, "input[name='serviceContract']", contrato, 8000, reg)
        except Exception as e:
            reg.info(f"contrato MSC err: {e}")
    # Booking Office (obligatorio si no viene preseleccionado)
    _msc_kendo_dropdown(page, "BookingOffice", ["CHILE"], reg, "Booking Office") or \
        _msc_kendo_dropdown(page, "BookingOffice", ["SANTIAGO"], reg, "Booking Office")
    esperar(page, 0.6)
    _msc_next(page, reg, "-> Route Details")
    _msc_esperar_paso(page, "shipment-details-tab", 8, reg)
    _msc_cookies(page, reg)

    # ---- Paso 2: Route Details ----
    reg.paso("Paso 2 · Route Details (fecha + puertos)...")
    desde = _msc_desde(reserva)
    _msc_fecha(page, desde.isoformat(), reg)
    esperar(page, 0.6)
    # Antes de elegir cada puerto, la evidencia de sus sugerencias (decisión de Marcelo, CICLO-origen-y-destino.md).
    # Sin una sugerencia elegida, NO ENVIADA: ninguna naviera sigue sin su origen o su destino (decisión de Marcelo,
    # encargo 42, CICLO-maersk-y-fila-sin-ruta.md). _msc_puerto ya cortaba si no veía ninguna; si fallaba al
    # escribir, la reserva seguía.
    if not _msc_puerto(page, "POLId_input", (reserva["pol"] or "").split(",")[0].strip(), reg, "Port of Load",
                       evidencia=f"msc_f{f}_origen"):
        raise ObjetivoNoEncontrado("Port of Load de MSC", _sugerencia_que_elegir(reserva["pol"]))
    esperar(page, 0.8)
    dest = (reserva["destino_final"] or reserva["destino_orig"] or "").split(",")[0].strip()
    if not _msc_puerto(page, "PODId_input", dest, reg, "Port of Discharge", evidencia=f"msc_f{f}_destino"):
        raise ObjetivoNoEncontrado("Port of Discharge de MSC", _sugerencia_que_elegir(dest))
    esperar(page, 0.8)
    reg.captura(page, f"msc_f{f}_2a_ruta", full=True)

    # Buscar itinerarios: el botón por su texto, o corta (_msc_buscar_itinerarios)
    reg.paso("Buscando itinerarios (Search Schedule)...")
    _msc_buscar_itinerarios(page, reg)
    # Esperar a que carguen los itinerarios (aparecen progresivamente); avanza al estabilizarse
    n = 0; estable = 0
    for _ in range(20):
        esperar(page, 1)
        try:
            c = int(page.evaluate(_JS_MSC_COUNT_SCHED))
        except Exception:
            c = 0
        if c and c == n:
            estable += 1
            if estable >= 2:   # dos lecturas iguales seguidas
                break
        else:
            estable = 0
        n = c
    reg.info(f"itinerarios cargados: {n}")
    _msc_cookies(page, reg)
    reg.captura(page, f"msc_f{f}_2b_schedules", full=True)

    # Seleccionar la NAVE pedida. Solo se acepta la que calza con nave Y viaje:
    # elegir "alguna otra" es un error operativo, no una aproximacion util.
    reg.paso(f"Buscando la nave '{reserva['nave']}' en los itinerarios...")
    def _norm(x):
        return " ".join(str(x or "").upper().replace("/", " ").split())
    pedida = _norm(reserva["nave"])
    toks = [t for t in pedida.split(" ") if len(t) > 1]
    naves = []
    for intento in range(3):
        try:
            naves = page.evaluate(_JS_MSC_NAVES) or []
        except Exception as e:
            reg.info(f"error leyendo itinerarios: {str(e)[:60]}")
        if naves:
            break
        esperar(page, 2.0)
    # Si la nave no está en lo que muestra la lista, baja por ella (no es un clic) para que MSC cargue más itinerarios,
    # hasta encontrarla o hasta que no lleguen tarjetas nuevas (_msc_bajar; decisión de Marcelo,
    # CICLO-ampliar-msc-y-cma.md). Hasta el encargo 33 cortaba con lo que había cargado de entrada.
    bajadas, por_que = 0, ""
    while not any(x.get("sel") and _trae_la_nave(_norm(x.get("nave")), toks) for x in naves):
        if bajadas >= AMPLIAR_MAX:
            por_que = f"bajé por la lista {AMPLIAR_MAX} veces, el tope"
            break
        por_que = _msc_bajar(page, reg, sum(1 for x in naves if x.get("sel")))
        if por_que:
            break
        bajadas += 1
        try:
            naves = page.evaluate(_JS_MSC_NAVES) or naves
        except Exception as e:
            reg.info(f"error leyendo itinerarios después de bajar: {str(e)[:60]}")

    # Todas las palabras de la nave en el campo de la nave de la tarjeta (_trae_la_nave). Hasta 9051f43, una fila sin
    # palabras de nave calzaba con todas las tarjetas (CICLO-cola-tres-items.md).
    exacta = [n for n in naves if n.get("sel") and _trae_la_nave(_norm(n.get("nave")), toks)]
    elegida, motivo = _msc_elegir_salida(exacta, desde) if exacta else (None, "")
    if exacta and elegida is None:
        return _msc_salida_ambigua(page, reg, reserva, exacta, motivo, desde)
    if len(exacta) > 1:
        reg.info(f"{len(exacta)} salidas calzan con '{reserva['nave']}'; elijo la próxima desde el {desde:%d-%m-%Y}")
        _anotar_desempate(reg, _msc_salidas(exacta), desde, _msc_transito)
    modo = ""
    if elegida:
        try:
            if page.evaluate(_JS_MSC_CLIC_NAVE, elegida["i"]):
                modo = f"exacto:{elegida['nave']}"
                reg.info(f"nave seleccionada -> {elegida['nave']} ETD {elegida.get('etd','')}")
        except Exception as e:
            reg.info(f"error al seleccionar: {str(e)[:60]}")

    if not modo:
        # El mismo barco con OTRO viaje es la confusion mas cara: se avisa aparte.
        parecidas = [n["nave"] for n in naves if _trae_la_nave(_norm(n.get("nave")), toks[:2])]
        lista = ", ".join(n["nave"] for n in naves if n.get("sel"))[:300]
        reg.paso(f"La nave '{reserva['nave']}' NO está en los itinerarios de MSC.")
        if parecidas:
            reg.paso(f"Sí aparece ese barco con otro viaje: {', '.join(parecidas)[:120]}. "
                     f"No la elijo por mi cuenta: corrige la columna 'Nave' si corresponde.")
        reg.info(f"itinerarios ofrecidos: {lista}")
        reg.captura(page, f"msc_f{f}_2c_sinnave", full=True)
        donde = "" if exacta else f": {_hasta_donde_busque([_msc_fecha_etd(n.get('etd')) for n in naves], por_que)}"
        return ("REVISAR", f"nave '{reserva['nave']}' no está en MSC{donde}"
                           + (f"; sí hay {', '.join(parecidas)[:80]}" if parecidas else "")
                           + f" (ofrecidos: {lista[:160]})")

    esperar(page, 0.8)
    _msc_cookies(page, reg)
    _msc_next(page, reg, "-> Container and Cargo")
    _msc_esperar_paso(page, "container-cargo-tab", 8, reg)
    _msc_cookies(page, reg)
    reg.captura(page, f"msc_f{f}_3a_cargo", full=True)

    # ---- Paso 3: Container and Cargo ----
    reg.paso("Paso 3 · Container and Cargo (ejemplo reefer salmón)...")
    # Tipo de contenedor: 40' High Cube Reefer (obligatorio)
    _msc_seleccionar_tipo_contenedor(page, reg)
    esperar(page, 1.5)   # al elegir reefer aparecen Temperatura, etc.

    # Condition: Operating (reefer activo)
    try:
        page.evaluate("""() => {
            if (window.jQuery) {
                const w = jQuery('#Condition, [name*="Condition"]').data('kendoDropDownList');
                if (w) {
                    const data = w.dataSource.data();
                    for (let i = 0; i < data.length; i++) {
                        const t = ((data[i].Text || data[i] || '') + '').toUpperCase();
                        if (t.includes('OPERAT')) { w.select(i); w.trigger('change'); break; }
                    }
                }
            }
        }""")
    except Exception:
        pass

    # Temperatura de la fila, o la de config.json
    t_val = _temp_reserva(reserva)
    if t_val.endswith(".0"):
        t_val = t_val[:-2]
    _msc_fill_id(page, "Temperature", t_val, reg, "Temperature")
    esperar(page, 0.4)

    # Harmonized Code: 030313 (Salmón congelado del Pacífico/Atlántico)
    # Espera a que cargue la lista de opciones y escoge Atlantic salmon (Salmo salar)
    _msc_set_hscode(page, "030313", reg)
    esperar(page, 0.8)

    # Commodity: asegurar Atlantic salmon si no se rellenó por el HS Code
    try:
        comm_val = str(page.evaluate("()=>{const e=document.getElementById('Commodity');return e?(e.value||e.textContent):''}"))
    except Exception:
        comm_val = ""
    if not comm_val.strip() or "salmon" not in comm_val.lower():
        _msc_kendo_autocomplete(page, "Commodity", "Atlantic salmon", reg, "Commodity")
        esperar(page, 0.6)

    # Short Description: FROZEN SALMON SALAR
    _msc_fill_id(page, "CargoDescription", "FROZEN SALMON SALAR", reg, "Short Description")

    # Peso bruto: el de config.json
    _msc_fill_id(page, "WeightPerUnit", _peso_reefer(), reg, "Gross Cargo Weight")

    # Tipo de bulto (obligatorio): BOX
    _msc_kendo_dropdown(page, "packageType", ["BOX"], reg, "Package Type") or \
        _msc_kendo_dropdown(page, "packageType", ["CARTON"], reg, "Package Type(2)") or \
        _msc_kendo_dropdown(page, "packageType", ["PACKAGE"], reg, "Package Type(3)")
    esperar(page, 0.8)
    _msc_cookies(page, reg)
    reg.captura(page, f"msc_f{f}_3b_cargo", full=True)
    if os.environ.get("AQUASHIELD_DESCUBRIR"):
        _guardar_html(page, "msc_dump.html", reg)
        _dump_carga(page, reg)

    # ---- Paso 3 -> 4: Parties ----
    _msc_next(page, reg, "-> Parties")
    _msc_esperar_paso(page, "parties-tab", 8, reg)
    _msc_cookies(page, reg)
    reg.captura(page, f"msc_f{f}_4_parties", full=True)

    # ---- Paso 4 -> 5: Summary (SIN emitir) ----
    _msc_next(page, reg, "-> Summary")
    _msc_esperar_paso(page, "summary-tab", 8, reg)
    _msc_cookies(page, reg)
    esperar(page, 1.2)

    # Comentarios corporativos (Customer Comments)
    _msc_llenar_comentarios(page, COSCO_REMARK, reg)
    esperar(page, 0.8)

    reg.url(page)
    reg.captura(page, f"msc_f{f}_5_summary", full=True)
    _evidencia_antes_de_la_guarda(page, reg, f"msc_f{f}_guarda")
    if not es_modo_emision():
        reg.paso("Me DETENGO en Summary (NO se emite la reserva).")
        return ("OK-EJEMPLO", f"MSC armada hasta Summary (nave: {reserva['nave']}); SIN emitir")

    # MODO EMISIÓN REAL
    reg.paso("🔴 MODO EMISIÓN REAL: Pulsando 'Submit' en MSC...")
    pulsado, error = None, None
    try:
        page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
        esperar(page, 0.8)
        pulsado = _pulsar_boton(page, "button:has-text('Submit'), button[type='submit']", _JS_CLICK_BTN, "^(submit|enviar)$")
        esperar(page, 5.0)
        _msc_cookies(page, reg)
    except Exception as e:
        error = e
    return _resultado_envio(page, reg, "msc", "MSC", f"msc_f{f}_6_confirmado", "Submit", pulsado, error)


# ============================================================
#  RESERVA · COSCO  (eBusiness · formulario dentro de iframe bkg2)
# ============================================================
def _cosco_frame(page, reg, intentos=12):
    """Devuelve el frame del formulario de booking (bkg2), esperando a que cargue."""
    for _ in range(intentos):
        for fr in page.frames:
            if "bkg2" in (fr.url or "").lower():
                return fr
        esperar(page, 1.5)
    reg.info("no encontré el iframe bkg2")
    return None


# Autocompletado dentro del frame COSCO: setea valor, dispara input y clica la sugerencia
_JS_COSCO_AUTO_SET = """(a)=>{
    const [phrx, val] = a;
    const re = new RegExp(phrx,'i');
    const inp = [...document.querySelectorAll('input')].find(e=>e.offsetParent && re.test(e.placeholder||''));
    if(!inp) return 'no-input';
    const s = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;
    inp.focus();
    try { inp.click(); } catch(e){}
    s.call(inp, val);
    inp.dispatchEvent(new Event('input',{bubbles:true}));
    inp.dispatchEvent(new Event('change',{bubbles:true}));
    return 'set';
}"""

# [texto, preferir Chile, pulsar]: pulsa solo con pulsar en true (o con el texto solo, como antes); con false, solo dice
# cuál pulsaría ('' si ninguna), para dejar antes la evidencia de la lista (CICLO-origen-y-destino.md).
_JS_COSCO_AUTO_PICK = """(args)=>{
    let txt = typeof args === 'string' ? args : (args[0] || '');
    let preferChile = Array.isArray(args) ? !!args[1] : false;
    const pulsar = Array.isArray(args) ? args[2] === true : true;
    const T = txt.toUpperCase().trim();
    const opts = [...document.querySelectorAll('li,ul li,[class*=option],[class*=item],.el-select-dropdown__item')]
        .filter(e=>e.offsetParent && (e.textContent||'').toUpperCase().includes(T)
                   && (e.textContent||'').trim().length<85);
    if(!opts.length) return '';
    if (preferChile) {
        const ch = opts.find(e => {
            const u = (e.textContent||'').toUpperCase();
            return u.includes('CHILE') || u.includes(', CL') || u.includes('(CL)');
        });
        if (ch) { if (pulsar) ch.click(); return ch.textContent.trim().slice(0,40); }
        // Si se pide Chile, nunca elegir una opción de otro país (evita Paraguay, etc.)
        return '';
    }
    const exactStart = opts.find(e => {
        const c = (e.textContent||'').trim().toUpperCase();
        return c.startsWith(T + ',') || c === T;
    });
    if (exactStart) { if (pulsar) exactStart.click(); return exactStart.textContent.trim().slice(0,40); }
    if (pulsar) opts[0].click();
    return opts[0].textContent.trim().slice(0,40);
}"""


def _cosco_autocomplete(frame, ph_regex, texto, match_texto, reg, etiqueta, preferir_chile=False, evidencia=""):
    """Escribe 'texto' en el autocompletado (por placeholder) y clica la sugerencia que calce.
       Reintenta el seteo si las sugerencias tardan (algunas ciudades demoran).
       Con 'evidencia' (el origen y el destino), antes de pulsarla deja con ese nombre la captura de la ventana y el
       HTML de la página y de sus marcos (la lista está en el del formulario): _JS_COSCO_AUTO_PICK, sin pulsar, dice si
       hay una que pulsaría (decisión de Marcelo, CICLO-origen-y-destino.md). Si vuelve a escribir, la de esa otra
       lista queda con «_reintento»; y después del clic, _avisar_lista_distinta.
       Con el texto vacío no escribe ni pulsa nada: corta (_TEXTO_DE_LA_FILA; encargo 42), porque calzaba con
       cualquier sugerencia. Solo con el vacío: este ayudante sirve también al contrato, que va tal como viene; el
       origen y el destino le llegan ya con _ciudad_de (_cosco_puerto_de_carga y reservar_cosco; revisión de
       código del encargo 42)."""
    if not str(match_texto or "").strip():
        raise ObjetivoNoEncontrado(f"{etiqueta} de COSCO", _TEXTO_DE_LA_FILA)
    picked = ""
    try:
        for reintento in range(2):
            r = str(frame.evaluate(_JS_COSCO_AUTO_SET, [ph_regex, texto]))
            if r != "set":
                reg.info(f"{etiqueta}: {r}"); return False
            nombre = evidencia + ("_reintento" if reintento and evidencia else "")
            pendiente, vista = bool(evidencia), ""
            for _ in range(12):        # hasta ~7s por intento
                esperar_frame(frame, 0.6)
                if pendiente:
                    vista = " ".join(str(_sugerencia_sin_pulsar(frame, _JS_COSCO_AUTO_PICK,
                                                                 [match_texto, preferir_chile])).split())
                    if vista:
                        # La página del marco (frame.page): la captura es de la ventana, y el HTML, de cada marco.
                        _evidencia_antes_de_la_guarda(getattr(frame, "page", frame), reg, nombre,
                                                      f"con las sugerencias de {etiqueta}", completa=False)
                        pendiente = False
                try:
                    picked = str(frame.evaluate(_JS_COSCO_AUTO_PICK, [match_texto, preferir_chile, True]))
                except Exception:
                    picked = ""
                if picked:
                    _avisar_lista_distinta(reg, etiqueta, nombre, vista, " ".join(picked.split()), pendiente)
                    break
            if not picked and pendiente:
                _evidencia_sin_sugerencia(getattr(frame, "page", frame), reg, nombre, etiqueta)
            if picked:
                break
        reg.info(f"{etiqueta} '{texto}': {picked or 'sin sugerencia'}")
        return bool(picked)
    except Exception as e:
        reg.info(f"{etiqueta}: err {str(e)[:70]}")
        return False


def esperar_frame(frame, seg):
    try:
        frame.wait_for_timeout(int(seg * 1000))
    except Exception:
        time.sleep(seg)


# Selección de nave COSCO: botón 'Book Now' de la FILA cuyo texto tenga todos los tokens
_JS_COSCO_LISTA_NAVES = """()=>{
    // Cada itinerario es la fila que contiene su boton 'Book now'. Se sube por
    // los ancestros hasta la fila (la que ya trae Service y Vessel) y se lee SU
    // texto, no el del contenedor de toda la tabla.
    // Servicios y naves se toman de sus propios elementos: en el texto plano
    // salen pegados ("SERVICIO1NAVE") porque el portal no pone separadores.
    // Sin RegExp construida desde string: los escapes se pierden al viajar de
    // Python a JavaScript y el patron termina siendo otro.
    // La salida y la llegada no estan en la fila: van arriba, en la tarjeta del
    // itinerario (el ancestro mas grande con un solo 'Book now'), como
    // «Sep27 (Sun)», sin año. La unica fecha de la fila es el CY Cutoff: hasta
    // 135e765 se leia como la ETD (CICLO-proxima-salida.md).
    const campo=(row,etq)=>{
        const E=etq.toUpperCase();
        const lbl=[...row.querySelectorAll('span,div,p')].filter(e=>{
            const x=(e.textContent||'').trim().toUpperCase();
            return x.startsWith(E) && x.length < E.length+6 && x.indexOf(':')>=0;
        }).pop();                       // el ultimo = el mas profundo = la etiqueta
        if(!lbl) return [];
        const cont=lbl.nextElementSibling;
        if(!cont) return [];
        const hijos=[...cont.querySelectorAll('span,div')]
            .map(e=>(e.textContent||'').trim()).filter(t=>t && t.length<45);
        return [...new Set(hijos)];
    };
    const btns=[...document.querySelectorAll('button,a,[class*=btn]')]
        .filter(e=>e.offsetParent && /book now/i.test(e.textContent||''));
    const tarjeta=(b)=>{
        let c=b;
        while(c.parentElement && btns.filter(x=>c.parentElement.contains(x)).length===1) c=c.parentElement;
        return c;
    };
    return btns.map((b,i)=>{
        let row=b, hallada=false;
        for(let k=0;k<8&&row;k++){
            const t=(row.textContent||'').toUpperCase();
            if(t.includes('SERVICE') && t.includes('VESSEL')) { hallada=btns.filter(x=>row.contains(x)).length===1; break; }
            row=row.parentElement;
        }
        // Sin su fila no hay nave que comparar: ni a 8 niveles, ni si la primera con «Service» y «Vessel» trae otro
        // «Book now» (la de toda la lista). Hasta a198645 leía el octavo ancestro, o esa lista, y se quedaba con la nave
        // de otro itinerario (CICLO-solo-la-nave-pedida.md). Los 8 «Book now» guardados tienen su fila, con uno solo.
        if(!hallada) row=null;
        const rt=row?(row.textContent||'').replace(/\\s+/g,' ').trim():'';
        const m=rt.match(/(\\d{4}-\\d{2}-\\d{2})/);
        const fechas=[...tarjeta(b).querySelectorAll('*')].filter(e=>!e.children.length)
            .map(e=>(e.textContent||'').trim()).filter(t=>/^[A-Za-z]{3}\\d{1,2} \\([A-Za-z]{3}\\)$/.test(t));
        return {i:i, texto:rt.slice(0,400),
                servicios: row?campo(row,'Service'):[],
                naves: row?campo(row,'Vessel / Voyage'):[],
                corte: m?m[1]:'', salida: fechas[0]||'', llegada: fechas.length===2 ? fechas[1] : ''};
    });
}"""

_JS_COSCO_CLIC_NAVE = """(i)=>{
    const btns=[...document.querySelectorAll('button,a,[class*=btn]')]
        .filter(e=>e.offsetParent && /book now/i.test(e.textContent||''));
    const b=btns[i]; if(!b) return false;
    b.scrollIntoView({block:'center'}); b.click(); return true;
}"""


def _cosco_resumen(fila):
    """Servicio y nave/viaje de una fila de itinerario, legible para el operador.
    Las rutas de COSCO suelen tener transbordo: dos servicios y dos naves en la
    misma fila es lo normal, no un error."""
    if not isinstance(fila, dict):
        return " ".join(str(fila or "").split())[:90]
    partes = []
    serv = [x for x in (fila.get("servicios") or []) if x]
    naves = [x for x in (fila.get("naves") or []) if x]
    if serv:
        partes.append("servicio " + " + ".join(serv))
    if naves:
        partes.append("nave " + " + ".join(naves))
    if fila.get("etd"):
        partes.append("ETD " + fila["etd"])
    if partes:
        return " · ".join(partes)
    return " ".join(str(fila.get("texto") or "").split())[:90]


_COSCO_DIAS = ("MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN")


def _cosco_fecha_tarjeta(texto, hoy=None):
    """Una fecha de la tarjeta de itinerario de COSCO, «Sep27 (Sun)», como datetime.date. La tarjeta no trae el año: vale
    el del año anterior, el de hoy o el siguiente, el único cuyo día de la semana calce. None si no se puede leer."""
    m = _re_mk.fullmatch(r"\s*([A-Za-z]{3})(\d{1,2}) \(([A-Za-z]{3})\)\s*", str(texto or ""))
    if not m or m.group(1).upper() not in _MESES_EN or m.group(3).upper() not in _COSCO_DIAS:
        return None
    hoy = hoy or datetime.date.today()
    calzan = []
    for anio in (hoy.year - 1, hoy.year, hoy.year + 1):
        try:
            d = datetime.date(anio, _MESES_EN.index(m.group(1).upper()) + 1, int(m.group(2)))
        except ValueError:
            continue
        if d.weekday() == _COSCO_DIAS.index(m.group(3).upper()):
            calzan.append(d)
    return calzan[0] if len(calzan) == 1 else None


def _cosco_con_salida(filas, hoy=None):
    """Los itinerarios que lee _JS_COSCO_LISTA_NAVES, cada uno con 'etd': su salida como 'AAAA-MM-DD', o '' si su
    tarjeta no la trae legible."""
    out = []
    for x in filas:
        d = _cosco_fecha_tarjeta(x.get("salida"), hoy)
        out.append(dict(x, etd=d.isoformat() if d else ""))
    return out


def _cosco_calzan(filas, toks_nave, toks_todos):
    """Los itinerarios de la nave de la fila: los que traen, en una sola de sus naves de «Vessel / Voyage» (las que lee
    _JS_COSCO_LISTA_NAVES), todas las palabras de la nave y del viaje, cada una como palabra entera; si ninguno, los
    que traen las de la nave, con otro viaje (ej: 341N vs 342N), y con esos reservar_cosco corta (_cosco_sin_el_viaje).
    Sin palabras de nave, ninguno (_trae_la_nave;
    decisiones de Marcelo, CICLO-cola-tres-items.md y CICLO-cola-seis-items.md). Medido: en las 15 elecciones de COSCO
    de logs/, la nave de la fila estaba con todas sus palabras en una sola de sus naves; y en las 16 naves de sus 2
    listas guardadas, la nave y su viaje van separados por un espacio. Hasta f68ce6c bastaba que cada palabra fuera
    parte del texto, también la del viaje. Hasta 9051f43 se buscaba en el texto de toda la fila, que trae el servicio
    y las dos naves del transbordo, así que las palabras podían salir de dos naves distintas, y una fila sin palabras de
    nave calzaba con todas, o por el viaje solo."""
    if not toks_nave:
        return []
    return [x for x in filas if _cosco_trae(x, toks_todos)] or [x for x in filas if _cosco_trae(x, toks_nave)]


def _cosco_trae(x, palabras):
    """Si un itinerario de COSCO trae esas palabras en una sola de sus naves de «Vessel / Voyage» (_trae_la_nave)."""
    return any(_trae_la_nave(n, palabras) for n in x.get("naves") or [])


def _cosco_sin_el_viaje(cand, toks_todos):
    """True si hay itinerarios de la nave (los de _cosco_calzan) y ninguno trae todas las palabras de la fila, la nave y
    el viaje: _cosco_calzan devolvió entonces los de la nave con otro viaje. reservar_cosco no elige ninguno y la
    reserva queda NO ENVIADA (decisión de Marcelo, CICLO-cierre-de-frenos.md); hasta 4948e16 elegía entre ellos. Una
    fila sin viaje da False: sus palabras son las de la nave, que esos itinerarios traen."""
    return bool(cand) and not any(_cosco_trae(x, toks_todos) for x in cand)


def _cosco_salidas(cand):
    return [(datetime.date.fromisoformat(x["etd"]) if x.get("etd") else None, x) for x in cand]


def _cosco_transito(x):
    """El tiempo de tránsito de un itinerario de COSCO: su llegada menos su salida, las dos de su tarjeta («Nov15 (Sun)»,
    con el año por el día de la semana). Medido en las 4 tarjetas del 2026-09-25: es el «N Days» que muestra la tarjeta
    (CICLO-cola-tres-items.md). None si no trae las dos o si la llegada no es posterior."""
    llegada = _cosco_fecha_tarjeta(x.get("llegada"))
    if not llegada or not x.get("etd"):
        return None
    tiempo = llegada - datetime.date.fromisoformat(x.get("etd"))
    return tiempo if tiempo.days > 0 else None


def _cosco_elegir_itinerario(cand, reserva):
    """De los itinerarios que calzan con la nave, (el que se elige, "") o, si no queda uno solo, (None, motivo): la
    próxima salida desde hoy o desde el día de carga de la fila (_desde, _proxima_salida). Nunca el primero. Hasta
    94e4102 tomaba el primero, y hasta 135e765 comparaba el día de carga con el CY Cutoff, que se leía como ETD
    (CICLO-proxima-salida.md)."""
    return _proxima_salida(_cosco_salidas(cand), _desde(reserva), _cosco_transito)


def _cosco_itinerario_ambiguo(page, reg, reserva, cand, motivo):
    """No queda un solo itinerario para la nave, o ninguno trae el viaje de la fila («sin-viaje»): no se elige ninguno.
    Deja la captura y el HTML de la lista
    (cosco_f<fila>_itinerarios), sin clics ni esperas, y la reserva queda NO ENVIADA con el motivo."""
    reg.info("itinerarios que calzan: " + " | ".join(_cosco_resumen(x) for x in cand[:6])[:400])
    _evidencia_antes_de_la_guarda(page, reg, f"cosco_f{reserva['fila']}_itinerarios", "en la lista de itinerarios",
                                  completa=False)
    por_que = _por_que_sin_salida(motivo, _cosco_salidas(cand), _desde(reserva), _cosco_transito)
    return _no_enviada(reg, f"COSCO: no elegí itinerario para esa nave ('{reserva['nave']}'): {por_que}. Revisa la fila "
                            f"y elige el itinerario en el portal.")


# Lee de vuelta cada campo del formulario junto a su etiqueta. Element Plus
# agrupa etiqueta y control dentro de .el-form-item, asi que se recorre eso.
_JS_COSCO_LEER_CAMPOS = """()=>{
    const vis=e=>{const r=e.getBoundingClientRect();
                  return e.offsetParent!==null && r.width>0 && r.height>0;};
    const out=[];
    document.querySelectorAll('.el-form-item').forEach(fi=>{
        if(!vis(fi)) return;
        const lb=fi.querySelector('.el-form-item__label');
        if(!lb) return;
        const etq=(lb.textContent||'').replace(/[:*\\s]+$/,'').trim();
        if(!etq) return;
        const vals=[...fi.querySelectorAll('input,textarea')]
            .map(e=>(e.value||'').trim()).filter(Boolean);
        const tags=[...fi.querySelectorAll('.el-tag,.el-select__tags-text,.el-select__selected-item')]
            .map(e=>(e.textContent||'').trim()).filter(Boolean);
        const v=[...new Set(vals.concat(tags))].join(' | ');
        out.push({etq:etq, val:v});
    });
    return out;
}"""


def _norm_ctrl(x):
    import unicodedata
    x = unicodedata.normalize("NFKD", str(x or ""))
    x = "".join(c for c in x if not unicodedata.combining(c))
    for ch in [",", ".", ":", ";", "*", "-", "_", "/", "(", ")"]:
        x = x.replace(ch, " ")
    return " ".join(x.upper().split())


# Campos del CONTROL de COSCO que se leen por el texto visible de su desplegable y que, si no se pueden leer, dicen
# «no pude leer», nunca «VACÍO» (CICLO-cola-nueve-items.md).
_COSCO_CONTROL_POR_DESPLEGABLE = ("Size Type",)


def _cosco_leer_control(frame, etiqueta):
    """Lo que el CONTROL lee de un campo, o None si no pudo leerlo. Los de _COSCO_CONTROL_POR_DESPLEGABLE se leen
    primero por el texto visible de su desplegable (_JS_COSCO_LEER_DESPLEGABLE); si no, como los demás, con
    _JS_COSCO_ETQ_LEER, que es como se lee Size Type en «Choose Service»."""
    try:
        if etiqueta in _COSCO_CONTROL_POR_DESPLEGABLE:
            visto = frame.evaluate(_JS_COSCO_LEER_DESPLEGABLE, etiqueta)
            if visto:
                return str(visto).strip()
        real = frame.evaluate(_JS_COSCO_ETQ_LEER, etiqueta)
    except Exception:
        return None
    return None if real is None else str(real).strip()


def _cosco_control(frame, reg, etapa, esperados):
    """CONTROL de etapa: lee lo que quedo escrito en pantalla y lo compara con lo
    que se pidio escribir. Usa el mismo localizador que al llenar, para que
    tambien alcance los campos que viven en tablas (Container Info, Cargo
    Information): recorrer solo .el-form-item los daba por vacios.
    Size Type se lee por el texto visible de su desplegable y, si no se puede leer, dice «no pude leer», nunca
    «VACÍO». Hasta 4884157 decía «VACÍO» en Booking Details porque no encontraba el campo
    (CICLO-cola-nueve-items.md)."""
    reg.paso(f"CONTROL · {etapa}")
    todo_ok = True
    sin_leer = []
    for etiqueta, esperado in esperados:
        real = _cosco_leer_control(frame, etiqueta)
        if etiqueta in _COSCO_CONTROL_POR_DESPLEGABLE and not real:
            reg.info(f"   ?  {etiqueta}: no pude leer (esperaba '{esperado}')")
            sin_leer.append(etiqueta)
            continue
        real = real or ""
        if not esperado:
            reg.info(f"   ·  {etiqueta}: {real or '(vacío)'}")
            continue
        if not real:
            reg.info(f"   ✗  {etiqueta}: VACÍO (esperaba '{esperado}')")
            todo_ok = False
        elif _norm_ctrl(esperado) in _norm_ctrl(real) or _norm_ctrl(real) in _norm_ctrl(esperado):
            reg.info(f"   ✓  {etiqueta}: {real}")
        else:
            reg.info(f"   ✗  {etiqueta}: '{real}' (esperaba '{esperado}')")
            todo_ok = False
    if not todo_ok:
        reg.paso(f"OJO: hay campos de '{etapa}' que no quedaron como se pidió.")
    if sin_leer:
        reg.paso(f"OJO: no pude leer {', '.join(sin_leer)} en '{etapa}'; revísalo en la captura.")
    return todo_ok


_JS_COSCO_BUSCAR = """
const _norm = s => (s||'').toUpperCase().replace(/[:*]/g,' ').replace(/\\s+/g,' ').trim();
const _ctrl = e => e && e.querySelector
    ? e.querySelector('input:not([type=checkbox]):not([type=radio]),textarea') : null;
const _visible = e => e && e.offsetParent !== null;
const _campo = (etq) => {
    const E = _norm(etq);
    const calza = t => { const n = _norm(t); return n.indexOf(E) === 0 || n.indexOf(E) > -1; };

    // 1) el-form-item: etiqueta y control viven juntos
    for (const f of [...document.querySelectorAll('.el-form-item')].filter(_visible)) {
        const l = f.querySelector('.el-form-item__label');
        if (l && calza(l.textContent)) {
            const i = _ctrl(f.querySelector('.el-form-item__content') || f);
            if (_visible(i)) return i;
        }
    }
    // 2) tabla: la etiqueta es un encabezado. Element Plus separa thead y tbody en dos <table> dentro de .el-table
    for (const th of [...document.querySelectorAll('th, thead td')].filter(_visible)) {
        if (!calza(th.textContent)) continue;
        const fila = th.parentElement;
        const col = [...fila.children].indexOf(th);
        if (col < 0) continue;
        const elTable = th.closest('.el-table');
        const tabla = th.closest('table');
        const cont = elTable || (tabla ? tabla.parentElement : null) || document;
        const trs = [...cont.querySelectorAll('.el-table__body-wrapper tbody tr, tbody tr')].filter(_visible);
        for (const tr of trs) {
            const celda = tr.children[col];
            if (!celda) continue;
            const i = _ctrl(celda);
            if (_visible(i)) return i;
            if (celda.offsetParent !== null) return celda;
        }
    }
    // 3) etiqueta suelta: el control mas cercano hacia abajo, sin salirse de su celda
    const sueltas = [...document.querySelectorAll('label,span,div,td,p')]
        .filter(e => _visible(e) && calza(e.textContent)
                     && _norm(e.textContent).length < E.length + 15);
    for (const l of sueltas) {
        const celda = l.closest('td,th');
        if (celda) {
            const hermana = celda.nextElementSibling;
            const i = _ctrl(hermana) || _ctrl(celda);
            if (_visible(i)) return i;
            continue;
        }
        let c = l;
        for (let k = 0; k < 3 && c; k++) {
            const i = _ctrl(c);
            if (_visible(i)) return i;
            c = c.parentElement;
        }
    }
    return null;
};
"""

_JS_COSCO_ETQ_FOCO = """(a)=>{""" + _JS_COSCO_BUSCAR + """
    const [etq, val] = a;
    const inp = _campo(etq);
    if (!inp) return 'sin-campo';
    inp.scrollIntoView({block:'center'});
    inp.focus(); try { inp.select(); } catch(e) {}
    const proto = inp.tagName === 'TEXTAREA' ? window.HTMLTextAreaElement.prototype
                                             : window.HTMLInputElement.prototype;
    const s = Object.getOwnPropertyDescriptor(proto,'value').set;
    s.call(inp, val || '');
    inp.dispatchEvent(new Event('input',{bubbles:true}));
    inp.dispatchEvent(new Event('change',{bubbles:true}));
    return inp.readOnly ? 'ok-readonly' : 'ok';
}"""

# Leer .value no alcanza. Los multiselect de Element Plus (Size Type) NO guardan
# nada en el input: el valor son fichas .el-tag al lado.
_JS_COSCO_ETQ_LEER = """(etq)=>{""" + _JS_COSCO_BUSCAR + """
    const inp = _campo(etq);
    if (!inp) {
        const re = new RegExp('^' + etq.trim().replace(/\\s+/g, '.*'), 'i');
        const byPh = [...document.querySelectorAll('input,textarea')].find(e => _visible(e) && re.test(e.placeholder || ''));
        if (byPh) return (byPh.value || '').trim();
        try {
            const normEtq = etq.toUpperCase().replace(/[:*]/g,' ').trim();
            const ths = [...document.querySelectorAll('th, thead td')].filter(_visible);
            const idx = ths.findIndex(th => (th.textContent || '').toUpperCase().replace(/[:*]/g,' ').includes(normEtq));
            if (idx >= 0) {
                const tr = document.querySelector('tbody tr');
                if (tr) {
                    const tds = [...tr.querySelectorAll('td')];
                    if (tds[idx]) {
                        const txt = (tds[idx].textContent || '').trim();
                        if (txt) return txt;
                    }
                }
            }
        } catch(e) {}
        return null;
    }
    const v = (inp.value !== undefined ? inp.value : '').trim();
    if (v) return v;
    const caja = inp.closest('.el-select') || inp.closest('.el-form-item') || inp.closest('td') || inp.parentElement;
    if (caja) {
        let fichas = [...caja.querySelectorAll('.el-tag')];
        if (!fichas.length) fichas = [...caja.querySelectorAll('.el-select__tags-text')];
        const txt = fichas.map(e => (e.textContent || '').replace(/[×✕✖]\\s*$/, '').trim())
                          .filter(Boolean);
        if (txt.length) return txt.join(', ');
        const inner = (inp.textContent || caja.textContent || '').trim();
        if (inner && inner.length < 120) return inner;
    }
    return '';
}"""

# Lee el texto visible de un desplegable de Element Plus ubicado por su placeholder («Please select Size Type»), su
# atributo propio: la opción elegida se ve en el valor de su campo. Devuelve null si no hay exactamente un
# desplegable visible con ese placeholder o si no muestra texto. Medido en la corrida del 2026-09-24: en Booking
# Details la etiqueta «Size Type» está en la fila de encabezados y el desplegable en otra fila, así que
# _JS_COSCO_ETQ_LEER no lo encontraba, y su respaldo por placeholder exige que empiece por la etiqueta
# (CICLO-cola-nueve-items.md).
_JS_COSCO_LEER_DESPLEGABLE = """(etq)=>{
    const E = (etq || '').trim().toUpperCase();
    const campos = [...document.querySelectorAll('.el-select input')]
        .filter(e => e.offsetParent !== null && (e.placeholder || '').toUpperCase().includes(E));
    if (campos.length !== 1) return null;
    return (campos[0].value || '').trim() || null;
}"""

_JS_COSCO_MARCAR = """(etq)=>{""" + _JS_COSCO_BUSCAR + """
    document.querySelectorAll('[data-aq]').forEach(e => e.removeAttribute('data-aq'));
    const inp = _campo(etq);
    if (!inp) return 'sin-campo';
    const clickTarget = inp.closest('.el-select') || inp.closest('.el-select__wrapper') || inp.closest('.el-input') || inp;
    clickTarget.setAttribute('data-aq', '1');
    clickTarget.scrollIntoView({block:'center'});
    return 'ok';
}"""

# Los desplegables de Element Plus se abren con un clic de confianza. El clic
# sintetico de JS no los abre: por eso 'no vi la opcion'. Se marca el control y
# se hace el clic con Playwright, que si genera el evento real.
_JS_COSCO_MARCAR_OPCION = """(txt)=>{
    const T = (txt||'').toUpperCase().trim();
    document.querySelectorAll('[data-aq-op]').forEach(e => e.removeAttribute('data-aq-op'));
    const todas = [...document.querySelectorAll(
        '.el-select-dropdown__item, li[class*=option], .el-scrollbar li, [class*=suggestion] li, [class*=suggestion] div')]
        .filter(e => e.offsetParent !== null);
    let op = todas.find(e => (e.textContent||'').trim().toUpperCase() === T);
    if (!op) op = todas.find(e => (e.textContent||'').toUpperCase().includes(T)
                                  && (e.textContent||'').trim().length < 60);
    if (!op) return '';
    op.setAttribute('data-aq-op', '1');
    op.scrollIntoView({block:'center'});
    return (op.textContent||'').trim().slice(0,45);
}"""

_JS_COSCO_OPCIONES = """()=>{
    return [...document.querySelectorAll(
        '.el-select-dropdown__item, li[class*=option], .el-scrollbar li, [class*=suggestion] li, [class*=suggestion] div')]
        .filter(e => e.offsetParent !== null)
        .map(e => (e.textContent||'').trim())
        .filter(t => t && t.length < 60).slice(0, 12);
}"""

_JS_COSCO_MARCAR_AUTO_OPCION = """(buscado)=>{
    const B = (buscado||'').toUpperCase().trim();
    document.querySelectorAll('[data-aq-op]').forEach(e => e.removeAttribute('data-aq-op'));
    const todos = [...document.querySelectorAll('div, li, p, span, tr, td, a, [role=option]')]
        .filter(e => {
            if (!e.offsetParent && e.offsetWidth === 0 && e.offsetHeight === 0) return false;
            const tag = e.tagName.toLowerCase();
            if (['input', 'textarea', 'select', 'script', 'style'].includes(tag)) return false;
            const r = e.getBoundingClientRect();
            if (r.width <= 0 || r.height <= 0) return false;
            const t = (e.textContent || '').toUpperCase();
            return t.includes(B);
        });
    if (!todos.length) return null;
    let cand = todos.filter(e => {
        const cls = (e.className || '') + ' ' + (e.getAttribute('role') || '');
        return /option|suggestion|item|card|dropdown|popper|list/i.test(cls);
    });
    if (!cand.length) cand = todos;
    cand.sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
    const el = cand[0];
    el.setAttribute('data-aq-op', '1');
    el.scrollIntoView({block: 'center'});
    const r = el.getBoundingClientRect();
    return {
        texto: (el.textContent || '').trim().replace(/\\s+/g, ' ').slice(0, 60),
        x: r.left + r.width / 2,
        y: r.top + r.height / 2
    };
}"""

_JS_COSCO_OPCION = """(txt)=>{
    const T = (txt||'').toUpperCase();
    const todas = [...document.querySelectorAll('.el-select-dropdown__item, li[class*=option], [class*=suggestion] li, [class*=suggestion] div, [role=option], li')]
        .filter(e => e.offsetParent !== null);
    const op = todas.filter(e => (e.textContent||'').trim().toUpperCase() === T);
    const cand = op.length ? op
        : todas.filter(e => (e.textContent||'').toUpperCase().includes(T)
                            && (e.textContent||'').trim().length < 60);
    if (!cand.length) return '';
    cand[0].scrollIntoView({block:'center'});
    try { cand[0].click(); } catch(e){}
    try { cand[0].dispatchEvent(new MouseEvent('click', {bubbles: true, cancelable: true})); } catch(e){}
    return (cand[0].textContent||'').trim().slice(0,45);
}"""


_JS_COSCO_REF_NUM = """()=>{""" + _JS_COSCO_BUSCAR + """
    // La columna 'Rate Reference Number' trae DOS controles: el desplegable con
    // el tipo de referencia y, al lado, el campo donde va el numero de contrato.
    for (const th of [...document.querySelectorAll('th,thead td')].filter(_visible)) {
        if (_norm(th.textContent).indexOf('RATE REFERENCE') !== 0) continue;
        const col = [...th.parentElement.children].indexOf(th);
        const tabla = th.closest('table');
        for (const tr of [...tabla.querySelectorAll('tbody tr')]) {
            const celda = tr.children[col];
            if (!celda) continue;
            const ins = [...celda.querySelectorAll('input')].filter(_visible)
                          .filter(e => !e.readOnly);
            if (ins.length) {
                const inp = ins[ins.length - 1];
                inp.scrollIntoView({block:'center'});
                inp.focus(); try { inp.select(); } catch(e) {}
                const s = Object.getOwnPropertyDescriptor(
                    window.HTMLInputElement.prototype,'value').set;
                s.call(inp, '');
                inp.dispatchEvent(new Event('input',{bubbles:true}));
                return 'ok';
            }
        }
    }
    return 'sin-campo';
}"""


def _cosco_ref_contrato(page, frame, contrato, reg):
    """Numero de contrato dentro de la columna Rate Reference Number."""
    try:
        r = str(frame.evaluate(_JS_COSCO_REF_NUM))
        if r != "ok":
            reg.info("Rate Reference: no encontré el campo del número"); return False
        page.keyboard.type(str(contrato), delay=45)
        page.keyboard.press("Tab")
        reg.info(f"Rate Reference Number = '{contrato}'")
        return True
    except Exception as e:
        reg.info(f"Rate Reference: err {str(e)[:60]}"); return False


def _cosco_fill_etq(page, frame, etiqueta, valor, reg):
    """Escribe en el campo de esa etiqueta con tecleo real."""
    try:
        r = str(frame.evaluate(_JS_COSCO_ETQ_FOCO, [etiqueta, ""]))
        if r.startswith("sin"):
            reg.info(f"{etiqueta}: no encontré el campo"); return False
        page.keyboard.type(str(valor), delay=45)
        page.keyboard.press("Tab")
        esperar(page, 0.4)
        quedo = frame.evaluate(_JS_COSCO_ETQ_LEER, etiqueta)
        reg.info(f"{etiqueta} = '{quedo or valor}'")
        return True
    except Exception as e:
        reg.info(f"{etiqueta}: err {str(e)[:60]}"); return False


# Marca 'Copy from my profile' por su texto y dice si el clic ocurrió. Hasta 83067a1 devolvía 'ok' aunque el
# clic fallara, y el log decía «click en 'Copy from my profile'» (CICLO-clics-a-ciegas.md).
_JS_COSCO_COPIAR_PERFIL = """()=>{
    const labels = [...document.querySelectorAll('label, .el-checkbox, span, div')]
        .filter(e => e.offsetParent !== null && /copy from my profile/i.test(e.textContent || ''));
    for (const l of labels) {
        const cb = l.tagName === 'INPUT' ? l : l.querySelector('input[type=checkbox]') || l;
        cb.scrollIntoView({block: 'center'});
        try { cb.click(); return 'ok'; } catch(e) { return 'fallo'; }
    }
    return 'no';
}"""

# Pulsa la opción que marcó _JS_COSCO_MARCAR_OPCION y dice si la pulsó.
_JS_COSCO_PULSAR_OPCION = "() => { const el = document.querySelector('[data-aq-op]'); if (!el) return false; el.click(); return true; }"


def _cosco_marcar_perfil(frame, reg):
    """Marca la casilla 'Copy from my profile' para auto-rellenar Shipper y dirección."""
    try:
        ok = frame.evaluate(_JS_COSCO_COPIAR_PERFIL)
        if ok == 'ok':
            reg.info("Shipper: click en 'Copy from my profile'")
            return True
        try:
            frame.click("text=/Copy from my profile/i", timeout=2000)
            reg.info("Shipper: frame.click en 'Copy from my profile'")
            return True
        except Exception:
            pass
    except Exception as e:
        reg.info(f"Copy from profile: {str(e)[:60]}")
    return False


def _cosco_auto_etq(page, frame, etiqueta, teclear, buscado, reg):
    """Autocompletado por etiqueta: teclea, espera las sugerencias y elige la que calza."""
    try:
        r = str(frame.evaluate(_JS_COSCO_ETQ_FOCO, [etiqueta, ""]))
        if r.startswith("sin"):
            reg.info(f"{etiqueta}: no encontré el campo"); return False
        page.keyboard.type(str(teclear), delay=70)

        exito = False
        for _ in range(14):                      # las sugerencias tardan
            esperar(page, 0.6)
            info_op = frame.evaluate(_JS_COSCO_MARCAR_AUTO_OPCION, buscado)
            if info_op:
                txt_op = info_op.get("texto", "")
                reg.info(f"{etiqueta}: sugerencia encontrada -> '{txt_op}'")

                # 1. Click real de Playwright en el frame
                try:
                    frame.click("[data-aq-op]", timeout=2000)
                except Exception:
                    pass
                esperar(page, 0.5)

                quedo = str(frame.evaluate(_JS_COSCO_ETQ_LEER, etiqueta) or "").strip()
                street_val = str(frame.evaluate(_JS_COSCO_ETQ_LEER, "Street") or "").strip() if etiqueta.upper() == "SHIPPER" else ""
                if (buscado.upper() in quedo.upper()) or (etiqueta.upper() == "SHIPPER" and len(street_val) > 4):
                    reg.info(f"{etiqueta} = '{quedo or buscado}'")
                    exito = True
                    break

                # 2. Eventos de puntero simulados completos
                frame.evaluate("""()=>{
                    const el = document.querySelector('[data-aq-op]');
                    if (!el) return;
                    ['pointerover','pointerdown','mousedown','pointerup','mouseup','click'].forEach(evt => {
                        el.dispatchEvent(new MouseEvent(evt, {bubbles: true, cancelable: true, view: window}));
                    });
                }""")
                esperar(page, 0.5)

                quedo = str(frame.evaluate(_JS_COSCO_ETQ_LEER, etiqueta) or "").strip()
                street_val = str(frame.evaluate(_JS_COSCO_ETQ_LEER, "Street") or "").strip() if etiqueta.upper() == "SHIPPER" else ""
                if (buscado.upper() in quedo.upper()) or (etiqueta.upper() == "SHIPPER" and len(street_val) > 4):
                    reg.info(f"{etiqueta} = '{quedo or buscado}' (pointer)")
                    exito = True
                    break

                # 3. Hasta fb63271, el teclado: flecha abajo y Enter elegían la opción que quedara ahí, fuera cual
                #    fuera (CICLO-cola-nueve-items.md). Ahora no se elige a ciegas: la reserva corta.
                raise ObjetivoNoEncontrado(f"{etiqueta} de COSCO", f"la sugerencia «{txt_op}» elegida en el campo (el "
                                                                   f"clic y los eventos de puntero no la dejaron; con el "
                                                                   f"teclado sería a ciegas)")

        if etiqueta.upper() == "SHIPPER":
            # Si aún no quedó seleccionado, probar 'Copy from my profile'
            quedo = str(frame.evaluate(_JS_COSCO_ETQ_LEER, "Shipper") or "").strip()
            street_val = str(frame.evaluate(_JS_COSCO_ETQ_LEER, "Street") or "").strip()
            if not ("AQUACHILE" in quedo.upper()) or not street_val:
                reg.info("Shipper: activando 'Copy from my profile'...")
                _cosco_marcar_perfil(frame, reg)
                esperar(page, 1.2)
                quedo = str(frame.evaluate(_JS_COSCO_ETQ_LEER, "Shipper") or "").strip()
                street_val = str(frame.evaluate(_JS_COSCO_ETQ_LEER, "Street") or "").strip()
                if "AQUACHILE" in quedo.upper() or len(street_val) > 4:
                    reg.info(f"Shipper = '{quedo or COSCO_SHIPPER}' (perfil activado)")
                    exito = True

            # Si Street sigue vacío, rellenar campos directamente
            street_val = str(frame.evaluate(_JS_COSCO_ETQ_LEER, "Street") or "").strip()
            if not street_val:
                reg.info("Shipper: completando campos de dirección directamente...")
                _cosco_fill_etq(page, frame, "Shipper", COSCO_SHIPPER, reg)
                _cosco_fill_etq(page, frame, "Street", COSCO_STREET, reg)
                _cosco_fill_etq(page, frame, "City", COSCO_CITY, reg)
                _cosco_select_etq(page, frame, "Country", COSCO_COUNTRY, reg)

            quedo = str(frame.evaluate(_JS_COSCO_ETQ_LEER, "Shipper") or "").strip()
            reg.info(f"Shipper final = '{quedo or COSCO_SHIPPER}'")
            return True

        if exito:
            return True
        reg.info(f"{etiqueta}: sin sugerencia para '{buscado}'")
        return False
    except Exception as e:
        reg.info(f"{etiqueta}: err {str(e)[:60]}"); return False


def _cosco_select_etq(page, frame, etiqueta, opcion, reg):
    """Desplegable por etiqueta. Abre con CLIC REAL (el sintetico no lo abre) y
    elige la opcion tambien con clic real. Si la opcion no esta, deja escritas
    las que si ofrece el portal para poder corregir el texto esperado."""
    try:
        # Si ya tiene el valor deseado, no tocar
        quedo = frame.evaluate(_JS_COSCO_ETQ_LEER, etiqueta)
        if quedo and (opcion.upper() in str(quedo).upper() or str(quedo).upper() in opcion.upper()):
            reg.info(f"{etiqueta} ya es '{quedo}'")
            return True

        if str(frame.evaluate(_JS_COSCO_MARCAR, etiqueta)) != "ok":
            reg.info(f"{etiqueta}: no encontré el desplegable"); return False
        try:
            frame.click("[data-aq]", timeout=3000)
        except Exception:
            frame.evaluate("() => { const el = document.querySelector('[data-aq]'); if(el) el.click(); }")
        esperar(page, 0.8)
        elegido = str(frame.evaluate(_JS_COSCO_MARCAR_OPCION, opcion) or "")
        if not elegido:
            esperar(page, 0.8)
            elegido = str(frame.evaluate(_JS_COSCO_MARCAR_OPCION, opcion) or "")
        if not elegido:
            try:
                ofrece = frame.evaluate(_JS_COSCO_OPCIONES) or []
            except Exception:
                ofrece = []
            reg.info(f"{etiqueta}: no vi '{opcion}'. El portal ofrece: "
                     f"{', '.join(ofrece) if ofrece else '(no se abrió el desplegable)'}")
            return False
        pulso = True
        try:
            frame.click("[data-aq-op]", timeout=4000)
        except Exception:
            pulso = bool(frame.evaluate(_JS_COSCO_PULSAR_OPCION))
        esperar(page, 0.5)
        if not pulso:
            # Hasta 83067a1 decía «{etiqueta} = '{elegido}'» aunque ningún clic hubiera ocurrido.
            reg.info(f"{etiqueta}: no pude pulsar la opción '{elegido}'")
            return False
        quedo = frame.evaluate(_JS_COSCO_ETQ_LEER, etiqueta)
        reg.info(f"{etiqueta} = '{quedo or elegido}'")
        return True
    except Exception as e:
        reg.info(f"{etiqueta}: err {str(e)[:60]}"); return False


def _cosco_fill_id(page, frame, ph_regex, valor, reg, etiqueta):
    """Rellena un input del frame por placeholder con TECLEO REAL (lo registra el validador)."""
    try:
        ok = str(frame.evaluate("""(rx)=>{
            const re=new RegExp(rx,'i');
            const inp=[...document.querySelectorAll('input,textarea')].find(e=>e.offsetParent && re.test(e.placeholder||''));
            if(!inp) return 'no';
            inp.focus(); try{inp.select();}catch(e){}
            const s=Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;
            s.call(inp,''); inp.dispatchEvent(new Event('input',{bubbles:true}));
            return 'ok';
        }""", ph_regex))
        if ok != "ok":
            reg.info(f"{etiqueta}: {ok}"); return False
        page.keyboard.type(str(valor), delay=55)   # teclas reales al campo enfocado del iframe
        page.keyboard.press("Tab")
        reg.info(f"{etiqueta}='{valor}': ok")
        return True
    except Exception as e:
        reg.info(f"{etiqueta}: err {str(e)[:60]}")
        return False


def _cosco_click_btn(frame, regex, reg):
    try:
        return bool(frame.evaluate("""(rx)=>{const re=new RegExp(rx,'i');
            const b=[...document.querySelectorAll('button,a,[class*=btn]')]
              .find(e=>e.offsetParent && re.test((e.textContent||'').trim()));
            if(b){b.scrollIntoView({block:'center'});b.click();return true;}return false;}""", regex))
    except Exception:
        return False


# Mapeo de puertos chilenos para COSCO: Biobío/Coronel embarca vía terminal Lirquén en el servicio de COSCO (visto en
# video manual). Traduce el puerto de carga de la fila ya normalizado (_cosco_puerto_de_la_celda: en mayúsculas, sin
# tildes y sin el país). Hasta c4df3ab traducía la celda entera, así que «CORONEL, CHILE» o «Lirquén» no se traducían.
MAPA_PUERTOS_COSCO = {
    "CORONEL": "Lirquen",
    "PUERTO CORONEL": "Lirquen",
    "LIRQUEN": "Lirquen",
    "PUERTO LIRQUEN": "Lirquen",
    "CONCEPCION": "Lirquen",
    "SAN VICENTE": "San Vicente",
    "SAN ANTONIO": "San Antonio",
    "VALPARAISO": "Valparaiso",
}


def _cosco_puerto_de_la_celda(celda):
    """El puerto de carga de la celda, normalizado antes de MAPA_PUERTOS_COSCO (decisión de Marcelo,
    CICLO-inicio-de-todas.md): la parte antes de la primera coma, en mayúsculas y sin tildes (_norm_ctrl), con todo lo
    que no es letra ni número como separador, y sin el país al final (PAIS_DEL_PUERTO: «CHILE» o «CL»), las veces que
    venga: el origen de COSCO siempre es de Chile (preferir_chile). Así «CORONEL, CHILE», «Coronel (Chile)», «CORONEL -
    CHILE», «CORONEL–CHILE» y «CORONEL CL» dan «CORONEL», y «Lirquén», «LIRQUEN». En medio del nombre, el país queda.
    Vacío si la celda no trae el puerto («», «, CHILE», «CHILE», «CL»): buscar el texto vacío, o solo el país, calzaría
    con cualquier sugerencia de Chile. «CL» se quita desde el encargo 46 (decisión de Marcelo,
    CICLO-maersk-pulsa-el-book.md): hasta ahí, solo «CHILE», y COSCO buscaba, por ejemplo, «CORONEL CL»."""
    palabras = _re_mk.sub(r"[^0-9A-Z]+", " ", _norm_ctrl(str(celda or "").split(",")[0])).split()
    while palabras and palabras[-1] in PAIS_DEL_PUERTO:
        palabras = palabras[:-1]
    return " ".join(palabras)


def _cosco_traduccion(celda):
    """El puerto desde el que COSCO arma la reserva cuando MAPA_PUERTOS_COSCO cambia el puerto de carga de la celda
    (_puerto_de_carga) por otro puerto; "" si no lo cambia: si no está en el mapa, o si el mapa solo cambia cómo se
    escribe, porque todas las palabras del puerto del mapa, normalizadas (_cosco_puerto_de_la_celda), están en el de la
    celda («Lirquén», «PUERTO LIRQUEN» o «San Antonio, Chile»). Así «CORONEL», «PUERTO CORONEL» y «Concepción» dan
    «Lirquen» (decisión de Marcelo, encargo 50: el mapa se mantiene, y log.txt y el motivo lo dicen)."""
    puerto = _puerto_de_carga(celda)
    otro = MAPA_PUERTOS_COSCO.get(puerto, "")
    return otro if otro and not set(_cosco_puerto_de_la_celda(otro).split()) <= set(puerto.split()) else ""


def _cosco_puerto_de_carga(frame, reserva, reg):
    """Elige en «Origin City» de COSCO el puerto de carga de la fila: su celda normalizada (_cosco_puerto_de_la_celda) y
    traducida por MAPA_PUERTOS_COSCO o, si no está ahí, tal como quedó al normalizarla, con una sugerencia de Chile
    (_cosco_autocomplete). Devuelve lo que buscó. Si la celda no trae el puerto, o si COSCO no deja elegir una sugerencia
    de Chile para él (también si no encuentra el campo o la búsqueda falla: log.txt lo dice antes), levanta
    ObjetivoNoEncontrado: la reserva queda NO ENVIADA, con la captura y el HTML (decisión de Marcelo,
    CICLO-cola-seis-items.md). Sin una palabra que no sea el país (_puerto_de_carga: «X», «X CHILE» o «CHILE X»), la
    celda no trae el puerto (revisiones del encargo 42).
    Hasta f68ce6c, sin sugerencia buscaba desde un puerto fijo del código, «Lirquen», y seguía aunque esa segunda
    búsqueda tampoco eligiera nada; si el puerto de la fila ya era «Lirquen», seguía sin elegir; y con la celda vacía
    podía elegir la primera sugerencia de Chile a la vista (cualquier texto calza con una búsqueda vacía) o caer al
    puerto fijo. Medido el 2026-09-26 en los 9 log.txt de logs/ (corridas del 2026-09-21 al 25): de las 19 reservas de
    COSCO, 18 llegaron a este paso, y en las 18 la primera búsqueda, con el puerto de la fila o el del mapa, eligió su
    sugerencia; ninguna cayó al puerto fijo.
    Desde el encargo 50, si MAPA_PUERTOS_COSCO tradujo el puerto de la celda a otro puerto (_cosco_traduccion), con la
    sugerencia ya elegida lo dice en pantalla y en log.txt, y deja en el Registro la nota que _con_el_puerto_de_cosco
    suma al motivo de la reserva: desde qué puerto se armó y qué dice la fila (decisión de Marcelo)."""
    celda = (reserva.get("pol") or "").strip()
    puerto = _puerto_de_carga(celda)
    pol_ciudad = MAPA_PUERTOS_COSCO.get(puerto, puerto)
    if not pol_ciudad:
        raise ObjetivoNoEncontrado("Origin City de COSCO",
                                   "el puerto de carga en la fila (la celda no trae su nombre; escríbelo en la planilla)")
    if not _cosco_autocomplete(frame, "origin ci", pol_ciudad, pol_ciudad, reg, "Origin City", preferir_chile=True,
                               evidencia=f"cosco_f{reserva.get('fila')}_origen"):
        en_la_fila = "" if celda.upper() == pol_ciudad.upper() else f" (en la fila, «{celda}»)"
        raise ObjetivoNoEncontrado("Origin City de COSCO",
                                   f"una sugerencia de Chile para el puerto de carga «{pol_ciudad}»{en_la_fila}")
    if _cosco_traduccion(celda):
        reg.paso(f"⚠ COSCO: el puerto de carga de la fila, «{celda}», lo traduce MAPA_PUERTOS_COSCO a «{pol_ciudad}»: "
                 f"la reserva se arma desde «{pol_ciudad}».")
        reg.cosco_puerto = (f"puerto de carga: COSCO la arma desde «{pol_ciudad}»; la fila dice «{celda}» "
                            f"(MAPA_PUERTOS_COSCO)")
    return pol_ciudad


# «Sailing Within N Weeks», el desplegable con que COSCO fija cuántas semanas busca, en el panel «Sailing Schedule» de
# Choose Service. Medido en las dos listas guardadas (cosco_f<fila>_itinerarios_marco2.html, 2026-09-25): un el-select
# cuyo campo nombra en aria-controls su lista (un ul con id), que trae solo las opciones de «Sailing Within 2 Weeks» a
# «Sailing Within 8 Weeks», oculta mientras está cerrada, con la elegida marcada (clase selected y aria-selected): la de
# 2. El campo se reconoce por esa lista, y las semanas elegidas, por esa marca: el valor del campo no queda en el HTML
# guardado (hasta el commit anterior se leía de ahí, y sobre las dos listas guardadas no veía ningún campo). Con
# 'marcar' = "campo" marca el campo; con "opcion", la opción con más semanas, si hay una sola a la vista. Devuelve
# cuántos campos hay a la vista y, si hay uno solo, las semanas elegidas (null si no hay una sola marcada) y las de la
# más larga.
_JS_COSCO_SEMANAS = """(marcar)=>{
    const rx = /^\\s*Sailing Within (\\d+) Weeks?\\s*$/i;
    const vis = e => e.offsetParent !== null;
    const semanas = t => parseInt(t.match(rx)[1], 10);
    document.querySelectorAll('[data-aq-semanas]').forEach(e => e.removeAttribute('data-aq-semanas'));
    const listas = [...document.querySelectorAll('ul')].filter(u => {
        const lis = [...u.querySelectorAll('li')];
        return u.id && lis.length > 0 && lis.every(li => rx.test(li.textContent || ''));
    });
    const campos = [...document.querySelectorAll('input')]
        .filter(e => vis(e) && listas.some(u => e.getAttribute('aria-controls') === u.id));
    if (campos.length !== 1) return {campos: campos.length};
    const opciones = [...listas.find(u => campos[0].getAttribute('aria-controls') === u.id).querySelectorAll('li')];
    const elegidas = opciones.filter(li => li.classList.contains('selected')
        || li.getAttribute('aria-selected') === 'true');
    const r = {campos: 1, actual: elegidas.length === 1 ? semanas(elegidas[0].textContent) : null,
               mayor: Math.max(...opciones.map(li => semanas(li.textContent))), marcada: false};
    if (marcar === 'campo') {
        campos[0].setAttribute('data-aq-semanas', '1');
        r.marcada = true;
    }
    if (marcar === 'opcion') {
        const la = opciones.filter(li => vis(li) && semanas(li.textContent) === r.mayor);
        if (la.length === 1) {
            la[0].setAttribute('data-aq-semanas', '1');
            r.marcada = true;
        }
    }
    return r;
}"""


def _cosco_semanas(frame, marcar=""):
    """_JS_COSCO_SEMANAS en el marco del formulario; {} si la lectura falla."""
    try:
        return frame.evaluate(_JS_COSCO_SEMANAS, marcar) or {}
    except Exception:
        return {}


def _cosco_ampliar(page, frame, reg):
    """Amplía la búsqueda de COSCO a su «Sailing Within N Weeks» más largo (decisión de Marcelo,
    CICLO-ampliar-la-busqueda.md): el único campo a la vista con ese texto y la opción con más semanas, por su texto
    (_JS_COSCO_SEMANAS), abiertos y elegidos con clic real, como _cosco_select_etq. No pulsa «Search Service».
    Devuelve "" si quedó elegida una más larga que la de antes; si no, por qué no se amplió, para _hasta_donde_busque:
    si ya estaba en la más larga, el portal no deja ampliar más (NO_AMPLIA_MAS)."""
    r = _cosco_semanas(frame)
    if r.get("campos") != 1:
        return f"no pude ampliar la búsqueda: había {r.get('campos', 0)} campos «Sailing Within» a la vista"
    antes = r["actual"]
    if antes is None:
        return "no pude ampliar la búsqueda: no pude leer qué opción de «Sailing Within» está elegida"
    if r.get("mayor") is not None and r["mayor"] <= antes:
        return NO_AMPLIA_MAS
    try:
        _cosco_semanas(frame, "campo")
        frame.click("[data-aq-semanas]", timeout=3000)
        esperar(page, 0.8)
        r = _cosco_semanas(frame, "opcion")
        if r.get("mayor") is None or r["mayor"] <= antes:
            return NO_AMPLIA_MAS
        if not r.get("marcada"):
            return f"no pude ampliar la búsqueda: no vi una sola opción «Sailing Within {r['mayor']} Weeks»"
        frame.click("[data-aq-semanas]", timeout=4000)
        esperar(page, 0.6)
    except Exception as e:
        return f"no pude ampliar la búsqueda: el clic en «Sailing Within» falló ({str(e)[:50]})"
    quedo = _cosco_semanas(frame).get("actual")
    if quedo != r["mayor"]:
        return f"no pude ampliar la búsqueda: «Sailing Within» quedó en {quedo} semanas, no en {r['mayor']}"
    reg.info(f"búsqueda ampliada: «Sailing Within {antes} Weeks» -> «Sailing Within {quedo} Weeks»")
    return ""


def _cosco_leer_itinerarios(page, frame, reg, antes=0):
    """Los itinerarios de la lista (_JS_COSCO_LISTA_NAVES), con hasta 15 lecturas mientras no llega ninguno, o COSCO no
    dice que no hay. Con 'antes' (después de ampliar), espera también a que haya más que esos, y si no llegan, se queda
    con lo que hay. None si el operador detuvo la corrida."""
    filas = []
    for intento in range(15):
        if _WEB.get("detener") and _WEB["detener"].is_set():
            return None
        try:
            filas = frame.evaluate(_JS_COSCO_LISTA_NAVES) or []
        except Exception as e:
            reg.info(f"error leyendo itinerarios: {str(e)[:60]}")
        if filas and len(filas) > antes:
            break
        # Si COSCO muestra explícitamente que no hay resultados tras esperar al menos 4s
        sin_res = False
        try:
            sin_res = frame.evaluate("""() => {
                const b = (document.body ? document.body.innerText : '').toLowerCase();
                return b.includes('no service') || b.includes('no record') || b.includes('no matching');
            }""")
        except Exception:
            pass
        if sin_res and intento >= 4:
            reg.info("COSCO reporta explícitamente sin itinerarios disponibles.")
            break
        esperar(page, 1.0)
    return filas


def _cosco_sin_formulario(page, reg, f, que, desde):
    """New Booking de COSCO sin su formulario ('que' dice qué faltó: su marco bkg2, o sus campos): deja la captura de la
    ventana y el HTML de la página y de sus marcos (cosco_f<fila>_sin_formulario), y la reserva queda NO ENVIADA, con lo
    que faltó y los segundos desde que abrió New Booking ('desde', de time.monotonic). Decisión de Marcelo, encargo 48
    (CICLO-calendario-cosco-y-cma.md): hasta ahí quedaba REVISAR, que en COSCO queda solo para la nave no encontrada,
    y su HTML no se guardaba (sin los campos, solo con AQUASHIELD_DESCUBRIR; sin el marco, nunca). Así quedó el
    2026-10-02, sin poder medir qué mostraba (CICLO-msc-recarga-y-corrida-02-10.md)."""
    segundos = time.monotonic() - desde
    _evidencia_antes_de_la_guarda(page, reg, f"cosco_f{f}_sin_formulario", "sin el formulario de New Booking",
                                  completa=False)
    return _no_enviada(reg, f"COSCO: abrí New Booking y {que} en {segundos:.0f} s; no pulsé nada y la reserva no se "
                            f"envió")


def _con_el_puerto_de_cosco(reservar):
    """Decorador de reservar_cosco: si _cosco_puerto_de_carga eligió en «Origin City» el puerto al que
    MAPA_PUERTOS_COSCO tradujo el de la fila (_cosco_traduccion), el motivo de la reserva termina diciéndolo, sea cual
    sea su estado: desde qué puerto la arma COSCO y qué dice la fila (decisión de Marcelo, encargo 50,
    CICLO-msc-segundo-intento.md). Toma la nota que _cosco_puerto_de_carga deja en el Registro, que borra antes y
    después de cada reserva. Va por fuera de todos, y así por fuera de _sin_clic_a_ciegas, para que también la diga el
    motivo de un paso sin su objetivo; la fila sin nave o sin ruta no llega a dejarla."""
    def reservar_con_el_puerto(page, reserva, creds, reg, on_pausa=None):
        vars(reg).pop("cosco_puerto", None)
        try:
            estado, detalle = reservar(page, reserva, creds, reg, on_pausa=on_pausa)
        finally:
            nota = vars(reg).pop("cosco_puerto", "")
        return (estado, " · ".join(x for x in (detalle, nota) if x)) if nota else (estado, detalle)
    reservar_con_el_puerto.__name__ = reservar.__name__
    reservar_con_el_puerto.__doc__ = reservar.__doc__
    return reservar_con_el_puerto


@_con_el_puerto_de_cosco
@_con_la_nave_de_la_fila
@_con_la_ruta_de_la_fila
@_sin_clic_a_ciegas("cosco")
def reservar_cosco(page, reserva, creds, reg, on_pausa=None):
    if _WEB.get("detener") and _WEB["detener"].is_set():
        return ("DETENIDO", "Cancelado por el operador")

    f = reserva["fila"]
    reg.paso(f"[COSCO fila {f}] {reserva['pol']} -> {reserva['destino_final']} | NAVE: {reserva['nave']}")
    _avisar_dia_carga(reserva, reg)

    # La pantalla New Booking se abre directo por URL (sin pelear con el menú)
    desde = time.monotonic()
    try:
        page.goto("https://elines.coscoshipping.com/ebusiness/bookingrequest/",
                  wait_until="domcontentloaded")
    except Exception as e:
        reg.info(f"goto booking: {str(e)[:60]}")
    _cosco_esperar_contenido(page, "origin|service|booking", 8, reg, "cargar New Booking")
    frame = _cosco_frame(page, reg)
    if not frame:
        reg.captura(page, f"cosco_f{f}_err", full=True)
        return _cosco_sin_formulario(page, reg, f, "no apareció el marco de su formulario (bkg2)", desde)
    # Esperar a que el formulario del iframe (bkg2) renderice sus campos
    listo = False
    for _ in range(20):
        if _WEB.get("detener") and _WEB["detener"].is_set():
            return ("DETENIDO", "Cancelado por el operador")
        frame = _cosco_frame(page, reg, intentos=1) or frame
        try:
            n = int(frame.evaluate("""()=>[...document.querySelectorAll('input')]
                .filter(e=>/origin ci/i.test(e.placeholder||'')).length"""))
        except Exception:
            n = 0
        if n:
            listo = True; break
        esperar(page, 1.5)
    reg.info(f"formulario bkg2 {'listo' if listo else 'NO cargó campos'}")
    reg.captura(page, f"cosco_f{f}_1_choose", full=True)
    if not listo:
        if os.environ.get("AQUASHIELD_DESCUBRIR"):
            _guardar_html(page, "cosco_dump.html", reg)
        return _cosco_sin_formulario(page, reg, f, "su formulario (el marco bkg2) no mostró sus campos («Origin City»)",
                                     desde)

    # ---- Paso 1: Choose Service ----
    reg.paso("Paso 1 · Choose Service (ruta)...")

    pol_ciudad = _cosco_puerto_de_carga(frame, reserva, reg)
    dest_ciudad = _ciudad_de(reserva.get("destino_final") or reserva.get("destino_orig"))
    esperar(page, 0.3)

    # Antes de elegir, la evidencia de la lista de sugerencias (decisión de Marcelo, CICLO-origen-y-destino.md).
    # Sin una sugerencia elegida, NO ENVIADA, como el origen (_cosco_puerto_de_carga): hasta el encargo 42 la reserva
    # seguía sin el destino (decisión de Marcelo, CICLO-maersk-y-fila-sin-ruta.md).
    if not _cosco_autocomplete(frame, "destinati", dest_ciudad, dest_ciudad, reg, "Destination",
                               evidencia=f"cosco_f{f}_destino"):
        raise ObjetivoNoEncontrado("Destination de COSCO", _sugerencia_que_elegir(dest_ciudad))
    esperar(page, 0.4)   # al elegir ruta se autocompletan Door/Booking Office/Contrato

    # Contrato: el portal rellena el primero de la cuenta; el de la fila o el de las credenciales, si viene, va
    # encima (el de destino Asia/China, en config.json).
    c_rsv = str(reserva.get("cotizacion") or "").strip()
    c_cfg = str((creds or {}).get("contrato") or "").strip()
    if c_rsv and not c_rsv.startswith("(") and "cuenta" not in c_rsv.lower() and "directo" not in c_rsv.lower():
        contrato = c_rsv
    elif c_cfg and not c_cfg.startswith("(") and "cuenta" not in c_cfg.lower() and "directo" not in c_cfg.lower():
        contrato = c_cfg
    else:
        contrato = ""

    if contrato:
        _cosco_autocomplete(frame, "contract number", contrato, contrato, reg, "Contract Number")
        esperar(page, 0.3)
    else:
        reg.info("sin contrato manual específico: queda el contrato de la cuenta del portal")

    # Asegurar modo puerto a puerto CY/CY (si ya está en CY, no abre el desplegable)
    _cosco_select_etq(page, frame, "Door Pickup", "CY", reg)
    _cosco_select_etq(page, frame, "Door Delivery", "CY", reg)
    esperar(page, 0.2)
    reg.captura(page, f"cosco_f{f}_2_ruta", full=True)

    _cosco_control(frame, reg, "Choose Service", [
        ("Origin City", pol_ciudad),
        ("Destination", dest_ciudad),
        ("Contract Number", contrato),
        ("Cargo Nature", "Reefer"),
        ("Size Type", "40RQ"),
        ("Door Pickup", "CY"),
        ("Door Delivery", "CY"),
        ("Booking Office", ""),
    ])

    if _WEB.get("detener") and _WEB["detener"].is_set():
        return ("DETENIDO", "Cancelado por el operador")

    # Buscar itinerarios (los campos POL y POD inferiores quedan vacíos igual que en la grabación manual)
    reg.paso("Buscando itinerarios (Search Service)...")
    _cosco_click_btn(frame, "search service", reg)
    _cosco_esperar_contenido(page, r"book\s+now|no\s+record|no\s+service", 12, reg, "resultados de itinerarios", minimo=1.5)

    # Seleccionar la NAVE por nombre
    reg.paso(f"Buscando la nave '{reserva['nave']}' en los itinerarios...")
    toks_nave = [t for t in (reserva["nave"] or "").upper().replace("/", " ").split() if len(t) > 1]
    toks_todos = list(toks_nave)
    if reserva.get("viaje"):
        for t in reserva["viaje"].upper().split():
            if t not in toks_todos and len(t) > 1:
                toks_todos.append(t)

    # Si la nave, o su viaje, no está en lo que COSCO muestra de entrada, amplía «Sailing Within» a lo más largo y
    # vuelve a buscar, una vez (decisión de Marcelo, CICLO-ampliar-la-busqueda.md). Hasta 4cae528 cortaba con lo primero
    # que veía.
    filas, ampliada, por_que = [], False, ""
    while True:
        antes = len(filas) if ampliada else 0
        filas = _cosco_leer_itinerarios(page, frame, reg, antes=antes)
        if filas is None:
            return ("DETENIDO", "Cancelado por el operador")
        filas = _cosco_con_salida(filas)
        cand = _cosco_calzan(filas, toks_nave, toks_todos)
        if ampliada or (cand and not _cosco_sin_el_viaje(cand, toks_todos)):
            break
        por_que = _cosco_ampliar(page, frame, reg)
        if por_que:
            reg.info(f"no amplié la búsqueda: {por_que}")
            break
        reg.paso("La nave no estaba en lo que mostró COSCO: amplié «Sailing Within» y busco de nuevo.")
        _cosco_click_btn(frame, "search service", reg)
        esperar(page, 2.0)
        ampliada, por_que = True, NO_AMPLIA_MAS
    if _cosco_sin_el_viaje(cand, toks_todos):
        return _cosco_itinerario_ambiguo(page, reg, reserva, cand, "sin-viaje")

    modo = ""
    elegido, motivo = _cosco_elegir_itinerario(cand, reserva) if cand else (None, "")
    if cand and elegido is None:
        return _cosco_itinerario_ambiguo(page, reg, reserva, cand, motivo)
    if len(cand) > 1:
        reg.info(f"{len(cand)} itinerarios calzan con '{reserva['nave']}'; elijo la próxima salida desde el "
                 f"{_desde(reserva):%d-%m-%Y}: ETD {elegido['etd']}")
        _anotar_desempate(reg, _cosco_salidas(cand), _desde(reserva), _cosco_transito)
    if elegido:
        try:
            if frame.evaluate(_JS_COSCO_CLIC_NAVE, elegido["i"]):
                modo = _cosco_resumen(elegido)
                reg.info(f"nave elegida -> {modo}")
        except Exception as e:
            reg.info(f"error al seleccionar: {str(e)[:60]}")
    if not modo:
        ofrecidos = " | ".join(_cosco_resumen(x) for x in filas[:6])
        reg.paso(f"La nave '{reserva['nave']}' NO está en los itinerarios de COSCO.")
        reg.info(f"itinerarios ofrecidos: {ofrecidos[:400]}")
        reg.captura(page, f"cosco_f{f}_3_sinnave", full=True)
        donde = "" if cand else f": {_hasta_donde_busque([d for d, _ in _cosco_salidas(filas)], por_que)}"
        return ("REVISAR", f"nave '{reserva['nave']}' no está en COSCO{donde} (ofrecidos: {ofrecidos[:180]})")

    if _WEB.get("detener") and _WEB["detener"].is_set():
        return ("DETENIDO", "Cancelado por el operador")

    # Esperar activamente a que el iframe bkg2 termine de cargar el Paso 2 (Booking Details)
    reg.paso("Cargando Booking Details (esperando formulario)...")
    listo_detalles = False
    for seg_idx in range(30):
        if _WEB.get("detener") and _WEB["detener"].is_set():
            return ("DETENIDO", "Cancelado por el operador")
        esperar(page, 0.8)
        frame = _cosco_frame(page, reg, intentos=1) or frame
        if not frame:
            continue
        try:
            res_chk = frame.evaluate("""() => {
                const bodyText = (document.body ? document.body.innerText : '') || '';
                if (bodyText.includes('Search Results') && !bodyText.includes('Container Info')) return false;
                const inps = [...document.querySelectorAll('input, textarea')].filter(e => e.offsetParent !== null);
                const hasWeight = inps.some(e => /gross weight/i.test(e.placeholder || ''));
                const hasContainer = /Container Info/i.test(bodyText) || /Party/i.test(bodyText);
                return (hasWeight || (hasContainer && inps.length >= 4));
            }""")
            if res_chk:
                listo_detalles = True
                reg.info(f"Booking Details listo ({seg_idx * 0.8:.1f}s)")
                break
        except Exception:
            pass

    if not listo_detalles:
        reg.info("Booking Details tardó en responder; esperando 3s adicionales...")
        esperar(page, 3.0)
        frame = _cosco_frame(page, reg, intentos=2) or frame

    reg.captura(page, f"cosco_f{f}_4_detalles", full=True)

    # ---- Paso 2: Booking Details ----
    reg.paso("Paso 2 · Booking Details (carga reefer)...")
    cant_str = str(reserva.get("cant", 1) or 1)

    # 1. Quantity: fill_id, fill_etq o selector directo
    ok_qty = _cosco_fill_id(page, frame, "^quantity$|quantity", cant_str, reg, "Quantity") or _cosco_fill_etq(page, frame, "Quantity", cant_str, reg)
    if not ok_qty:
        try:
            res_q = frame.evaluate("""(val) => {
                const inps = [...document.querySelectorAll('input')].filter(e => e.offsetParent !== null);
                const qInp = inps.find(e => /quantity/i.test(e.placeholder || '')) ||
                             inps.find(e => e.value === '0' || e.placeholder === '0');
                if (qInp) {
                    qInp.focus();
                    const s = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
                    s.call(qInp, val);
                    qInp.dispatchEvent(new Event('input', {bubbles: true}));
                    qInp.dispatchEvent(new Event('change', {bubbles: true}));
                    return true;
                }
                return false;
            }""", cant_str)
            if res_q:
                reg.info(f"Quantity = '{cant_str}' (vía selector directo)")
                ok_qty = True
        except Exception:
            pass

    # 2. Gross Weight (el de config.json): fill_id, fill_etq o selector directo
    peso_kg = _peso_reefer()
    ok_gw = _cosco_fill_id(page, frame, "gross weight", peso_kg, reg, "Gross Weight") or _cosco_fill_etq(page, frame, "Gross Weight", peso_kg, reg)
    if not ok_gw:
        try:
            res_gw = frame.evaluate("""(val) => {
                const inps = [...document.querySelectorAll('input')].filter(e => e.offsetParent !== null);
                const gwInp = inps.find(e => /gross weight/i.test(e.placeholder || ''));
                if (gwInp) {
                    gwInp.focus();
                    const s = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
                    s.call(gwInp, val);
                    gwInp.dispatchEvent(new Event('input', {bubbles: true}));
                    gwInp.dispatchEvent(new Event('change', {bubbles: true}));
                    return true;
                }
                return false;
            }""", peso_kg)
            if res_gw:
                reg.info(f"Gross Weight = '{peso_kg}' (vía selector directo)")
                ok_gw = True
        except Exception:
            pass

    # 3. Temperature: -20
    _cosco_fill_id(page, frame, "^temperature$|temperature", _temp_reserva(reserva), reg, "Temperature") or _cosco_fill_etq(page, frame, "Temperature", _temp_reserva(reserva), reg)
    esperar(page, 0.3)
    if os.environ.get("AQUASHIELD_DESCUBRIR"):
        _guardar_html(page, "cosco_dump.html", reg)

    # 4. Datos requeridos en Booking Details según el flujo del video de referencia:
    _cosco_auto_etq(page, frame, "Shipper", "AQUA", COSCO_SHIPPER, reg)
    esperar(page, 0.3)
    reg.captura(page, f"cosco_f{f}_4b_shipper", full=True)
    _cosco_auto_etq(page, frame, "Cargo Descriptions", "FROZ", COSCO_DESC_CARGA, reg)
    esperar(page, 0.3)
    _cosco_fill_etq(page, frame, "HS Code", COSCO_HS_CODE, reg)
    esperar(page, 0.2)
    _cosco_select_etq(page, frame, "Generator Set", COSCO_GENSET, reg)
    esperar(page, 0.2)

    _cosco_fill_etq(page, frame, "Remark", COSCO_REMARK, reg)
    esperar(page, 0.2)
    correo = str((creds or {}).get("usuario") or "").strip()
    if "@" in correo:
        _cosco_fill_etq(page, frame, "booking confirmation sent", correo, reg)
        esperar(page, 0.2)

    # Verificación estricta de campos obligatorios antes de pulsar Submit
    try:
        gw_actual = frame.evaluate("""() => {
            const inps = [...document.querySelectorAll('input')].filter(e => e.offsetParent !== null);
            const gw = inps.find(e => /gross weight/i.test(e.placeholder || ''));
            return gw ? gw.value : '';
        }""")
        qty_actual = frame.evaluate("""() => {
            const inps = [...document.querySelectorAll('input')].filter(e => e.offsetParent !== null);
            const q = inps.find(e => /quantity/i.test(e.placeholder || '')) || inps.find(e => e.value === '1' || e.value === '0');
            return q ? q.value : '';
        }""")
        if not gw_actual:
            reg.info(f"Reintentando forzar Gross Weight = {peso_kg} antes de Submit...")
            frame.evaluate("""(val) => {
                const inps = [...document.querySelectorAll('input')].filter(e => e.offsetParent !== null);
                const gw = inps.find(e => /gross weight/i.test(e.placeholder || ''));
                if (gw) {
                    gw.focus();
                    const s = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
                    s.call(gw, val);
                    gw.dispatchEvent(new Event('input', {bubbles: true}));
                    gw.dispatchEvent(new Event('change', {bubbles: true}));
                }
            }""", peso_kg)
            esperar(page, 0.3)
        if not qty_actual or qty_actual == '0':
            reg.info(f"Reintentando forzar Quantity = {cant_str} antes de Submit...")
            frame.evaluate("""(val) => {
                const inps = [...document.querySelectorAll('input')].filter(e => e.offsetParent !== null);
                const q = inps.find(e => /quantity/i.test(e.placeholder || '')) || inps.find(e => e.value === '0');
                if (q) {
                    q.focus();
                    const s = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
                    s.call(q, val);
                    q.dispatchEvent(new Event('input', {bubbles: true}));
                    q.dispatchEvent(new Event('change', {bubbles: true}));
                }
            }""", cant_str)
            esperar(page, 0.3)
    except Exception:
        pass

    _cosco_control(frame, reg, "Booking Details", [
        ("Quantity", cant_str),
        ("Size Type", "40RQ"),
        ("Gross Weight", peso_kg),
        ("Temperature", _temp_reserva(reserva)),
        ("Shipper", COSCO_SHIPPER),
        ("Street", "SECTOR CARDONAL"),
        ("Cargo Descriptions", COSCO_DESC_CARGA),
        ("HS Code", COSCO_HS_CODE),
        ("Generator Set", COSCO_GENSET),
        ("Remark", COSCO_REMARK),
    ])
    reg.captura(page, f"cosco_f{f}_5_carga", full=True)

    if _WEB.get("detener") and _WEB["detener"].is_set():
        return ("DETENIDO", "Cancelado por el operador")

    _evidencia_antes_de_la_guarda(page, reg, f"cosco_f{f}_guarda")
    if not es_modo_emision():
        reg.paso("Me DETENGO en Booking Details antes de emitir (NO se pulsa Submit).")
        return ("OK-EJEMPLO", f"COSCO armada hasta Booking Details ({modo}); SIN emitir")

    # MODO EMISIÓN REAL
    reg.paso("🔴 MODO EMISIÓN REAL: Pulsando 'Submit' en COSCO...")
    pulsado, error = None, None
    campos, error_portal, vio_reminder = [], "", False
    try:
        try:
            frame.evaluate("window.scrollTo(0, document.body.scrollHeight)")
        except Exception:
            pass
        esperar(page, 0.8)
        pulsado = _pulsar_boton(frame, "button:has-text('Submit'), .btn:has-text('Submit')", _JS_COSCO_SUBMIT)
        if pulsado:
            campos, error_portal, vio_reminder = _cosco_esperar_resultado(page, frame, reg)
    except Exception as e:
        error = e
    if campos and vio_reminder:
        # Con la ventana Reminder ya vista no está medido si esos errores frenaron el envío.
        error_portal = "; ".join(campos + ([error_portal] if error_portal else []))
        campos = []
    # COSCO no tiene forma medida (sus capturas tras el envío no muestran confirmación): no
    # llega a EMITIDA hasta que se mida (CICLO-numero-booking.md).
    return _resultado_envio(page, reg, "cosco", "COSCO", f"cosco_f{f}_6_confirmado", "Submit", pulsado, error,
                            campos=campos, error_portal=error_portal)


# Pulsa el Submit del formulario de COSCO buscándolo por su texto; true solo si lo pulsó.
_JS_COSCO_SUBMIT = """() => {
    const b = [...document.querySelectorAll('button, a, span')].find(e => /^submit$/i.test((e.textContent||'').trim()));
    if (b) { b.click(); return true; }
    return false;
}"""

# Errores que COSCO muestra tras Submit: el texto bajo cada campo que no validó (p. ej. «Gross
# Weight is required») y el aviso de error del portal; sin los avisos informativos.
_JS_COSCO_ERRORES = """() => {
    const esAviso = (t) => {
        const l = (t || '').toLowerCase();
        return l.includes('allocation needs further confirmation') ||
               l.includes('you can still continue to book') ||
               l.includes('special stowage') ||
               l.includes('booking confirmation sent');
    };
    const visibles = (sel) => [...document.querySelectorAll(sel)]
        .filter(e => e.offsetParent !== null)
        .map(e => (e.textContent || '').replace(/\\s+/g, ' ').trim())
        .filter(t => t && !esAviso(t));
    const campos = [...new Set(visibles('.el-form-item__error'))];
    const avisos = visibles('.el-message--error, .el-alert--error, .el-notification--error');
    return {campos: campos, portal: avisos.length ? avisos[0] : ''};
}"""


def _cosco_errores(frame, page):
    """(campos, aviso) que muestra COSCO en el formulario (frame) y en la página, sin repetir.
    Un alcance que no se deja leer no tapa al otro."""
    campos, portal = [], ""
    for alcance in (frame, page):
        if not alcance:
            continue
        try:
            r = alcance.evaluate(_JS_COSCO_ERRORES) or {}
        except Exception:
            continue
        campos += [c for c in (r.get("campos") or []) if c not in campos]
        portal = portal or str(r.get("portal") or "")
    return campos, portal


# Plazo, en segundos, para esperar el resultado de COSCO después de Submit sin volver a pulsar nada (decisión de
# Marcelo, CICLO-revision-corrida-completa.md). HIPÓTESIS NO MEDIDA: en c4 la ventana «Reminder» siguió abierta los
# 85 a 92 s que el programa esperó, y las reservas sí se crearon (CICLO-cosco-campos-y-reminder.md).
COSCO_ESPERA_CONFIRMACION_SEG = 180
# Cada vuelta de la espera.
_COSCO_PASO_SEG = 1.5

# ¿Está abierta la ventana «Reminder»? Su texto, medido en las capturas.
_JS_COSCO_HAY_REMINDER = """() => {
    const b = document.body ? document.body.innerText : '';
    return b.includes('To complete your booking request') || (b.includes('Reminder') && b.includes('submit below document'));
}"""

# Pulsa el «Submit» que está DENTRO de la ventana «Reminder», medida en las capturas: el título «Reminder», el texto
# «To complete your booking request, please submit below document(s) before deadline» y los botones «Submit» y
# «Back». La ventana es el elemento visible más interno que tiene el título y el texto, y dentro de ella tiene que
# haber un solo «Submit». Nunca «el último Submit» de la página. Devuelve 'pulsado', 'sin-ventana', 'sin-boton' o
# 'ambiguo' (más de un «Submit» en la ventana): solo con 'pulsado' hubo clic.
_JS_COSCO_SUBMIT_DEL_REMINDER = r"""() => {
    const vis = e => !!e && e.getClientRects().length > 0;
    const esVentana = e => /\bReminder\b/.test(e.textContent || '')
        && /To complete your booking request/i.test(e.textContent || '');
    const ventana = [...document.querySelectorAll('body *')]
        .find(e => vis(e) && esVentana(e) && ![...e.children].some(c => vis(c) && esVentana(c)));
    if (!ventana) return 'sin-ventana';
    const esSubmit = e => /^\s*submit\s*$/i.test(e.textContent || '');
    const subs = [...ventana.querySelectorAll('button, a, span')]
        .filter(b => vis(b) && esSubmit(b) && ![...b.children].some(esSubmit));
    if (!subs.length) return 'sin-boton';
    if (subs.length > 1) return 'ambiguo';
    subs[0].click();
    return 'pulsado';
}"""

# ¿COSCO sigue procesando? Su máscara de carga (el barco).
_JS_COSCO_EN_CARGA = """() => {
    const mask = document.querySelector('.el-loading-mask, [class*=loading-mask], .bkg-loading, svg[class*=loading]');
    const boat = document.querySelector('[class*=boat], [class*=ship], [class*=water]');
    return !!((mask && mask.offsetParent !== null) || (boat && boat.offsetParent !== null));
}"""

# Un posible número de reserva en la pantalla: solo sirve para dejar de esperar (COSCO no tiene forma medida).
_JS_COSCO_NUMERO = """() => {
    const b = document.body ? document.body.innerText : '';
    const m = b.match(/Booking\\s+(?:Request\\s+No\\.?|No\\.?)[\\s:]*([A-Z0-9]{8,16})/i) ||
              b.match(/Booking\\s+Number[\\s:]*([A-Z0-9]{8,16})/i) ||
              b.match(/Request\\s+No\\.?[:\\s]*([A-Z0-9]{8,16})/i);
    if (m) return m[1].trim();
    const m2 = b.match(/\\b(11\\d{8})\\b/);
    if (m2) return m2[1].trim();
    return '';
}"""
# Los dos números son los registros públicos del sitio de COSCO (el ICP y el de seguridad pública) que trae el pie
# de la página: no son números de reserva (revisión del encargo 44).
_COSCO_NO_ES_NUMERO = ("31022102000157", "13003917", "TEMPLATES", "TEMPLATE", "SEARCH", "DETAILS", "REQUEST", "BOOKING",
                       "NONE", "COPYRIGHT", "SUMMARY", "SERVICE", "CONTRACT", "PARTIES", "SCHEDULE", "ORIGIN",
                       "DESTINATION", "VOYAGE", "SHIPPER", "CONSIGNEE")

# Una señal de que COSCO recibió el envío: solo sirve para dejar de esperar.
_JS_COSCO_EXITO = """() => {
    const b = (document.body ? document.body.innerText : '').toLowerCase();
    return b.includes('submitted successfully') ||
           b.includes('booking request submitted') ||
           b.includes('booking request no') ||
           b.includes('booking confirmation sent to');
}"""

# ¿Sigue en pantalla el Submit del formulario?
_JS_COSCO_SUBMIT_PRESENTE = """() => {
    const b = [...document.querySelectorAll('button, a, span')].find(e => e.offsetParent !== null && /^submit$/i.test((e.textContent||'').trim()));
    return !!b;
}"""


def _cosco_en_alguno(frame, page, js):
    """El primer resultado verdadero de 'js' en el marco del formulario o en la página; un alcance que no se deja
    leer no tapa al otro."""
    for alcance in (frame, page):
        if not alcance:
            continue
        try:
            r = alcance.evaluate(js)
        except Exception:
            continue
        if r:
            return r
    return None


def _cosco_hay_numero(frame, page):
    """¿Algún alcance muestra algo con forma de número de reserva que no sea un texto fijo del portal?"""
    for alcance in (frame, page):
        if not alcance:
            continue
        try:
            cand = alcance.evaluate(_JS_COSCO_NUMERO)
        except Exception:
            continue
        if cand and str(cand).upper() not in _COSCO_NO_ES_NUMERO:
            return True
    return False


def _cosco_pulsar_reminder(frame, page):
    """Pulsa UNA vez el «Submit» de la ventana «Reminder» (_JS_COSCO_SUBMIT_DEL_REMINDER), en el marco del
    formulario o en la página. Devuelve (pulsó, motivo): si no lo identifica sin ambigüedad, no pulsa nada."""
    motivos = []
    for alcance in (frame, page):
        if not alcance:
            continue
        try:
            r = alcance.evaluate(_JS_COSCO_SUBMIT_DEL_REMINDER)
        except Exception as e:
            r = _texto_error(e)
        if r == "pulsado":
            return True, r
        motivos.append(str(r or "sin respuesta"))
    return False, ", ".join(motivos)


def _cosco_esperar_resultado(page, frame, reg):
    """Después de pulsar Submit en COSCO, espera el resultado (decisión de Marcelo,
    CICLO-revision-corrida-completa.md):
    - si aparece la ventana «Reminder», pulsa UNA sola vez el «Submit» que está dentro de ella (por su título y su
      texto, medidos en las capturas), nunca «el último Submit» de la página;
    - después solo espera, sin volver a pulsar nada, hasta ver errores o una señal de envío, o hasta
      COSCO_ESPERA_CONFIRMACION_SEG.
    Devuelve (campos, error_portal, vio_reminder). No decide el estado: sin errores, _resultado_envio da ENVIADA –
    REVISAR EN PORTAL, porque COSCO no tiene forma medida. Hasta 0f1507e pulsaba «el último Submit» y lo repetía
    durante unos 70 s, y las reservas se creaban igual (CICLO-cosco-campos-y-reminder.md)."""
    reg.info("Esperando el resultado de COSCO (la ventana 'Reminder' o la confirmación)...")
    campos, error_portal = [], ""
    vio_reminder = rem_pulsado = rem_avisado = vio_carga = False
    esperado = 0.0
    while esperado < COSCO_ESPERA_CONFIRMACION_SEG:
        esperar(page, _COSCO_PASO_SEG)
        esperado += _COSCO_PASO_SEG
        # La ventana «Reminder»: su Submit se pulsa una sola vez; mientras siga abierta, solo se espera.
        if _cosco_en_alguno(frame, page, _JS_COSCO_HAY_REMINDER):
            vio_reminder = True
            if not rem_pulsado:
                rem_pulsado, motivo = _cosco_pulsar_reminder(frame, page)
                if rem_pulsado:
                    reg.info("Ventana 'Reminder': pulsé una vez su Submit, el de la ventana (por su título y su texto).")
                elif not rem_avisado:
                    reg.info(f"Ventana 'Reminder': no identifiqué su Submit sin ambigüedad ({motivo}); no pulsé nada.")
                    rem_avisado = True
            continue
        # La máscara de carga: COSCO sigue procesando.
        if _cosco_en_alguno(frame, page, _JS_COSCO_EN_CARGA):
            vio_carga = True
            continue
        # Sin ventana ni carga: un respiro y leer el resultado.
        esperar(page, _COSCO_PASO_SEG)
        esperado += _COSCO_PASO_SEG
        campos, error_portal = _cosco_errores(frame, page)
        if campos or error_portal:
            break
        if _cosco_hay_numero(frame, page) or _cosco_en_alguno(frame, page, _JS_COSCO_EXITO):
            break
        try:
            if not frame.evaluate(_JS_COSCO_SUBMIT_PRESENTE) and (vio_carga or vio_reminder or esperado >= 12):
                break
        except Exception:
            pass
    else:
        reg.info(f"Se cumplió el plazo de {COSCO_ESPERA_CONFIRMACION_SEG} s sin confirmación de COSCO.")
    return campos, error_portal, vio_reminder


# ============================================================
#  RESERVA · HYUNDAI (HMM · wizard Booking Step by Step)
# ============================================================
def _hmm_autocomplete(page, sel, texto, reg, etiqueta, evidencia=""):
    """Escribe en un autocompletado de HMM y clica la sugerencia que calce con la ciudad. Con 'evidencia' (el origen y
    el destino), antes de pulsarla deja con ese nombre la captura de la ventana y el HTML de la página y de sus marcos,
    con la lista: el mismo JavaScript, sin pulsar, dice si hay una que pulsaría (decisión de Marcelo,
    CICLO-origen-y-destino.md); y después del clic, _avisar_lista_distinta.
    Sin una palabra antes de la primera coma (_ciudad_de: vacío, «-», «X») no escribe ni pulsa nada: corta
    (_TEXTO_DE_LA_FILA; encargo 42), porque calzaba con cualquier sugerencia que lo trajera."""
    if not _ciudad_de(texto):
        raise ObjetivoNoEncontrado(f"{etiqueta} de HYUNDAI", _TEXTO_DE_LA_FILA)
    # [ciudad, pulsar]: pulsa solo con pulsar en true; con false, solo dice cuál pulsaría ('' si ninguna).
    js = """(args)=>{
        const [c, pulsar]=args;
        const o=[...document.querySelectorAll('li,ul li,[class*=auto] *,[class*=list] li,[class*=drop] li,td')]
            .filter(e=>e.offsetParent && (e.textContent||'').toUpperCase().includes(c)
                       && (e.textContent||'').trim().length<45);
        if(o.length){if(pulsar===true) o[0].click();return o[0].textContent.trim().slice(0,40);}return '';
    }"""
    try:
        loc = page.locator(sel).first
        loc.wait_for(state="visible", timeout=8000)
        loc.click()
        try: loc.fill("")
        except Exception: pass
        loc.type(texto, delay=90)
        ciudad = texto.split(",")[0].strip().upper()
        picked, vista = "", ""
        pendiente = bool(evidencia)
        for _ in range(10):
            esperar(page, 0.5)
            if pendiente:
                vista = " ".join(str(_sugerencia_sin_pulsar(page, js, [ciudad])).split())
                if vista:
                    _evidencia_antes_de_la_guarda(page, reg, evidencia, f"con las sugerencias de {etiqueta}",
                                                  completa=False)
                    pendiente = False
            try:
                picked = str(page.evaluate(js, [ciudad, True]))
            except Exception:
                picked = ""
            if picked:
                _avisar_lista_distinta(reg, etiqueta, evidencia, vista, " ".join(picked.split()), pendiente)
                break
        if not picked and pendiente:
            _evidencia_sin_sugerencia(page, reg, evidencia, etiqueta)
        reg.info(f"{etiqueta} '{texto}': {picked or 'sin sugerencia'}")
        return bool(picked)
    except Exception as e:
        reg.info(f"{etiqueta}: err {str(e)[:70]}")
        return False


# Devuelve el índice de la tarjeta de itinerario (a.preview-area) que calza con
# los tokens de la nave solicitada en la planilla. Si la nave está cerrada o no
# existe, devuelve idx: -1 con el motivo exacto. NUNCA usa fallback automático.
# Desde el encargo 32 es solo la interfaz anterior: las tarjetas con «Book Now» las lee _JS_HMM_TARJETAS, por su
# «1st Vessel» (CICLO-ampliar-la-busqueda.md). Hasta 4cae528 las calzaba con el texto de toda la tarjeta, y pulsaba la
# primera que la traía, en cualquiera de sus campos.
# Una tarjeta calza solo si trae todas las palabras de la nave, cada una como palabra entera (_JS_TRAE_LA_NAVE;
# decisiones de Marcelo, CICLO-cola-tres-items.md y CICLO-cola-seis-items.md). El texto de la tarjeta es su
# textContent: en los 8 que dejaron los log.txt («nave elegida y botón Book Now presionado»), la etiqueta «MAIN VESSEL»,
# la nave y su viaje van separados por espacios. Hasta f68ce6c bastaba que cada palabra fuera parte del texto. Hasta
# 9051f43 también le bastaba la primera, que en la planilla es el prefijo de la naviera: calzaba cualquier nave suya, y
# así se armaron reservas con otro buque (CICLO-proxima-salida.md). Hasta a198645 quitaba además AUTO, PRIMERA,
# DISPONIBLE y CUALQUIERA, que son ahora comodines de las seis (NAVES_COMODIN), y NW2, VIAJE, V. y VOY: con «HMM NW2»
# quedaba solo el prefijo, y calzaba la primera nave suya (CICLO-solo-la-nave-pedida.md).
_JS_HMM_INDICE_NAVE = """(toks)=>{""" + _JS_TRAE_LA_NAVE + """
    const vis = e => {
        const r = e.getBoundingClientRect();
        return e.offsetParent !== null && r.width > 0 && r.height > 0;
    };
    const isAvail = (card) => {
        const cls = ((card.className || '') + ' ' + ((card.parentElement || {}).className || '')).toLowerCase();
        if (cls.includes('closed') || cls.includes('unavailable') || cls.includes('disabled')) return false;
        const txt = (card.textContent || '').toLowerCase();
        if (txt.includes('booking closed') || txt.includes('booking unavailable')) return false;
        const vEl = card.querySelector('.vessel') || card;
        const color = window.getComputedStyle(vEl).color || '';
        const m = color.match(/rgb\\((\\d+),\\s*(\\d+),\\s*(\\d+)\\)/);
        if (m) {
            const r = parseInt(m[1], 10), b = parseInt(m[3], 10);
            if (r > 180 && b < 100) return false; // Texto rojo = cerrada
        }
        return true;
    };
    const T = (toks || []).map(s => s.toUpperCase()).filter(s => s.length > 1);

    if (T.length === 0) return { idx: -1, motivo: 'sin_nave' };

    // --- Interfaz ANTERIOR: tarjetas a.preview-area ---
    const cards = [...document.querySelectorAll('a.preview-area')].filter(vis);
    if (cards.length > 0) {
        for (let i = 0; i < cards.length; i++) {
            const v = (cards[i].textContent || '').toUpperCase().replace(/\\s+/g, ' ');
            if (_traeLaNave(v, T)) {
                if (isAvail(cards[i])) return { idx: i, motivo: 'ok', tipo: 'preview_area' };
                else return { idx: -1, motivo: 'cerrada' };
            }
        }
    }

    // NUNCA tomar una nave distinta por cuenta propia
    return { idx: -1, motivo: 'no_encontrada' };
}"""

# Las tarjetas de la lista de HYUNDAI con «Book Now», medidas en hmm_f<fila>_naves.html (2026-09-26): cada una es el
# ancestro más alto de su «Book Now» que no trae otro, sin pasar del li que mide cada resultado, con sus campos
# .schedule-info-text de dos hijos, la etiqueta y el valor («Main Vessel», «Route», «Operator», «1st Vessel» y los
# cortes), y dos .place-content, el origen y el destino, cada uno con su fecha AAAA-MM-DD. La nave de la fila es la de
# «1st Vessel», la que sale de Chile (decisión de Marcelo, CICLO-ampliar-la-busqueda.md): calza solo si ese valor trae
# todas sus palabras (_JS_TRAE_LA_NAVE). Por tarjeta: i (su «Book Now» entre los que están a la vista), primera (el
# valor de «1st Vessel»), calza, salida, llegada (si trae dos fechas), disponible (la regla de _JS_HMM_INDICE_NAVE),
# book (cuántos «Book Now» trae) y directa: true si su único .mid-state dice «Direct», false si dice «Transshipment», y
# null si no hay uno solo o dice otra cosa (medido en las 12 tarjetas del 26-09, en div.place-transshipment >
# .transshipment-line > .mid-state; CICLO-ampliar-msc-y-cma.md). Solo lee.
_JS_HMM_TARJETAS = """(toks)=>{""" + _JS_TRAE_LA_NAVE + """
    const vis = e => {
        const r = e.getBoundingClientRect();
        return e.offsetParent !== null && r.width > 0 && r.height > 0;
    };
    const esBook = b => /^\\s*book\\s*now\\s*$/i.test(b.textContent || '');
    const T = (toks || []).map(x => x.toUpperCase()).filter(x => x.length > 1);
    const isAvail = (card) => {
        const cls = ((card.className || '') + ' ' + ((card.parentElement || {}).className || '')).toLowerCase();
        if (cls.includes('closed') || cls.includes('unavailable') || cls.includes('disabled')) return false;
        const txt = (card.textContent || '').toLowerCase();
        if (txt.includes('booking closed') || txt.includes('booking unavailable')) return false;
        const vEl = card.querySelector('.vessel') || card;
        const color = window.getComputedStyle(vEl).color || '';
        const m = color.match(/rgb\\((\\d+),\\s*(\\d+),\\s*(\\d+)\\)/);
        if (m && parseInt(m[1], 10) > 180 && parseInt(m[3], 10) < 100) return false;
        return true;
    };
    const campo = (card, etiqueta) => {
        const cajas = [...card.querySelectorAll('.schedule-info-text')].filter(c => c.children.length === 2
            && (c.children[0].textContent || '').trim().toLowerCase() === etiqueta);
        return cajas.length === 1 ? (cajas[0].children[1].textContent || '').replace(/\\s+/g, ' ').trim() : null;
    };
    return [...document.querySelectorAll('button, a')].filter(b => vis(b) && esBook(b)).map((btn, i) => {
        let card = btn;
        while (card.tagName !== 'LI' && card.parentElement && card.parentElement !== document.body
               && [...card.parentElement.querySelectorAll('button, a')].filter(esBook).length === 1) {
            card = card.parentElement;
        }
        const fechas = [...card.querySelectorAll('.place-content')]
            .map(p => ((p.textContent || '').match(/\\d{4}-\\d{2}-\\d{2}/) || [''])[0]);
        const primera = campo(card, '1st vessel');
        const salida = fechas.length ? fechas[0] : '';
        const llegada = fechas.length === 2 ? fechas[1] : '';
        const tipo = [...card.querySelectorAll('.mid-state')].map(e => (e.textContent || '').trim());
        const directa = tipo.length !== 1 ? null : /^direct$/i.test(tipo[0]) ? true
            : /^transshipment$/i.test(tipo[0]) ? false : null;
        return {i: i, primera: primera || '', calza: primera !== null && _traeLaNave(primera, T),
                salida: salida, llegada: llegada,
                disponible: isAvail(card), book: [...card.querySelectorAll('button, a')].filter(esBook).length,
                directa: directa};
    });
}"""

# Pulsa el «Book Now» de la tarjeta elegida, {i, toks, salida, directa}: vuelve a leer las tarjetas con
# _JS_HMM_TARJETAS, en el mismo JavaScript, y pulsa el i-ésimo «Book Now» a la vista solo si la tarjeta i sigue siendo
# la elegida: su «1st Vessel» calza con toks, se puede reservar, sale el día 'salida' y es directa o no como la elegida.
# Si no, no pulsa nada. Hasta e8b027b pulsaba el i-ésimo sin volver a leer la tarjeta, y entre leer y pulsar corre la
# evidencia de la lista ampliada (revisión del encargo 32, CICLO-ampliar-la-busqueda.md). Hasta 2044222 no miraba si
# era directa: desde a37373f, dos tarjetas del mismo día y la misma nave pueden diferir solo en eso
# (CICLO-ampliar-msc-y-cma.md).
_JS_HMM_CLIC_TARJETA = """(args)=>{
    const t = (""" + _JS_HMM_TARJETAS + """)(args.toks)[args.i];
    if (!t || !t.calza || !t.disponible || t.salida !== args.salida || t.directa !== args.directa) return false;
    const vis = e => {
        const r = e.getBoundingClientRect();
        return e.offsetParent !== null && r.width > 0 && r.height > 0;
    };
    const b = [...document.querySelectorAll('button, a')]
        .filter(x => vis(x) && /^\\s*book\\s*now\\s*$/i.test(x.textContent || ''))[args.i];
    if (!b) return false;
    b.scrollIntoView({block: 'center'});
    b.click();
    return true;
}"""

# «Duration», el desplegable de semanas de HYUNDAI en Select Vessel: #srchSelWeeks, con las opciones «1 weeks» a
# «8 weeks» (medido en hmm_f<fila>_naves.html, 2026-09-26). Devuelve si se ve, las semanas elegidas y las opciones
# (texto y semanas), o null si no está.
_JS_HMM_SEMANAS = """()=>{
    const s = document.querySelector('#srchSelWeeks');
    if (!s) return null;
    const rx = /^\\s*(\\d+) weeks?\\s*$/i;
    const n = o => rx.test(o.textContent || '') ? parseInt(o.textContent.match(rx)[1], 10) : null;
    const elegida = s.options[s.selectedIndex];
    return {visible: s.offsetParent !== null, actual: elegida ? n(elegida) : null,
            opciones: [...s.options].filter(o => n(o) !== null).map(o => ({texto: o.textContent.trim(), n: n(o)}))};
}"""


def _hmm_salidas(tarjetas):
    """[(salida como datetime.date, o None si no se lee, tarjeta)] de las que lee _JS_HMM_TARJETAS."""
    out = []
    for t in tarjetas:
        try:
            out.append((datetime.date.fromisoformat(t.get("salida") or ""), t))
        except ValueError:
            out.append((None, t))
    return out


def _hmm_transito(tarjeta):
    """El tiempo de tránsito de una tarjeta de HYUNDAI: su llegada menos su salida. Medido en las 12 tarjetas del
    2026-09-26: es el «N Days» que muestra la tarjeta. None si no trae las dos o si la llegada no es posterior."""
    try:
        tiempo = (datetime.date.fromisoformat(tarjeta.get("llegada") or "")
                  - datetime.date.fromisoformat(tarjeta.get("salida") or ""))
    except ValueError:
        return None
    return tiempo if tiempo > datetime.timedelta(0) else None


def _hmm_leer_tarjetas(page, toks, reg, antes=0):
    """Las tarjetas de la lista (_JS_HMM_TARJETAS), con hasta 4 lecturas mientras no llega ninguna; con 'antes' (después
    de ampliar), hasta 20, mientras no haya más que esas. [] si la lectura falla."""
    tarjetas = []
    for _ in range(20 if antes else 4):
        try:
            tarjetas = page.evaluate(_JS_HMM_TARJETAS, toks) or []
        except Exception as e:
            reg.info(f"error buscar nave: {str(e)[:60]}")
            tarjetas = []
        if len(tarjetas) > antes:
            break
        esperar(page, 1.0 if antes else 0.8)
    return tarjetas


def _hmm_ampliar(page, reg):
    """Amplía la búsqueda de HYUNDAI a la opción con más semanas de «Duration» (#srchSelWeeks, _JS_HMM_SEMANAS), por su
    texto, si es más larga que la elegida (decisión de Marcelo, CICLO-ampliar-la-busqueda.md). No pulsa «Retrieve».
    Devuelve "" si amplió; si no, por qué no, para _hasta_donde_busque: si ya está en la más larga, el portal no deja
    ampliar más (NO_AMPLIA_MAS)."""
    try:
        r = page.evaluate(_JS_HMM_SEMANAS)
    except Exception as e:
        return f"no pude ampliar la búsqueda: no pude leer «Duration» ({str(e)[:50]})"
    if not r or not r.get("visible"):
        return "no pude ampliar la búsqueda: no vi «Duration» a la vista"
    if r.get("actual") is None or not r.get("opciones"):
        return "no pude ampliar la búsqueda: no pude leer las semanas de «Duration»"
    mayor = max(r["opciones"], key=lambda o: o["n"])
    if mayor["n"] <= r["actual"]:
        return NO_AMPLIA_MAS
    try:
        page.select_option("#srchSelWeeks", label=mayor["texto"], timeout=4000)
        esperar(page, 0.5)
        quedo = (page.evaluate(_JS_HMM_SEMANAS) or {}).get("actual")
    except Exception as e:
        return f"no pude ampliar la búsqueda: no pude elegir «{mayor['texto']}» en «Duration» ({str(e)[:50]})"
    if quedo != mayor["n"]:
        return f"no pude ampliar la búsqueda: «Duration» quedó en {quedo} semanas, no en {mayor['n']}"
    reg.info(f"búsqueda ampliada: «Duration» de {r['actual']} a {mayor['n']} semanas")
    return ""


def _hmm_indice_anterior(page, toks, reg):
    """La interfaz anterior de HYUNDAI (a.preview-area), como hasta ahora: _JS_HMM_INDICE_NAVE, con hasta 4 lecturas."""
    res_nave = {"idx": -1, "motivo": "no_encontrada"}
    for _ in range(4):
        try:
            res_nave = page.evaluate(_JS_HMM_INDICE_NAVE, toks)
            if not isinstance(res_nave, dict):
                res_nave = {"idx": int(res_nave), "motivo": "ok" if int(res_nave) >= 0 else "no_encontrada"}
        except Exception as e:
            reg.info(f"error buscar nave: {str(e)[:60]}")
            res_nave = {"idx": -1, "motivo": "error"}
        if res_nave.get("idx", -1) >= 0:
            break
        esperar(page, 0.8)
    return res_nave


def _hmm_elegir_nave(page, reg, reserva, toks):
    """Elige la salida de HYUNDAI y pulsa su «Book Now» (decisiones de Marcelo, CICLO-ampliar-la-busqueda.md): la nave
    de la fila es la «1st Vessel» de la tarjeta, la que sale de Chile (_JS_HMM_TARJETAS). Si ninguna la trae, amplía
    «Duration» (_hmm_ampliar), vuelve a buscar con «Retrieve» y deja la evidencia de la lista ampliada
    (hmm_f<fila>_naves_mas). Entre las que la traen y se pueden reservar, la próxima salida desde hoy o desde el día de
    carga (_proxima_salida, CICLO-proxima-salida.md), y ese día la directa (_directas_primero,
    CICLO-ampliar-msc-y-cma.md). Devuelve lo que devolvía _JS_HMM_INDICE_NAVE: {idx, motivo, tipo, texto},
    con 'busqueda' (fechas, por qué dejó de ampliar) si la nave no apareció, o {'corte': (estado, detalle)} si
    no queda una sola salida. Sin tarjetas con «Book Now», la interfaz anterior (_hmm_indice_anterior). Hasta 4cae528
    calzaba con el texto de toda la tarjeta y pulsaba la primera en la página que traía la nave, en cualquier campo."""
    tarjetas = _hmm_leer_tarjetas(page, toks, reg)
    if not tarjetas:
        return _hmm_indice_anterior(page, toks, reg)
    por_que = ""
    if not any(t.get("calza") for t in tarjetas):
        por_que = _hmm_ampliar(page, reg)
        if not por_que:
            reg.paso("La nave no estaba en lo que mostró HYUNDAI: amplié «Duration» y busco de nuevo.")
            if not _hmm_realclick(page, "Retrieve", reg, "buscar itinerarios"):
                _hmm_next(page, "retrieve", reg, "buscar itinerarios (js)")
            tarjetas = _hmm_leer_tarjetas(page, toks, reg, antes=len(tarjetas))
            _evidencia_antes_de_la_guarda(page, reg, f"hmm_f{reserva['fila']}_naves_mas",
                                          "en la lista ampliada de naves", completa=False)
            por_que = NO_AMPLIA_MAS
    de_la_nave = [t for t in tarjetas if t.get("calza")]
    if not de_la_nave:
        fechas = [d for d, _ in _hmm_salidas(tarjetas)]
        reg.info(f"nave '{reserva['nave']}': ninguna tarjeta la trae como 1st Vessel; "
                 f"{_hasta_donde_busque(fechas, por_que)}")
        return {"idx": -1, "motivo": "no_encontrada", "busqueda": (fechas, por_que)}
    disponibles = [t for t in de_la_nave if t.get("disponible") and t.get("book") == 1]
    if not disponibles:
        return {"idx": -1, "motivo": "cerrada"}
    desde = _desde(reserva)
    disponibles = _directas_primero(disponibles, desde, reg, _hmm_salidas)
    elegida, motivo = _proxima_salida(_hmm_salidas(disponibles), desde, _hmm_transito)
    if elegida is None:
        reg.info("tarjetas con la nave como 1st Vessel: " + " | ".join(f"{t.get('primera')} sale {t.get('salida')}"
                                                                       for t in disponibles[:6])[:400])
        por_que_una = _por_que_sin_salida(motivo, _hmm_salidas(disponibles), desde, _hmm_transito)
        return {"corte": _no_enviada(reg, f"HYUNDAI: no elegí salida para esa nave ('{reserva['nave']}'): "
                                          f"{por_que_una}. Revisa la fila y elige la salida en el portal.")}
    if len(disponibles) > 1:
        reg.info(f"{len(disponibles)} tarjetas traen la nave como 1st Vessel; elijo la próxima salida desde el "
                 f"{desde:%d-%m-%Y}")
        _anotar_desempate(reg, _hmm_salidas(disponibles), desde, _hmm_transito)
    try:
        pulso = bool(page.evaluate(_JS_HMM_CLIC_TARJETA, {"i": elegida["i"], "toks": toks,
                                                          "salida": elegida.get("salida", ""),
                                                          "directa": elegida.get("directa")}))
        if not pulso:
            reg.info("no pulsé el «Book Now» de la tarjeta elegida: al volver a leer la lista, ya no estaba o no era la "
                     "misma")
    except Exception as e:
        reg.info(f"error al pulsar la tarjeta elegida: {str(e)[:60]}")
        pulso = False
    if not pulso:
        return {"idx": -1, "motivo": "error"}
    return {"idx": elegida["i"], "motivo": "ok", "tipo": "book_now",
            "texto": f"1st Vessel {elegida.get('primera', '')}, sale {elegida.get('salida', '')}"[:70]}


_JS_HMM_NAVE_TEXTO = """(i)=>{
    const vis = e => {
        const r = e.getBoundingClientRect();
        return e.offsetParent !== null && r.width > 0 && r.height > 0;
    };
    const cards = [...document.querySelectorAll('a.preview-area')].filter(vis);
    if (i < 0 || i >= cards.length) return '';
    const vEl = cards[i].querySelector('.vessel');
    if (vEl && vEl.textContent.trim()) return vEl.textContent.trim().slice(0, 50);
    return cards[i].textContent.replace(/\\s+/g, ' ').trim().slice(0, 50);
}"""


# El modal «Alternate Vessel Option» de HYUNDAI pregunta qué hacer si la nave pedida no estuviera disponible. Medido en
# hmm_f<fila>_otra_nave.html (2026-09-26, CICLO-cierre-de-frenos.md): #alternate_vessel_opt, con tres label.radio-area,
# cada una con su input vessel-option y su texto, y el OK, #vesselOptionSubmit. Decisión de Marcelo
# (CICLO-ampliar-la-busqueda.md): marcar «I do not want to choose an alternate vessel», por su texto, y pulsar OK; si
# esa opción no está, la reserva queda NO ENVIADA con HMM_SIN_OPCION. Hasta a198645 el programa pulsaba el OK con lo que
# viniera marcado («Any», según la captura) y seguía; hasta 4cae528 no pulsaba nada y cortaba, con «HYUNDAI ofreció otra
# nave en lugar de la pedida».
HMM_OPCION_MANTENER = "I do not want to choose an alternate vessel"
HMM_SIN_OPCION = "HYUNDAI no ofreció la opción de mantener la nave pedida; la reserva no se envió"
HMM_NO_AVANZO = ("HYUNDAI siguió mostrando el modal «Alternate Vessel Option» después de marcar «I do not want to "
                 "choose an alternate vessel» y pulsar OK; no pulsé nada más y la reserva no se envió")


def _hmm_mantener_nave(page, reg, f, ya=False):
    """El modal «Alternate Vessel Option», si está a la vista (su OK, #vesselOptionSubmit): deja su evidencia
    (hmm_f<fila>_otra_nave), marca HMM_OPCION_MANTENER por su texto y pulsa OK (decisión de Marcelo,
    CICLO-ampliar-la-busqueda.md). Devuelve None si no está, "marcada" si marcó y pulsó, o el corte, NO ENVIADA: con
    HMM_SIN_OPCION si esa opción no está; si el clic no la deja marcada, o si no hay un solo «OK»; y con HMM_NO_AVANZO
    si ya la había marcado ('ya') y el modal sigue, sin otro clic y con la evidencia hmm_f<fila>_otra_nave_sigue (FRENO
    de Marcelo: si marcarla no deja avanzar sin otro clic nuevo, se frena)."""
    try:
        visible = page.locator("#vesselOptionSubmit").first.is_visible(timeout=3000)
    except Exception as e:
        reg.info(f"modal 'Alternate Vessel Option': no pude mirarlo ({str(e)[:50]})")
        return None
    if not visible:
        reg.info("modal 'Alternate Vessel Option': no apareció")
        return None
    if ya:
        reg.paso("HYUNDAI sigue mostrando el modal «Alternate Vessel Option» después de pulsar OK. No pulso nada más.")
        _evidencia_antes_de_la_guarda(page, reg, f"hmm_f{f}_otra_nave_sigue", "con el modal todavía a la vista",
                                      completa=False)
        return _no_enviada(reg, HMM_NO_AVANZO)
    reg.paso("HYUNDAI mostró el modal «Alternate Vessel Option»: marco que no quiero otra nave y pulso OK.")
    _evidencia_antes_de_la_guarda(page, reg, f"hmm_f{f}_otra_nave", "con el modal «Alternate Vessel Option»",
                                  completa=False)
    opcion = page.locator("#alternate_vessel_opt label.radio-area").filter(
        has_text=_re_mk.compile(r"^\s*" + _re_mk.escape(HMM_OPCION_MANTENER) + r"\s*$"))
    if opcion.count() != 1:
        return _no_enviada(reg, HMM_SIN_OPCION)
    opcion.first.click(timeout=4000)
    if not opcion.first.locator("input[type=radio]").is_checked():
        return _no_enviada(reg, f"HYUNDAI: el clic en «{HMM_OPCION_MANTENER}» no la dejó marcada; no pulsé OK y la "
                                f"reserva no se envió")
    ok = page.locator("#alternate_vessel_opt #vesselOptionSubmit").filter(has_text=_re_mk.compile(r"^\s*OK\s*$"))
    if ok.count() != 1:
        return _no_enviada(reg, f"HYUNDAI: marqué «{HMM_OPCION_MANTENER}», pero no encontré un solo botón «OK» en el "
                                f"modal; no pulsé nada más y la reserva no se envió")
    ok.first.click(timeout=4000)
    reg.info(f"modal 'Alternate Vessel Option': marqué «{HMM_OPCION_MANTENER}» y pulsé OK")
    return "marcada"


def _hmm_fecha(page, valor, reg):
    """Fija la fecha de zarpe (#srchSailDate, input type=date) si viene en la planilla, leída con _fecha_planilla; si
    no trae una que se entienda, deja el valor por defecto."""
    d = _fecha_planilla(valor)
    if not d:
        return
    iso = d.isoformat()
    try:
        page.evaluate("""(v)=>{const el=document.querySelector('#srchSailDate');
            if(el){el.value=v; el.dispatchEvent(new Event('input',{bubbles:true}));
                   el.dispatchEvent(new Event('change',{bubbles:true}));}}""", iso)
        reg.info(f"fecha zarpe: {iso}")
    except Exception:
        pass


def _hmm_realclick(page, nombre, reg, motivo=""):
    """Clic REAL (eventos de mouse confiables) sobre un botón HMM.
    Los botones del wizard HMM ignoran el .click() sintético de JS: hay que
    usar el clic de Playwright (get_by_role/get_by_text)."""
    for meth in ("role", "text"):
        try:
            if meth == "role":
                loc = page.get_by_role("button", name=nombre, exact=False).first
            else:
                loc = page.get_by_text(nombre, exact=False).first
            loc.scroll_into_view_if_needed(timeout=3000)
            loc.click(timeout=4500)
            reg.info(f"NEXT ok ({meth}) {motivo}")
            return True
        except Exception:
            continue
    # último recurso: clic por JS (por si algún botón sí responde)
    ok = bool(page.evaluate("""(nm)=>{const t=nm.toLowerCase();
        const b=[...document.querySelectorAll('button,a,input[type=button],[class*=btn],[role=button]')]
          .find(e=>e.offsetParent && (e.textContent||e.value||'').trim().toLowerCase().includes(t));
        if(b){b.scrollIntoView({block:'center'});b.click();return true;}return false;}""", nombre))
    reg.info(f"NEXT {'ok(js)' if ok else 'NO'} {motivo}")
    return ok


def _hmm_next(page, texto_regex, reg, motivo=""):
    ok = bool(page.evaluate("""(rx)=>{const re=new RegExp(rx,'i');
        const b=[...document.querySelectorAll('button,a,input[type=button],[class*=btn]')]
          .find(e=>e.offsetParent && re.test((e.textContent||e.value||'').trim()));
        if(b){b.scrollIntoView({block:'center'});b.click();return true;}return false;}""", texto_regex))
    reg.info(f"NEXT {'ok' if ok else 'NO'} {motivo}")
    return ok


def _hmm_select_por_texto(page, sel, tokens, reg, etiqueta):
    """Selecciona en un <select> nativo la opción cuyo texto contiene todos los
    tokens (o, si no hay match total, la primera que contenga el primer token)."""
    T = [t.upper() for t in tokens if t]
    try:
        val = page.evaluate("""(args)=>{
            const {sel, toks} = args;
            const s=document.querySelector(sel); if(!s) return '__NOSEL__';
            const ops=[...s.options];
            let o=ops.find(o=>toks.every(t=>(o.textContent||'').toUpperCase().includes(t)));
            if(!o && toks.length) o=ops.find(o=>(o.textContent||'').toUpperCase().includes(toks[0]));
            return o? o.value : '';
        }""", {"sel": sel, "toks": T})
    except Exception as e:
        reg.info(f"{etiqueta}: err lectura ({str(e)[:50]})"); return False
    if val == "__NOSEL__" or val == "":
        reg.info(f"{etiqueta}: sin opción para {tokens}"); return False
    try:
        page.select_option(sel, value=val, timeout=5000)
        reg.info(f"{etiqueta}: '{val}'")
        return True
    except Exception as e:
        reg.info(f"{etiqueta}: err select ({str(e)[:50]})"); return False


def _hmm_llenar_detalles(page, reserva, reg):
    """Completa la sección 'Container & Cargo' del paso Booking Details:
    Type, Size, Qty, SOC, Sign, Temp, Unit, Vent, Genset. No emite."""
    cont = (reserva.get("contenedor") or "").upper()
    cant = str(reserva.get("cant") or "1").strip() or "1"
    es_reefer = "REEF" in cont or "RF" in cont or "RH" in cont or "HR" in cont
    partes = []

    # Tipo de contenedor
    tipo_tok = ["REEFER"] if es_reefer else ["DRY"]
    if _hmm_select_por_texto(page, "#containerType0", tipo_tok, reg, "Type"):
        partes.append("tipo=" + ("Reefer" if es_reefer else "Dry"))

    # El Size se puebla de forma asíncrona según el Type: esperar a que
    # aparezcan opciones reales (más de 1) antes de elegir.
    opciones = []
    for _ in range(10):
        esperar(page, 0.7)
        try:
            opciones = page.evaluate("""()=>{const s=document.querySelector('#containerSize0');
                return s? [...s.options].map(o=>(o.textContent||'').trim()) : [];}""")
        except Exception:
            opciones = []
        if len([o for o in opciones if o and o.lower() != "select"]) >= 1:
            break
    reg.info("Size opciones: " + " | ".join([o for o in opciones if o][:12]))

    # Tamaño: HMM usa códigos cortos (p.ej. "4H" = 40'HC reefer, "40", "20", "45").
    size_num = "40"
    for n in ("45", "40", "20"):
        if n in cont:
            size_num = n; break
    quiere_hc = ("HC" in cont or "HIGH" in cont or "HQ" in cont or (es_reefer and size_num == "40"))
    if size_num == "40":
        candidatos = (["4H", "40H", "40 HIGH", "40'HC"] if quiere_hc else []) + ["40", "4"]
    elif size_num == "45":
        candidatos = ["45", "4E", "4"]
    else:
        candidatos = ["20", "2"]
    reales = [o for o in opciones if o and o.lower() != "select"]
    elegido = ""
    for c in candidatos:
        cu = c.upper()
        match = next((o for o in reales if o.upper() == cu), None) \
                or next((o for o in reales if cu in o.upper()), None)
        if match:
            if _hmm_select_por_texto(page, "#containerSize0", [match], reg, "Size"):
                elegido = match; break
    if not elegido:
        # fallback: primera opción que empiece por el dígito del tamaño
        match = next((o for o in reales if o.strip().startswith(size_num[0])), None)
        if match and _hmm_select_por_texto(page, "#containerSize0", [match], reg, "Size"):
            elegido = match
    if elegido:
        partes.append("size=" + elegido)
    esperar(page, 0.6)

    # Cantidad
    if rellenar(page, "#containerQuantity0", cant, 5000, reg):
        partes.append("qty=" + cant)

    # SOC (Shipper Owned Container) -> No
    try:
        soc_no = page.locator("#socFlgN0, input[name='socFlg0'][value='N']").first
        if soc_no.count():
            soc_no.check(force=True, timeout=2000)
            partes.append("soc=No")
    except Exception:
        pass

    # Reefer: temperatura, ventilación, genset
    if es_reefer:
        try:
            _hmm_select_por_texto(page, "#reeferUnit0", ["C"], reg, "Reefer unidad")
        except Exception:
            pass
        temp = _temp_reserva(reserva)
        # signo si existe el selector
        try:
            signo = "-" if temp.strip().startswith("-") else "+"
            page.evaluate("""(args)=>{const s=document.querySelector(args.sel);
                if(s){const o=[...s.options].find(o=>(o.textContent||'').includes(args.sig)|| (o.value||'')===args.sig);
                if(o){s.value=o.value; s.dispatchEvent(new Event('change',{bubbles:true}));}}}""",
                {"sel": "#reeferSign0", "sig": signo})
        except Exception:
            pass
        tnum = temp.replace("+", "").replace("-", "").strip()
        if rellenar(page, "#reeferTemp0", tnum, 5000, reg):
            partes.append("temp=" + temp + "C")

        # Ventilación -> 0% CLOSED
        try:
            _hmm_select_por_texto(page, "#reeferVentilation0", ["0%", "CLOSED"], reg, "Vent")
            partes.append("vent=0% CLOSED")
        except Exception:
            pass

        # Genset -> N (evitar timeout si viene disabled)
        try:
            set_g = page.evaluate("""()=>{
                const s = document.querySelector('#gensetFlg0');
                if (!s) return 'nosel';
                if (s.disabled || s.value === 'N') return 'ya_n';
                s.value = 'N';
                s.dispatchEvent(new Event('change', {bubbles:true}));
                return 'set_n';
            }""")
            reg.info(f"Genset: {set_g}")
            partes.append("genset=N")
        except Exception:
            pass

    reg.info("carga: " + (", ".join(partes) if partes else "sin datos"))
    return ", ".join(partes) if partes else "carga incompleta"


# Marcan casillas de HMM por su id o su texto y dicen lo que hicieron. Hasta 83067a1 el log decía «(js)» o
# «activado» aunque el JavaScript no encontrara nada que marcar (CICLO-clics-a-ciegas.md).
_JS_HMM_MARCAR_POR_ID = """(sel)=>{
    const el = document.querySelector(sel);
    if (!el) return false;
    el.checked = true; el.dispatchEvent(new Event('change', {bubbles:true}));
    return true;
}"""

_JS_HMM_AVISO_CORREO = """()=>{
    const el = document.querySelector('#emailChk');
    if (!el) return '';
    if (el.checked) return 'ya';
    el.click();
    return 'marcado';
}"""

_JS_HMM_NO_RESIDUO = """()=>{
    const els = [...document.querySelectorAll('label, span')];
    const el = els.find(e => (e.textContent||'').trim().toLowerCase() === 'non-waste');
    if (!el) return false;
    const inp = el.querySelector('input') || el;
    inp.click();
    return true;
}"""


# Escribe el Remark corporativo en su campo: el único textarea del formulario cuyo título (.box-title) dice
# «Remark (n / m)», con su contador de caracteres. Medido en la corrida del 2026-09-25 (CICLO-pendientes-con-evidencia.md):
# ese textarea no tiene id, name ni clase, su formulario trae ese título y ese solo campo, y los otros 9 textarea de la
# pantalla están ocultos. Devuelve 'ok' si lo escribió, o lo que faltó: 'sin-titulo', 'varios-titulos', 'sin-campo',
# 'varios-campos' u 'oculto'. Hasta e423a38 escribía en el primer textarea visible de la página (el FRENO de
# CICLO-cola-nueve-items.md).
_JS_HMM_REMARK = r"""(txt)=>{
    const titulos = [...document.querySelectorAll('.box-title')]
        .filter(e => /^Remark\s*\(\s*\d+\s*\/\s*\d+\s*\)$/.test((e.textContent || '').replace(/\s+/g, ' ').trim()));
    if (titulos.length === 0) return 'sin-titulo';
    if (titulos.length > 1) return 'varios-titulos';
    const form = titulos[0].closest('form');
    const campos = form ? [...form.querySelectorAll('textarea')] : [];
    if (campos.length === 0) return 'sin-campo';
    if (campos.length > 1) return 'varios-campos';
    const ta = campos[0];
    if (ta.offsetParent === null) return 'oculto';
    ta.scrollIntoView({block: 'center'});
    ta.focus();
    ta.value = txt;
    ta.dispatchEvent(new Event('input', {bubbles: true}));
    ta.dispatchEvent(new Event('change', {bubbles: true}));
    return 'ok';
}"""

# Lo que no encontró _JS_HMM_REMARK, para el aviso de NO ENVIADA.
_HMM_REMARK_NO_HALLADO = {
    "sin-titulo": "el recuadro «Remark (n / m)» de Additional Information",
    "varios-titulos": "un solo recuadro «Remark (n / m)»: hay más de uno y no elijo uno a ciegas",
    "sin-campo": "el campo del recuadro «Remark (n / m)»",
    "varios-campos": "un solo campo en el recuadro «Remark (n / m)»: hay más de uno y no elijo uno a ciegas",
    "oculto": "el campo del recuadro «Remark (n / m)» a la vista: está oculto",
}


def _hmm_marcar_no(page, reg, nombre, selector, id_campo):
    """Marca «No» en una pregunta de la carga de HMM (Dangerous, Chemical) y deja escrito lo que pasó."""
    try:
        loc = page.locator(selector).first
        if loc.count():
            loc.check(force=True, timeout=2500)
            reg.info(f"{nombre}: No")
        elif page.evaluate(_JS_HMM_MARCAR_POR_ID, id_campo):
            reg.info(f"{nombre}: No (js)")
        else:
            reg.info(f"{nombre}: no encontré {id_campo}; no marqué nada")
    except Exception as e:
        reg.info(f"{nombre.lower()} err: {str(e)[:50]}")


def _hmm_no_residuo(page, reg):
    """Marca 'Non-waste' en Scrap/Waste y deja escrito lo que pasó. Hasta 83067a1 decía «Non-waste (js)»
    aunque el JavaScript no encontrara nada que marcar."""
    try:
        nw = page.locator("label:has-text('Non-waste'), input[value*='Non' i], input[id*='nonWaste' i]").first
        if nw.count() and nw.is_visible():
            nw.click(timeout=3000)
            reg.info("Scrap/Waste: Non-waste")
        elif page.evaluate(_JS_HMM_NO_RESIDUO):
            reg.info("Scrap/Waste: Non-waste (js)")
        else:
            reg.info("Scrap/Waste: no encontré «Non-waste»; no marqué nada")
    except Exception as e:
        reg.info(f"non-waste err: {str(e)[:50]}")


def _hmm_aviso_correo(page, reg):
    """Activa 'E-mail Notice Setting' (#emailChk) y deja escrito lo que pasó."""
    try:
        r = page.evaluate(_JS_HMM_AVISO_CORREO)
        reg.info({"marcado": "E-mail Notice Setting: activado",
                  "ya": "E-mail Notice Setting: ya estaba activado"}.get(
            r, "E-mail Notice Setting: no encontré #emailChk; no marqué nada"))
    except Exception as e:
        reg.info(f"email notice err: {str(e)[:50]}")


def _hmm_remark(page, reg):
    """Escribe el Remark corporativo en su campo, el del recuadro «Remark (n / m)» (_JS_HMM_REMARK). Si no lo
    encuentra, no escribe en otro: corta la reserva (ObjetivoNoEncontrado) y _sin_clic_a_ciegas la deja NO ENVIADA con
    la evidencia. Hasta e423a38 escribía en el primer textarea visible (CICLO-pendientes-con-evidencia.md)."""
    try:
        donde = page.evaluate(_JS_HMM_REMARK, COSCO_REMARK)
    except Exception as e:
        reg.info(f"remark err: {str(e)[:50]}")
        return
    if donde != "ok":
        raise ObjetivoNoEncontrado("Remark de HYUNDAI", _HMM_REMARK_NO_HALLADO.get(
            donde, _HMM_REMARK_NO_HALLADO["sin-campo"]))
    reg.info(f"Remark corporativo: '{COSCO_REMARK}' (ok)")
    esperar(page, 0.2)


@_con_la_nave_de_la_fila
@_con_la_ruta_de_la_fila
@_sin_clic_a_ciegas("hmm")
def reservar_hyundai(page, reserva, creds, reg, on_pausa=None):
    f = reserva["fila"]
    nave_pedida = (reserva.get("nave") or "").strip()
    _avisar_dia_carga(reserva, reg)

    try:
        page.goto("https://www.hmm21.com/e-service/export/bookingrequest/BookingStepByStep1.do",
                  wait_until="domcontentloaded")
    except Exception as e:
        reg.info(f"goto booking: {str(e)[:60]}")
    esperar_hasta(page, "#previousBkgNo, #referenceNo0", 6, reg, "cargar Booking Step by Step")
    reg.captura(page, f"hmm_f{f}_1_ref", full=True)

    # Paso 1: Booking Reference (opcional) -> Select Vessel
    _hmm_realclick(page, "NEXT - Select Vessel", reg, "-> Select Vessel")

    # esperar a que aparezca el campo de origen del paso 2 (hasta 15s)
    ok_paso2 = False
    for _ in range(15):
        try:
            if page.locator("#schOriginText").first.is_visible():
                ok_paso2 = True; break
        except Exception:
            pass
        esperar(page, 1)
    if not ok_paso2:
        reg.paso("No avanzó a Select Vessel (no apareció #schOriginText).")
        reg.captura(page, f"hmm_f{f}_2x_sinpaso2", full=True)
        return ("REVISAR", "HYUNDAI: no se abrió el paso Select Vessel")

    # Paso 2: ruta + fecha + Contrato + Retrieve + nave
    reg.paso("Paso 2 · Select Vessel (ruta y nave)...")
    # Antes de elegir cada sugerencia, la evidencia de la lista (decisión de Marcelo, CICLO-origen-y-destino.md).
    # Sin una sugerencia elegida, NO ENVIADA: hasta el encargo 42 la reserva seguía sin el campo (decisión de Marcelo,
    # CICLO-maersk-y-fila-sin-ruta.md).
    if not _hmm_autocomplete(page, "#schOriginText", reserva["pol"], reg, "Origen", evidencia=f"hmm_f{f}_origen"):
        raise ObjetivoNoEncontrado("Origen de HYUNDAI", _sugerencia_que_elegir(reserva["pol"]))
    esperar(page, 0.8)
    dest = reserva["destino_final"] or reserva["destino_orig"]
    if not _hmm_autocomplete(page, "#schDestinationText", dest, reg, "Destino", evidencia=f"hmm_f{f}_destino"):
        raise ObjetivoNoEncontrado("Destino de HYUNDAI", _sugerencia_que_elegir(dest))
    esperar(page, 0.8)
    _hmm_fecha(page, reserva.get("dia_carga", ""), reg)

    # Seleccionar contrato en Paso 2 si está disponible. Sin contrato (ni en las credenciales ni en config.json)
    # no elige nada: con un texto vacío, _hmm_select_por_texto tomaría la primera opción (encargo 44).
    ctto = creds.get("contrato", "") or _contrato_por_defecto("hyundai")
    if ctto:
        try:
            _hmm_select_por_texto(page, "select[id*='contract' i], select[name*='contract' i]", [ctto], reg,
                                  "Contract No (Paso 2)")
        except Exception:
            pass
    else:
        reg.info("Contract No (Paso 2): sin contrato en las credenciales ni en config.json; queda el del portal")

    if not _hmm_realclick(page, "Retrieve", reg, "buscar itinerarios"):
        _hmm_next(page, "retrieve", reg, "buscar itinerarios (js)")
    esperar_hasta(page, "button:has-text('Book Now'), a:has-text('Book Now'), a.preview-area", 10, reg, "resultados de naves", asentar=1.0)

    # Filtrar solo naves disponibles ("Available Vessels Only")
    try:
        chk_avail = page.locator("label:has-text('Available Vessels Only'), input#availVesselOnly, input[name*='avail' i]").first
        if chk_avail.count() and chk_avail.is_visible():
            chk_avail.click(timeout=3000)
            reg.info("Filtro 'Available Vessels Only' activado")
            esperar(page, 1.2)
        else:
            clicked = page.evaluate("""()=>{
                const els = [...document.querySelectorAll('label, span, div')];
                const t = els.find(e => (e.textContent||'').trim().toLowerCase().includes('available vessels only'));
                if(t){
                    const inp = t.querySelector('input') || t;
                    inp.click();
                    return true;
                }
                return false;
            }""")
            if clicked:
                reg.info("Filtro 'Available Vessels Only' activado (js)")
                esperar(page, 1.2)
    except Exception as e:
        reg.info(f"filtro available err: {str(e)[:50]}")

    reg.captura(page, f"hmm_f{f}_2_naves", full=True)

    # --- Elegir nave: esperar a que aparezcan los resultados ---
    for _ in range(6):
        try:
            if page.locator("button:has-text('Book Now'), a:has-text('Book Now'), a.preview-area").first.is_visible():
                break
        except Exception:
            pass
        esperar(page, 1.5)

    # La lista de naves tal como está cuando se lee: la captura de la ventana y su HTML, sin clics ni esperas. Hace
    # falta para medir la fecha, el tránsito y los transbordos de cada salida (decisión de Marcelo,
    # CICLO-cola-siete-items.md).
    _evidencia_antes_de_la_guarda(page, reg, f"hmm_f{f}_naves", "en la lista de naves", completa=False)
    toks = [t for t in (nave_pedida or "").upper().replace("/", " ").split() if len(t) > 1]
    res_nave = _hmm_elegir_nave(page, reg, reserva, toks)
    if res_nave.get("corte"):
        return res_nave["corte"]

    idx = res_nave.get("idx", -1)
    motivo_nave = res_nave.get("motivo", "no_encontrada")

    if idx < 0:
        if motivo_nave == "cerrada":
            reg.paso(f"Nave '{nave_pedida}' encontrada en HMM pero está CERRADA (Booking Closed).")
            reg.captura(page, f"hmm_f{f}_2b_cerrada", full=True)
            return ("REVISAR", f"nave '{nave_pedida}' CERRADA en HMM")
        else:
            reg.paso(f"Nave '{nave_pedida}' NO encontrada en el itinerario de HMM.")
            reg.captura(page, f"hmm_f{f}_2b_sinnave", full=True)
            donde = f": {_hasta_donde_busque(*res_nave['busqueda'])}" if res_nave.get("busqueda") else ""
            return ("REVISAR", f"nave '{nave_pedida}' no encontrada en HMM{donde}")

    modo = ""
    tipo_sel = res_nave.get("tipo", "preview_area")
    if tipo_sel == "book_now":
        modo = res_nave.get("texto") or "botón Book Now"
        reg.info(f"nave elegida y botón Book Now presionado: {modo}")
        esperar(page, 2.0)
    else:
        nave_txt = ""
        try:
            nave_txt = str(page.evaluate(_JS_HMM_NAVE_TEXTO, idx))
        except Exception:
            pass
        # Elegir la tarjeta en interfaz legacy:
        try:
            card = page.locator("a.preview-area").nth(idx)
            card.scroll_into_view_if_needed(timeout=3000)
            try:
                card.locator(".check-wrap").first.click(timeout=4000)
            except Exception:
                card.click(timeout=4000)
            esperar(page, 1.5)
            modo = nave_txt or f"tarjeta #{idx}"
            reg.info(f"nave elegida: {modo}")
        except Exception as e:
            reg.info(f"clic nave err: {str(e)[:60]}")

        if not modo:
            reg.paso(f"NO se pudo seleccionar la nave '{nave_pedida}'.")
            reg.captura(page, f"hmm_f{f}_2b_sinnave", full=True)
            return ("REVISAR", f"error al seleccionar nave '{nave_pedida}' en HMM")

        # Avanzar a Booking Details
        esperar(page, 1.0)
        avanzo = False
        try:
            card = page.locator("a.preview-area").nth(idx)
            btn_inner = card.locator("button:has-text('NEXT - Booking Details'), a:has-text('NEXT - Booking Details')").first
            if btn_inner.count() and btn_inner.is_visible():
                btn_inner.click(timeout=4000)
                reg.info("NEXT ok (card interno) -> Booking Details")
                avanzo = True
        except Exception as e:
            reg.info(f"inner next err: {str(e)[:50]}")

        if not avanzo:
            _hmm_realclick(page, "NEXT - Booking Details", reg, "-> Booking Details")

    esperar(page, 1.5)
    modal = _hmm_mantener_nave(page, reg, f)
    if isinstance(modal, tuple):
        return modal

    # Validar que efectivamente avanzó a Paso 3 (Booking Details)
    ok_step3 = False
    for _ in range(12):
        try:
            if page.locator("#contractHolder, #containerType0, #bkgOfceCd").first.is_visible():
                ok_step3 = True
                break
        except Exception:
            pass
        esperar(page, 1.0)

    if not ok_step3:
        modal = _hmm_mantener_nave(page, reg, f, ya=modal == "marcada")
        if isinstance(modal, tuple):
            return modal
        for _ in range(5):
            try:
                if page.locator("#contractHolder, #containerType0, #bkgOfceCd").first.is_visible():
                    ok_step3 = True
                    break
            except Exception:
                pass
            esperar(page, 1.0)
        # Si el modal apareció recién en la segunda mirada y se marcó ahí, se mira una vez más: si sigue a la vista, es
        # el FRENO de Marcelo (NO ENVIADA, sin otro clic); si no, REVISAR como antes. Hasta e8b027b quedaba REVISAR sin
        # volver a mirarlo (revisión del encargo 32, CICLO-ampliar-la-busqueda.md).
        if not ok_step3 and modal == "marcada":
            modal = _hmm_mantener_nave(page, reg, f, ya=True)
            if isinstance(modal, tuple):
                return modal

    if not ok_step3:
        reg.paso("No avanzó a Booking Details (no apareció #contractHolder / #containerType0).")
        reg.captura(page, f"hmm_f{f}_3x_sinpaso3", full=True)
        return ("REVISAR", "HYUNDAI: no avanzó al paso Booking Details")

    reg.captura(page, f"hmm_f{f}_3_detalles", full=True)
    if os.environ.get("AQUASHIELD_DESCUBRIR"):
        _guardar_html(page, "hmm_dump.html", reg)
        _dump_carga(page, reg)

    # Paso 3: Customer & Contract
    reg.paso("Paso 3 · Completando Customer & Contract y Carga...")
    _hmm_select_por_texto(page, "#contractHolder", ["Shipper"], reg, "Contract Holder")
    esperar(page, 1.2)

    # 1. Booking Shipper: abrir modal de búsqueda y seleccionar AQUACHILE S.A.
    try:
        codigo_shipper = _codigo_shipper_hyundai()      # de config.json desde el encargo 44 (puede venir vacío)
        btn_s = page.locator("#shipperName ~ button.search, #shipperName ~ button, div.input:has(#shipperName) button.search").first
        if btn_s.count():
            btn_s.scroll_into_view_if_needed(timeout=2500)
            btn_s.click(timeout=3000)
            reg.info("Abriendo modal Booking Shipper Selection...")
            esperar(page, 1.2)
            try:
                # En el modal 'Booking shipper Selection', seleccionar AQUACHILE S.A. o su código de cliente, si
                # config.json lo trae (con un texto vacío, «has-text» calzaría con cualquier fila).
                filas = ["AQUACHILE S.A."] + ([codigo_shipper] if codigo_shipper else []) + ["AQUACHILE"]
                opt_aqua = page.locator(", ".join(f"tr:has-text('{t}')" for t in filas)).first
                opt_aqua.wait_for(state="visible", timeout=6000)
                radio = opt_aqua.locator("input[type='radio'], span.radio-box, label").first
                if radio.count():
                    radio.click(force=True, timeout=2500)
                else:
                    opt_aqua.click(force=True, timeout=2500)
                esperar(page, 0.6)
                btn_app_s = page.locator("button:has-text('Apply'), .btn:has-text('Apply')").first
                if btn_app_s.count() and btn_app_s.is_visible():
                    btn_app_s.click(timeout=3000)
                    reg.info("Booking Shipper 'AQUACHILE S.A.' seleccionado desde modal")
                    esperar(page, 2.5)
            except Exception as e:
                reg.info(f"modal shipper select err: {str(e)[:50]}")
        # Inyección JS como respaldo si sigue vacío
        page.evaluate("""(codigo)=>{
            const sn = document.querySelector('#shipperName');
            const sc = document.querySelector('#shipperCode');
            if (sn && !sn.value) {
                sn.value = 'AQUACHILE S.A.';
                sn.dispatchEvent(new Event('input', {bubbles:true}));
                sn.dispatchEvent(new Event('change', {bubbles:true}));
            }
            if (sc && !sc.value && codigo) {
                sc.value = codigo;
                sc.dispatchEvent(new Event('input', {bubbles:true}));
                sc.dispatchEvent(new Event('change', {bubbles:true}));
            }
        }""", codigo_shipper)
    except Exception as e:
        reg.info(f"shipper err: {str(e)[:50]}")

    # 2. Contract No: esperar a que carguen las opciones del contrato tras fijar Shipper. Sin contrato (ni en las
    # credenciales ni en config.json) la reserva no sigue: elegir uno sería por su posición (encargo 44).
    ctto = creds.get("contrato", "") or _contrato_por_defecto("hyundai")
    if not ctto:
        raise ObjetivoNoEncontrado("Contract No de HYUNDAI", "un contrato en las credenciales o en config.json → "
                                                             "opciones → contratos_por_defecto → hyundai")
    c_opciones = []
    for _ in range(15):
        esperar(page, 0.4)
        try:
            c_opciones = page.evaluate("""()=>{const s=document.querySelector('#selContractNo');
                return s ? [...s.options].map(o=>(o.textContent||'').trim()) : [];}""")
        except Exception:
            c_opciones = []
        reales_c = [o for o in c_opciones if o and o.lower() not in ("select", "dummy", "direct input")]
        if reales_c:
            break
    reg.info("Contract No opciones: " + " | ".join([o for o in c_opciones if o][:6]))

    if not _hmm_select_por_texto(page, "#selContractNo", [ctto], reg, "Contract No"):
        reales_c = [o for o in c_opciones if o and o.lower() not in ("select", "dummy", "direct input")]
        if reales_c:
            _hmm_select_por_texto(page, "#selContractNo", [reales_c[0]], reg, "Contract No (primera real)")
    esperar(page, 0.3)

    # 2b. Named Customer (si tiene opciones cargadas)
    try:
        actual_shippers = page.evaluate("""()=>{
            const s = document.querySelector('#actualShipperCode');
            return s ? [...s.options].map(o=>o.value).filter(v=>v && v.toLowerCase()!=='select') : [];
        }""")
        if actual_shippers:
            page.select_option("#actualShipperCode", value=actual_shippers[0], timeout=3000)
            reg.info(f"Named Customer: '{actual_shippers[0]}'")
    except Exception:
        pass

    # 3. HMM Sales Person
    try:
        sales = page.evaluate("""()=>{
            const s = document.querySelector('#hmmSalesmanCd');
            return s ? [...s.options].map(o=>o.value).filter(v=>v && v.toLowerCase()!=='select') : [];
        }""")
        if sales:
            page.select_option("#hmmSalesmanCd", value=sales[0], timeout=4000)
            reg.info(f"HMM Sales Person: '{sales[0]}'")
    except Exception as e:
        reg.info(f"Sales person err: {str(e)[:50]}")

    # 4. Gross Weight
    try:
        gw = page.locator("#grossWeight").first
        if gw.count() and gw.is_visible():
            peso_kg = _peso_reefer()
            gw.fill(peso_kg)
            reg.info(f"Gross Weight: {peso_kg} KGS")
    except Exception:
        pass

    # 5. Commodity: Buscar 'SALMON' mediante modal Commodity Search
    try:
        comm_val = page.evaluate("()=>((document.querySelector('#commodityDesc')||{}).value||'').trim()")
        if not comm_val or "salmon" not in comm_val.lower():
            btn_c = page.locator("#commodityDesc ~ button.search, #commodityDesc ~ button, div.input:has(#commodityDesc) button.search").first
            if btn_c.count():
                btn_c.scroll_into_view_if_needed(timeout=2500)
                btn_c.click(timeout=3000)
                reg.info("Abriendo modal Commodity Search...")
                esperar(page, 0.4)
                try:
                    # En el modal 'Commodity Search', seleccionar SALMON (B000000006)
                    opt_s = page.locator("tr:has-text('SALMON'), tr:has-text('B000000006')").first
                    opt_s.wait_for(state="visible", timeout=6000)
                    radio = opt_s.locator("input[type='radio'], span.radio-box, label").first
                    if radio.count():
                        radio.click(force=True, timeout=2500)
                    else:
                        opt_s.click(force=True, timeout=2500)
                    esperar(page, 0.2)
                    btn_app = page.locator("button:has-text('Apply'), .btn:has-text('Apply')").first
                    if btn_app.count() and btn_app.is_visible():
                        btn_app.click(timeout=2500)
                        reg.info("Commodity 'SALMON' seleccionado desde modal")
                        esperar(page, 0.5)
                except Exception as e:
                    reg.info(f"commodity modal select err: {str(e)[:50]}")
            # Inyección de respaldo JS para fijar description y code
            page.evaluate("""()=>{
                const d = document.querySelector('#commodityDesc');
                const c = document.querySelector('input[name=\"commodityCode\"]');
                if (d && (!d.value || !d.value.toLowerCase().includes('salmon'))) {
                    d.value = 'SALMON';
                    d.dispatchEvent(new Event('input', {bubbles:true}));
                    d.dispatchEvent(new Event('change', {bubbles:true}));
                }
                if (c && !c.value) {
                    c.value = 'B000000006';
                    c.dispatchEvent(new Event('input', {bubbles:true}));
                    c.dispatchEvent(new Event('change', {bubbles:true}));
                }
            }""")
    except Exception as e:
        reg.info(f"commodity err: {str(e)[:50]}")

    # Paso 3: Container & Cargo (Type / Size / Qty / SOC / Temp / Vent / Genset)
    det = _hmm_llenar_detalles(page, reserva, reg)

    # 6. Dangerous Cargo -> No
    _hmm_marcar_no(page, reg, "Dangerous Cargo",
                   "#dangerousN, label:has(#dangerousN), input[name='dangerous'][value='N']", "#dangerousN")

    # 7. Chemical Cargo(CAS No.) -> No
    _hmm_marcar_no(page, reg, "Chemical Cargo",
                   "#nonChemCgoFlgN, label:has(#nonChemCgoFlgN), input[name='nonChemCgoFlg'][value='N']",
                   "#nonChemCgoFlgN")

    # 8. E-mail Notice Setting -> Checkbox Checked
    _hmm_aviso_correo(page, reg)

    reg.captura(page, f"hmm_f{f}_4_carga", full=True)

    # Paso 4: Additional Information
    reg.paso("Paso 4 · Avanzando a Additional Information...")
    _hmm_realclick(page, "NEXT - Additional Information", reg, "-> Additional Information")
    esperar(page, 0.5)

    # Confirmar modal Warning (Reefer pre-cool undertaking) si aparece
    for _ in range(4):
        try:
            btn_warn_conf = page.locator("button:has-text('Confirm'), .btn:has-text('Confirm')").first
            if btn_warn_conf.count() and btn_warn_conf.is_visible():
                btn_warn_conf.click(timeout=3000)
                reg.info("Modal 'Warning (Reefer Undertaking)': Confirmado (Confirm)")
                esperar(page, 0.4)
                break
            else:
                ok_conf = page.evaluate("""()=>{
                    const btns = [...document.querySelectorAll('button, .btn, a')];
                    const b = btns.find(x => (x.textContent||'').trim().toLowerCase() === 'confirm' && x.offsetParent);
                    if (b) { b.click(); return true; }
                    return false;
                }""")
                if ok_conf:
                    reg.info("Modal 'Warning (Reefer Undertaking)': Confirmado (js)")
                    esperar(page, 0.4)
                    break
        except Exception:
            pass
        esperar(page, 0.3)

    # Validar que efectivamente avanzó a Paso 4
    esperar_hasta(page, "label:has-text('Non-waste'), textarea:visible, [data-tagid='step4']", 8, reg, "pantalla Additional Information")
    ok_step4 = False
    try:
        ok_step4 = bool(page.locator("label:has-text('Non-waste'), textarea:visible").first.is_visible())
    except Exception:
        pass

    if not ok_step4:
        # Reintento rápido si el modal o botón quedó pendiente
        _hmm_realclick(page, "NEXT - Additional Information", reg, "-> Additional Information (reintento)")
        esperar(page, 0.4)
        try:
            btn_warn_conf = page.locator("button:has-text('Confirm'), .btn:has-text('Confirm')").first
            if btn_warn_conf.count() and btn_warn_conf.is_visible():
                btn_warn_conf.click(timeout=3000)
                esperar(page, 0.4)
        except Exception:
            pass

    # Scrap/Waste -> Non-waste
    _hmm_no_residuo(page, reg)

    # La pantalla donde se escribe el Remark, para medir su objetivo con el candado cerrado
    # (CICLO-evidencia-remark-hyundai.md): la captura de la ventana y el HTML, sin clics, teclas ni esperas.
    _evidencia_antes_de_la_guarda(page, reg, f"hmm_f{f}_remark", "antes de escribir el Remark", completa=False)

    # Remark corporativo: "COSTOS PREPAID B/L EMISION EN ORIGEN", en su campo (_hmm_remark). Hasta e423a38 iba al
    # primer textarea visible (FRENO de CICLO-cola-nueve-items.md); lo cerró la evidencia de hmm_f<fila>_remark.
    _hmm_remark(page, reg)

    reg.captura(page, f"hmm_f{f}_4_additional", full=True)

    # Paso 5: Review & Book
    reg.paso("Paso 5 · Avanzando a Review & Book...")
    _hmm_realclick(page, "NEXT - Review & Book", reg, "-> Review & Book")
    esperar(page, 1.0)
    esperar_hasta(page, "button:has-text('Create NOW'), .btn:has-text('Create NOW')", 8, reg, "pantalla Review & Book")

    reg.captura(page, f"hmm_f{f}_5_review", full=True)
    _evidencia_antes_de_la_guarda(page, reg, f"hmm_f{f}_guarda")
    if not es_modo_emision():
        reg.paso("Me DETENGO en Review & Book antes de emitir (NO se pulsa Create NOW).")
        return ("OK-EJEMPLO", f"HYUNDAI armada hasta Review & Book ({modo}); {det}; SIN emitir")
    else:
        # Modo emisión real
        reg.paso("EMISIÓN: Pulsando 'Create NOW'...")
        pulsado, error = None, None
        try:
            pulsado = _pulsar_boton(page, "button:has-text('Create NOW'), .btn:has-text('Create NOW')")
            if pulsado:
                esperar(page, 3.0)
                try:
                    modal_ok = page.locator("#confirmBtn, button:has-text('Confirm'), button:has-text('Yes'), button:has-text('Aceptar')").first
                    if modal_ok.is_visible(timeout=3000):
                        modal_ok.click()
                        esperar(page, 2.0)
                except Exception:
                    pass
            esperar(page, 5.0)
        except Exception as e:
            error = e
        return _resultado_envio(page, reg, "hyundai", "HYUNDAI", f"hmm_f{f}_6_confirmado", "Create NOW", pulsado, error)


def _mk_got_it(page):
    """Cierra tooltips 'Got it' / 'Inland options have moved' de MAERSK."""
    try:
        b = page.get_by_role("button", name="Got it", exact=False).first
        if b.is_visible():
            b.click(timeout=2000); esperar(page, 0.6)
    except Exception:
        pass


# La regla con que MAERSK elige el origen y el destino (decisión de Marcelo, encargo 43,
# CICLO-maersk-elige-exacto.md): entre las sugerencias Container Yard, la única cuya parte antes de la primera
# coma, sin lo que va entre paréntesis, es lo escrito, sin distinguir mayúsculas ni tildes. El tipo de lugar está en la
# raíz shadow de cada opción, donde lo ve el filtro de Playwright y no text_content: «Container Yard» o «Store Door», y
# su sigla (medido en las 4 listas del 30-09, CICLO-maersk-y-fila-sin-ruta.md). Hasta el encargo 43, la primera con
# «container yard» o, si no había, la primera: así eligió el 29-09 y el 30-09 otro destino que el de la fila.
MK_CONTAINER_YARD = "Container Yard"


def _mk_plano(texto):
    """'texto' sin tildes, en mayúsculas y con los espacios de a uno: así se compara lo escrito con una sugerencia de
    MAERSK (_mk_las_exactas). Los signos cuentan."""
    import unicodedata
    t = unicodedata.normalize("NFKD", str(texto or ""))
    return " ".join("".join(c for c in t if not unicodedata.combining(c)).upper().split())


def _mk_base(sugerencia):
    """La parte de una sugerencia de MAERSK antes de su primera coma, sin lo que va entre paréntesis y en _mk_plano: si
    es lo escrito, la sugerencia tiene la forma de la regla de Marcelo (encargo 43). «Alfa (Beta), Gama» da «ALFA»."""
    t = str(sugerencia or "").split(",")[0]
    while True:
        sin = _re_mk.sub(r"\([^()]*\)", " ", t)
        if sin == t:
            return _mk_plano(t)
        t = sin


def _prefijo_de_la_lista(ciudad):
    """Con qué reconocen MAERSK (_mk_sugerencias) y CMA (_cma_puerto, _cma_entrega) su lista de sugerencias: los
    primeros 5 caracteres ASCII de la ciudad en _mk_plano (sin tildes, la Ñ como N, en mayúsculas y con los espacios de
    a uno); otra letra fuera de ASCII se cae, y si no queda ninguno, los primeros 4 en _mk_plano. CMA, desde el encargo
    48 (decisión de Marcelo, CICLO-calendario-cosco-y-cma.md): hasta ahí armaba el suyo como MAERSK hasta el 46, con la
    letra con tilde y la ñ caídas y los espacios como venían."""
    plano = _mk_plano(ciudad)
    return "".join(ch for ch in plano if ord(ch) < 128).strip()[:5] or plano[:4]


def _mk_sugerencias(page, ciudad):
    """Las sugerencias a la vista de MAERSK (mc-option) que traen los primeros 5 caracteres ASCII de la ciudad, sin sus
    tildes (la Ñ como N) y con los espacios de a uno (_prefijo_de_la_lista): con ellas sabe _mk_ciudad que llegó la
    lista de lo que escribió, y entre ellas elige (_mk_las_exactas). Otra letra fuera de ASCII se cae. Hasta el encargo
    46, la letra con tilde y la ñ también se caían: con una de ellas entre la segunda y la quinta letra, el prefijo no
    estaba en ninguna sugerencia y la fila quedaba NO ENVIADA en ese campo (decisión de Marcelo,
    CICLO-maersk-pulsa-el-book.md; pregunta 2 del encargo 43, CICLO-maersk-elige-exacto.md). La sugerencia se mira como
    viene: en las 119 de las 6 listas de MAERSK de logs/, ninguna trae una letra fuera de ASCII. Hasta la revisión de
    código del encargo 43, con un espacio doble entre las 5 primeras letras («SAN  ALFA») el prefijo no estaba en
    ninguna sugerencia."""
    prefijo = _prefijo_de_la_lista(ciudad)
    return page.locator("mc-option:visible").filter(has_text=_re_mk.compile(_re_mk.escape(prefijo), _re_mk.I))


def _mk_las_exactas(cand, ciudad):
    """Entre las sugerencias 'cand' (_mk_sugerencias), las Container Yard (MK_CONTAINER_YARD, en su raíz shadow):
    devuelve (su localizador, el texto de cada una, el de text_content, sin la raíz shadow y en una línea, y las
    posiciones de las que tienen la forma de la regla: _mk_base igual a la ciudad escrita, en _mk_plano)."""
    cy = cand.filter(has_text=_re_mk.compile(_re_mk.escape(MK_CONTAINER_YARD), _re_mk.I))
    textos = [" ".join((t or "").split()) for t in cy.all_text_contents()]
    escrita = _mk_plano(ciudad)
    return cy, textos, [i for i, t in enumerate(textos) if _mk_base(t) == escrita]


# Cuántas veces lee _mk_ciudad el campo después de pulsar la sugerencia, una cada 0,4 s, hasta que quede con ella
# (revisión de código del encargo 43: una sola lectura, a los 0,4 s, no espera a un campo que se asienta tarde).
# Hipótesis, sin medir: en la única corrida que lo anota, el campo ya estaba en la primera.
MK_LECTURAS_CAMPO = 5


def _mk_sin_una_exacta(ciudad, n):
    """Lo que buscaba _mk_ciudad cuando no hay una sola sugerencia con la forma de la regla ('n' la tienen), para el
    motivo de la NO ENVIADA."""
    return (f"una sola sugerencia {MK_CONTAINER_YARD} que diga «{ciudad}» antes de su primera coma (sin lo que va "
            f"entre paréntesis): {f'hay {n}' if n else 'no hay ninguna'}")


def _mk_ciudad(page, texto, reg, etiqueta, campo="", evidencia=""):
    """Autocompletado de ciudad/puerto de MAERSK. Escribe la ciudad (la parte de la celda antes de la primera coma) en
    el campo de su id (#mc-input-<campo>) o, sin él, en el primero «Enter city or port» visible y vacío (y si no hay uno
    vacío, en el primero), espera las sugerencias que traen sus primeros 5 caracteres ASCII (_mk_sugerencias) y pulsa la
    única Container Yard cuya parte antes de la primera coma, sin lo que va entre paréntesis, es la ciudad
    (_mk_las_exactas). Después comprueba que el campo quedó con el texto de esa sugerencia. Si no hay una sola, o el
    campo no calza, vuelve a escribir la ciudad una vez, y si tampoco, corta (ObjetivoNoEncontrado, con el motivo): la
    reserva queda NO ENVIADA, con la captura y el HTML de _sin_clic_a_ciegas (decisión de Marcelo, encargo 43,
    CICLO-maersk-elige-exacto.md). Si el campo no responde, también corta. Hasta el encargo 43 pulsaba la
    primera con «container yard» o, si no había, la primera, y solo miraba que el campo trajera los 4 primeros
    caracteres, que lo tecleado también trae; y hasta el 42, si no elegía, la reserva seguía sin el campo. Las
    sugerencias están en shadow DOM: se eligen con localizadores de Playwright (penetran shadow).
    Con 'evidencia', antes de pulsar deja con ese nombre la captura de la ventana y el HTML de la página y de sus
    marcos, con la lista (si vuelve a escribir la ciudad, la de esa otra lista, con «_reintento»; decisión de Marcelo,
    CICLO-origen-y-destino.md), y después del clic, _avisar_lista_distinta. Elige de la lista que dejó: si al dejarla no
    había una sola con la forma de la regla, en esa vuelta no pulsa. Decide con la lista quieta (dos lecturas iguales
    seguidas de sus Container Yard) y compara el campo como la regla (_mk_plano), leyéndolo hasta MK_LECTURAS_CAMPO
    veces (revisión de código del encargo 43).
    Devuelve (la sugerencia que pulsó, lo que quedó en el campo), cada una entera y en una línea: desde el encargo 43,
    iguales salvo mayúsculas, tildes o espacios de más, como compara la regla (_mk_plano). Sin una palabra antes de la
    primera coma (_ciudad_de: vacío, «-», «X») no escribe ni pulsa nada: corta (_TEXTO_DE_LA_FILA)."""
    ciudad = _ciudad_de(texto)
    if not ciudad:
        raise ObjetivoNoEncontrado(f"{etiqueta} de MAERSK", _TEXTO_DE_LA_FILA)
    # MAERSK expone ids fijos para cada extremo de la ruta; son lo más confiable
    # (el formulario puede conservar datos de una reserva anterior, así que NO
    # sirve buscar "el primer campo vacío").
    loc = None
    if campo:
        try:
            c = page.locator(f"#mc-input-{campo}").first
            if c.is_visible():
                loc = c
        except Exception:
            loc = None
    if loc is None:
        campos = page.get_by_placeholder("Enter city or port")
        try:
            total = campos.count()
        except Exception:
            total = 0
        for i in range(min(total, 8)):
            c = campos.nth(i)
            try:
                if c.is_visible() and not (c.input_value() or "").strip():
                    loc = c; break
            except Exception:
                continue
        if loc is None:
            loc = campos.first
    try:
        loc.scroll_into_view_if_needed(timeout=4000)
        loc.click(timeout=5000)
        try: loc.fill("", timeout=2500)
        except Exception: pass
        loc.type(ciudad.upper(), delay=90)
    except Exception as e:
        reg.info(f"{etiqueta}: err campo ({str(e)[:50]})")
        raise ObjetivoNoEncontrado(f"{etiqueta} de MAERSK", f"el campo donde escribir «{ciudad}»")
    _mk_got_it(page)

    def en_una_linea(texto_):
        return " ".join((texto_ or "").split())

    def la_exacta(cand):
        """(el localizador de la única sugerencia con la forma de la regla y su texto, "") o (None, "", por qué no
        hay una sola)."""
        cy, textos, exactas = _mk_las_exactas(cand, ciudad)
        if len(exactas) == 1:
            return cy.nth(exactas[0]), textos[exactas[0]], ""
        reg.info(f"{etiqueta}: {len(exactas)} de las {len(textos)} sugerencias {MK_CONTAINER_YARD} dicen «{ciudad}» "
                 f"antes de su primera coma")
        return None, "", _mk_sin_una_exacta(ciudad, len(exactas))

    por_que = f"una sugerencia para «{ciudad}»"         # si la lista no aparece
    picked = quedo = ""
    for intento in range(2):
        pendiente = bool(evidencia)
        nombre = evidencia + ("_reintento" if intento and evidencia else "")
        anterior = None
        for vuelta in range(14):
            esperar(page, 0.5)
            try:
                cand = _mk_sugerencias(page, ciudad)
                if cand.count():
                    # La lista puede llegar de a poco: decide con dos lecturas iguales seguidas de sus Container Yard
                    # y, si no se queda quieta, con la última (como _mk_resultados_quietos; revisión de código del
                    # encargo 43: con la primera, una segunda exacta que llegara después no contaba).
                    lectura = _mk_las_exactas(cand, ciudad)[1]
                    if lectura != anterior and vuelta < 13:
                        anterior = lectura
                        continue
                    vista = ""
                    if pendiente:
                        _, vista, falta = la_exacta(cand)
                        _evidencia_antes_de_la_guarda(page, reg, nombre, f"con las sugerencias de {etiqueta}",
                                                      completa=False)
                        pendiente = False
                        if not vista:
                            por_que = falta
                            break
                    target, txt, falta = la_exacta(cand)
                    if target is None:
                        por_que = falta
                        break
                    target.scroll_into_view_if_needed(timeout=2000)
                    target.click(timeout=3000)
                    _avisar_lista_distinta(reg, etiqueta, nombre, vista, txt, False)
                    esperar(page, 0.4)
                    # El texto en pantalla no basta: hay que confirmar que el dato
                    # quedó realmente en el campo. Un clic que no registra deja el
                    # input con texto y el modelo vacío, y la validación falla varios
                    # pasos después sin explicación. Desde el encargo 43, con el texto
                    # entero de la sugerencia, sin distinguir mayúsculas, tildes ni
                    # espacios (_mk_plano, como la regla): lo tecleado no basta. Lo lee
                    # hasta MK_LECTURAS_CAMPO veces, por si se asienta tarde.
                    calza = False
                    for lectura_campo in range(MK_LECTURAS_CAMPO):
                        if lectura_campo:
                            esperar(page, 0.4)
                        try:
                            quedo = en_una_linea(loc.input_value(timeout=2000))
                        except Exception:
                            quedo = ""
                        calza = _mk_plano(quedo) == _mk_plano(txt)
                        if calza:
                            break
                    if calza:
                        picked = txt
                    else:
                        reg.info(f"{etiqueta}: la sugerencia no quedó en el campo "
                                 f"({quedo[:30]!r})")
                        por_que = f"la sugerencia «{txt}» en el campo, que quedó " + (f"con «{quedo}»" if quedo
                                                                                      else "vacío")
                        picked = ""
                    break
            except Exception:
                picked = ""
        if pendiente:
            _evidencia_sin_sugerencia(page, reg, nombre, etiqueta)
        if picked or intento:
            break
        # segundo intento: la app puede no haber estado lista para sugerir
        reg.info(f"{etiqueta}: reintento de sugerencias")
        try:
            loc.click(timeout=4000)
            try: loc.fill("", timeout=2000)
            except Exception: pass
            esperar(page, 1)
            loc.type(ciudad.upper(), delay=110)
        except Exception:
            break
    reg.info(f"{etiqueta} '{ciudad}': {picked[:45] or 'sin sugerencia'}")
    if not picked:
        raise ObjetivoNoEncontrado(f"{etiqueta} de MAERSK", por_que)
    esperar(page, 0.8)
    return (picked, quedo)


def _mk_ruta_buscada(origen, destino):
    """El origen y el destino con que MAERSK buscó las salidas, para el motivo de SIN-CUPO (decisión de Marcelo,
    CICLO-origen-y-destino.md): de cada uno, lo que devolvió _mk_ciudad, la sugerencia que pulsó y, si su campo no quedó
    con ella, lo que quedó. El 29-09, la búsqueda volvió vacía con otro destino que el de la fila, y el motivo no lo
    decía (CICLO-maersk-busqueda-vacia.md). Sin la palabra «elegida»: el registro del panel pinta de verde la línea
    que la trae (clase, en JS_INDEX). Desde el encargo 43, _mk_ciudad corta si el campo no quedó con el texto entero
    de la sugerencia, comparado como la regla (en el 42 cortaba reservar_maersk, con lo que devolvía): desde
    reservar_maersk ya no se alcanza la rama de «ninguna sugerencia quedó en el campo», y la de «el campo quedó con»
    solo cuando el campo quedó con la sugerencia escrita de otra forma (mayúsculas, tildes o espacios)."""
    def uno(nombre, par):
        sugerencia, quedo = par
        if not sugerencia:
            return f"{nombre} (ninguna sugerencia quedó en el campo)"
        if quedo and quedo != sugerencia:
            return f"{nombre} «{sugerencia}» (el campo quedó con «{quedo}»)"
        return f"{nombre} «{sugerencia}»"
    return f"{uno('origen', origen)} y {uno('destino', destino)}"


def _mk_motivo_sin_cupo(aviso, det, origen, destino):
    """El motivo de SIN-CUPO: lo que dice el portal, el origen y el destino con que buscó (_mk_ruta_buscada) y lo que
    llenó del formulario ('det')."""
    return (f"MAERSK dice: \"{aviso}\"; busqué con {_mk_ruta_buscada(origen, destino)} "
            f"(formulario completo: {', '.join(det)}; SIN emitir)")


def _mk_genset(page, reg, det, valor="No"):
    """MAERSK exige declarar si el contenedor reefer necesita GenSet (el generador
    diesel que alimenta el equipo en el tramo terrestre). Son radios dentro de
    'Advanced options' y, si quedan vacíos, el asistente NO avanza: muestra
    'Please correct the following errors -> GenSet Import'. Antes el programa
    confundía esa pantalla con falta de cupo. Marcadores tomados de la traza real.
    'No' corresponde a un movimiento puerta a puerto (CY/CY), sin tramo terrestre."""
    puestos = []
    for nombre, etiqueta in (("genSetImport", "importación"), ("genSetExport", "exportación")):
        grupo = page.locator(f'mc-radio-group[name="{nombre}"]').first
        try:
            if not grupo.count() or not grupo.is_visible():
                continue
            if (grupo.get_attribute("value") or "").strip():
                continue                      # el portal ya lo traía marcado
        except Exception:
            continue
        try:
            r = page.locator(f'mc-radio[name="{nombre}"][value="{valor}"]').first
            r.scroll_into_view_if_needed(timeout=2500)
            r.click(timeout=4000)
            esperar(page, 0.4)
            quedo = (grupo.get_attribute("value") or "").strip()
            if quedo:
                puestos.append(f"{etiqueta}={quedo}")
            else:
                reg.info(f"GenSet {etiqueta}: el clic no registró el valor")
        except Exception as e:
            reg.info(f"GenSet {etiqueta}: {str(e)[:45]}")
    if puestos:
        reg.info("GenSet: " + ", ".join(puestos))
        det.append("genset=" + valor)
    return bool(puestos)


def _mk_paso_actual(page):
    """Nombre del paso vigente según el indicador del asistente. Es el único
    marcador fiable: la URL no cambia (es una SPA) y los nombres de TODOS los
    pasos están siempre en pantalla, así que buscarlos por texto da falsos
    positivos."""
    try:
        it = page.locator('mc-step-indicator-item[state="current"]').first
        return " ".join((it.text_content(timeout=2000) or "").split()).lower()
    except Exception:
        return ""


# El recorrido que comparten los JavaScript de MAERSK que leen la pantalla: cada elemento, también dentro de las raíces
# shadow, con la lista de sus ancestros (el anfitrión de una raíz shadow cuenta como ancestro de lo que tiene adentro).
_JS_MK_RECORRER = r"""
    function mkRecorrer() {
        const todos = [];
        (function w(nodo, anc) {
            for (const c of (nodo.children || [])) {
                todos.push({el: c, anc: anc});
                const anc2 = anc.concat([c]);
                if (c.shadowRoot) w(c.shadowRoot, anc2);
                w(c, anc2);
            }
        })(document, []);
        return todos;
    }
    const mkTag = e => (e.tagName || '').toLowerCase();
    const mkAtr = (e, a) => (e.getAttribute && e.getAttribute(a)) || '';
    const mkTexto = e => (e.textContent || '').replace(/\s+/g, ' ').trim();
    // A la vista: con cajas y, si el navegador lo sabe decir, sin visibility:hidden ni opacidad cero. Un anfitrión sin
    // cajas propias (display:contents) cuenta si lo que dibuja adentro está a la vista.
    function mkVisible(e, prof = 0) {
        if (!e) return false;
        if (e.getClientRects && e.getClientRects().length > 0)
            return !(e.checkVisibility && !e.checkVisibility({checkOpacity: true, checkVisibilityCSS: true}));
        if (prof > 2) return false;
        const hijos = [...((e.shadowRoot && e.shadowRoot.children) || []), ...(e.children || [])];
        return hijos.some(h => mkVisible(h, prof + 1));
    }
"""

# Lo que el portal pide cuando rechaza un paso (decisión de Marcelo, CICLO-maersk-retiro-y-terminos.md), leído de sus
# avisos de error del Maersk Design System. Medido en mk_f10_sin_objetivo.html (2026-09-27, «Additional details» sin la
# fecha de retiro): el resumen, un mc-notification appearance="error" con el heading «Please correct the following
# errors», nombra cada campo en un enlace de su pie (slot "actions") que lleva a ese campo: «Pickup date», con el href
# «#containerPickupDatePicker»; el aviso del campo lo dice en su atributo body: «Pick up date cannot be left blank». Un
# enlace a otra página no es un campo (revisión del encargo 36). También los campos marcados con el atributo invalid,
# por su legend, label o name, y su errormessage, como los leía _mk_errores (sin medir). Hasta el encargo 36,
# _mk_errores leía el texto alrededor de «correct the following errors»: ahí daba solo ese encabezado, porque el enlace
# está fuera de la raíz shadow del aviso.
_JS_MK_LO_QUE_PIDE = "() => {" + _JS_MK_RECORRER + r"""
    const todos = mkRecorrer();
    const campos = [], mensajes = [];
    for (const x of todos) {
        const e = x.el;
        if (mkTag(e) === 'mc-notification' && mkAtr(e, 'appearance') === 'error' && mkVisible(e)) {
            // Los campos: los enlaces a una parte de la página («#…», como el medido) y los ítems de una lista.
            const enlaces = todos.filter(y => y.anc.includes(e) && (mkTag(y.el) === 'li'
                                 || mkTag(y.el) === 'a' && mkAtr(y.el, 'href').startsWith('#')))
                                 .map(y => mkTexto(y.el)).filter(Boolean);
            campos.push(...enlaces);
            const m = mkAtr(e, 'body').replace(/\s+/g, ' ').trim() || (enlaces.length ? '' : mkTexto(e));
            if (m) mensajes.push(m);
        } else if (e.hasAttribute && e.hasAttribute('invalid') && mkAtr(e, 'invalid') !== 'false' && mkVisible(e)) {
            const c = (mkAtr(e, 'legend') || mkAtr(e, 'label') || mkAtr(e, 'name')).replace(/\s+/g, ' ').trim();
            if (c) campos.push(c);
            const m = mkAtr(e, 'errormessage').replace(/\s+/g, ' ').trim();
            if (m) mensajes.push(m);
        }
    }
    return {campos: [...new Set(campos)], mensajes: [...new Set(mensajes)]};
}"""


def _mk_lo_que_pide(page):
    """Lo que el portal pide en la pantalla (_JS_MK_LO_QUE_PIDE): los campos que nombra y, entre paréntesis, los
    mensajes de sus avisos, como «Pickup date («Pick up date cannot be left blank»)»; «» si no muestra ninguno o no se
    pudo leer. Solo lee."""
    try:
        r = page.evaluate(_JS_MK_LO_QUE_PIDE)
    except Exception:
        return ""
    if not isinstance(r, dict):
        return ""
    campos = [" ".join(str(c).split())[:80] for c in (r.get("campos") or [])][:6]
    mensajes = ["«" + " ".join(str(m).split())[:120] + "»" for m in (r.get("mensajes") or [])][:4]
    if campos and mensajes:
        return f"{', '.join(campos)} ({'; '.join(mensajes)})"
    return ", ".join(campos) or "; ".join(mensajes)


def _mk_booking_sin_avanzar(page, reg, det, f):
    """«Booking Information» que no avanzó después de pulsar su botón: NO ENVIADA con lo que el portal pide
    (_mk_lo_que_pide), y la evidencia mk_f<fila>_booking para medir esa pantalla, cuyos avisos no están medidos. No
    pulsa nada. Hasta el encargo 37 quedaba REVISAR (decisión de Marcelo, CICLO-maersk-ultimos-puntos.md)."""
    pide = _mk_lo_que_pide(page)
    que = (f"el portal no dejó avanzar y pide: {pide}" if pide
           else "el portal no dejó avanzar, y no pude leer qué pide")
    _evidencia_antes_de_la_guarda(page, reg, f"mk_f{f}_booking", "en «Booking Information», sin avanzar",
                                  completa=False)
    return _no_enviada(reg, f"MAERSK: en «Booking Information», {que}; {_MK_NADA_MAS} ({', '.join(det)})")


def _mk_formulario_incompleto(page, reg, det, f):
    """«Booking Information» sin un botón para seguir a la selección de nave que acepte el clic: NO ENVIADA con lo que
    el portal pide (_mk_lo_que_pide), sin otro clic, y la evidencia de esa pantalla (mk_f<fila>_booking, como
    _mk_booking_sin_avanzar). Hasta el encargo 38 quedaba REVISAR, «formulario incompleto» (decisión de Marcelo,
    CICLO-maersk-shipper-y-cortes.md). Sin avisos a la vista, o sin poder leerlos, dice que no vio qué pide."""
    pide = _mk_lo_que_pide(page)
    que = f", y el portal pide: {pide}" if pide else ", y no vi qué pide el portal"
    _evidencia_antes_de_la_guarda(page, reg, f"mk_f{f}_booking", "en «Booking Information», incompleto",
                                  completa=False)
    return _no_enviada(reg, f"MAERSK: formulario incompleto{que}; {_MK_NADA_MAS} ({', '.join(det)})")


def _mk_esperar_avance(page, desde, seg, reg, minimo=1.2):
    """Espera a que el indicador de pasos cambie de verdad o la URL avance a /sailings."""
    import time as _t
    t0 = _t.time()
    esperar(page, minimo)
    while _t.time() - t0 < seg:
        u = page.url.lower()
        if "/sailings" in u or "/additional" in u or "/review" in u:
            reg.info(f"avance detectado por URL: {u} ({_t.time() - t0:.1f}s)")
            return True
        ahora = _mk_paso_actual(page)
        if ahora and ahora != desde:
            reg.info(f"paso: '{desde or '?'}' -> '{ahora}' ({_t.time() - t0:.1f}s)")
            return True
        try:
            if page.get_by_text("correct the following errors", exact=False).count():
                reg.info(f"el portal marca errores de validación ({_t.time() - t0:.1f}s)")
                return False
        except Exception:
            pass
        esperar(page, 0.5)
    reg.info(f"sin avance tras {seg:.0f}s (sigue en '{desde or '?'}')")
    return False


def _mk_desenlace_sailing(page, reg, seg=45, minimo=2.0):
    """Al entrar a 'Select sailing' el portal busca tarifas e itinerarios.
    Espera a que desaparezca el indicador de carga y aparezcan los zarpes reales. Devuelve «sin-zarpes», con el aviso
    del portal, o «con-zarpes». Un zarpe cuenta solo si su tarjeta trae su «Book», contado como lo cuenta la lista
    (_JS_MK_SALIDAS; decisión de Marcelo, CICLO-maersk-busqueda-vacia.md). Hasta el encargo 40 bastaba cualquier botón
    o enlace «Book» a la vista más abajo de 100 px, y en los 14 desenlaces de logs/ la búsqueda terminó así, a los 2 s.
    El 29-09, lo más probable es que con uno de los 3 enlaces «Book» a /booking/new del encabezado o el pie, que trae
    cada una de las 9 páginas de MAERSK guardadas (los únicos «Book» fuera de las tarjetas); el aviso de que no había
    salidas está en el HTML guardado 22 s después. La fila quedó REVISAR y no SIN-CUPO.
    A los 'seg' s sin desenlace dice «con-zarpes» y la reserva sigue a buscar la nave: si no aparece, REVISAR por
    _mk_sin_nave (decisión de Marcelo, CICLO-maersk-cuatro-puntos.md)."""
    import time as _t
    t0 = _t.time()
    esperar(page, minimo)
    aviso = ""
    while _t.time() - t0 < seg:
        try:
            n = page.get_by_text("no sailings for your search", exact=False)
            if n.count() and n.first.is_visible():
                aviso = (n.first.text_content() or "").strip()[:150]
                reg.info(f"el portal responde: no hay zarpes ({_t.time() - t0:.1f}s)")
                return "sin-zarpes", aviso
        except Exception:
            pass
        try:
            # Detección rápida de tarifas o itinerarios ya cargados
            precios = page.locator("text=/USD\\s*[\\d,.]+/i")
            if precios.count() and precios.first.is_visible():
                reg.info(f"tarifas cargadas en pantalla ({_t.time() - t0:.1f}s)")
                return "con-zarpes", ""
        except Exception:
            pass
        try:
            salidas = page.evaluate(_JS_MK_SALIDAS, {"toks": [], "viaje": ""}) or []
            if any(s.get("book") for s in salidas):
                reg.info(f"salidas con su «Book» en la página ({_t.time() - t0:.1f}s)")
                return "con-zarpes", ""
        except Exception:
            pass
        esperar(page, 1.0)
    reg.info(f"la búsqueda de zarpes tardó más de {seg:.0f}s; procedo a buscar naves")
    return "con-zarpes", ""


def _mk_cliente(reserva, creds):
    """Cliente MAERSK: de la reserva si viene, si no del config, si no AQUACHILE S.A."""
    return (str(reserva.get("cliente") or "").strip()
            or str(creds.get("cliente") or "").strip()
            or "AQUACHILE S.A.")


def _mk_asegurar_cliente(page, cliente, reg):
    """Si estamos en la página de selección de cliente, elige el indicado."""
    if "customer" not in page.url.lower():
        return
    reg.info(f"seleccionar cliente: {cliente}")
    for texto in (cliente, cliente.replace(" S.A.", "")):
        try:
            loc = page.get_by_text(texto, exact=False).first
            loc.scroll_into_view_if_needed(timeout=3000)
            loc.click(timeout=4000)
            esperar(page, 6)
            return
        except Exception:
            continue


def _mk_listo_para_reservar(page, cliente, reg, intentos=5):
    """Deja MAERSK en el formulario /book/ listo para llenar. Resuelve en el
    camino la pantalla 'You are authenticated / Continue as' y la selección de
    cliente, que aparecen de forma intermitente según la sesión."""
    for i in range(intentos):
        try:
            u = page.url.lower()
        except Exception:
            u = ""
        _maersk_cookies(page, reg)
        # ¿ya estamos en el formulario?
        if "/book" in u:
            try:
                if page.get_by_placeholder("Enter city or port").first.is_visible():
                    return True
            except Exception:
                pass
        # pantalla intermedia 'Continue as <usuario>'
        try:
            b = page.get_by_role("button", name="Continue", exact=True).first
            if b.is_visible():
                reg.info("pantalla 'Continue as' -> Continue")
                b.click(timeout=4000); esperar(page, 5); continue
        except Exception:
            pass
        # selección de cliente
        if "customer" in u:
            _mk_asegurar_cliente(page, cliente, reg)
            esperar(page, 3); continue
        # si no, ir al formulario
        try:
            page.goto("https://www.maersk.com/book/", wait_until="domcontentloaded")
        except Exception:
            pass
        esperar(page, 6)
    reg.info("no llegué al formulario /book/")
    return False


def _mk_detenida(page, reg, fila):
    """MAERSK se detuvo en «Select sailing»: deja la captura y el HTML de esa pantalla (mk_f<fila>_detenida) con el
    mecanismo de la guarda, sin clics ni esperas. Sin la nave, sin una sola salida, en SIN-CUPO y, desde el encargo 46,
    con la nave y sin poder pulsar su «Book» (_mk_book_sin_pulsar)."""
    _evidencia_antes_de_la_guarda(page, reg, f"mk_f{fila}_detenida", "donde se detuvo", completa=False)


def _mk_sin_una_salida(page, reg, reserva, salidas, motivo, desde):
    """No queda una sola salida de MAERSK para la nave de la fila (_proxima_salida): no se elige ninguna. Deja la
    evidencia de «Select sailing» (_mk_detenida) y la reserva queda NO ENVIADA con el motivo (CICLO-proxima-salida.md).
    Con «no-reservable», la salida pedida está, pero sin «Book»: el motivo es SALIDA_NO_RESERVABLE (decisión de Marcelo,
    CICLO-ampliar-la-busqueda.md)."""
    reg.info("salidas que calzan: " + " | ".join(f"sale {s.get('salida')}" for s in salidas[:6])[:400])
    _mk_detenida(page, reg, reserva["fila"])
    por_que = _por_que_sin_salida(motivo, _mk_salidas(salidas), desde, _mk_transito)
    if motivo == "no-reservable":
        return _no_enviada(reg, f"MAERSK: {por_que} ('{reserva['nave']}')")
    return _no_enviada(reg, f"MAERSK: no elegí salida para esa nave ('{reserva['nave']}'): {por_que}. Revisa la fila y "
                            f"elige la salida en el portal.")


def _mk_book_sin_pulsar(page, reg, reserva, salida, por_que):
    """La nave de la fila estaba en «Select sailing» y el programa eligió su salida, pero no pudo pulsar su «Book»
    (_mk_pulsar_book dice por qué): la reserva queda NO ENVIADA, con la evidencia de esa pantalla (_mk_detenida: la
    captura de la ventana y su HTML) y un motivo que dice que la nave estaba (decisión de Marcelo, encargo 46,
    CICLO-maersk-pulsa-el-book.md). Hasta ahí seguía por la rama de la nave que no está (_mk_sin_nave): el 2026-10-01
    quedó REVISAR con «la nave … no está en los itinerarios», y estaba (encargo 45, CICLO-login-msc-y-maersk.md)."""
    _mk_detenida(page, reg, reserva["fila"])
    return _no_enviada(reg, f"MAERSK: la nave '{reserva['nave']}' estaba en «Select sailing» y elegí su salida (sale "
                            f"{salida.get('salida')}), pero no pude pulsar su «Book»: {por_que}. No pulsé nada más, y "
                            f"la reserva no se envió")


def _mk_sin_nave(page, reg, reserva, det, busqueda=None):
    """La nave de la fila no está en los itinerarios de MAERSK: la reserva se detiene en «Select sailing», con la
    captura y el HTML de esa pantalla, y el estado y el mensaje lo dicen. Con 'busqueda' (las fechas de salida de todo
    lo que cargó y por qué dejó de ampliar, de _mk_elegir_nave), el mensaje dice también hasta qué fecha buscó
    (_hasta_donde_busque; decisión de Marcelo, CICLO-ampliar-la-busqueda.md). Hasta e910bf1 seguía hasta la guarda y
    escribía «Me DETENGO en Review booking» y «armada hasta Review» sin haber llegado a la revisión
    (CICLO-cola-nueve-items.md)."""
    _mk_detenida(page, reg, reserva["fila"])
    reg.paso("Me detuve en «Select sailing»: la nave de la fila no está en los itinerarios de MAERSK.")
    donde = f": {_hasta_donde_busque(*busqueda)}" if busqueda else ""
    return ("REVISAR", f"MAERSK: me detuve en «Select sailing»: la nave '{reserva['nave']}' no está en los "
                       f"itinerarios{donde} ({', '.join(det)}); SIN emitir")


def _mk_esperar_revision(page):
    """Espera la pantalla de revisión de MAERSK (/book/review) unos 15 s. Si no aparece, corta la reserva
    (ObjetivoNoEncontrado): hasta 2b69304 seguía sin avisar, marcaba «el último checkbox» de la pantalla en que
    se había quedado y, con el candado cerrado, terminaba en OK-EJEMPLO «armada hasta Review»
    (CICLO-maersk-corta-en-la-revision.md). El corte lleva lo que el portal pide en la pantalla en que se quedó
    (_mk_lo_que_pide; decisión de Marcelo, CICLO-maersk-retiro-y-terminos.md): el 27-09, «Pickup date»."""
    for _ in range(30):
        esperar(page, 0.5)
        if "/review" in page.url.lower():
            return
    raise ObjetivoNoEncontrado("Revisión de MAERSK", "la pantalla de revisión («Review booking»), que no "
                                                     "apareció en 15 s", pide=_mk_lo_que_pide(page))


# «Review booking», el botón con que «Additional details» pasa a la revisión, por su texto. Medido en
# mk_f10_sin_objetivo.html del 27-09: lo traen dos elementos, el mc-button con label="Review booking" y su botón
# interno, que son el mismo control; mc-button con ese texto hay uno. Hasta el encargo 38, si no lo encontraba, pulsaba
# por JavaScript el primer elemento a la vista cuyo texto lo traía, y ese era <html>, cuyo texto es el de toda la página
# (decisión de Marcelo, CICLO-maersk-shipper-y-cortes.md).
MK_REVISION = "Review booking"
MK_INTENTOS_REVISION = 15      # veces que lo busca, una por segundo


def _mk_pulsar_revision(page, reg, f):
    """Pulsa «Review booking» (MK_REVISION): el único mc-button a la vista con ese texto. Lo busca hasta
    MK_INTENTOS_REVISION veces, una por segundo; si la revisión ya apareció (un clic que falló pudo haber salido), no
    hace falta. Sin uno solo a la vista, corta sin otro clic (ObjetivoNoEncontrado, con lo que el portal pide). Si está,
    pero no acepta el clic, deja la evidencia mk_f<fila>_revision y devuelve el corte, NO ENVIADA. Si no, None. Hasta la
    revisión del encargo 38 tomaba el primero, visible o no, entre botones y enlaces, y decía «no encontré» también
    cuando estaba a la vista y no aceptaba el clic."""
    vistos, leer, clic = 0, "", ""
    for intento in range(MK_INTENTOS_REVISION):
        if intento:
            esperar(page, 1.0)
        if "/review" in page.url.lower():
            reg.info(f"la revisión ya apareció; no hace falta pulsar '{MK_REVISION}'")
            return None
        try:
            botones = page.locator("mc-button").filter(has_text=_re_mk.compile(MK_REVISION, _re_mk.I))
            a_la_vista = [botones.nth(i) for i in range(botones.count()) if botones.nth(i).is_visible()]
            vistos, leer = len(a_la_vista), ""
        except Exception as e:
            a_la_vista, leer = [], _texto_error(e)
        if len(a_la_vista) != 1:
            continue
        [boton] = a_la_vista
        try:
            boton.scroll_into_view_if_needed(timeout=3000)
            boton.click(timeout=4000)
        except Exception as e:
            clic = _texto_error(e)
            continue
        reg.info(f"pulsado '{MK_REVISION}'")
        return None
    if clic:
        _evidencia_antes_de_la_guarda(page, reg, f"mk_f{f}_revision", f"con «{MK_REVISION}» sin aceptar el clic",
                                      completa=False)
        return _no_enviada(reg, f"MAERSK: el botón «{MK_REVISION}» estaba a la vista, pero no aceptó el clic ({clic}); "
                                f"{_MK_NADA_MAS}")
    cuantos = f"no pude leer la página: {leer}" if leer else f"había {vistos}"
    raise ObjetivoNoEncontrado("Review booking de MAERSK",
                               f"un solo botón «{MK_REVISION}» a la vista, por su texto, en {MK_INTENTOS_REVISION} "
                               f"intentos ({cuantos})", pide=_mk_lo_que_pide(page))


# «Continue», el botón con que «Recommended services» pasa a «Additional details» (decisión de Marcelo,
# CICLO-maersk-cuatro-puntos.md): se pulsa solo si hay exactamente uno a la vista; con cero o más de uno, la reserva
# queda NO ENVIADA. Su HTML no está medido: ninguna corrida guardó esa pantalla, y en sus 6 capturas (del 21 y el 27-09)
# no se lee, porque queda fuera de lo capturado; el programa lo pulsó por su texto las 6 veces. Un «Continue» es un
# mc-button (por su label o su texto), un button, un enlace o lo que tenga role button, con ese texto entero y sin
# distinguir mayúsculas; lo que está dentro de otro (el botón interno de un mc-button) es el mismo control. Hasta el
# encargo 39 pulsaba el primero con ese texto o, por JavaScript, el primer elemento a la vista con ese texto, y si no
# encontraba ninguno seguía sin cortar. La misma lectura, con sus textos, es la de «Continue to book» en «Booking
# Information» (_mk_pulsar_unico, encargo 40).
MK_CONTINUAR = "Continue"
MK_INTENTOS_CONTINUAR = 15     # veces que lo busca, una por segundo

_JS_MK_CONTINUAR_LEER = r"""
    function mkContinuar(a) {
        const todos = mkRecorrer();
        const buscados = a.textos.map(t => t.toLowerCase());
        const esControl = e => ['mc-button', 'button', 'a'].includes(mkTag(e)) || mkAtr(e, 'role') === 'button';
        const texto = e => ((mkTag(e) === 'mc-button' && mkAtr(e, 'label')) || mkTexto(e)).trim().toLowerCase();
        const vistos = todos.filter(x => esControl(x.el) && buscados.includes(texto(x.el)) && mkVisible(x.el));
        // Lo que está dentro de otro (el botón interno de un mc-button) es el mismo control.
        return vistos.filter(x => !vistos.some(y => y !== x && x.anc.includes(y.el))).map(x => x.el);
    }
"""
_JS_MK_CONTINUAR = "(a) => {" + _JS_MK_RECORRER + _JS_MK_CONTINUAR_LEER + r"""
    return mkContinuar(a).length;
}"""
# El que se pulsa, leído otra vez justo antes: uno y ningún otro; si no, null.
_JS_MK_CONTINUAR_PULSAR = "(a) => {" + _JS_MK_RECORRER + _JS_MK_CONTINUAR_LEER + r"""
    const [uno, ...otros] = mkContinuar(a);
    return uno && !otros.length ? uno : null;
}"""


def _mk_pulsar_unico(page, textos, ya):
    """El único botón a la vista cuyo texto entero es uno de 'textos' (_JS_MK_CONTINUAR), buscado hasta
    MK_INTENTOS_CONTINUAR veces, una por segundo; el clic va sobre lo que _JS_MK_CONTINUAR_PULSAR vuelve a leer justo
    antes. Si la URL ya trae 'ya', la pantalla siguiente apareció (un clic que falló pudo haber salido) y no hace falta.
    Devuelve («pulsado», «») o («ya», «»); («clic», el error) si estaba a la vista y no aceptó el clic; o («no-uno»,
    cuántos había) si nunca hubo uno solo. Lo comparten «Continue» de «Recommended services» y «Continue to book» de
    «Booking Information» (encargo 40)."""
    vistos, leer, clic, cambio = 0, "", "", False
    args = {"textos": list(textos)}
    for intento in range(MK_INTENTOS_CONTINUAR):
        if intento:
            esperar(page, 1.0)
        if ya in page.url.lower():
            return "ya", ""
        try:
            vistos, leer = int(page.evaluate(_JS_MK_CONTINUAR, args) or 0), ""
        except Exception as e:
            vistos, leer = 0, _texto_error(e)
        if vistos != 1:
            continue
        try:
            el = page.evaluate_handle(_JS_MK_CONTINUAR_PULSAR, args).as_element()
            if el is None:
                cambio = True
                continue
            el.scroll_into_view_if_needed(timeout=3000)
            el.click(timeout=4000)
        except Exception as e:
            clic = _texto_error(e)
        else:
            return "pulsado", ""
    if clic:
        return "clic", clic
    if leer:
        return "no-uno", f"no pude leer la página: {leer}"
    releido = ", pero al volver a leer ya no era uno solo" if cambio and vistos == 1 else ""
    return "no-uno", f"había {vistos}{releido}"


def _mk_continuar_servicios(page, reg, f):
    """Pulsa «Continue» (MK_CONTINUAR) en «Recommended services», solo si hay exactamente uno a la vista
    (_mk_pulsar_unico; decisión de Marcelo, CICLO-maersk-cuatro-puntos.md); si «Additional details» ya apareció, no hace
    falta. Con cero o más de uno, corta sin pulsar nada (ObjetivoNoEncontrado, con lo que el portal pide). Si está,
    pero no acepta el clic, deja la evidencia mk_f<fila>_servicios y devuelve el corte, NO ENVIADA. Si no, None."""
    res, que = _mk_pulsar_unico(page, [MK_CONTINUAR], "additional-details")
    if res == "ya":
        reg.info(f"«Additional details» ya apareció; no hace falta pulsar '{MK_CONTINUAR}'")
        return None
    if res == "pulsado":
        reg.info(f"pulsado '{MK_CONTINUAR}' en Recommended services")
        return None
    if res == "clic":
        detalle = (f"MAERSK: el botón «{MK_CONTINUAR}» de «Recommended services» estaba a la vista, pero no aceptó el "
                   f"clic ({que}); {_MK_NADA_MAS}")
        _evidencia_antes_de_la_guarda(page, reg, f"mk_f{f}_servicios", f"con «{MK_CONTINUAR}» sin aceptar el clic",
                                      completa=False)
        return _no_enviada(reg, detalle)
    buscaba = f"un solo botón «{MK_CONTINUAR}» a la vista, por su texto, en {MK_INTENTOS_CONTINUAR} intentos ({que})"
    raise ObjetivoNoEncontrado("Recommended services de MAERSK", buscaba, pide=_mk_lo_que_pide(page))


# «Continue to book», el botón con que «Booking Information» pasa a la selección de nave, o «Continue» (decisión de
# Marcelo, CICLO-maersk-busqueda-vacia.md): se pulsa solo si hay exactamente uno a la vista entre los dos; con cero o
# más de uno, la reserva queda NO ENVIADA. Medido con OCR en las 11 capturas legibles de esa pantalla, del 21 al 27-09
# (mk_f<fila>_3_detalle; de las 14, las otras 3, del 26 y el 29-09, el OCR no las reconoce): un solo botón, «Continue to
# book», al pie. En el HTML de
# la selección de nave del 29-09, que todavía trae el formulario, es un mc-button con label="Continue to book" y su
# botón interno. Hasta el encargo 40 se pulsaba el primer botón habilitado cuyo nombre accesible traía «Continue to
# book» o, si no había, «Continue», sin mirar si se veía.
def _mk_continuar_a_la_nave(page, reg, det, f, textos):
    """En «Booking Information», pulsa el único botón a la vista cuyo texto entero es uno de 'textos' («Continue to
    book» o «Continue»; _mk_pulsar_unico); si la selección de nave ya apareció, no hace falta. Con cero o más de uno,
    corta sin pulsar nada (ObjetivoNoEncontrado, con lo que el portal pide). Si está, pero no acepta el clic, el
    formulario quedó incompleto (_mk_formulario_incompleto): NO ENVIADA. Si no, None."""
    nombres = " o ".join(f"«{t}»" for t in textos)
    res, que = _mk_pulsar_unico(page, textos, "/sailings")
    if res == "ya":
        reg.info(f"«Select sailing» ya apareció; no hace falta pulsar {nombres}")
        return None
    if res == "pulsado":
        reg.info(f"pulsado el único {nombres} a la vista")
        return None
    if res == "clic":
        reg.captura(page, f"mk_f{f}_4_sailing", full=True)
        reg.paso(f"No pude continuar a la selección de nave: {nombres} no aceptó el clic ({que}).")
        return _mk_formulario_incompleto(page, reg, det, f)
    raise ObjetivoNoEncontrado("Booking Information de MAERSK",
                               f"un solo botón {nombres} a la vista, por su texto, en {MK_INTENTOS_CONTINUAR} intentos "
                               f"({que})", pide=_mk_lo_que_pide(page))


# La fecha de retiro de MAERSK (decisión de Marcelo, CICLO-maersk-retiro-y-terminos.md): el primer día hábil (de lunes a
# viernes y sin los feriados de Chile) después del día en que se corre el programa; si ese día no está habilitado en el
# calendario, el siguiente día hábil habilitado, nunca un sábado, un domingo ni un feriado
# (CICLO-maersk-ultimos-puntos.md y CICLO-maersk-shipper-y-cortes.md; hasta el encargo 37, el siguiente habilitado,
# aunque fuera fin de semana, y hasta el 38, los feriados contaban como hábiles). Se elige con tres clics, cada uno por
# lo que es: «Choose another date» (el único botón a la vista con ese nombre accesible, medido en
# mk_f10_sin_objetivo.html del 27-09), el día del calendario por su fecha, y «Done». Del 24-09 (0f1507e) al encargo 36
# no se elegía: la definía la naviera, y el portal no pasaba a la revisión sin ella (CICLO-maersk-fecha-de-retiro.md).
# Hasta 0f1507e se pulsaba el primer día del calendario que no se viera deshabilitado, sin mirar su fecha: así llegaron
# a la revisión las 5 filas del 21-09.
MK_OTRA_FECHA = "Choose another date"
MK_LISTO = "Done"
MK_ESPERA_CALENDARIO = 10      # s que espera el calendario después de «Choose another date» (hipótesis, sin medir)
_MK_NADA_MAS = "no pulsé nada más y la reserva no se envió"
_DIAS_ES = ("lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo")

# Las fechas escritas en un texto, sin ambigüedad: AAAA-MM-DD (o con barras), «29 September 2026» y «September 29,
# 2026», con el mes entero o abreviado, con o sin el día de la semana. Las de solo cifras con el día y el mes
# (29/09/2026) no: no se sabe cuál es cuál.
_JS_MK_FECHAS = r"""
    const MK_MESES = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september',
                      'october', 'november', 'december'];
    const mkMes = s => {
        const t = String(s || '').toLowerCase().replace(/\.$/, '');
        return t.length < 3 ? -1 : MK_MESES.findIndex(m => m.startsWith(t));
    };
    const mkIso = (a, m, d) => {
        const f = new Date(Date.UTC(a, m, d));
        return f.getUTCFullYear() === a && f.getUTCMonth() === m && f.getUTCDate() === d
            ? f.toISOString().slice(0, 10) : '';
    };
    function mkFechasEn(s) {
        const t = String(s || ''), out = [];
        const ISO = /(?<!\d)(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})(?!\d)/g;
        const DIA_MES = /(?<!\d)(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?([A-Za-z]{3,9})\.?,?\s+(\d{4})(?!\d)/g;
        const MES_DIA = /(?<![A-Za-z])([A-Za-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})(?!\d)/g;
        for (const x of t.matchAll(ISO)) out.push(mkIso(+x[1], +x[2] - 1, +x[3]));
        for (const x of t.matchAll(DIA_MES)) if (mkMes(x[2]) >= 0) out.push(mkIso(+x[3], mkMes(x[2]), +x[1]));
        for (const x of t.matchAll(MES_DIA)) if (mkMes(x[1]) >= 0) out.push(mkIso(+x[3], mkMes(x[1]), +x[2]));
        return [...new Set(out.filter(Boolean))];
    }
"""

# El calendario de la fecha de retiro, medido el 2026-10-02 en mk_f10_calendario.html, el primero que guardó una
# corrida (encargo 48, CICLO-calendario-cosco-y-cma.md): va en un mc-modal («Container pick-up details»); el mes y el
# año, en dos mc-button de su cabecera, con label «October» y «2026», sin una leyenda que traiga los dos; cada día, un
# mc-button con su número por label y, adentro, un button con el número por aria-label y disabled si no se puede
# elegir. Hasta ahí se sabía solo que tiene un «Done» (el código de antes de 0f1507e lo pulsaba) y que sus días llevan
# su número como texto (así los encontraba). mkCalendario lo lee así:
# - el calendario es el ancestro más cercano del único «Done» a la vista que contiene al menos 28 celdas de día;
# - una celda de día: algo que se puede pulsar (button, td, a, role gridcell, button u option, tabindex, o una etiqueta
#   con «day») cuyo texto entero es un número del 1 al 31, sin los números de semana; lo de adentro con el mismo número
#   es la misma celda;
# - su fecha, por un atributo que la trae entera (aria-label, title, data-date…) con ese mismo día; si no, por el mes y
#   el año de la única leyenda «September 2026» de su bloque; y si el calendario no trae ninguna leyenda, por los de
#   su cabecera: un solo botón a la vista cuyo nombre es un mes y uno solo cuyo nombre es un año, y solo si sus días,
#   sin los marcados de otro mes, van del 1 al último de ese mes, una vez cada uno (decisión de Marcelo, encargo 48:
#   con el calendario del 02-10, la regla elige el 13-10). Los días marcados de otro mes no toman la leyenda ni la
#   cabecera, y una fecha que queda en dos celdas queda solo en la de su propio mes, o en ninguna;
# - deshabilitada, si ella o lo de adentro trae disabled, aria-disabled="true", o una clase o un part con disab, inact,
#   unavailable, out-of-range, not-allowed o blocked.
# Lo que no se identifica así no se pulsa (_mk_elegir_dia_de_retiro): la reserva queda NO ENVIADA, y la evidencia
# mk_f<fila>_calendario deja el HTML del calendario para medirlo. Hasta el encargo 48, sin una leyenda, ningún día tenía
# fecha: así quedó NO ENVIADA la fila de MAERSK del 2026-10-02 (CICLO-msc-recarga-y-corrida-02-10.md).
_JS_MK_DIAS = r"""
    function mkCalendario() {
        const todos = mkRecorrer();
        const nombre = e => (mkAtr(e, 'label') || mkAtr(e, 'aria-label') || mkTexto(e)).trim().toLowerCase();
        const esBoton = e => ['button', 'mc-button'].includes(mkTag(e)) || mkAtr(e, 'role') === 'button';
        const listos = todos.filter(x => esBoton(x.el) && nombre(x.el) === 'done' && mkVisible(x.el));
        const deListos = new Set(listos.map(x => x.el));
        const unicos = listos.filter(x => !x.anc.some(a => deListos.has(a)));
        if (unicos.length !== 1) return {listos: unicos.length, raiz: false, meses: [], dias: []};
        const numero = e => { const t = mkTexto(e); return /^\d{1,2}$/.test(t) ? +t : 0; };
        // Un número de semana: una clase o un part con «week» que no sea «weekend» (revisión del encargo 36).
        const deSemana = e => mkTag(e) === 'th' || /week(?!end)/i.test(mkAtr(e, 'class') + ' ' + mkAtr(e, 'part'))
                              || /header/i.test(mkAtr(e, 'role'));
        const pulsable = e => ['button', 'td', 'a'].includes(mkTag(e)) || e.hasAttribute('tabindex')
                              || ['gridcell', 'button', 'option'].includes(mkAtr(e, 'role')) || /day/i.test(mkTag(e));
        const cands = todos.filter(x => numero(x.el) >= 1 && numero(x.el) <= 31 && pulsable(x.el) && !deSemana(x.el)
                                        && mkVisible(x.el));
        const deCands = new Set(cands.map(x => x.el));
        // Una celda: el candidato de más afuera. Los de adentro son la misma celda: su texto entero es el mismo número.
        const celdas = cands.filter(x => !x.anc.some(a => deCands.has(a))).map(x => ({x, dia: numero(x.el),
            miembros: cands.filter(y => y.el === x.el || y.anc.includes(x.el))}));
        const cuenta = new Map();
        for (const c of celdas) for (const a of c.x.anc) cuenta.set(a, (cuenta.get(a) || 0) + 1);
        const raiz = unicos[0].anc.slice().reverse().find(a => (cuenta.get(a) || 0) >= 28);
        if (!raiz) return {listos: 1, raiz: false, meses: [], dias: []};
        const enRaiz = x => x.el === raiz || x.anc.includes(raiz);
        const leyendas = todos.filter(x => enRaiz(x) && mkVisible(x.el)).map(x => {
            const m = mkTexto(x.el).match(/^([A-Za-z]{3,9})\.?,?\s+(\d{4})$/);
            return m && mkMes(m[1]) >= 0 ? {x, clave: m[2] + '-' + String(mkMes(m[1]) + 1).padStart(2, '0')} : null;
        }).filter(Boolean);
        const mesDe = c => {
            for (let k = c.x.anc.length - 1; k >= c.x.anc.indexOf(raiz); k--) {
                const a = c.x.anc[k];
                const claves = new Set(leyendas.filter(l => l.x.el === a || l.x.anc.includes(a)).map(l => l.clave));
                if (claves.size === 1) return [...claves][0];
                if (claves.size > 1) return '';
            }
            return '';
        };
        const ATRS = ['aria-label', 'title', 'data-date', 'data-day', 'data-value', 'data-iso', 'datetime', 'value',
                      'id', 'date', 'data-test'];
        const porAtributo = c => {
            const fs = new Set();
            for (const m of c.miembros) for (const a of ATRS) for (const f of mkFechasEn(mkAtr(m.el, a)))
                if (+f.slice(8, 10) === c.dia) fs.add(f);
            return fs.size === 1 ? [...fs][0] : '';
        };
        const marcas = c => c.miembros.map(m => mkAtr(m.el, 'class') + ' ' + mkAtr(m.el, 'part')).join(' ');
        const FUERA = new RegExp(['outside', 'other-?month', 'adjacent', 'out-?of-?month', 'not-?current',
                                  'prev-?month', 'next-?month', 'overflow', 'different-?month'].join('|'), 'i');
        const APAGADO = /disab|inact|unavailable|out-?of-?range|not-?allowed|blocked/i;
        const fueraDe = c => FUERA.test(marcas(c)) || c.miembros.some(m => mkAtr(m.el, 'aria-hidden') === 'true');
        // Sin una leyenda, el mes y el año de la cabecera (encargo 48): un solo botón a la vista cuyo nombre es un mes
        // y uno solo cuyo nombre es un año, si los días, sin los de otro mes, van del 1 al último de ese mes.
        const cabecera = () => {
            const botones = todos.filter(x => enRaiz(x) && esBoton(x.el) && mkVisible(x.el));
            const unico = calza => {
                const c = botones.filter(x => calza(nombre(x.el)));
                const de = new Set(c.map(x => x.el));
                const afuera = c.filter(x => !x.anc.some(a => de.has(a)));
                return afuera.length === 1 ? nombre(afuera[0].el) : '';
            };
            const mes = unico(t => /^[a-z]{3,9}$/.test(t) && mkMes(t) >= 0), anio = unico(t => /^\d{4}$/.test(t));
            if (!mes || !anio) return '';
            const ultimo = new Date(Date.UTC(+anio, mkMes(mes) + 1, 0)).getUTCDate();
            const numeros = celdas.filter(c => enRaiz(c.x) && !fueraDe(c)).map(c => c.dia).sort((a, b) => a - b);
            return numeros.length === ultimo && numeros.every((n, i) => n === i + 1)
                ? anio + '-' + String(mkMes(mes) + 1).padStart(2, '0') : '';
        };
        const cab = leyendas.length ? '' : cabecera();
        const dias = celdas.filter(c => enRaiz(c.x)).map(c => {
            const fuera = fueraDe(c);
            let fecha = porAtributo(c), como = fecha ? 'atributo' : '';
            if (!fecha && !fuera) {
                const k = mesDe(c) || cab;
                fecha = k ? mkIso(+k.slice(0, 4), +k.slice(5, 7) - 1, c.dia) : '';
                como = fecha ? (cab ? 'cabecera' : 'mes') : '';
            }
            const habilitado = !APAGADO.test(marcas(c)) && !c.miembros.some(m => m.el.hasAttribute('disabled')
                                                                         || mkAtr(m.el, 'aria-disabled') === 'true');
            return {c, dia: c.dia, fecha, como: como || (fuera ? 'otro-mes' : ''), habilitado};
        });
        // Una fecha en más de una celda: queda solo en la de su propio mes (la leyenda de su bloque es la de esa
        // fecha), si hay una sola así; si no, en ninguna (revisión del encargo 36: con dos meses a la vista, el 1-10 de
        // la grilla de septiembre ya no borra el de la de octubre).
        const veces = new Map();
        for (const d of dias) if (d.fecha) veces.set(d.fecha, (veces.get(d.fecha) || []).concat([d]));
        for (const [f, ds] of veces) {
            if (ds.length < 2) continue;
            const propias = ds.filter(d => mesDe(d.c) === f.slice(0, 7));
            for (const d of ds) if (propias.length !== 1 || d !== propias[0]) { d.fecha = ''; d.como = 'repetida'; }
        }
        // El «Done» del calendario, para pulsarlo: su botón de más adentro (el de un mc-button está en su raíz shadow).
        const [done] = unicos;
        const botones = todos.filter(y => y.anc.includes(done.el) && mkTag(y.el) === 'button');
        const listo = botones.find(b => !botones.some(o => o.el !== b.el && o.anc.includes(b.el))) || done;
        return {listos: 1, raiz: true, meses: [...new Set(leyendas.map(l => l.clave))], dias, listo: listo.el};
    }
    // Lo que se pulsa de una celda: su botón de más adentro, si tiene; si no, la celda.
    const mkPulsable = c => {
        const b = c.miembros.find(m => mkTag(m.el) === 'button' && !c.miembros.some(o => o.el !== m.el
                                  && mkTag(o.el) === 'button' && o.anc.includes(m.el)));
        return b ? b.el : c.x.el;
    };
"""

_JS_MK_CALENDARIO = "() => {" + _JS_MK_RECORRER + _JS_MK_FECHAS + _JS_MK_DIAS + r"""
    const r = mkCalendario();
    return {listos: r.listos, raiz: r.raiz, meses: r.meses,
            dias: r.dias.map(d => ({dia: d.dia, fecha: d.fecha, como: d.como, habilitado: d.habilitado}))};
}"""

# El día elegido, para pulsarlo: vuelve a leer el calendario, y lo da solo si esa fecha está en una sola celda
# habilitada.
_JS_MK_DIA_DE_RETIRO = "(a) => {" + _JS_MK_RECORRER + _JS_MK_FECHAS + _JS_MK_DIAS + r"""
    const c = mkCalendario().dias.filter(d => d.fecha === a.fecha && d.habilitado);
    return c.length === 1 ? mkPulsable(c[0].c) : null;
}"""

# El «Done» del calendario, para pulsarlo: vuelve a leer el calendario, y lo da solo si lo encuentra (su único «Done» a
# la vista, con al menos 28 días alrededor). Un «Done» que no es del calendario no se pulsa (revisión del encargo 36).
_JS_MK_LISTO = "() => {" + _JS_MK_RECORRER + _JS_MK_FECHAS + _JS_MK_DIAS + r"""
    const r = mkCalendario();
    return r.raiz ? r.listo : null;
}"""

# La tarjeta de la fecha de retiro (medida en mk_f10_sin_objetivo.html del 27-09): la sección
# #containerPickupDatePicker; sin fecha, trae «No date selected» (data-test "haulage-invalid-date"). Con fecha, su forma
# no está medida: en las capturas del 21-09, el OCR lee el mes con su año («September 2026»), pero no el número del día
# junto a él. Da la fecha escrita entera, o el mes con su año y el único número de día suelto de la tarjeta; y el valor
# del input type=date oculto de su sección (data-test "sameContainersPickupDateDetails"), si trae uno.
_JS_MK_RETIRO_PUESTO = "() => {" + _JS_MK_RECORRER + _JS_MK_FECHAS + r"""
    const todos = mkRecorrer();
    const tarjetas = todos.filter(x => mkAtr(x.el, 'id') === 'containerPickupDatePicker');
    if (tarjetas.length !== 1) return {tarjeta: false, vacia: false, fechas: [], valor: ''};
    const t = tarjetas[0].el;
    const dentro = todos.filter(x => x.anc.includes(t));
    const vacia = dentro.some(x => mkAtr(x.el, 'data-test') === 'haulage-invalid-date' && mkVisible(x.el));
    const texto = mkTexto(t);
    let fechas = mkFechasEn(texto);
    if (!fechas.length) {
        const meses = [...texto.matchAll(/(?<![A-Za-z])([A-Za-z]{3,9})\.?,?\s+(\d{4})(?!\d)/g)]
            .filter(m => mkMes(m[1]) >= 0);
        const sueltos = [...new Set(dentro.map(x => mkTexto(x.el)).filter(s => /^\d{1,2}$/.test(s)))];
        const f = meses.length === 1 && sueltos.length === 1
            ? mkIso(+meses[0][2], mkMes(meses[0][1]), +sueltos[0]) : '';
        fechas = f ? [f] : [];
    }
    const secciones = todos.filter(x => mkAtr(x.el, 'data-test') === 'sameContainersPickupDateDetails');
    const campos = secciones.length === 1 ? todos.filter(x => x.anc.includes(secciones[0].el) && mkTag(x.el) === 'input'
        && String(x.el.type || mkAtr(x.el, 'type')).toLowerCase() === 'date') : [];
    const valor = campos.length === 1 ? String(campos[0].el.value || '') : '';
    return {tarjeta: true, vacia, fechas, valor: /^\d{4}-\d{2}-\d{2}$/.test(valor) ? valor : ''};
}"""

# Los avisos a la vista que hablan de cargos (charge, fee y cost como palabras enteras, para que «discharge» no cuente;
# free time, demurrage, detention): los mc-notification (su heading, su body y su texto) y lo que tiene role alert o
# status. Medido en mk_f10_sin_objetivo.html (27-09): junto a la fecha, antes de elegirla, «Additional charges can incur
# if the container is picked up from a different location than the origin or the date selected exceeds the agreed free
# time…» (data-test "haulage-disclaimer").
_JS_MK_AVISOS_CARGOS = "() => {" + _JS_MK_RECORRER + r"""
    const CARGOS = /\bcharges?\b|\bfees?\b|\bcosts?\b|free ?time|demurrage|detention/i;
    const out = [];
    for (const x of mkRecorrer()) {
        const e = x.el;
        const aviso = mkTag(e) === 'mc-notification' || ['alert', 'status'].includes(mkAtr(e, 'role'));
        if (!aviso || !mkVisible(e)) continue;
        const t = [mkAtr(e, 'heading'), mkAtr(e, 'body'), mkTexto(e)].filter(Boolean).join(' · ')
            .replace(/\s+/g, ' ').trim();
        if (CARGOS.test(t)) out.push(t.slice(0, 300));
    }
    return [...new Set(out)];
}"""


def _feriados_de_chile(hoy):
    """Los feriados de Chile para la fecha de retiro de MAERSK (decisión de Marcelo, CICLO-maersk-shipper-y-cortes.md):
    los de la librería holidays, country_holidays("CL"), de este año y del siguiente, copiados a un diccionario de fecha
    a nombre dentro del try: la librería calcula cada año recién al consultarlo, y un fallo ahí escaparía como ERROR
    (revisión del encargo 38). Si la librería no está o falla, lo avisa una vez por corrida
    (_avisar_en_pantalla_y_log) y devuelve {}: los días hábiles quedan de lunes a viernes. Se instala con
    «python -m pip install --user holidays»."""
    try:
        import holidays
        return dict(holidays.country_holidays("CL", years=(hoy.year, hoy.year + 1)))
    except Exception as e:
        _avisar_en_pantalla_y_log(
            f"⚠ No pude usar los feriados de Chile de la librería holidays ({_texto_error(e)}): la fecha de retiro "
            f"de MAERSK sigue de lunes a viernes, sin feriados. Se instala con «python -m pip install --user "
            f"holidays».",
            una_vez="feriados")
        return {}


def _mk_dia_habil(d, feriados=()):
    """Un día hábil: de lunes a viernes, y que no sea feriado ('feriados', de _feriados_de_chile)."""
    return d.weekday() < 5 and d not in feriados


def _mk_dia_de_retiro(hoy, feriados=()):
    """El primer día hábil después de 'hoy' (_mk_dia_habil): del viernes, del sábado o del domingo, el lunes siguiente,
    si no es feriado. Con 'feriados' vacío, la regla queda de lunes a viernes."""
    d = hoy + datetime.timedelta(days=1)
    while not _mk_dia_habil(d, feriados):
        d += datetime.timedelta(days=1)
    return d


def _mk_feriados_saltados(hoy, objetivo, feriados):
    """Los feriados de lunes a viernes entre 'hoy' y 'objetivo', para decirlo en log.txt: «; el 12-10-2026 (nombre)
    es feriado en Chile», o «» si no hay."""
    dias = [hoy + datetime.timedelta(days=i) for i in range(1, (objetivo - hoy).days)]
    saltados = [f"el {d:%d-%m-%Y} ({feriados.get(d) or 'feriado'})" for d in dias if d.weekday() < 5 and d in feriados]
    if not saltados:
        return ""
    lista = saltados[0] if len(saltados) == 1 else ", ".join(saltados[:-1]) + " y " + saltados[-1]
    return f"; {lista} {'es feriado' if len(saltados) == 1 else 'son feriados'} en Chile"


def _mk_elegir_dia_de_retiro(dias, objetivo, feriados=()):
    """El día que se elige en el calendario: 'objetivo' si está habilitado; si no, el siguiente día hábil habilitado
    (_mk_dia_habil): nunca un sábado, un domingo ni un feriado de 'feriados' (decisión de Marcelo,
    CICLO-maersk-ultimos-puntos.md y CICLO-maersk-shipper-y-cortes.md; hasta el encargo 37, el siguiente habilitado,
    aunque fuera fin de semana). 'dias' es lo que da _JS_MK_CALENDARIO: cada uno
    con su fecha («AAAA-MM-DD», o vacía si no se pudo identificar) y si está habilitado. 'objetivo' tiene que estar a
    la vista, y cada día hábil desde él hasta el elegido, identificado por su fecha: cambiar de mes sería un clic que no
    está entre los permitidos. Devuelve (fecha, "") o (fecha, por qué no es 'objetivo'); o (None, por qué no se puede
    elegir)."""
    fechas = {}
    for d in dias or []:
        try:
            fechas[datetime.date.fromisoformat(str(d.get("fecha") or ""))] = bool(d.get("habilitado"))
        except ValueError:
            continue
    if not fechas:
        return None, "no pude identificar por su fecha ningún día del calendario"
    primero, ultimo = min(fechas), max(fechas)
    if not primero <= objetivo <= ultimo:
        return None, (f"el día que toca, el {objetivo:%d-%m-%Y}, no está a la vista: el calendario muestra del "
                      f"{primero:%d-%m-%Y} al {ultimo:%d-%m-%Y}, y cambiar de mes es un clic que no está permitido")
    d = objetivo
    while d <= ultimo:
        if not _mk_dia_habil(d, feriados):
            d += datetime.timedelta(days=1)
            continue
        if d not in fechas:
            return None, f"no pude identificar por su fecha el {d:%d-%m-%Y} en el calendario"
        if fechas[d]:
            return d, ("" if d == objetivo else f"el {objetivo:%d-%m-%Y} no está habilitado en el calendario: elijo el "
                                                f"siguiente día hábil habilitado, el {d:%d-%m-%Y} "
                                                f"({_DIAS_ES[d.weekday()]})")
        d += datetime.timedelta(days=1)
    return None, (f"no hay un día hábil habilitado del {objetivo:%d-%m-%Y} al {ultimo:%d-%m-%Y}, el último que muestra "
                  f"el calendario, y cambiar de mes es un clic que no está permitido")


def _mk_resumen_calendario(cal):
    """Una línea para log.txt con lo que leyó _JS_MK_CALENDARIO: cuántos días, cuántos con su fecha y habilitados, entre
    qué fechas y cómo se identificaron; o, si no lo encontró, por qué (_mk_sin_calendario)."""
    if not cal.get("raiz"):
        return f"no lo encontré: {_mk_sin_calendario(cal)}"
    dias = cal.get("dias") or []
    con = [str(d.get("fecha")) for d in dias if d.get("fecha")]
    habiles = sum(1 for d in dias if d.get("fecha") and d.get("habilitado"))
    como = {}
    for d in dias:
        k = d.get("como") or "sin fecha"
        como[k] = como.get(k, 0) + 1
    rango = f", del {min(con)} al {max(con)}" if con else ""
    return (f"{len(dias)} días, {len(con)} con su fecha y {habiles} de ellos habilitados{rango} ("
            + (", ".join(f"{k}: {v}" for k, v in sorted(como.items())) or "ninguno") + ")")


def _mk_sin_calendario(cal):
    """Por qué _JS_MK_CALENDARIO no encontró el calendario, según cuántos «Done» había a la vista."""
    n = cal.get("listos") or 0
    if n > 1:
        return f"había {n} «{MK_LISTO}» a la vista, y no sé cuál es el del calendario"
    if n == 1:
        return f"junto al «{MK_LISTO}» a la vista no hay un calendario de al menos 28 días"
    return f"no apareció el calendario en {MK_ESPERA_CALENDARIO} s (ningún «{MK_LISTO}» a la vista)"


def _mk_esperar_calendario(page, reg):
    """Espera hasta MK_ESPERA_CALENDARIO s a que _JS_MK_CALENDARIO encuentre el calendario: su único «Done» a la vista,
    con al menos 28 días alrededor. Con más de un «Done», no espera más. Anota en log.txt lo que leyó
    (_mk_resumen_calendario) y lo devuelve; {} si no se pudo leer. Hasta la revisión del encargo 36 esperaba un «Done»
    cualquiera: uno que ya estuviera en la página contaba como el del calendario."""
    cal = {}
    for _ in range(MK_ESPERA_CALENDARIO * 2):
        esperar(page, 0.5)
        try:
            cal = page.evaluate(_JS_MK_CALENDARIO)
        except Exception:
            cal = {}
        cal = cal if isinstance(cal, dict) else {}
        if cal.get("raiz") or (cal.get("listos") or 0) > 1:
            break
    reg.info(f"calendario de la fecha de retiro: {_mk_resumen_calendario(cal)}")
    return cal


def _mk_avisos_de_cargos(page):
    """Los avisos de cargos a la vista (_JS_MK_AVISOS_CARGOS); [] si no se pudieron leer."""
    try:
        r = page.evaluate(_JS_MK_AVISOS_CARGOS)
    except Exception:
        return []
    return [" ".join(str(t).split())[:300] for t in r] if isinstance(r, list) else []


def _mk_anotar_cargos(page, reg, antes, anotados):
    """Anota en log.txt cada aviso de cargos a la vista que todavía no anotó ('anotados'), y si ya estaba antes de
    elegir la fecha ('antes'). La reserva sigue (decisión de Marcelo, CICLO-maersk-retiro-y-terminos.md)."""
    for t in _mk_avisos_de_cargos(page):
        if t not in anotados:
            anotados.add(t)
            ya = " (ya estaba antes de elegirla)" if t in antes else ""
            reg.info(f"aviso de MAERSK sobre la fecha de retiro{ya}: «{t}»")


def _mk_fecha_de_retiro(page, reg, det, f, hoy=None):
    """La fecha de retiro de «Additional details» (decisión de Marcelo, CICLO-maersk-retiro-y-terminos.md): el primer
    día hábil después de hoy (_mk_dia_de_retiro) o, si no está habilitado, el siguiente día hábil habilitado, nunca un
    sábado, un domingo ni un feriado de Chile (_mk_elegir_dia_de_retiro, _feriados_de_chile;
    CICLO-maersk-ultimos-puntos.md y CICLO-maersk-shipper-y-cortes.md). Espera hasta
    MK_ESPERA_CALENDARIO s el botón «Choose another date», lo pulsa, espera el calendario (_mk_esperar_calendario), deja
    su evidencia (mk_f<fila>_calendario), pulsa el día y el «Done» del calendario (_mk_pulsar_dia_y_listo), anota los
    avisos de cargos y mira la fecha que quedó (_mk_comprobar_retiro). Sin un solo «Choose another date» a la vista, o
    con un «Done» ya en la página, corta sin pulsar nada (ObjetivoNoEncontrado). Después de pulsarlo, si el calendario
    no aparece o el día no se puede elegir por su fecha, devuelve el corte, NO ENVIADA, sin otro clic (FRENO de
    Marcelo: ningún clic fuera de esos tres, ni cambiar de mes). Si no, None."""
    hoy = hoy or datetime.date.today()
    feriados = _feriados_de_chile(hoy)
    objetivo = _mk_dia_de_retiro(hoy, feriados)
    reg.paso(f"Fecha de retiro: el primer día hábil después de hoy es el {objetivo:%d-%m-%Y} "
             f"({_DIAS_ES[objetivo.weekday()]}){_mk_feriados_saltados(hoy, objetivo, feriados)}.")
    boton, n = None, 0
    for _ in range(MK_ESPERA_CALENDARIO * 2):
        boton, n = _mk_boton_unico(page, MK_OTRA_FECHA)
        if n:
            break
        esperar(page, 0.5)
    listos = _mk_boton_unico(page, MK_LISTO)[1]
    if boton is None or listos:
        raise ObjetivoNoEncontrado("Fecha de retiro de MAERSK", f"un solo botón «{MK_OTRA_FECHA}» a la vista y ningún "
                                                              f"«{MK_LISTO}» antes de abrir el calendario (había {n} y "
                                                              f"{listos})")
    antes, anotados = set(_mk_avisos_de_cargos(page)), set()
    try:
        boton.scroll_into_view_if_needed(timeout=3000)
        boton.click(timeout=4000)
    except Exception as e:
        return _no_enviada(reg, f"MAERSK: falló el clic en «{MK_OTRA_FECHA}» ({_texto_error(e)}); {_MK_NADA_MAS}")
    reg.info(f"pulsado '{MK_OTRA_FECHA}'")
    cal = _mk_esperar_calendario(page, reg)
    _evidencia_antes_de_la_guarda(page, reg, f"mk_f{f}_calendario", "con el calendario de la fecha de retiro",
                                  completa=False)
    if not cal.get("raiz"):
        return _no_enviada(reg, f"MAERSK: pulsé «{MK_OTRA_FECHA}», pero {_mk_sin_calendario(cal)}; {_MK_NADA_MAS}")
    elegido, por_que = _mk_elegir_dia_de_retiro(cal.get("dias"), objetivo, feriados)
    if elegido is None:
        return _no_enviada(reg, f"MAERSK: abrí el calendario de la fecha de retiro, pero {por_que}; {_MK_NADA_MAS}")
    if por_que:
        reg.paso(f"Fecha de retiro: {por_que}.")
    return (_mk_pulsar_dia_y_listo(page, reg, det, elegido, antes, anotados)
            or _mk_comprobar_retiro(page, reg, f, elegido))


def _mk_pulsar_dia_y_listo(page, reg, det, elegido, antes, anotados):
    """Pulsa el día elegido por su fecha (_JS_MK_DIA_DE_RETIRO, que vuelve a leer el calendario), anota los avisos de
    cargos y pulsa el «Done» del calendario (_JS_MK_LISTO); si el calendario se cerró solo, no hace falta. Devuelve
    None, o el corte, NO ENVIADA sin otro clic: si el día ya no está, si hay un «Done» que no es del calendario o si
    falla un clic."""
    try:
        dia = page.evaluate_handle(_JS_MK_DIA_DE_RETIRO, {"fecha": elegido.isoformat()}).as_element()
        if dia is None:
            return _no_enviada(reg, f"MAERSK: al volver a leer el calendario, el {elegido:%d-%m-%Y} ya no estaba "
                                    f"habilitado o no era uno solo; {_MK_NADA_MAS}")
        dia.click(timeout=4000)
    except Exception as e:
        return _no_enviada(reg, f"MAERSK: falló el clic en el {elegido:%d-%m-%Y} del calendario ({_texto_error(e)}); "
                                f"{_MK_NADA_MAS}")
    reg.info(f"elegido en el calendario: {elegido:%d-%m-%Y} ({_DIAS_ES[elegido.weekday()]})")
    det.append(f"retiro={elegido:%d-%m-%Y}")
    esperar(page, 0.5)
    _mk_anotar_cargos(page, reg, antes, anotados)
    try:
        listo = page.evaluate_handle(_JS_MK_LISTO).as_element()
        otros = 0 if listo is not None else _mk_boton_unico(page, MK_LISTO)[1]
        if otros:
            return _no_enviada(reg, f"MAERSK: elegí el {elegido:%d-%m-%Y}, pero había {otros} «{MK_LISTO}» a la vista "
                                    f"y ninguno es el del calendario; {_MK_NADA_MAS}")
        if listo is None:
            reg.info(f"el calendario se cerró al elegir el día, sin «{MK_LISTO}»")
        else:
            listo.click(timeout=4000)
            reg.info(f"pulsado '{MK_LISTO}'")
    except Exception as e:
        return _no_enviada(reg, f"MAERSK: elegí el {elegido:%d-%m-%Y}, pero falló el clic en «{MK_LISTO}» "
                                f"({_texto_error(e)}); {_MK_NADA_MAS}")
    esperar(page, 1.0)
    _mk_anotar_cargos(page, reg, antes, anotados)
    return None


def _mk_comprobar_retiro(page, reg, f, elegido):
    """La fecha que quedó (_JS_MK_RETIRO_PUESTO), hasta 5 s mientras la tarjeta no la muestre: sin fecha, sin tarjeta o
    sin poder leerla (revisión del encargo 37: hasta ahí esperaba solo sin fecha). Si muestra la elegida (la tarjeta
    puede traer otras fechas además de ella), lo anota y devuelve None. Si no, deja la evidencia mk_f<fila>_retiro y
    devuelve el corte, NO ENVIADA: si sigue sin fecha (con lo que el portal pide), si el campo oculto o la tarjeta
    muestran otra, o si no se puede leer qué fecha muestra. Hasta el encargo 37, esto último seguía con un aviso
    (decisión de Marcelo, CICLO-maersk-ultimos-puntos.md)."""
    r, error = {}, ""
    for intento in range(10):
        if intento:
            esperar(page, 0.5)
        try:
            r, error = page.evaluate(_JS_MK_RETIRO_PUESTO), ""
        except Exception as e:
            r, error = {}, _texto_error(e)
        r = r if isinstance(r, dict) else {}
        if r.get("tarjeta") and not r.get("vacia") and (r.get("fechas") or r.get("valor")):
            break
    fechas, valor, iso = {str(x) for x in (r.get("fechas") or [])}, str(r.get("valor") or ""), elegido.isoformat()
    otra = (valor and valor != iso) or (fechas and iso not in fechas)
    if not r.get("vacia") and not otra and (valor == iso or iso in fechas):
        reg.info(f"la tarjeta muestra la fecha de retiro elegida, el {elegido:%d-%m-%Y}")
        return None
    _evidencia_antes_de_la_guarda(page, reg, f"mk_f{f}_retiro", "después de elegir la fecha de retiro",
                                  completa=False)
    if r.get("vacia"):
        pide = _mk_lo_que_pide(page)
        return _no_enviada(reg, f"MAERSK: elegí el {elegido:%d-%m-%Y} en el calendario, pero la tarjeta sigue sin "
                                f"fecha de retiro{f' y el portal pide: {pide}' if pide else ''}; {_MK_NADA_MAS}")
    if otra:
        otras = sorted((fechas | ({valor} if valor else set())) - {iso})
        muestra = ", ".join(datetime.date.fromisoformat(v).strftime("%d-%m-%Y") for v in otras)
        return _no_enviada(reg, f"MAERSK: elegí el {elegido:%d-%m-%Y} en el calendario, pero el portal quedó con el "
                                f"{muestra}; {_MK_NADA_MAS}")
    if error:
        cual = f" (no pude leer la página: {error})"
    else:
        cual = "" if r.get("tarjeta") else " (no la encontré)"
    return _no_enviada(reg, f"MAERSK: elegí el {elegido:%d-%m-%Y} en el calendario, pero no pude leer qué fecha "
                            f"muestra la tarjeta{cual}; {_MK_NADA_MAS}")


# La referencia de retiro («haulage reference») de «Additional details», por lo que es: el único textarea a la vista con
# name="haulageReference" (medido en mk_f10_sin_objetivo.html del 27-09: el de la raíz shadow del mc-textarea «Enter
# haulage reference (optional)»; ese name lo llevan también el mc-textarea y un input oculto, que no son textarea).
# Hasta el encargo 37 iba en «el primer textarea» («mc-textarea textarea, textarea», .first), que ese día era el campo
# oculto del asistente «Ask Maersk», y llegaba a su campo por el respaldo de la etiqueta (decisión de Marcelo,
# CICLO-maersk-ultimos-puntos.md).
MK_REFERENCIA = "textarea[name='haulageReference']"


def _mk_referencia_de_retiro(page, reg, det, texto):
    """Escribe 'texto' en la referencia de retiro (MK_REFERENCIA). Sin un solo campo a la vista, corta sin escribir
    (ObjetivoNoEncontrado); si falla el clic o la escritura, devuelve el corte, NO ENVIADA. Si no, None."""
    error = ""
    try:
        campos = page.locator(MK_REFERENCIA)
        vistos = [campos.nth(i) for i in range(campos.count()) if campos.nth(i).is_visible()]
    except Exception as e:
        vistos, error = [], _texto_error(e)
    if len(vistos) != 1:
        cuantos = f"no pude leer la página: {error}" if error else f"había {len(vistos)}"
        raise ObjetivoNoEncontrado("Referencia de retiro de MAERSK",
                                   f"un solo campo «haulageReference» a la vista ({cuantos})")
    [campo] = vistos
    try:
        campo.scroll_into_view_if_needed(timeout=3000)
        campo.click(timeout=3000)
        campo.fill(texto, timeout=3000)
    except Exception as e:
        return _no_enviada(reg, f"MAERSK: falló la escritura de la referencia de retiro ({_texto_error(e)}); "
                                f"{_MK_NADA_MAS}")
    reg.info(f"haulage reference completada: '{texto}'")
    det.append("haulageRef=" + texto)
    return None


# El Shipper de «Additional details», por lo que es: la única tarjeta de parte a la vista con title="Shipper" (medido en
# mk_f10_sin_objetivo.html del 27-09: un mc-c-party-card con title="Shipper" e id="shipper", con el nombre del cliente
# en su raíz shadow; las demás partes usan el mismo componente con otro title). Si no trae a AQUACHILE, lo elige con dos
# clics, cada uno por lo que es (decisión de Marcelo, CICLO-maersk-shipper-y-cortes.md): el «Add» de esa tarjeta, por
# su texto, y en el buscador de partes el único resultado a la vista con AQUACHILE como palabra entera. Medido en el
# mismo HTML, que es de después de los clics de antes:
# - cada una de las 8 tarjetas vacías trae un solo mc-button «Add» (data-cy="addButton") en su raíz shadow; el de la
#   tarjeta del Shipper vacía se infiere de ellas;
# - el buscador es uno solo (mc-c-party-finder), con su ventana titulada «Shipper» y la pestaña «Previously used»
#   activa; sus resultados se ven sin buscar, cada uno un label con su mc-c-party-card, y no tiene botón de confirmar:
#   solo «Close», las dos pestañas y «Cancel».
# AQUACHILE se busca en el party__info de cada parte, que trae el nombre y, adentro, el código (party__code): medido en
# las 2 tarjetas llenas y en los 3 resultados, donde el código no trae letras; la dirección no cuenta. La tarjeta se
# identifica por su title: las 8 vacías comparten un mismo id. Antes de elegir, espera que la lista de resultados se
# quede quieta, y después comprueba que la tarjeta muestre a AQUACHILE y que el buscador se haya cerrado: ni sus
# resultados ni su encabezado a la vista (revisión del encargo 38). El segundo clic va al label del resultado, que no
# tiene for (la casilla de opción está a su lado): no está medido si lo elige. Hasta el encargo 37 pulsaba el primer
# «+ Add» de la página y el último elemento con AQUACHILE, y lo más probable es que así lo eligiera; en el encargo 37
# cortaba sin pulsar nada (CICLO-maersk-ultimos-puntos.md).
# Si después del resultado la tarjeta ya muestra a AQUACHILE y el buscador sigue abierto, pulsa su «Close», un tercer
# clic, solo en ese caso (decisión de Marcelo, CICLO-maersk-cuatro-puntos.md): el único mc-button a la vista del
# buscador con label="Close" (medido: uno solo en la página, en la cabecera de la ventana del buscador, con
# data-cy="close" y el texto oculto). La casilla de opción de cada resultado está al lado de su label, fuera de él, y
# nada la une al resultado salvo su posición y las cifras visibles del código: si el clic en el resultado no lo elige,
# se pulsa solo si las dos apuntan a la misma (decisión de Marcelo, CICLO-maersk-busqueda-vacia.md; en el encargo 39 era
# un FRENO); si no, corta.
MK_SHIPPER = "Shipper"
MK_EMPRESA = "AQUACHILE"
MK_AGREGAR = "Add"
MK_CERRAR = "Close"
MK_ESPERA_SHIPPER = 5          # s que espera la tarjeta «Shipper» con AQUACHILE (hipótesis, sin medir)
MK_ESPERA_BUSCADOR = 10        # s que espera en el buscador un resultado con AQUACHILE, quieto (hipótesis, sin medir)
_MK_ARGS_SHIPPER = {"titulo": MK_SHIPPER, "empresa": MK_EMPRESA, "agregar": MK_AGREGAR, "cerrar": MK_CERRAR}

# Lo que leen _JS_MK_SHIPPER y _JS_MK_SHIPPER_PULSAR, con la palabra entera de la nave (_JS_TRAE_LA_NAVE).
_JS_MK_SHIPPER_LEER = r"""
    // El texto de un elemento, nodo por nodo y con el de las raíces shadow de adentro (ahí van los nombres de las
    // partes), separado por espacios: el textContent pegaría el título de la tarjeta al nombre, y ya no sería una
    // palabra entera.
    function mkTextoHondo(e) {
        const partes = [];
        (function w(n) {
            for (const c of (n.childNodes || [])) {
                if (c.nodeType === 3) {
                    partes.push(c.nodeValue || '');
                } else if (c.nodeType === 1 && !['STYLE', 'SCRIPT'].includes(c.tagName)) {
                    if (c.shadowRoot) w(c.shadowRoot);
                    w(c);
                }
            }
        })({childNodes: [...((e.shadowRoot && e.shadowRoot.childNodes) || []), ...(e.childNodes || [])]});
        return partes.join(' ').replace(/\s+/g, ' ').trim().toUpperCase();
    }
    function mkShipper(a) {
        const todos = mkRecorrer();
        // La empresa, en el party__info de cada parte: el nombre y, adentro, el código (party__code); no la dirección.
        const nombres = e => todos.filter(y => y.anc.includes(e)
                                              && mkAtr(y.el, 'class').split(/\s+/).includes('party__info'));
        const conEmpresa = e => nombres(e).some(y => _palabraEn(mkTextoHondo(y.el), String(a.empresa).toUpperCase(),
                                                                0) >= 0);
        const tarjetas = todos.filter(x => mkTag(x.el) === 'mc-c-party-card' && mkAtr(x.el, 'title') === a.titulo
                                           && mkVisible(x.el)).map(x => x.el);
        const [t] = tarjetas;
        // Su «Add»: un mc-button a la vista de esa tarjeta, con ese texto entero.
        const agregar = tarjetas.length !== 1 ? [] : todos.filter(x => x.anc.includes(t)
            && mkTag(x.el) === 'mc-button' && mkTexto(x.el) === a.agregar && mkVisible(x.el));
        // El buscador de partes: sus resultados a la vista (cada uno, un label con su tarjeta), su encabezado, que
        // se ve mientras está abierto, en cualquier pestaña, y su título.
        const enBuscador = x => x.anc.some(y => mkTag(y) === 'mc-c-party-finder');
        const conTarjeta = x => todos.some(y => mkTag(y.el) === 'mc-c-party-card' && y.anc.includes(x.el));
        const resultados = todos.filter(x => mkTag(x.el) === 'label' && enBuscador(x) && mkVisible(x.el)
                                             && conTarjeta(x));
        const encabezados = todos.filter(x => mkAtr(x.el, 'slot') === 'heading' && enBuscador(x) && mkVisible(x.el));
        const titulo = encabezados.some(x => _palabraEn(mkTextoHondo(x.el), String(a.titulo).toUpperCase(), 0) >= 0);
        // Su «Close»: el mc-button a la vista del buscador con ese label (medido el 27-09: uno solo en la página, en la
        // cabecera de la ventana del buscador, con data-cy="close" y el texto oculto).
        const cerrar = todos.filter(x => enBuscador(x) && mkTag(x.el) === 'mc-button'
                                         && mkAtr(x.el, 'label') === a.cerrar && mkVisible(x.el));
        const conLaEmpresa = resultados.map(x => x.el).filter(conEmpresa);
        // La casilla del resultado con la empresa (decisión de Marcelo, CICLO-maersk-busqueda-vacia.md): la que va
        // justo antes de su label, en un contenedor donde casillas (input radio) y labels van alternados, y la única
        // del contenedor cuyo id termina con las cifras del código (party__code) de la tarjeta del resultado; las dos
        // tienen que ser la misma. Si no, 'por' dice por qué no la hay.
        const esCasilla = e => mkTag(e) === 'input' && mkAtr(e, 'type').toLowerCase() === 'radio';
        const casilla = (() => {
            if (!titulo) return {el: null, por: 'titulo'};
            if (conLaEmpresa.length !== 1) return {el: null, por: 'resultado'};
            const [lb] = conLaEmpresa;
            const hijos = [...((lb.parentElement && lb.parentElement.children) || [])];
            const alternados = hijos.length > 0 && hijos.length % 2 === 0
                && hijos.every((h, i) => (i % 2 ? mkTag(h) === 'label' : esCasilla(h)));
            if (!alternados) return {el: null, por: 'posicion'};
            const codigos = todos.filter(y => y.anc.includes(lb)
                                              && mkAtr(y.el, 'class').split(/\s+/).includes('party__code'));
            const cifras = codigos.length === 1 ? mkTextoHondo(codigos[0].el).replace(/\D/g, '') : '';
            if (!cifras) return {el: null, por: 'codigo'};
            const porCifras = hijos.filter(h => esCasilla(h) && mkAtr(h, 'id').endsWith(cifras));
            if (porCifras.length !== 1) return {el: null, por: 'cifras'};
            const [porCodigo] = porCifras;
            return porCodigo === hijos[hijos.indexOf(lb) - 1] ? {el: porCodigo, por: 'coinciden'}
                                                              : {el: null, por: 'distintas'};
        })();
        return {tarjetas, agregar: agregar.map(x => x.el), resultados: resultados.map(x => x.el),
                conEmpresa: conLaEmpresa, titulo, cerrar: cerrar.map(x => x.el),
                abierto: encabezados.length > 0 || resultados.length > 0, casilla: casilla.el, casillaPor: casilla.por,
                empresa: tarjetas.length === 1 ? conEmpresa(t) : null};
    }
"""
_JS_MK_SHIPPER = "(a) => {" + _JS_MK_RECORRER + _JS_TRAE_LA_NAVE + _JS_MK_SHIPPER_LEER + r"""
    const s = mkShipper(a);
    return {n: s.tarjetas.length, empresa: s.empresa, agregar: s.agregar.length, resultados: s.resultados.length,
            con_empresa: s.conEmpresa.length, titulo: s.titulo, abierto: s.abierto, cerrar: s.cerrar.length};
}"""
# Lo que pulsa cada clic, leído otra vez justo antes: con a.que «agregar», el «Add» de la tarjeta; con «resultado», el
# resultado con la empresa en el buscador titulado con el Shipper; con «cerrar», el «Close» del buscador, solo si la
# tarjeta ya muestra a la empresa (CICLO-maersk-cuatro-puntos.md). Solo si es uno; si no, null.
_JS_MK_SHIPPER_PULSAR = "(a) => {" + _JS_MK_RECORRER + _JS_TRAE_LA_NAVE + _JS_MK_SHIPPER_LEER + r"""
    const s = mkShipper(a);
    const lista = a.que === 'agregar' ? s.agregar
                : a.que === 'cerrar' ? (s.empresa === true ? s.cerrar : [])
                : (s.titulo ? s.conEmpresa : []);
    const [uno] = lista;
    return lista.length === 1 ? uno : null;
}"""
# La casilla del resultado con la empresa, para _mk_marcar_casilla: «coinciden» si su posición y las cifras de su código
# apuntan a la misma, o por qué no la hay; y si está marcada (null si no la hay).
_JS_MK_SHIPPER_CASILLA = "(a) => {" + _JS_MK_RECORRER + _JS_TRAE_LA_NAVE + _JS_MK_SHIPPER_LEER + r"""
    const s = mkShipper(a);
    return {casilla: s.casillaPor, marcada: s.casilla ? s.casilla.checked === true : null};
}"""
# Su clic, de JavaScript en el input, leído otra vez justo antes: solo si la hay y la única tarjeta «Shipper» sigue sin
# la empresa. Devuelve si la pulsó.
_JS_MK_SHIPPER_MARCAR = "(a) => {" + _JS_MK_RECORRER + _JS_TRAE_LA_NAVE + _JS_MK_SHIPPER_LEER + r"""
    const s = mkShipper(a);
    if (s.empresa !== false || !s.casilla) return false;
    s.casilla.click();
    return true;
}"""


def _mk_leer_shipper(page, hasta, seg):
    """Lee el Shipper (_JS_MK_SHIPPER) cada medio segundo, hasta 'seg' s, mientras 'hasta' no se cumpla con lo leído.
    Devuelve lo último que leyó (un diccionario, vacío si no pudo) y el error de esa lectura, o «»."""
    r, error = {}, ""
    for intento in range(seg * 2):
        if intento:
            esperar(page, 0.5)
        try:
            r, error = page.evaluate(_JS_MK_SHIPPER, _MK_ARGS_SHIPPER), ""
        except Exception as e:
            r, error = {}, _texto_error(e)
        r = r if isinstance(r, dict) else {}
        if hasta(r):
            break
    return r, error


def _mk_resultados_quietos():
    """Para _mk_leer_shipper: los resultados del buscador, con alguno con AQUACHILE, iguales en dos lecturas seguidas.
    Llegan de a poco, y con la lista a medias «un solo resultado» podría no serlo (revisión del encargo 38)."""
    anterior = {}

    def quietos(r):
        nonlocal anterior
        listo = bool(r.get("con_empresa")) and all(r.get(k) == anterior.get(k)
                                                   for k in ("resultados", "con_empresa", "titulo"))
        anterior = r
        return listo
    return quietos


def _mk_shipper_puesto(r):
    """La única tarjeta «Shipper» a la vista trae a AQUACHILE."""
    return r.get("n") == 1 and r.get("empresa") is True


def _mk_shipper_listo(r):
    """La tarjeta «Shipper» trae a AQUACHILE y el buscador ya se cerró: lo que se espera después de cada clic que lo
    elige."""
    return _mk_shipper_puesto(r) and not r.get("abierto")


def _mk_shipper(page, reg, det, f):
    """El Shipper (decisiones de Marcelo, CICLO-maersk-ultimos-puntos.md y CICLO-maersk-shipper-y-cortes.md): la única
    tarjeta «Shipper» a la vista (_JS_MK_SHIPPER) tiene que traer a AQUACHILE; la espera hasta MK_ESPERA_SHIPPER s. Si
    la trae, lo anota y no pulsa nada. Si no hay una sola tarjeta, o si no lo trae y no hay un solo «Add» a la vista en
    ella, corta sin pulsar nada (ObjetivoNoEncontrado). Si no lo trae, lo elige (_mk_elegir_shipper). Devuelve None, o
    el corte."""
    r, error = _mk_leer_shipper(page, _mk_shipper_puesto, MK_ESPERA_SHIPPER)
    if r.get("n") != 1:
        cuantas = f"no pude leer la página: {error}" if error else f"había {r.get('n') or 0}"
        raise ObjetivoNoEncontrado("Shipper de MAERSK", f"una sola tarjeta «{MK_SHIPPER}» a la vista ({cuantas})")
    if r.get("empresa") is True:
        reg.info(f"Shipper: {MK_EMPRESA} ya viene en la tarjeta «{MK_SHIPPER}»; no pulsé nada")
        det.append("shipper=" + MK_EMPRESA)
        return None
    if r.get("agregar") != 1:
        raise ObjetivoNoEncontrado("Shipper de MAERSK", f"a {MK_EMPRESA} en la tarjeta «{MK_SHIPPER}», ni un solo "
                                                       f"«{MK_AGREGAR}» a la vista en ella para elegirlo (había "
                                                       f"{r.get('agregar') or 0})")
    return _mk_elegir_shipper(page, reg, det, f)


def _mk_elegir_shipper(page, reg, det, f):
    """Elige a AQUACHILE como Shipper con los clics que decidió Marcelo (CICLO-maersk-shipper-y-cortes.md):
    pulsa el «Add» de la tarjeta «Shipper»; espera hasta MK_ESPERA_BUSCADOR s a que el buscador de partes muestre un
    resultado con AQUACHILE y su lista se quede quieta (_mk_resultados_quietos: llegan de a poco), y deja su evidencia
    (mk_f<fila>_buscador); en el buscador titulado «Shipper», pulsa el único resultado a la vista con AQUACHILE; y
    comprueba, hasta MK_ESPERA_SHIPPER s, que la tarjeta lo muestre y que el buscador se haya cerrado. Si la única
    tarjeta no lo muestra, pulsa la casilla de ese resultado, solo si su posición y las cifras de su código apuntan a
    la misma, y lo vuelve a comprobar (_mk_marcar_casilla; decisión de Marcelo, CICLO-maersk-busqueda-vacia.md); si la
    tarjeta lo muestra y el buscador sigue abierto, lo cierra con su «Close» (_mk_cerrar_buscador; decisión de Marcelo,
    CICLO-maersk-cuatro-puntos.md). Cada clic va sobre lo que su JavaScript vuelve a leer justo antes. Si algo de eso
    no se cumple, corta sin otro clic (_mk_shipper_corte): buscar o cambiar de pestaña serían clics que no están
    permitidos. Devuelve None, o el corte."""
    agregar = f"el «{MK_AGREGAR}» de la tarjeta «{MK_SHIPPER}»"
    corte = _mk_pulsar_en_el_shipper(page, reg, f, "agregar", agregar)
    if corte:
        return corte
    r, error = _mk_leer_shipper(page, _mk_resultados_quietos(), MK_ESPERA_BUSCADOR)
    if not r.get("resultados"):
        leer = f" (no pude leer la página: {error})" if error else ""
        return _mk_shipper_corte(page, reg, f, f"pulsé {agregar}, pero el buscador de partes no mostró resultados en "
                                               f"{MK_ESPERA_BUSCADOR} s{leer}")
    _evidencia_antes_de_la_guarda(page, reg, f"mk_f{f}_buscador", "con el buscador del Shipper abierto",
                                  completa=False)
    if not r.get("titulo"):
        return _mk_shipper_corte(page, reg, f, f"pulsé {agregar}, pero el buscador que se abrió no está titulado "
                                               f"«{MK_SHIPPER}»")
    if r.get("con_empresa") != 1:
        cuantos = f"había {r.get('con_empresa') or 0} de {r.get('resultados')}"
        return _mk_shipper_corte(page, reg, f, f"pulsé {agregar}, pero en el buscador no hay un solo resultado con "
                                               f"{MK_EMPRESA} ({cuantos})")
    pulsado = f"el resultado con {MK_EMPRESA} del buscador"
    corte = _mk_pulsar_en_el_shipper(page, reg, f, "resultado", pulsado)
    if corte:
        return corte
    r, error = _mk_leer_shipper(page, _mk_shipper_listo, MK_ESPERA_SHIPPER)
    if r.get("empresa") is False:
        # El clic en el resultado no lo eligió: su casilla, solo si su posición y las cifras de su código apuntan a la
        # misma (_mk_marcar_casilla; decisión de Marcelo, CICLO-maersk-busqueda-vacia.md).
        corte, pulsado = _mk_marcar_casilla(page, reg, f, pulsado)
        if corte:
            return corte
        r, error = _mk_leer_shipper(page, _mk_shipper_listo, MK_ESPERA_SHIPPER)
    if not _mk_shipper_puesto(r):
        que = (f"no pude leer la tarjeta «{MK_SHIPPER}» ({error})" if error
               else f"la tarjeta «{MK_SHIPPER}» no lo muestra")
        return _mk_shipper_corte(page, reg, f, f"pulsé {pulsado}, pero {que}")
    if r.get("abierto"):
        corte = _mk_cerrar_buscador(page, reg, f, r)
        if corte:
            return corte
    reg.info(f"Shipper: elegí a {MK_EMPRESA} en el buscador, y la tarjeta «{MK_SHIPPER}» lo muestra")
    det.append("shipper=" + MK_EMPRESA)
    return None


def _mk_cerrar_buscador(page, reg, f, r):
    """La tarjeta «Shipper» ya muestra a AQUACHILE y el buscador siguió abierto: pulsa su «Close» (MK_CERRAR), el único
    a la vista en el buscador, que _JS_MK_SHIPPER_PULSAR vuelve a leer justo antes y da solo si la tarjeta sigue
    mostrándolo (decisión de Marcelo, CICLO-maersk-cuatro-puntos.md). Antes deja mk_f<fila>_cerrar: ese estado no se ha
    visto nunca (el HTML del 27-09 tiene el buscador cerrado). Comprueba, hasta MK_ESPERA_SHIPPER s, que el buscador
    se haya cerrado y que la tarjeta lo siga mostrando. Si no, corta sin otro clic. 'r' es la última lectura de
    _JS_MK_SHIPPER. Devuelve None, o el corte."""
    if r.get("cerrar") != 1:
        return _mk_shipper_corte(page, reg, f, f"la tarjeta «{MK_SHIPPER}» ya muestra a {MK_EMPRESA}, pero el buscador "
                                               f"siguió abierto y no hay un solo «{MK_CERRAR}» a la vista en él "
                                               f"(había {r.get('cerrar') or 0})")
    cerrar = f"el «{MK_CERRAR}» del buscador"
    _evidencia_antes_de_la_guarda(page, reg, f"mk_f{f}_cerrar", f"con el buscador abierto y {MK_EMPRESA} en la tarjeta",
                                  completa=False)
    # La relectura no lo da si ya no hay un solo «Close» o si la tarjeta ya no muestra a AQUACHILE (revisión del
    # encargo 39: el motivo decía solo lo primero).
    corte = _mk_pulsar_en_el_shipper(page, reg, f, "cerrar", cerrar,
                                     releido=f"al volver a leer la página, ya no había un solo «{MK_CERRAR}» a la "
                                             f"vista en el buscador, o la tarjeta «{MK_SHIPPER}» ya no mostraba a "
                                             f"{MK_EMPRESA}")
    if corte:
        return corte
    r, error = _mk_leer_shipper(page, _mk_shipper_listo, MK_ESPERA_SHIPPER)
    if error:
        return _mk_shipper_corte(page, reg, f, f"pulsé {cerrar}, pero no pude leer la página ({error})")
    if r.get("abierto"):
        return _mk_shipper_corte(page, reg, f, f"pulsé {cerrar}, pero siguió abierto")
    if not _mk_shipper_puesto(r):
        return _mk_shipper_corte(page, reg, f, f"pulsé {cerrar}, pero la tarjeta «{MK_SHIPPER}» ya no muestra a "
                                               f"{MK_EMPRESA}")
    return None


# Por qué no se pulsa la casilla del resultado con AQUACHILE, según _JS_MK_SHIPPER_CASILLA (decisión de Marcelo,
# CICLO-maersk-busqueda-vacia.md). Medido en el HTML del 27-09: la posición y las cifras del código apuntan a la misma
# casilla en los 3 resultados. Va con un clic de JavaScript en el input, como la casilla de los términos, porque su
# estilo no está en el HTML guardado y no se sabe si se ve; no está probado en el portal.
MK_SIN_CASILLA = {"titulo": f"el buscador ya no está titulado «{MK_SHIPPER}»",
                  "resultado": f"no hay un solo resultado con {MK_EMPRESA} a la vista",
                  "posicion": "en su contenedor, las casillas y los resultados no van alternados",
                  "codigo": "la tarjeta del resultado no muestra un solo código con cifras",
                  "cifras": "no hay una sola casilla cuyo id termine con las cifras de su código",
                  "distintas": "la casilla que va antes del resultado no es la que dan las cifras de su código"}


def _mk_marcar_casilla(page, reg, f, pulsado):
    """La única tarjeta «Shipper» no muestra a AQUACHILE después del clic en 'pulsado' (su resultado en el buscador):
    pulsa la casilla de ese resultado, solo si su posición y las cifras de su código apuntan a la misma
    (_JS_MK_SHIPPER_CASILLA), con el clic de JavaScript de _JS_MK_SHIPPER_MARCAR, que la vuelve a leer justo antes.
    Antes deja mk_f<fila>_casilla, el único HTML que puede medir ese estado, y después anota si estaba marcada. Si al
    volver a leer justo antes del clic ya no la da, pero la tarjeta ya muestra a AQUACHILE (el clic en el resultado
    tardó en verse), sigue sin pulsarla (revisión del encargo 40). Si no la hay, o el clic no sale, corta sin otro clic
    (_mk_shipper_corte), como hasta el encargo 40, y el motivo dice por qué. Devuelve el corte, o None, y lo que se
    pulsó para los motivos que siguen: 'pulsado' y, si la pulsó, «y su casilla»."""
    no_la = f"pulsé {pulsado}, pero la tarjeta «{MK_SHIPPER}» no lo muestra, y no pulsé la casilla del resultado"
    try:
        c = page.evaluate(_JS_MK_SHIPPER_CASILLA, _MK_ARGS_SHIPPER)
    except Exception as e:
        return _mk_shipper_corte(page, reg, f, f"{no_la}: no pude leer la página ({_texto_error(e)})"), pulsado
    c = c if isinstance(c, dict) else {}
    if c.get("casilla") != "coinciden":
        razon = MK_SIN_CASILLA.get(c.get("casilla"), "no pude identificarla")
        return _mk_shipper_corte(page, reg, f, f"{no_la}: {razon}"), pulsado
    _evidencia_antes_de_la_guarda(page, reg, f"mk_f{f}_casilla", f"con el resultado de {MK_EMPRESA} sin elegir",
                                  completa=False)
    try:
        pulso = page.evaluate(_JS_MK_SHIPPER_MARCAR, _MK_ARGS_SHIPPER) is True
    except Exception as e:
        return _mk_shipper_corte(page, reg, f, f"falló el clic en la casilla del resultado con {MK_EMPRESA} "
                                               f"({_texto_error(e)})"), pulsado
    if not pulso:
        r, _ = _mk_leer_shipper(page, _mk_shipper_puesto, 1)
        if _mk_shipper_puesto(r):
            reg.info(f"Shipper: la tarjeta «{MK_SHIPPER}» ya muestra a {MK_EMPRESA}; no pulsé la casilla del resultado")
            return None, pulsado
        return _mk_shipper_corte(page, reg, f, f"{no_la}: al volver a leer la página, su posición y las cifras de su "
                                               f"código ya no apuntaban a la misma, o ya no había una sola tarjeta "
                                               f"«{MK_SHIPPER}» sin {MK_EMPRESA}"), pulsado
    marcada = {True: "sí", False: "no"}.get(c.get("marcada"), "no pude leerlo")
    reg.info(f"Shipper: pulsé la casilla del resultado con {MK_EMPRESA}; antes del clic, marcada: {marcada}")
    return None, f"{pulsado} y su casilla"


def _mk_pulsar_en_el_shipper(page, reg, f, que, nombre, releido=""):
    """Pulsa lo que _JS_MK_SHIPPER_PULSAR da para 'que' («agregar», «resultado» o «cerrar»), leído otra vez justo
    antes. Si no lo da, o si el clic falla, devuelve el corte (_mk_shipper_corte); el del primero dice 'releido', si
    viene. Si no, lo anota y devuelve None."""
    try:
        el = page.evaluate_handle(_JS_MK_SHIPPER_PULSAR, dict(_MK_ARGS_SHIPPER, que=que)).as_element()
        if el is None:
            return _mk_shipper_corte(page, reg, f, releido or
                                     f"al volver a leer la página, {nombre} ya no era uno solo a la vista")
        el.scroll_into_view_if_needed(timeout=3000)
        el.click(timeout=4000)
    except Exception as e:
        return _mk_shipper_corte(page, reg, f, f"falló el clic en {nombre} ({_texto_error(e)})")
    reg.info(f"Shipper: pulsé {nombre}")
    return None


def _mk_shipper_corte(page, reg, f, que):
    """El Shipper no quedó elegido: deja la evidencia mk_f<fila>_shipper y devuelve NO ENVIADA con 'que', sin otro
    clic."""
    _evidencia_antes_de_la_guarda(page, reg, f"mk_f{f}_shipper", "en el Shipper", completa=False)
    return _no_enviada(reg, f"MAERSK: {que}; {_MK_NADA_MAS}")


# La casilla de los términos y condiciones de la revisión de MAERSK, por su texto (decisión de Marcelo,
# CICLO-maersk-retiro-y-terminos.md): el que se lee con OCR en las capturas de la revisión del 21-09 (mk_f30 a mk_f34,
# _6_review), justo antes de «Submit booking». Su HTML no está guardado: ninguna corrida con evidencia llegó a la
# revisión. Hasta el encargo 36 era «el último checkbox» de la pantalla, por cuatro vías (el FRENO de
# CICLO-clics-a-ciegas.md); el 21-09, en las 5 filas, la marcó la tercera: el clic en el último mc-checkbox.
MK_TERMINOS = "I have read and accept all the terms and conditions of this booking"
MK_ESPERA_TERMINOS = 10        # s que espera la casilla en la revisión (hipótesis, sin medir)

# Las casillas a la vista cuyo texto es 'buscado', entero: sin distinguir mayúsculas, espacios de más ni un punto, un
# asterisco o dos puntos al final. Una casilla es un mc-checkbox, un input checkbox o lo que tenga role checkbox, y su
# texto es su label, su aria-label, lo que dice adentro o la etiqueta que la contiene. La de adentro de un mc-checkbox
# es ese mismo control. De cada una: lo que se pulsa (su input, si tiene: pulsar el centro del mc-checkbox puede caer en
# el enlace de «terms and conditions» o en un espacio vacío, revisión del encargo 36), y si está marcada: true o false
# si todo lo que dice su estado (su aria-checked, el checked del mc-checkbox y el de su input) coincide; null si no se
# puede leer o no coincide.
_JS_MK_CASILLAS = r"""
    function mkCasillas(buscado) {
        const norma = s => String(s || '').replace(/\s+/g, ' ').trim().replace(/[\s.*:]+$/, '').toLowerCase();
        const b = norma(buscado);
        const controles = new Map();
        for (const x of mkRecorrer()) {
            const e = x.el;
            const esCasilla = mkTag(e) === 'mc-checkbox' || mkAtr(e, 'role') === 'checkbox'
                || (mkTag(e) === 'input' && String(e.type || mkAtr(e, 'type')).toLowerCase() === 'checkbox');
            if (!esCasilla) continue;
            // El mc-checkbox de más adentro que la contiene, si hay uno: ese es el control.
            const anfitrion = x.anc.filter(a => mkTag(a) === 'mc-checkbox').reverse().find(Boolean);
            const ctl = mkTag(e) === 'mc-checkbox' ? e : (anfitrion || e);
            if (!controles.has(ctl)) controles.set(ctl, {el: ctl, objetivo: ctl, textos: [], estados: []});
            const c = controles.get(ctl);
            c.textos.push(mkAtr(e, 'label'), mkAtr(e, 'aria-label'), mkTexto(e));
            for (const l of (e.labels || [])) c.textos.push(mkTexto(l));
            const etiqueta = x.anc.filter(a => mkTag(a) === 'label').reverse().find(Boolean);
            if (etiqueta) c.textos.push(mkTexto(etiqueta));
            if (mkTag(e) === 'input') c.objetivo = e;
            if (mkAtr(e, 'aria-checked')) c.estados.push(mkAtr(e, 'aria-checked') === 'true');
            else if (typeof e.checked === 'boolean') c.estados.push(e.checked);
        }
        return [...controles.values()].filter(c => mkVisible(c.el) && c.textos.some(t => norma(t) === b)).map(c =>
            Object.assign(c, {marcada: !c.estados.length ? null : c.estados.every(Boolean) ? true
                                       : c.estados.some(Boolean) ? null : false}));
    }
"""

_JS_MK_TERMINOS = "(t) => {" + _JS_MK_RECORRER + _JS_MK_CASILLAS + r"""
    const cs = mkCasillas(t);
    return {n: cs.length, marcada: cs.length === 1 ? cs[0].marcada : null};
}"""

# La marca: vuelve a buscar la casilla, y solo si hay una sola y está sin marcar, pulsa su input (o el control, si no
# tiene uno). Devuelve si la pulsó.
_JS_MK_TERMINOS_PULSAR = "(t) => {" + _JS_MK_RECORRER + _JS_MK_CASILLAS + r"""
    const cs = mkCasillas(t);
    if (cs.length !== 1) return false;
    const [c] = cs;
    if (c.marcada !== false) return false;
    c.objetivo.click();
    return true;
}"""


def _mk_leer_terminos(page):
    """Lo que da _JS_MK_TERMINOS con MK_TERMINOS: cuántas casillas y si la única está marcada; {} si no se pudo leer."""
    try:
        r = page.evaluate(_JS_MK_TERMINOS, MK_TERMINOS)
    except Exception:
        return {}
    return r if isinstance(r, dict) else {}


def _mk_marcar_terminos(page, reg, f):
    """La casilla de los términos de la revisión, por su texto (MK_TERMINOS; decisión de Marcelo,
    CICLO-maersk-retiro-y-terminos.md). Baja al final de la página, que no es un clic, y espera la casilla hasta
    MK_ESPERA_TERMINOS s. Sin una sola, corta sin pulsar nada (ObjetivoNoEncontrado: NO ENVIADA con la evidencia de la
    revisión). Con una sola, deja la evidencia de la revisión (mk_f<fila>_terminos) y, si está sin marcar, la marca
    (_JS_MK_TERMINOS_PULSAR) y lo comprueba: una sola casilla, marcada, y la página en la misma dirección. Si no se
    puede leer si estaba marcada, no la pulsa. En esos casos devuelve el corte, NO ENVIADA sin otro clic; si no,
    None."""
    try:
        page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
    except Exception:
        pass
    r = {}
    for _ in range(MK_ESPERA_TERMINOS * 2):
        esperar(page, 0.5)
        r = _mk_leer_terminos(page)
        if r.get("n"):
            break
    if r.get("n") != 1:
        raise ObjetivoNoEncontrado("Términos de MAERSK", f"una sola casilla «{MK_TERMINOS}» (había {r.get('n') or 0})")
    _evidencia_antes_de_la_guarda(page, reg, f"mk_f{f}_terminos", "con la casilla de los términos", completa=False)
    if r.get("marcada") is True:
        reg.info("la casilla de los términos ya estaba marcada: no la pulsé")
        return None
    if r.get("marcada") is not False:
        return _no_enviada(reg, f"MAERSK: no pude leer si la casilla «{MK_TERMINOS}» estaba marcada, así que no la "
                                f"pulsé; la reserva no se envió")
    url = page.url
    try:
        pulso = bool(page.evaluate(_JS_MK_TERMINOS_PULSAR, MK_TERMINOS))
    except Exception as e:
        return _no_enviada(reg, f"MAERSK: falló el clic en la casilla «{MK_TERMINOS}» ({_texto_error(e)}); "
                                f"{_MK_NADA_MAS}")
    if not pulso:
        return _no_enviada(reg, f"MAERSK: al volver a buscar la casilla «{MK_TERMINOS}», ya no era una sola sin "
                                f"marcar; {_MK_NADA_MAS}")
    esperar(page, 0.5)
    r = _mk_leer_terminos(page)
    if page.url != url:
        return _no_enviada(reg, f"MAERSK: después del clic en la casilla «{MK_TERMINOS}», la página cambió; "
                                f"{_MK_NADA_MAS}")
    if r.get("n") != 1 or r.get("marcada") is not True:
        sin_marca = r.get("n") == 1 and r.get("marcada") is False
        que = "no quedó marcada" if sin_marca else "no pude comprobar que quedó marcada"
        return _no_enviada(reg, f"MAERSK: pulsé la casilla «{MK_TERMINOS}», pero {que}; {_MK_NADA_MAS}")
    reg.info("marcado: términos y condiciones aceptados, la casilla por su texto")
    return None


@_con_la_nave_de_la_fila
@_con_la_ruta_de_la_fila
@_sin_clic_a_ciegas("mk")
def reservar_maersk(page, reserva, creds, reg, on_pausa=None):
    """MAERSK: llena 'Booking Information' (ruta, commodity, contenedor, fecha de zarpe),
    pasa a 'Select sailing', elige nave leyendo la pantalla, elige la fecha de retiro con la regla de
    Marcelo (_mk_fecha_de_retiro) y se detiene SIN emitir. Si la revisión no aparece, corta (NO ENVIADA). Antes del
    botón final, lo que no sale queda NO ENVIADA, y REVISAR solo si la nave de la fila no está (_mk_sin_nave; decisión
    de Marcelo, CICLO-maersk-shipper-y-cortes.md)."""
    f = reserva["fila"]
    reg.paso(f"[MAERSK fila {f}] {reserva['pol']} -> {reserva['destino_final']} | NAVE: {reserva['nave']}")
    _avisar_dia_carga(reserva, reg)
    # Dejar la página en el formulario /book/: puede aparecer la pantalla
    # 'You are authenticated / Continue as' y/o la selección de cliente.
    if not _mk_listo_para_reservar(page, _mk_cliente(reserva, creds), reg):
        reg.paso("No logré abrir el formulario de reserva de MAERSK.")
        reg.captura(page, f"mk_f{f}_0_sinform", full=True)
        # El motivo va en su propio literal: test_candado fotografía los textos de antes de la guarda.
        return _no_enviada(reg, "MAERSK: no se abrió el formulario /book/" + f"; {_MK_NADA_MAS}")
    _maersk_cookies(page, reg)
    _mk_got_it(page)
    esperar_hasta(page, "#mc-input-origin", 6, reg, "cargar formulario de reserva", asentar=1.6)
    reg.captura(page, f"mk_f{f}_1_form", full=True)

    # Ruta. Antes de elegir cada sugerencia, la evidencia de la lista (decisión de Marcelo, CICLO-origen-y-destino.md).
    # _mk_ciudad pulsa la única Container Yard que dice lo escrito, comprueba que quedó en el campo y, si no, corta: la
    # reserva queda NO ENVIADA (decisiones de Marcelo: encargo 42, CICLO-maersk-y-fila-sin-ruta.md, y encargo 43,
    # CICLO-maersk-elige-exacto.md). Hasta el encargo 42 seguía sin el campo, y en el 42 cortaba aquí.
    origen = _mk_ciudad(page, reserva["pol"], reg, "Origen", campo="origin", evidencia=f"mk_f{f}_origen")
    esperar(page, 0.8)
    dest = reserva["destino_final"] or reserva["destino_orig"]
    destino = _mk_ciudad(page, dest, reg, "Destino", campo="destination", evidencia=f"mk_f{f}_destino")
    esperar(page, 0.8)

    # Commodity (obligatorio; desbloquea el resto del formulario). Se prueban
    # varios términos y se elige la primera opción real de la lista.
    cont = (reserva.get("contenedor") or "").upper()
    es_reefer = "REEF" in cont or "RF" in cont or "RH" in cont
    base_com = str(reserva.get("commodity") or "").strip()
    terminos = [base_com] if base_com else (["SALMON", "FISH", "SEAFOOD"] if es_reefer else ["FISH", "GOODS"])
    det = []
    ok = ""
    try:
        com = page.get_by_placeholder("Type in minimum 2 characters").first
        com.scroll_into_view_if_needed(timeout=3000)
        for term in terminos:
            try:
                com.click(timeout=5000)
                try: com.fill("", timeout=2000)
                except Exception: pass
                com.type(term, delay=80)
            except Exception:
                continue
            for _ in range(8):
                esperar(page, 0.6)
                cand = page.locator("mc-option:visible")
                if cand.count():
                    target = cand.first
                    if es_reefer:
                        exact_salmon = cand.filter(has_text=_re_mk.compile(r"^\s*salmon,\s*frozen,\s*fish", _re_mk.I))
                        if exact_salmon.count():
                            target = exact_salmon.first
                        else:
                            frz = cand.filter(has_text=_re_mk.compile(r"frozen", _re_mk.I))
                            if frz.count():
                                target = frz.first
                    ok = (target.text_content() or "").strip()[:40]
                    target.click(timeout=3000); break
            if ok:
                reg.info(f"commodity '{term}' -> {ok}"); det.append("commodity=" + ok); break
            reg.info(f"commodity '{term}': sin sugerencia")
    except Exception as e:
        reg.info(f"commodity err: {str(e)[:50]}")

    # Reefer: (1) marcar control de temperatura. Los ajustes reefer se llenan
    # DESPUES del contenedor principal, porque el portal recien ofrece los tipos
    # reefer una vez que sabe el contenedor elegido.
    if es_reefer:
        try:
            page.get_by_text("requires temperature control", exact=False).first.click(timeout=3000)
            reg.info("marcado: requiere control de temperatura"); det.append("reefer")
            esperar(page, 1.5)
        except Exception:
            pass

    reg.captura(page, f"mk_f{f}_2_ruta", full=True)

    # Precio: yo soy el price owner (radio obligatorio; el clicable es label.mc-radio)
    puesto_po = False
    for intento in (
        lambda: page.locator("label.mc-radio").filter(has_text="I am the price owner").first,
        lambda: page.get_by_text("I am the price owner", exact=True).first,
    ):
        try:
            loc = intento()
            loc.scroll_into_view_if_needed(timeout=2500)
            loc.click(timeout=4000); puesto_po = True; break
        except Exception:
            continue
    reg.info("price owner: yo" if puesto_po else "price owner: no pude marcarlo")

    # Contenedor (tipo/tamaño, cantidad, peso). Va antes de la fecha porque la
    # fecha suele quedar habilitada al final.
    _mk_contenedor(page, reserva, es_reefer, reg, det)

    # Ajustes reefer (van DESPUES del contenedor principal): tipo reefer y
    # temperatura. El input[name=reeferContainer] esta oculto; el campo real se
    # alcanza por su placeholder y trae 'showlistonfocus'.
    if es_reefer:
        import re as _re3
        size_tok = "40"
        for n in ("45", "40", "20"):
            if n in cont:
                size_tok = n; break
        try:
            rc = page.get_by_placeholder("Select reefer container type and size").first
            rc.scroll_into_view_if_needed(timeout=3000)
            rc.click(timeout=4000)
            esperar(page, 1.5)
            elegido = ""
            for _ in range(10):
                op = page.locator("mc-option:visible")
                if op.count():
                    cand = op.filter(has_text=_re3.compile(_re3.escape(size_tok)))
                    target = cand.first if cand.count() else op.first
                    elegido = (target.text_content() or "").strip()[:28]
                    target.click(timeout=3000)
                    break
                esperar(page, 0.6)
            reg.info(f"reefer cont: {elegido or 'sin opcion'}")
            if elegido:
                det.append("reeferCont=" + elegido)
            esperar(page, 1.5)
        except Exception as e:
            reg.info(f"reefer cont err: {str(e)[:45]}")
        temp = _temp_reserva(reserva)
        try:
            t = page.locator("#mc-input-reeferTemperatureInput").first
            t.scroll_into_view_if_needed(timeout=2500)
            t.click(timeout=4000); t.fill(temp, timeout=3000)
            reg.info(f"reefer temp: {temp}C"); det.append("temp=" + temp + "C")
        except Exception as e:
            reg.info(f"reefer temp err: {str(e)[:40]}")
        # Obligatorio para reefer: sin esto el asistente no avanza.
        _mk_genset(page, reg, det, os.environ.get("AQUASHIELD_GENSET", "No"))

    # Fecha (earliest departure): el día de carga o, si no se puede, desde mañana, avisando (_mk_fecha).
    _mk_fecha(page, reserva, reg, det)

    reg.captura(page, f"mk_f{f}_3_detalle", full=True)
    if os.environ.get("AQUASHIELD_DESCUBRIR"):
        _guardar_html(page, "maersk_dump.html", reg)

    # Continuar a la selección de nave: el único «Continue to book» o «Continue» a la vista (_mk_continuar_a_la_nave;
    # decisión de Marcelo, CICLO-maersk-busqueda-vacia.md). Hasta el encargo 40, el primero habilitado cuyo nombre
    # accesible los traía, sin mirar si se veía.
    paso_antes = _mk_paso_actual(page)
    corte = _mk_continuar_a_la_nave(page, reg, det, f, ("Continue to book", MK_CONTINUAR))
    if corte:
        return corte

    # Que el botón acepte el clic NO significa que el asistente avanzó: si algún
    # campo obligatorio falta, el portal se queda en el mismo paso y muestra sus
    # errores. Sin esta comprobación el programa leía el panel lateral de tarifas
    # ('Not available') y reportaba SIN-CUPO cuando el problema era el formulario.
    avanzo = _mk_esperar_avance(page, paso_antes, 35, reg)
    reg.captura(page, f"mk_f{f}_4_sailing", full=True)
    if not avanzo:
        return _mk_booking_sin_avanzar(page, reg, det, f)

    # ¿El portal ofrece zarpes? Primero hay que dejar que termine de buscar.
    desenlace, aviso = _mk_desenlace_sailing(page, reg)
    if desenlace == "sin-zarpes":
        reg.captura(page, f"mk_f{f}_5_sincupo", full=True)
        # Y la evidencia de «Select sailing» (_mk_detenida), la misma que deja cuando la nave no está: con la del 29-09,
        # que quedó REVISAR por eso, se midió qué destino buscó (CICLO-maersk-busqueda-vacia.md).
        _mk_detenida(page, reg, f)
        reg.paso(f"MAERSK: {aviso}")
        # Con el origen y el destino con que buscó (decisión de Marcelo, CICLO-origen-y-destino.md).
        return ("SIN-CUPO", _mk_motivo_sin_cupo(aviso, det, origen, destino))
    # Sin desenlace a los 45 s, la búsqueda sigue a elegir la nave (decisión de Marcelo, CICLO-maersk-cuatro-puntos.md).
    # Hasta el encargo 39 había aquí una rama para «indefinido», que _mk_desenlace_sailing nunca devuelve.

    # Selección de nave (Select sailing): leer y elegir
    modo, sin_una, sin_nave, sin_book = _mk_elegir_nave(page, reserva, reg)
    reg.captura(page, f"mk_f{f}_5_nave", full=True)
    if os.environ.get("AQUASHIELD_DESCUBRIR"):
        _guardar_html(page, "maersk_sailing.html", reg)
    if sin_una:
        return _mk_sin_una_salida(page, reg, reserva, *sin_una)
    # La nave estaba y no se pudo pulsar su «Book»: NO ENVIADA, con su propio motivo (decisión de Marcelo, encargo 46).
    if sin_book:
        return _mk_book_sin_pulsar(page, reg, reserva, *sin_book)
    if not modo:
        return _mk_sin_nave(page, reg, reserva, det, sin_nave)

    if modo:
        # Avanzar por Recommended Services y Additional Details hasta Review
        reg.paso("Nave seleccionada. Avanzando a Recommended Services y Additional Details...")
        esperar(page, 0.8)
        for _ in range(30):
            u = page.url.lower()
            if "/additional" in u or "/review" in u:
                break
            esperar(page, 0.6)

        # Paso: Recommended services (/book/additional-services)
        u = page.url.lower()
        if "additional-services" in u or "services" in u:
            reg.paso("Paso 'Recommended services': omitiendo servicios opcionales...")
            reg.captura(page, f"mk_f{f}_5b_services", full=True)
            # «Continue», solo si hay exactamente uno a la vista (_mk_continuar_servicios; decisión de Marcelo,
            # CICLO-maersk-cuatro-puntos.md). Hasta el encargo 39 pulsaba el primero con ese texto o, por JavaScript,
            # el primer elemento a la vista con ese texto, y si no encontraba ninguno seguía sin cortar.
            corte = _mk_continuar_servicios(page, reg, f)
            if corte:
                return corte
            esperar(page, 0.8)

        # Paso: Additional details (/book/additional-details)
        for _ in range(30):
            u = page.url.lower()
            if "additional-details" in u or "/details" in u or "/review" in u:
                break
            esperar(page, 1.0)

        u = page.url.lower()
        if "additional-details" in u or "/details" in u:
            reg.paso("Paso 'Additional details': fecha de retiro, referencia y Shipper...")

            # 1) La fecha de retiro: el primer día hábil después de hoy, o el siguiente día hábil habilitado (decisión
            # de Marcelo, CICLO-maersk-retiro-y-terminos.md y CICLO-maersk-ultimos-puntos.md). Del 24-09 al encargo 36
            # no se elegía, y el portal no pasaba a la revisión sin ella (CICLO-maersk-fecha-de-retiro.md).
            corte = _mk_fecha_de_retiro(page, reg, det, f)
            if corte:
                return corte

            # 2) La referencia de retiro, en su campo por su name (_mk_referencia_de_retiro; decisión de Marcelo,
            # CICLO-maersk-ultimos-puntos.md). Hasta el encargo 37 iba en «el primer textarea».
            ref_txt = str(reserva.get("comentario") or "").strip() or COSCO_REMARK
            corte = _mk_referencia_de_retiro(page, reg, det, ref_txt)
            if corte:
                return corte

            # 3) El Shipper: la tarjeta «Shipper» tiene que traer a AQUACHILE, y si no, lo elige con el «Add» de la
            # tarjeta y su resultado en el buscador de partes (_mk_shipper; decisiones de Marcelo,
            # CICLO-maersk-ultimos-puntos.md y CICLO-maersk-shipper-y-cortes.md). Hasta el encargo 37 pulsaba el primer
            # «+ Add» y el último elemento con AQUACHILE.
            corte = _mk_shipper(page, reg, det, f)
            if corte:
                return corte

            # Sin la tecla Escape que se pulsaba aquí (decisión de Marcelo, CICLO-maersk-shipper-y-cortes.md): no está
            # medido si cerraba el buscador de partes o si este se cerraba solo al elegir.
            reg.captura(page, f"mk_f{f}_5c_details", full=True)

            # El botón «Review booking», por su texto (_mk_pulsar_revision): si no está, corta (decisión de Marcelo,
            # CICLO-maersk-shipper-y-cortes.md). Hasta el encargo 38 pulsaba por JavaScript <html>.
            corte = _mk_pulsar_revision(page, reg, f)
            if corte:
                return corte

        # Paso: Review booking (/book/review). Si no aparece, corta: no marca nada en otra pantalla.
        _mk_esperar_revision(page)

        # Los términos y condiciones, la casilla por su texto (decisión de Marcelo, CICLO-maersk-retiro-y-terminos.md).
        # Hasta el encargo 36, «el último checkbox» de la pantalla, por cuatro vías.
        corte = _mk_marcar_terminos(page, reg, f)
        if corte:
            return corte

    reg.captura(page, f"mk_f{f}_6_review", full=True)
    _evidencia_antes_de_la_guarda(page, reg, f"mk_f{f}_guarda")
    if not es_modo_emision():
        reg.paso("Me DETENGO en Review booking antes de emitir (NO se pulsa Submit booking).")
        estado = "OK-EJEMPLO" if modo else "REVISAR"
        return (estado, f"MAERSK: {', '.join(det)}; nave={modo or 'no-encontrada'}; armada hasta Review; SIN emitir")
    else:
        # Modo emisión real
        reg.paso("EMISIÓN: Pulsando 'Submit booking'...")
        pulsado, error = None, None
        try:
            pulsado = _pulsar_boton(page, "button:has-text('Submit booking'), button:has-text('Book now')")
            if pulsado:
                esperar(page, 4.0)
            esperar(page, 5.0)
        except Exception as e:
            error = e
        return _resultado_envio(page, reg, "maersk", "MAERSK", f"mk_f{f}_7_confirmado", "Submit booking", pulsado, error)


def _mk_fecha_txt(valor):
    """El día de carga en el formato de MAERSK, 'DD MMM YYYY', o '' si la fila no trae uno que se entienda
    (_fecha_planilla)."""
    d = _fecha_planilla(valor)
    if not d:
        return ""
    meses = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"]
    return f"{d.day:02d} {meses[d.month-1]} {d.year}"


def _mk_fecha(page, reserva, reg, det):
    """La fecha de zarpe más temprana (earliest departure): el día de carga de la planilla. Si la fila no trae uno que
    se entienda, el enlace 'Select tomorrow', y lo avisa en pantalla y en log.txt. Marcelo decidió que MAERSK busque desde
    hoy, como las demás, pero sin el portal no se sabe si acepta la fecha de hoy: ninguna evidencia guardada muestra ese
    campo (FRENO, CICLO-cola-siete-items.md). Por eso sigue desde mañana, avisándolo. Hasta 16d3583 el aviso decía «la
    fila no trae un día de carga», y hasta 50e3f04 no había aviso. Si el campo no acepta la fecha escrita, también
    'Select tomorrow', con su propio aviso. Devuelve lo que puso."""
    fecha = _mk_fecha_txt(reserva.get("dia_carga", ""))
    puesta = ""
    if fecha:
        try:
            d = page.get_by_placeholder("DD MMM YYYY").first
            d.scroll_into_view_if_needed(timeout=3000); d.click(timeout=4000); d.type(fecha, delay=60)
            page.keyboard.press("Escape")
            puesta = fecha
        except Exception as e:
            reg.info(f"fecha (texto) err: {str(e)[:40]}")
    if not puesta:
        try:
            page.get_by_text("Select tomorrow", exact=False).first.click(timeout=4000)
            puesta = "mañana"
            if fecha:
                reg.paso(f"⚠ MAERSK: no pude escribir el día de carga ({fecha}), así que busco las salidas desde mañana.")
            else:
                reg.paso("⚠ MAERSK: busco las salidas desde mañana, no desde hoy: todavía no sé si el portal acepta la "
                         "fecha de hoy.")
        except Exception as e:
            reg.info(f"fecha (tomorrow) err: {str(e)[:40]}")
    if puesta:
        reg.info(f"fecha: {puesta}"); det.append("fecha=" + puesta)
    return puesta


def _mk_contenedor(page, reserva, es_reefer, reg, det):
    """Rellena tipo/tamaño de contenedor, cantidad y peso en el form de MAERSK."""
    cont = (reserva.get("contenedor") or "").upper()
    cant = str(reserva.get("cant") or "1").strip() or "1"
    # El tipo/tamaño es un mc-typeahead: se escribe una palabra clave y se
    # elige la opción (mc-option) que calce.
    import re as _re
    toks = []
    for n in ("45", "40", "20"):
        if n in cont:
            toks.append(n); break
    if es_reefer:
        toks.append("Reefer")
    elif "HIGH" in cont or "HC" in cont:
        toks.append("High")
    clave = " ".join(toks) or "40"
    try:
        cc = page.get_by_placeholder("Select container type and size").first
        cc.scroll_into_view_if_needed(timeout=3000)
        cc.click(timeout=4000)
        cc.type(clave, delay=90)
        esperar(page, 1.2)
        ok = ""
        for _ in range(8):
            esperar(page, 0.5)
            cand = page.locator("mc-option:visible")
            for t in toks:
                cand = cand.filter(has_text=_re.compile(_re.escape(t), _re.I))
            if cand.count() == 0 and toks:
                cand = page.locator("mc-option:visible").filter(has_text=_re.compile(_re.escape(toks[0]), _re.I))
            if cand.count():
                ok = (cand.first.text_content() or "").strip()[:30]
                cand.first.click(timeout=3000); break
        reg.info(f"contenedor tipo: {ok or 'sin opción'}")
        if ok: det.append("cont=" + ok)
    except Exception as e:
        reg.info(f"contenedor err: {str(e)[:50]}")
    # cantidad (si no es 1)
    if cant and cant != "1":
        try:
            q = page.locator("[name='containers']").first
            q.click(timeout=2500); q.fill(cant, timeout=2500); det.append("qty=" + cant)
        except Exception:
            pass
    # peso por contenedor (obligatorio; ejemplo si no viene en la planilla)
    peso = str(reserva.get("peso") or "").strip() or (_peso_reefer() if es_reefer else "20000")
    try:
        w = page.locator("#mc-input-weight").first
        w.scroll_into_view_if_needed(timeout=2000)
        w.click(timeout=2500); w.fill(peso, timeout=2500)
        det.append("peso=" + peso)
    except Exception as e:
        reg.info(f"peso err: {str(e)[:40]}")


# Las salidas de MAERSK en «Select sailing» (CICLO-proxima-salida.md), medidas en la corrida del 2026-09-25: cada una es
# un mc-card.new-sailings-card. Su encabezado trae, cada par en su bloque .new-sailings-group-header__content, la
# etiqueta (__label: «Departure», «Transit time», «Arrival», «Vessel/voyage», «Gate-in deadline») y su valor (__value);
# la fecha va como «D Mon AAAA, HH:MM». Todo eso está fuera de las raíces shadow. Solo las que el portal deja reservar
# traen su «Book»: un mc-button con label="Book" (data-test="sailings-book-btn"), cuyo texto está DENTRO de su raíz
# shadow, en el botón de adentro (aria-label «Book»): el textContent del mc-button viene vacío. Se cuenta por su
# atributo label, o por su texto si lo trae (medido en los 6 mk_f*_detenida.html del 25 al 27-09: 52 tarjetas, 42 con
# ese mc-button, sin disabled, y 10 sin ningún «Book» en el HTML; ninguna con «Book» como texto del mc-button). Hasta
# el encargo 34 se contaba solo por el texto, y daba 0 en todas: la salida pedida de las corridas del 26 y del 27-09
# traía su «Book», y quedó REVISAR y después NO ENVIADA, «la salida pedida ya no se puede reservar»
# (CICLO-one-y-maersk-eligen-la-nave.md). La nave calza con todas sus palabras, en orden y cada una como palabra entera
# (_palabraEn de _JS_TRAE_LA_NAVE), en el valor de «Vessel/voyage» (la nave con su viaje), como MSC en su campo de la
# nave (decisiones de Marcelo, CICLO-cola-tres-items.md y CICLO-cola-seis-items.md; medido en las 4 tarjetas con salida
# del 2026-09-25). Hasta f68ce6c bastaba que cada palabra fuera parte del texto. Hasta 9051f43 se buscaban en el
# texto de toda la tarjeta, que trae también los puertos: una nave con nombre de puerto calzaba con la tarjeta de otra
# que iba a ese puerto. El viaje de la fila también va como palabra entera en ese valor, sin distinguir mayúsculas
# (decisión de Marcelo, CICLO-inicio-de-todas.md): «541W» no es el viaje de «1541W» ni de «541WA». Hasta c4df3ab
# bastaba que fuera parte del texto. _mk_elegir_nave lo usa para quedarse con las salidas de la nave que traen ese
# viaje; si ninguna lo trae, no elige ninguna y la reserva queda NO ENVIADA (decisión de Marcelo,
# CICLO-cierre-de-frenos.md). Hasta 4948e16 elegía entre todas las de la nave, sin avisarlo.
_JS_MK_SALIDAS = """(args) => {""" + _JS_TRAE_LA_NAVE + _JS_HTML_ENTERO + """
    const T = (args.toks || []).map(s => s.toUpperCase());
    const V = (args.viaje || '').toUpperCase();
    const esBook = (b) => /^\\s*book\\s*$/i.test((b.getAttribute && b.getAttribute('label')) || b.textContent || '');
    // Con args.iguales, el HTML entero de cada tarjeta (su etiqueta con sus atributos y su contenido con todas sus
    // raíces shadow, como el de la evidencia), para contar como una sola las idénticas: '' si no se puede leer, y
    // entonces cuenta aparte (decisión de Marcelo, encargo 43).
    const entero = (c) => {
        if (typeof c.getHTML !== 'function') return '';
        try { return abreDe(c) + c.getHTML({shadowRoots: raicesDe(c)}); } catch (x) { return ''; }
    };
    const tarjetas = [...document.querySelectorAll('mc-card.new-sailings-card')];
    const enteros = args.iguales ? tarjetas.map(entero) : [];
    return tarjetas.map((c, i) => {
        let salida = '', suNave = '', transito = '';
        for (const b of c.querySelectorAll('.new-sailings-group-header__content')) {
            const l = b.querySelector('.new-sailings-group-header__label');
            const v = b.querySelector('.new-sailings-group-header__value');
            if (!l || !v) continue;
            if (!salida && (l.textContent || '').trim().toLowerCase() === 'departure') salida = (v.textContent || '').trim();
            if (!suNave && (l.textContent || '').trim().toLowerCase() === 'vessel/voyage') suNave = v.textContent || '';
            if (!transito && (l.textContent || '').trim().toLowerCase() === 'transit time') transito = (v.textContent || '').trim();
        }
        const t = suNave.toUpperCase().replace(/\\s+/g, ' ');
        let pos = 0, calza = T.length > 0;
        for (const x of T) {
            const j = _palabraEn(t, x, pos);
            if (j < 0) { calza = false; break; }
            pos = j + x.length;
        }
        return {i: i, calza: calza, viaje: !!V && _palabraEn(t, V, 0) >= 0, salida: salida, transito: transito,
                book: [...c.querySelectorAll("mc-button, button, [role='button']")].filter(esBook).length};
    }).map((s, i) => (args.iguales ? Object.assign(s, {igual: enteros[i] ? enteros.indexOf(enteros[i]) : i}) : s));
}"""


def _mk_fecha_salida(texto):
    """La salida de una tarjeta de «Select sailing» de MAERSK («27 Sep 2026, 18:00»), como datetime.date; None si no se
    puede leer."""
    m = _re_mk.match(r"\s*(\d{1,2}) ([A-Za-z]{3}) (\d{4})\b", str(texto or ""))
    if not m or m.group(2).upper() not in _MESES_EN:
        return None
    try:
        return datetime.date(int(m.group(3)), _MESES_EN.index(m.group(2).upper()) + 1, int(m.group(1)))
    except ValueError:
        return None


def _mk_salidas(salidas):
    return [(_mk_fecha_salida(s.get("salida")), s) for s in salidas]


def _mk_transito(salida):
    """El tiempo de tránsito de una salida de MAERSK, de su «Transit time» («44 days 6 hours», o sin las horas), como
    datetime.timedelta; None si viene de otra forma (CICLO-cola-tres-items.md). Medido en las 4 tarjetas con salida del
    2026-09-25: es 4 horas menos que la llegada menos la salida en todas, porque las dos van en la hora de su puerto."""
    m = _re_mk.fullmatch(r"\s*(\d+) days?(?: (\d+) hours?)?\s*", str(salida.get("transito") or ""), _re_mk.I)
    return datetime.timedelta(days=int(m.group(1)), hours=int(m.group(2) or 0)) if m else None


def _mk_pulsar_book(page, i):
    """Pulsa el «Book» de la salida i (su mc-card.new-sailings-card) como lo hacía hasta 16d3583 la búsqueda por
    jerarquía: el primer botón «Book» visible de esa tarjeta, a más de 100 px del borde de arriba de la ventana. El
    mc-button y su botón interno son el mismo control: un solo clic. Antes de mirar esa altura trae la tarjeta a la
    vista (scroll_into_view_if_needed, sin clics ni teclas), y la regla de los 100 px se aplica después (decisión de
    Marcelo, encargo 46, CICLO-maersk-pulsa-el-book.md). Hasta el encargo 46 la miraba antes: el 2026-10-01, la salida
    elegida, la primera de 3 tarjetas idénticas, había quedado arriba de la ventana, y no la pulsó (encargo 45,
    CICLO-login-msc-y-maersk.md). Devuelve "" si lo pulsó; si no, por qué, para el motivo (_mk_book_sin_pulsar)."""
    tarjeta = page.locator("mc-card.new-sailings-card").nth(i)
    try:
        tarjeta.scroll_into_view_if_needed(timeout=3000)
    except Exception as e:
        return f"no pude traer su tarjeta a la vista ({_texto_error(e)})"
    b = tarjeta.locator("mc-button, button, [role='button']").filter(
        has_text=_re_mk.compile(r"^\s*Book\s*$", _re_mk.I))
    altura = None
    for j in range(b.count()):
        btn = b.nth(j)
        if btn.is_visible():
            box = btn.bounding_box()
            if box and box['y'] > 100:
                try:
                    btn.scroll_into_view_if_needed(timeout=3000)
                    btn.click(timeout=4000)
                except Exception as e:
                    return f"el clic en el «Book» falló ({_texto_error(e)})"
                return ""
            if box and altura is None:
                altura = round(box['y'])
    if altura is not None:
        return (f"con su tarjeta a la vista, el «Book» quedó a {altura} px del borde de arriba de la ventana, y lo "
                f"pulso solo si está a más de 100 px")
    return "su tarjeta no trae un «Book» a la vista"


# Cuánto espera MAERSK, en segundos, a que «Search more sailing options» se habilite (mientras carga, el portal lo
# deja deshabilitado) y a que lleguen las salidas nuevas. Hipótesis: el 2026-09-25, 7 s no bastaron, y en las dos
# corridas el botón seguía cargando cuando el programa se rindió (CICLO-ampliar-la-busqueda.md).
MK_ESPERA_MAS = 40


def _mk_leer_salidas(page, toks, viaje, reg, iguales=False):
    """Las salidas de «Select sailing» como las lee _JS_MK_SALIDAS; [] si la lectura falla. Con 'iguales', cada una
    trae también «igual»: la posición de la primera tarjeta con su mismo HTML entero (la suya, si no hay otra antes o si
    su HTML no se pudo leer; encargo 43)."""
    try:
        args = {"toks": toks, "viaje": viaje}
        if iguales:
            args["iguales"] = True
        return page.evaluate(_JS_MK_SALIDAS, args) or []
    except Exception as e:
        reg.info(f"elegir nave err: {str(e)[:50]}")
        return []


# El texto del botón con que MAERSK carga más salidas (medido en mk_f<fila>_detenida.html: el label del mc-button
# load-more-sailings-btn y el aria-label del botón de adentro).
MK_BOTON_MAS = "Search more sailing options"


def _mk_sin_repetidas(salidas):
    """Las salidas de MAERSK sin las tarjetas repetidas: de las que traen el HTML entero idéntico (su «igual»,
    _mk_leer_salidas), queda la primera, y su «Book» es el que se pulsa (decisión de Marcelo, encargo 43,
    CICLO-maersk-elige-exacto.md). Las que difieren en cualquier cosa, o cuyo HTML no se pudo leer, cuentan aparte: el
    empate sigue como antes. Medido en las 8 listas guardadas: 7 traen tarjetas repetidas, idénticas en su HTML con
    sus raíces shadow, en 12 grupos de 2 o 3; el 30-09 a las 15:31, la salida de la nave venía 3 veces, y la reserva
    quedó NO ENVIADA por el empate (CICLO-maersk-y-fila-sin-ruta.md). Devuelve (las que quedan, cuántas se
    descartaron)."""
    unicas = [s for s in salidas if s.get("igual", s.get("i")) == s.get("i")]
    return unicas, len(salidas) - len(unicas)


def _mk_boton_unico(page, nombre):
    """El único botón a la vista con ese nombre accesible, exacto (get_by_role lo lee del aria-label, o del texto si no
    lo trae). Devuelve (el localizador, o None si no hay uno solo, y cuántos hay a la vista)."""
    b = page.get_by_role("button", name=nombre, exact=True)
    vistos = [b.nth(j) for j in range(b.count()) if b.nth(j).is_visible()]
    return (vistos[0] if len(vistos) == 1 else None), len(vistos)


def _mk_boton_mas(page):
    """«Search more sailing options», el botón con que MAERSK carga más salidas: el único a la vista con ese nombre
    (MK_BOTON_MAS, _mk_boton_unico)."""
    return _mk_boton_unico(page, MK_BOTON_MAS)


def _mk_ampliar(page, reg, antes):
    """Pide más salidas con «Search more sailing options» (_mk_boton_mas): espera hasta MK_ESPERA_MAS s a que se
    habilite, lo pulsa y espera otro tanto a que haya más de 'antes' salidas. Devuelve "" si llegaron más; si no, por
    qué no se amplió, para _hasta_donde_busque. Sin el botón, o si no llegó ninguna salida nueva, el portal no deja
    ampliar más (NO_AMPLIA_MAS)."""
    boton, n, listo = None, 0, False
    for _ in range(MK_ESPERA_MAS):
        boton, n = _mk_boton_mas(page)
        listo = n == 1 and boton.is_enabled()
        if n != 1 or listo:
            break
        esperar(page, 1.0)
    if n == 0:
        return NO_AMPLIA_MAS
    if n > 1:
        return f"no pude ampliar la búsqueda: había {n} botones «Search more sailing options» a la vista"
    if not listo:
        return f"no pude ampliar la búsqueda: «Search more sailing options» siguió deshabilitado {MK_ESPERA_MAS} s"
    reg.info("pulsando 'Search more sailing options'...")
    try:
        boton.scroll_into_view_if_needed(timeout=3000)
        boton.click(timeout=4000)
    except Exception as e:
        return f"no pude ampliar la búsqueda: el clic en «Search more sailing options» falló ({str(e)[:50]})"
    for _ in range(MK_ESPERA_MAS):
        esperar(page, 1.0)
        if len(_mk_leer_salidas(page, [], "", reg)) > antes:
            return ""
    return NO_AMPLIA_MAS


def _mk_elegir_nave(page, reserva, reg):
    """En «Select sailing», entre las salidas de la nave de la fila que el portal deja reservar (si la fila trae viaje,
    las de ese viaje), la próxima desde hoy o desde el día de carga (_desde, _proxima_salida; decisión de Marcelo,
    CICLO-proxima-salida.md). Si no está en lo cargado, pide más salidas (_mk_ampliar) hasta encontrarla o hasta que el
    portal no deje ampliar más (decisión de Marcelo, CICLO-ampliar-la-busqueda.md). Devuelve (modo, sin_una, sin_nave,
    sin_book):
    - (etiqueta, None, None, None) si la eligió y pulsó su «Book»;
    - ("", None, None, (salida, por_que)) si la eligió y no pudo pulsar su «Book» (_mk_pulsar_book dice por qué): la
      nave estaba (decisión de Marcelo, encargo 46, CICLO-maersk-pulsa-el-book.md). Hasta ahí devolvía lo mismo que la
      nave que no está, y el motivo decía «no está en los itinerarios» (el 2026-10-01, encargo 45);
    - ("", (salidas, motivo, desde), None, None) si no queda una sola; con motivo «no-reservable» si el viaje de la fila
      está, pero solo en salidas sin «Book» (no amplía: ese viaje es una sola salida), o si, sin viaje en la fila y
      ampliada la búsqueda, la nave está solo en salidas sin «Book»; con «sin-viaje» si, ampliada la búsqueda, la nave
      está y ninguna de sus salidas trae el viaje de la fila (decisión de Marcelo, CICLO-cierre-de-frenos.md);
    - ("", None, (fechas, por_que), None) si la nave no apareció: las fechas de salida de todo lo que cargó y por qué
      dejó de ampliar, para _hasta_donde_busque.
    Hasta 4cae528 pedía más salidas solo hasta 3 veces, esperando 7 s, y no decía hasta dónde buscó: el 2026-09-25 se
    rindió con el botón todavía cargando. También cortaba por el viaje con el primer lote, y la salida pedida sin «Book»
    quedaba REVISAR como una nave que no está. Hasta 4948e16, sin el viaje de la fila elegía entre todas las de la nave.
    Hasta 16d3583 recorría los candidatos del último al primero: con la nave en dos salidas, pulsaba la de la tarjeta
    que venía después en la página. Hasta a198645, con AQUASHIELD_PRIMERA_NAVE, sin nave que calzara tomaba la primera
    salida que se podía reservar, fuera la nave que fuera (CICLO-solo-la-nave-pedida.md)."""
    nave_solicitada = str(reserva.get("nave") or "").strip()
    viaje_solicitado = str(reserva.get("viaje") or "").strip()
    toks = [t for t in nave_solicitada.upper().replace("/", " ").split() if len(t) > 1]
    desde = _desde(reserva)

    # Esperar hasta 20s a que aparezcan tarjetas con USD o Book
    for _ in range(20):
        try:
            if page.locator("text=/USD\\s*[\\d,.]+/i").count() > 0:
                break
            b_cand = page.locator("mc-button, button, [role='button']").filter(has_text=_re_mk.compile(r"^\s*Book\s*$", _re_mk.I))
            if b_cand.count() > 0:
                break
        except Exception:
            pass
        esperar(page, 1.0)

    ampliadas, por_que = 0, ""
    while True:
        salidas = _mk_leer_salidas(page, toks, viaje_solicitado, reg, iguales=True)
        de_la_nave, repetidas = _mk_sin_repetidas([s for s in salidas if s.get("calza")])
        if repetidas:
            copias = "1 es copia" if repetidas == 1 else f"{repetidas} son copias"
            reg.info(f"{len(de_la_nave) + repetidas} tarjetas de la nave; {copias} de otra, con el HTML entero "
                     f"idéntico: cuentan como una sola salida (quedan {len(de_la_nave)})")
        pedidas = [s for s in de_la_nave if s.get("viaje")] if viaje_solicitado else de_la_nave
        cand = [s for s in pedidas if s.get("book") == 1]
        if len(cand) < len(pedidas):
            reg.info(f"{len(pedidas) - len(cand)} salida(s) de la nave sin un solo «Book»: el portal no deja "
                     f"reservarlas")
        if cand:
            elegida, motivo = _proxima_salida(_mk_salidas(cand), desde, _mk_transito)
            if elegida is None:
                return "", (cand, motivo, desde), None, None
            if len(cand) > 1:
                reg.info(f"{len(cand)} salidas calzan con '{nave_solicitada}'; elijo la próxima desde el {desde:%d-%m-%Y}")
                _anotar_desempate(reg, _mk_salidas(cand), desde, _mk_transito)
            sin_pulsar = _mk_pulsar_book(page, elegida["i"])
            if not sin_pulsar:
                reg.info(f"nave seleccionada: {nave_solicitada}, sale {elegida.get('salida')}")
                return f"nave: {nave_solicitada}", None, None, None
            reg.info(f"no pude pulsar el «Book» de la salida elegida: {sin_pulsar}")
            return "", None, None, (elegida, sin_pulsar)
        if viaje_solicitado and pedidas:
            return "", (pedidas, "no-reservable", desde), None, None
        if ampliadas >= AMPLIAR_MAX:
            por_que = f"ya amplié la búsqueda {AMPLIAR_MAX} veces, el tope"
            break
        por_que = _mk_ampliar(page, reg, len(salidas))
        if por_que:
            break
        ampliadas += 1

    if de_la_nave:
        # El motivo de la NO ENVIADA no dice que la búsqueda se cortó: queda en log.txt (revisión del encargo 32).
        reg.info(f"dejé de ampliar la búsqueda: {por_que}")
        return "", (de_la_nave, "sin-viaje" if viaje_solicitado else "no-reservable", desde), None, None
    fechas = [_mk_fecha_salida(s.get("salida")) for s in salidas]
    reg.info(f"nave '{nave_solicitada}': no se encontró en itinerarios disponibles; "
             f"{_hasta_donde_busque(fechas, por_que)}")
    return "", None, (fechas, por_que), None



