#  RESERVA · CMA-CGM  (Click & Book)
# ============================================================
def _cma_puerto(page, sel, texto, reg, etiqueta, evidencia=""):
    """Autocompletado de puertos de CMA (Element UI). La seleccion valida deja
    el codigo del puerto en el campo (p.ej. 'LIRQUEN ; CL ; CLLQN'); si solo
    queda el texto escrito, el portal NO da la ruta por valida.
    Si el clic en la sugerencia que dice la ciudad no deja el código, no elige otra y corta la reserva
    (ObjetivoNoEncontrado): hasta fb63271 volvía a escribir y elegía con el teclado la sugerencia que quedara
    primera, fuera cual fuera (CICLO-cola-nueve-items.md).
    Con 'evidencia' (el origen y el destino), antes de pulsarla deja con ese nombre la captura de la ventana y el HTML
    de la página y de sus marcos, con la lista (decisión de Marcelo, CICLO-origen-y-destino.md); y después del clic,
    _avisar_lista_distinta. Sin una palabra antes de la primera coma (_ciudad_de: vacío, «-», «X») no escribe ni
    pulsa nada: corta (_TEXTO_DE_LA_FILA; encargo 42), porque calzaba con cualquier sugerencia que lo trajera.
    Reconoce la lista por _prefijo_de_la_lista, como MAERSK: desde el encargo 48, la letra con tilde y la ñ ya no se
    caen (decisión de Marcelo, CICLO-calendario-cosco-y-cma.md). Lo escrito en el campo sigue con ellas."""
    import re as _r
    ciudad = _ciudad_de(texto)
    if not ciudad:
        raise ObjetivoNoEncontrado(f"{etiqueta} de CMA", _TEXTO_DE_LA_FILA)
    pref = _prefijo_de_la_lista(ciudad)
    rx = _r.compile(_r.escape(pref), _r.I)

    def _valor():
        try:
            return (page.locator(sel).first.input_value() or "").strip()
        except Exception:
            return ""

    def _ok(v):
        return bool(v) and ";" in v          # trae el codigo => seleccion real

    def _escribir():
        loc = page.locator(sel).first
        loc.scroll_into_view_if_needed(timeout=4000)
        loc.click(timeout=5000)
        try: loc.fill("", timeout=2500)
        except Exception: pass
        loc.type(ciudad.upper(), delay=100)
        return loc

    val = ""
    pendiente = bool(evidencia)
    # 1) clic real sobre la sugerencia de la lista VISIBLE
    try:
        _escribir()
        for _ in range(14):
            esperar(page, 0.5)
            try:
                li = page.locator(".el-autocomplete-suggestion:visible li:visible").filter(has_text=rx)
                if li.count():
                    vista = ""
                    if pendiente:
                        vista = " ".join((li.first.text_content() or "").split())
                        _evidencia_antes_de_la_guarda(page, reg, evidencia, f"con las sugerencias de {etiqueta}",
                                                      completa=False)
                        pendiente = False
                    pulsada = " ".join((li.first.text_content() or "").split())
                    li.first.click(timeout=3000)
                    _avisar_lista_distinta(reg, etiqueta, evidencia, vista, pulsada, False)
                    esperar(page, 1.2); break
            except Exception:
                pass
        if pendiente:
            _evidencia_sin_sugerencia(page, reg, evidencia, etiqueta)
        val = _valor()
    except Exception as e:
        reg.info(f"{etiqueta}: clic err ({str(e)[:45]})")

    try:
        page.keyboard.press("Tab"); esperar(page, 0.6)
    except Exception:
        pass
    val = _valor() or val
    if not _ok(val):
        reg.info(f"{etiqueta} '{ciudad}': SIN codigo de puerto ('{val}')")
        raise ObjetivoNoEncontrado(f"{etiqueta} de CMA", f"la sugerencia del puerto «{ciudad}» (por su texto) que deja "
                                                         f"el código del puerto en el campo")
    reg.info(f"{etiqueta} '{ciudad}': {val}")
    return True


def _cma_fecha_txt(valor):
    """El día de carga como 'dd/mm/aaaa', o '' si la fila no trae uno que se entienda (_fecha_planilla). Hasta ecbdfaa
    no validaba el mes: «2026-13-01» pasaba como «01/13/2026»."""
    d = _fecha_planilla(valor)
    return f"{d.day:02d}/{d.month:02d}/{d.year}" if d else ""


def _cma_entrega(page, texto, reg, evidencia=""):
    """Abre 'Anadir direccion de entrega' y elige el destino terrestre (Ramp).
    Algunos contratos de CMA son puerto->Ramp y no puerto->puerto. Con 'evidencia', antes de pulsar la sugerencia deja
    con ese nombre la captura de la ventana y el HTML de la página y de sus marcos, con la lista (decisión de Marcelo,
    CICLO-origen-y-destino.md); y después del clic, _avisar_lista_distinta. Devuelve la sugerencia que pulsó, o ''
    si no pulsó ninguna: desde el encargo 42, reservar_cma corta ahí.
    Sin una palabra antes de la primera coma (_ciudad_de: vacío, «-», «X») no abre el campo, ni escribe ni pulsa
    nada: corta (_TEXTO_DE_LA_FILA), porque calzaba con cualquier sugerencia que lo trajera. Reconoce la lista por
    _prefijo_de_la_lista, como el puerto (encargo 48)."""
    import re as _r
    ciudad = _ciudad_de(texto)
    if not ciudad:
        raise ObjetivoNoEncontrado("Lugar de entrega de CMA", _TEXTO_DE_LA_FILA)
    pref = _prefijo_de_la_lista(ciudad)
    sel = "input[placeholder*='entrega' i], input[placeholder*='delivery' i]"
    try:
        if not page.locator(sel).first.is_visible():
            page.get_by_text("Añadir dirección de entrega", exact=False).first.click(timeout=4000)
            esperar(page, 1.5)
    except Exception:
        try:
            page.get_by_text("dirección de entrega", exact=False).first.click(timeout=4000)
            esperar(page, 1.5)
        except Exception as e:
            reg.info(f"entrega: no pude abrir el campo ({str(e)[:40]})"); return ""
    try:
        loc = page.locator(sel).first
        loc.scroll_into_view_if_needed(timeout=3000)
        loc.click(timeout=4000)
        try: loc.fill("", timeout=2000)
        except Exception: pass
        loc.type(ciudad.upper(), delay=100)
    except Exception as e:
        reg.info(f"entrega: err campo ({str(e)[:40]})"); return ""
    rx = _r.compile(_r.escape(pref), _r.I)
    rx_ramp = _r.compile("ramp", _r.I)

    def la_de_la_regla(li):
        ramp = li.filter(has_text=rx_ramp)
        return ramp.first if ramp.count() else li.first

    pendiente = bool(evidencia)
    for _ in range(14):
        esperar(page, 0.5)
        try:
            li = page.locator(".el-autocomplete-suggestion:visible li:visible").filter(has_text=rx)
            if li.count():
                vista = ""
                if pendiente:
                    vista = " ".join((la_de_la_regla(li).text_content() or "").split())
                    _evidencia_antes_de_la_guarda(page, reg, evidencia, "con las sugerencias del lugar de entrega",
                                                  completa=False)
                    pendiente = False
                target = la_de_la_regla(li)
                bruto = target.text_content() or ""
                txt = bruto.strip()[:45]
                target.click(timeout=3000)
                _avisar_lista_distinta(reg, "Lugar de entrega", evidencia, vista, " ".join(bruto.split()), False)
                esperar(page, 1.2)
                try:
                    page.keyboard.press("Escape")
                except Exception:
                    pass
                reg.info(f"lugar de entrega: {txt}")
                return txt
        except Exception:
            pass
    if pendiente:
        _evidencia_sin_sugerencia(page, reg, evidencia, "el lugar de entrega")
    reg.info("lugar de entrega: sin sugerencia")
    return ""


def _cma_aviso(page):
    try:
        return str(page.evaluate(r"""()=>{
          const vis=e=>{const r=e.getBoundingClientRect();return e.offsetParent!==null&&r.width>0&&r.height>0;};
          const el=[...document.querySelectorAll('*')].filter(e=>vis(e)
             && /no matching|quotation *:/i.test(e.textContent||'')
             && (e.textContent||'').trim().length<160);
          return el.length? el[el.length-1].textContent.trim().replace(/\s+/g,' ').slice(0,140) : '';}""") or "")
    except Exception:
        return ""


def _cma_anunciar_ruta(reg, resultado):
    """Tras «Validar ruta», dice lo que el programa vio. Da la ruta por validada solo si el portal respondió
    (itinerarios o un aviso); si _cma_esperar_resultado venció («indefinido») o no se pudo pulsar «Validar ruta»
    («error»), avisa que no pudo confirmarla y la reserva sigue, sin cortar.
    Hasta e910bf1 escribía «Ruta validada con éxito» también después de «sin respuesta del portal»
    (CICLO-cola-nueve-items.md)."""
    if resultado in ("itinerarios", "aviso"):
        reg.paso("Ruta validada con éxito. Continuando con datos de carga e itinerario...")
        return
    causa = ("el portal no respondió a «Validar ruta»" if resultado == "indefinido"
             else "no pude pulsar «Validar ruta»")
    reg.paso(f"⚠ No pude confirmar la ruta: {causa}. Sigo con los datos de carga e itinerario, sin darla por "
             f"validada.")


def _cma_esperar_resultado(page, seg, reg, minimo=1.5):
    """Tras 'Validar ruta' hay dos desenlaces: aparecen itinerarios o el portal
    devuelve un aviso (por ejemplo, la cotizacion no cubre la ruta). Esperar un
    selector de resultados que a veces no existe gastaba 9s ciegos por intento."""
    import time as _t
    t0 = _t.time()
    esperar(page, minimo)
    while _t.time() - t0 < seg:
        av = _cma_aviso(page)
        if av:
            reg.info(f"el portal responde ({_t.time() - t0:.1f}s)")
            return "aviso"
        try:
            if page.locator("[class*=itinerar]:visible, [class*=route-result]:visible").count():
                reg.info(f"itinerarios en pantalla ({_t.time() - t0:.1f}s)")
                return "itinerarios"
        except Exception:
            pass
        esperar(page, 0.4)
    reg.info(f"sin respuesta del portal tras {seg:.0f}s")
    return "indefinido"


