# La lectura y la elección de «Route choices» de CMA: cada tarjeta sube desde su botón «Seleccionar»; calza la que trae
# todas las palabras de la nave, cada una como palabra entera (_JS_TRAE_LA_NAVE; decisiones de Marcelo,
# CICLO-cola-tres-items.md y CICLO-cola-seis-items.md), y se pulsa la primera que calza. Hasta f68ce6c iba escrita
# dentro de _cma_seleccionar_itinerario y bastaba que cada palabra fuera parte del texto de la tarjeta.
_JS_CMA_RUTAS = r"""(args)=>{""" + _JS_TRAE_LA_NAVE + r"""
    const toks = args.toks || [];
    const vis = e => {
        const r = e.getBoundingClientRect();
        return e.offsetParent !== null && r.width > 0 && r.height > 0;
    };
    const allBtns = [...document.querySelectorAll('button, a')].filter(e =>
        vis(e) && /^\s*(seleccionar|select|deseleccionar|deselect)\s*$/i.test((e.textContent || '').trim())
    );
    if (!allBtns.length) return {ok: false, error: 'sin_botones', msg: 'sin botones de selección'};

    function getCard(btn) {
        let curr = btn;
        let card = btn;
        for (let d = 0; d < 8; d++) {
            if (!curr || !curr.parentElement || curr.parentElement.tagName === 'BODY' || curr.parentElement.tagName === 'HTML') break;
            const parent = curr.parentElement;
            const otherBtns = allBtns.filter(b => b !== btn && parent.contains(b));
            if (otherBtns.length > 0) {
                card = curr;
                break;
            }
            const pTxt = (parent.innerText || parent.textContent || '');
            if (/Detalle\s+las\s+partes|Booking\s+Party|Nuestros\s+servicios|Descubra\s+CMA/i.test(pTxt)) {
                card = curr;
                break;
            }
            if (parent.tagName === 'MAIN' || parent.id === 'app') {
                card = curr;
                break;
            }
            card = curr;
            curr = parent;
        }
        return card;
    }

    const cards = [];
    for (let i = 0; i < allBtns.length; i++) {
        const btn = allBtns[i];
        const card = getCard(btn);
        const txt = (card.innerText || card.textContent || '').replace(/\s+/g, ' ').trim();
        const upperTxt = txt.toUpperCase();
        const isSelected = /^\s*(deseleccionar|deselect)\s*$/i.test((btn.textContent || '').trim());

        let vMatch = txt.match(/(?:Buque\s+principal|Main\s+vessel)\s*[:\s]+([A-Z0-9\s\.\-_]+?)(?=\s*(?:Primer\s+servicio|Ref\.|\bPOD\b|\bPOL\b|Terminal|Port\s+Cut|Viaje|Voyage|Service|\n|\r|$))/i) ||
                     txt.match(/(?:Buque|Vessel)\s*[:\s]+([A-Z0-9\s\.\-_]+?)(?=\s*(?:Primer\s+servicio|Ref\.|\bPOD\b|\bPOL\b|Terminal|Port\s+Cut|Viaje|Voyage|Service|\n|\r|$))/i);
        let vessel = vMatch ? vMatch[1].trim() : '';

        let cMatch = txt.match(/Port\s+Cut[- ]off\s*[:\s]+([^\n\r]+?)(?=\s*(?:Buque|Main\s+vessel|Primer|Ref\.|\n|\r|$))/i);
        let cutoff = cMatch ? cMatch[1].trim() : '';

        let rMatch = txt.match(/(?:Ref\.\s*de\s*viaje|Voyage\s*ref|Ref\.)\s*[:\s]+([A-Z0-9\-_]+)/i);
        let voyage = rMatch ? rMatch[1].trim() : '';

        const matched = _traeLaNave(upperTxt, toks);

        cards.push({
            idx: i,
            vessel: vessel,
            cutoff: cutoff,
            voyage: voyage,
            isSelected: isSelected,
            matched: matched
        });
    }

    // Si hay coincidencia
    const matchIdx = cards.findIndex(c => c.matched);
    if (matchIdx >= 0) {
        const m = cards[matchIdx];
        if (m.isSelected) {
            return {ok: true, match: true, vessel: m.vessel, cutoff: m.cutoff, voyage: m.voyage, msg: 'nave ya seleccionada: ' + (m.vessel || toks.join(' '))};
        }
        allBtns[matchIdx].scrollIntoView({block: 'center'});
        allBtns[matchIdx].click();
        return {ok: true, match: true, vessel: m.vessel, cutoff: m.cutoff, voyage: m.voyage, msg: 'nave seleccionada: ' + (m.vessel || toks.join(' '))};
    }

    // Sin coincidencia: registrar lo ofrecido
    const ofrecidas = cards.map(c => {
        let s = c.vessel || 'Sin nombre';
        if (c.voyage) s += ` (Viaje ${c.voyage})`;
        if (c.cutoff) s += ` [Cut-off: ${c.cutoff}]`;
        return s;
    });

    return {ok: false, match: false, cardsCount: cards.length, ofrecidas: ofrecidas, msg: 'nave no encontrada en este bloque'};
}"""


# «Cargar N siguientes resultados», el enlace al final de la lista de «Route choices» con que CMA carga más rutas (N
# cambia). Dato de Marcelo, no medido: ninguna corrida guardó la lista entera. Se pulsa por ese texto, las veces
# que haga falta, hasta encontrar la nave o hasta que el enlace desaparezca (decisión de Marcelo,
# CICLO-ampliar-msc-y-cma.md). Reemplaza el clic de la Nota H23, que pulsaba una vez el primer botón o enlace con
# «mostrar más», «ver más», «show more» o «más viajes»: por su expresión nunca habría pulsado este enlace, y en logs/
# nunca se pulsó. CMA_ESPERA_MAS: los segundos que se esperan rutas nuevas (hipótesis).
CMA_CARGAR_MAS = r"^\s*Cargar\s+\d+\s+siguientes\s+resultados\s*$"
CMA_ESPERA_MAS = 20
# Por qué dejó de cargar rutas, para _hasta_donde_busque: el enlace desapareció, o nunca tuvo ese texto.
CMA_SIN_ENLACE = "ya no vi el enlace «Cargar … siguientes resultados»"

# Cuántas rutas hay en «Route choices»: los botones «Seleccionar» o «Deseleccionar» a la vista, como los cuenta
# _JS_CMA_RUTAS.
_JS_CMA_CONTAR = r"""()=>[...document.querySelectorAll('button, a')].filter(e => {
    const r = e.getBoundingClientRect();
    return e.offsetParent !== null && r.width > 0 && r.height > 0
        && /^\s*(seleccionar|select|deseleccionar|deselect)\s*$/i.test((e.textContent || '').trim());
}).length"""

# La salida de cada tarjeta de «Route choices»: la primera fecha (.date) de cada .wrap-card, «Lunes, 05-oct-2026»
# (medido en la tarjeta elegida de las corridas del 24 y el 25-09; CICLO-ampliar-msc-y-cma.md), o '' si no la trae.
_JS_CMA_FECHAS = r"""()=>[...document.querySelectorAll('.wrap-card')].map(c => {
    const d = c.querySelector('.date');
    return d ? (d.textContent || '').trim() : '';
})"""
_MESES_ES = ("ENE", "FEB", "MAR", "ABR", "MAY", "JUN", "JUL", "AGO", "SEP", "OCT", "NOV", "DIC")


def _cma_fecha_tarjeta(texto):
    """La fecha de una tarjeta de CMA («Lunes, 05-oct-2026»; el mes en español, de tres o cuatro letras, como «sept»),
    como datetime.date; None si no se lee o no existe."""
    m = _re_mk.search(r"(\d{1,2})-([^\W\d_]{3,4})\.?-(\d{4})", str(texto or ""))
    if not m or m.group(2).upper()[:3] not in _MESES_ES:
        return None
    try:
        return datetime.date(int(m.group(3)), _MESES_ES.index(m.group(2).upper()[:3]) + 1, int(m.group(1)))
    except ValueError:
        return None


def _cma_fechas(page):
    """Las salidas de todas las tarjetas de «Route choices» (_JS_CMA_FECHAS), como datetime.date o None."""
    try:
        return [_cma_fecha_tarjeta(t) for t in page.evaluate(_JS_CMA_FECHAS) or []]
    except Exception:
        return []


def _cma_contar_rutas(page):
    """Cuántas rutas hay en «Route choices» (_JS_CMA_CONTAR), o 0 si no se pueden contar."""
    try:
        return int(page.evaluate(_JS_CMA_CONTAR) or 0)
    except Exception:
        return 0


def _cma_enlace_mas(page):
    """El enlace «Cargar N siguientes resultados»: el único enlace o botón a la vista cuyo texto entero calza con
    CMA_CARGAR_MAS. Devuelve (el localizador, o None si no hay uno solo, y cuántos hay a la vista)."""
    e = page.locator("a, button, [role=link], [role=button]").filter(
        has_text=_re_mk.compile(CMA_CARGAR_MAS, _re_mk.I))
    vistos = [e.nth(j) for j in range(e.count()) if e.nth(j).is_visible()]
    return (vistos[0] if len(vistos) == 1 else None, len(vistos))


def _cma_ampliar(page, reg, antes):
    """Pulsa «Cargar N siguientes resultados» (_cma_enlace_mas) y espera hasta CMA_ESPERA_MAS s a que haya más de
    'antes' rutas (_cma_contar_rutas). Devuelve "" si llegaron; si no, por qué, para _hasta_donde_busque: sin el enlace,
    CMA_SIN_ENLACE; si pulsó y no llegó ninguna ruta nueva, eso, con los segundos que esperó."""
    try:
        enlace, cuantos = _cma_enlace_mas(page)
    except Exception as e:
        return f"no pude ampliar la búsqueda: no pude mirar el enlace «Cargar … siguientes resultados» ({str(e)[:50]})"
    if cuantos == 0:
        return CMA_SIN_ENLACE
    if cuantos > 1:
        return f"no pude ampliar la búsqueda: había {cuantos} enlaces «Cargar … siguientes resultados» a la vista"
    reg.info("CMA · pulso «Cargar … siguientes resultados» para buscar la nave")
    try:
        enlace.scroll_into_view_if_needed(timeout=3000)
        enlace.click(timeout=4000)
    except Exception as e:
        return f"no pude ampliar la búsqueda: el clic en «Cargar … siguientes resultados» falló ({str(e)[:50]})"
    for _ in range(CMA_ESPERA_MAS):
        esperar(page, 1.0)
        rutas = _cma_contar_rutas(page)
        if rutas > antes:
            reg.info(f"búsqueda ampliada: {antes} -> {rutas} rutas")
            return ""
    return f"pulsé «Cargar … siguientes resultados» y no llegaron rutas nuevas en {CMA_ESPERA_MAS} s"


def _cma_seleccionar_itinerario(page, reserva, reg):
    """En 'Route choices', selecciona la tarjeta que contenga la nave de la reserva.
    Si no aparece, pulsa «Cargar N siguientes resultados» hasta encontrarla o hasta que el enlace desaparezca
    (_cma_ampliar); si no la encuentra, el aviso dice hasta qué fecha buscó.
    REGLA ESTRICTA: NUNCA seleccionar una nave errónea si la planilla pide una nave específica.
    Si la nave requerida no está en las opciones ofrecidas, reporta REVISAR con las opciones disponibles."""
    nave_pedida = str(reserva.get("nave") or "").strip()
    viaje_pedido = str(reserva.get("viaje") or "").strip()
    nave_especificada = not _fila_sin_nave(nave_pedida)     # hasta a198645, CMA tenía su propia lista de comodines
    reg.paso(f"CMA · Buscando nave '{nave_pedida}' en Route choices...")

    # Palabras clave para la nave: la tarjeta calza solo si las trae todas, y una nave comodín (NAVES_COMODIN) o con solo
    # prefijos de naviera (NAVES_PREFIJO) no trae ninguna (decisiones de Marcelo, CICLO-cola-tres-items.md,
    # CICLO-solo-la-nave-pedida.md y CICLO-cola-seis-items.md).
    # Hasta 9051f43 bastaban las que no eran prefijo de naviera
    # (MSC, CMA, CGM, HMM, ONE, COSCO, MV), y el comodín se buscaba como nave antes de cortar.
    # Las palabras se separan como en _fila_sin_nave, con la Ñ y las tildes como letras: hasta f68ce6c se partían en
    # ellas («PIÑA» daba «PI»), y como palabra entera ya no calzarían (CICLO-cola-seis-items.md).
    toks = ([t for t in _re_mk.findall(r"[0-9A-ZÑÁÉÍÓÚÜ]+", nave_pedida.upper()) if len(t) > 1]
            if nave_especificada else [])

    # Esperar a que aparezcan los botones de selección o ruta ya seleccionada
    esperar_btn = False
    for _ in range(15):
        try:
            if page.locator("button:has-text('Seleccionar'), button:has-text('Select'), button:has-text('Deseleccionar'), button:has-text('Deselect')").count():
                esperar_btn = True
                break
        except Exception:
            pass
        esperar(page, 1.0)

    if not esperar_btn:
        return False, "CMA: no aparecieron opciones de ruta (botones de selección no encontrados)"

    ultimo_resultado, cargas, por_que = {}, 0, ""
    while True:
        # La lista de «Route choices» tal como está cuando se lee (tras cada «Cargar … siguientes resultados», otra): la
        # captura de la ventana y su HTML, sin clics ni esperas (decisión de Marcelo, CICLO-cola-siete-items.md).
        sufijo = "" if not cargas else "_mas" if cargas == 1 else f"_mas{cargas}"
        nombre = f"cma_f{reserva.get('fila', '')}_rutas" + sufijo
        _evidencia_antes_de_la_guarda(page, reg, nombre, "en la lista de rutas", completa=False)
        try:
            res = page.evaluate(_JS_CMA_RUTAS, {"toks": toks})
            ultimo_resultado = res or {}
            if res.get("ok"):
                reg.info(f"itinerario CMA: {res.get('msg')}")
                esperar(page, 2.5)
                return True, res.get("msg")
        except Exception as e:
            reg.info(f"lectura {cargas + 1} de las rutas err: {str(e)[:50]}")
        # Si no la encontró, «Cargar N siguientes resultados», por su texto, hasta que el enlace desaparezca
        # (_cma_ampliar; decisión de Marcelo, CICLO-ampliar-msc-y-cma.md). Hasta el encargo 33, una sola vez el
        # primer botón o enlace con «mostrar más», «ver más», «show more» o «más viajes» (Nota H23), que en logs/
        # nunca se pulsó.
        if not toks:
            por_que = "la fila no trae palabras de nave que buscar"
            break
        if cargas >= AMPLIAR_MAX:
            por_que = f"cargué más rutas {AMPLIAR_MAX} veces, el tope"
            break
        por_que = _cma_ampliar(page, reg, _cma_contar_rutas(page))
        if por_que:
            break
        cargas += 1

    # No se encontró la nave tras buscar en todos los bloques
    ofrecidas = ultimo_resultado.get("ofrecidas") or []
    ofrecidas_txt = "; ".join(ofrecidas) if ofrecidas else "ninguna ruta detectada"

    if not nave_especificada:
        # Hasta 83067a1, sin nave en la planilla, pulsaba el primer «Seleccionar» de la lista, fuera el
        # itinerario que fuera (CICLO-clics-a-ciegas.md).
        raise ObjetivoNoEncontrado("Itinerario de CMA", "la nave de la reserva: la fila no trae nave, y no elijo "
                                                        "un itinerario a ciegas")

    # Si se especificó nave pero NO coincide: NUNCA ELEGIR UNA NAVE ERRÓNEA
    reg.paso(f"CMA · ALERTA: Nave '{nave_pedida}' NO disponible en las opciones del portal.")
    reg.info(f"CMA · Rutas ofrecidas en el portal: {ofrecidas_txt}")
    reg.info("CMA · NO se selecciona nave errónea para evitar reservas incorrectas.")
    donde = _hasta_donde_busque(_cma_fechas(page), por_que)
    return False, (f"CMA: nave '{nave_pedida}' no disponible en el portal: {donde} (rutas ofrecidas: {ofrecidas_txt}). "
                   "No se seleccionó nave errónea.")


# El panel Reefer de CMA es el único cajón o diálogo a la vista (si hay uno dentro de otro, cuenta el de afuera). Lo
# comparten la temperatura y el botón de guardar. Hasta 1ed40f4 la temperatura se buscaba en el primer contenedor de
# la página aunque estuviera oculto: en la corrida del 2026-09-24 era un diálogo «u-hidden» (CICLO-cola-nueve-items.md).
_JS_CMA_PANELES_VISIBLES = r"""
    const visible = (e) => {
        const r = e.getBoundingClientRect();
        return r.width > 0 && r.height > 0 && getComputedStyle(e).visibility !== 'hidden';
    };
    const vis = [...document.querySelectorAll('.el-drawer, [class*="drawer"], [role="dialog"]')].filter(visible);
    const paneles = vis.filter(p => !vis.some(q => q !== p && q.contains(p)));"""

# Enfoca el campo de la temperatura del panel Reefer de CMA por su etiqueta: el bloque .el-form-item cuya
# .el-form-item__label dice «Temperature», dentro del panel visible. Medido en la corrida del 2026-09-25
# (CICLO-pendientes-con-evidencia.md): el panel trae otros 7 campos y un textarea, y ninguna otra etiqueta dice eso.
# Devuelve 'ok' si lo enfocó, o lo que faltó: 'sin-panel', 'varios-paneles', 'sin-campo' o 'varios-campos'. Hasta
# 1e8d510 lo reconocía también por el texto de su bloque, su placeholder o un «°C»; hasta 83067a1, si no lo
# encontraba, pulsaba el primer campo del panel (CICLO-clics-a-ciegas.md).
_JS_CMA_REEFER_TEMPERATURA = r"""(tempVal)=>{""" + _JS_CMA_PANELES_VISIBLES + r"""
    if (paneles.length === 0) return 'sin-panel';
    if (paneles.length > 1) return 'varios-paneles';
    const bloques = [...paneles[0].querySelectorAll('.el-form-item')].filter(b => {
        const etq = b.querySelector('.el-form-item__label');
        return !!etq && /^temperature$/i.test((etq.textContent || '').replace(/\s+/g, ' ').trim());
    });
    if (bloques.length === 0) return 'sin-campo';
    if (bloques.length > 1) return 'varios-campos';
    const inp = [...bloques[0].querySelectorAll('input')].find(e => {
        const r = e.getBoundingClientRect();
        return e.offsetParent !== null && r.width > 0 && r.height > 0;
    });
    if (!inp) return 'sin-campo';
    inp.focus(); inp.click(); return 'ok';
}"""

# Lo que no encontró _JS_CMA_REEFER_TEMPERATURA, para el aviso de NO ENVIADA.
_CMA_TEMPERATURA_NO_HALLADA = {
    "sin-panel": "el panel Reefer: no hay ningún panel visible en la página",
    "varios-paneles": "un solo panel Reefer: hay más de un panel visible y no elijo uno a ciegas",
    "sin-campo": "el campo «Temperature» dentro del panel Reefer visible (por su etiqueta)",
    "varios-campos": "un solo campo «Temperature» en el panel Reefer: hay más de uno y no elijo uno a ciegas",
}

# Dice si un botón está dentro del panel Reefer visible, el mismo de la temperatura. Hasta 1e8d510 pulsaba por
# JavaScript el primer «Guardar», «Save», «Confirm» o «Confirmar» de cualquier cajón, también de uno oculto.
_JS_CMA_REEFER_GUARDAR = r"""(boton)=>{""" + _JS_CMA_PANELES_VISIBLES + r"""
    return paneles.length === 1 && paneles[0].contains(boton);
}"""


def _cma_ajustes_reefer(page, reserva, reg):
    """En la sección Carga, abre los ajustes de 'Reefer TO COMPLETE', escribe la temperatura y los guarda. Cada
    paso busca su objetivo por su texto o su etiqueta; si no lo encuentra, no pulsa nada y corta la reserva
    (ObjetivoNoEncontrado). Hasta 83067a1 caía a clics a ciegas: el primer botón de un bloque con
    «Reefer», el primer campo del panel y el botón principal de cualquier ventana (CICLO-clics-a-ciegas.md).
    La temperatura se busca solo dentro del panel visible (CICLO-cola-nueve-items.md), por su etiqueta «Temperature»,
    y se guarda con el botón «Guardar» de ese mismo panel (CICLO-pendientes-con-evidencia.md).
    Deja la captura de la ventana y el HTML del panel abierto (cma_f<fila>_reefer_panel) y de la pantalla tras
    guardarlo (cma_f<fila>_reefer_guardado), sin clics ni esperas nuevas (CICLO-cma-reefer-y-fecha-maersk.md)."""
    reg.paso("CMA · Configurando Ajustes Reefer...")
    f = reserva["fila"]
    temp = _temp_reserva(reserva)
    try:
        # 1. Abrir los ajustes de la sección Reefer: el botón «Modifique el reefer» de su fila. Medido en la corrida
        #    del 2026-09-24 (CICLO-revision-corrida-completa.md): «text=/TO COMPLETE/i» calzaba con la insignia de
        #    estado «to complete», que no abre nada, y «button:has-text('Reefer')» calza primero con el encabezado
        #    «Detalles de la carga».
        abierto = False
        for selector in (
            "button:has-text('Modifique el reefer')",
        ):
            try:
                btn = page.locator(selector).first
                if btn.count() and btn.is_visible():
                    btn.scroll_into_view_if_needed(timeout=2500)
                    btn.click(timeout=3000)
                    abierto = True
                    break
            except Exception:
                continue
        if not abierto:
            raise ObjetivoNoEncontrado("Sección Reefer de CMA", "el botón «Modifique el reefer» de la fila Reefer")

        esperar(page, 2.0)
        try:
            reg.captura(page, f"cma_f{f}_4b_reefer_drawer", full=True)
        except Exception:
            pass
        _evidencia_antes_de_la_guarda(page, reg, f"cma_f{f}_reefer_panel", "en el panel Reefer", completa=False)

        # 2. La temperatura, solo dentro del panel Reefer visible (ver _JS_CMA_REEFER_TEMPERATURA)
        donde = page.evaluate(_JS_CMA_REEFER_TEMPERATURA, temp)
        if donde != "ok":
            raise ObjetivoNoEncontrado("Temperatura Reefer de CMA", _CMA_TEMPERATURA_NO_HALLADA.get(
                donde, _CMA_TEMPERATURA_NO_HALLADA["sin-campo"]))
        page.keyboard.press("Control+A")
        page.keyboard.press("Backspace")
        page.keyboard.type(temp, delay=60)
        reg.info(f"temperatura reefer: {temp} °C (focus)")

        esperar(page, 0.8)
        # 3. Guardar: el único botón «Guardar» a la vista, y tiene que ser del panel visible (NO «Guardar plantilla» del
        #    pie de página). Medido en la corrida del 2026-09-25: el panel trae «Guardar» y «Cancelar», y es el único
        #    «Guardar» de la página (CICLO-pendientes-con-evidencia.md).
        import re as _r
        btn_g = page.locator(".el-drawer button, [class*='drawer'] button").filter(
            has_text=_r.compile(r"^\s*Guardar\s*$", _r.I), visible=True)
        if btn_g.count() != 1 or not btn_g.evaluate(_JS_CMA_REEFER_GUARDAR):
            raise ObjetivoNoEncontrado("Guardar los ajustes Reefer de CMA", "el botón «Guardar» del panel Reefer visible")
        btn_g.click(timeout=4000)
        reg.info("ajustes reefer guardados")
        esperar(page, 1.5)
        _evidencia_antes_de_la_guarda(page, reg, f"cma_f{f}_reefer_guardado", "tras guardar el panel Reefer",
                                      completa=False)
        # Asegurar que no quede ningún modal ni popup abierto
        try:
            page.keyboard.press("Escape")
            esperar(page, 0.4)
        except Exception:
            pass
        return True
    except Exception as e:
        reg.info(f"ajustes reefer err: {str(e)[:50]}")
        return False


def _cma_marcar_i_agree(page, reg):
    """Marca la casilla 'I Agree' por su texto. Hasta 83067a1, si no estaba, marcaba la primera casilla visible
    de la página, fuera la que fuera (el log decía «marcado 'I Agree'» en las 5 reservas medidas y ninguna
    captura muestra esa casilla): ahora no pulsa nada y corta la reserva (CICLO-clics-a-ciegas.md)."""
    for s in [
        "label:has-text('I Agree')",
        ".el-checkbox:has-text('I Agree')",
    ]:
        try:
            chk = page.locator(s).first
            if chk.count() and chk.is_visible():
                chk.scroll_into_view_if_needed(timeout=2000)
                chk.click(timeout=2000)
                reg.info("marcado 'I Agree'")
                return True
        except Exception:
            continue
    raise ObjetivoNoEncontrado("«I Agree» de CMA", "la casilla «I Agree» (por su texto)")


def _cma_comentarios(page, reg):
    """Escribe la observación corporativa en el campo de Comentarios de forma limpia,
    sin doble clic ni selección azul del texto. El campo se busca por su placeholder o su etiqueta; si no está, no
    escribe en otro y corta la reserva (ObjetivoNoEncontrado). Hasta fb63271 escribía en el primer textarea visible
    de la página (CICLO-cola-nueve-items.md)."""
    reg.paso("CMA · Ingresando comentarios adicionales...")
    try:
        # Esperar a que el drawer / overlay termine de cerrarse
        try:
            page.locator(".el-drawer__wrapper, .el-overlay, .v-modal").first.wait_for(state="hidden", timeout=2500)
        except Exception:
            pass

        # Deseleccionar cualquier texto resaltado en la página para evitar que se vea azul
        try:
            page.evaluate("() => { if (window.getSelection) window.getSelection().removeAllRanges(); }")
        except Exception:
            pass

        # Ubicar y llenar directamente vía setter de DOM (evita clics accidentales o selección azul)
        ok = page.evaluate(r"""(val) => {
            try { if (window.getSelection) window.getSelection().removeAllRanges(); } catch(e){}
            const allTa = [...document.querySelectorAll('textarea')].filter(e => e.offsetParent !== null);
            const ta = allTa.find(e => {
                const ph = (e.placeholder || '').toLowerCase();
                const p = (e.closest('.el-form-item') || e.parentElement || {}).textContent || '';
                return /facil[ií]tenos|comentario|comment|remark/i.test(ph) || /comentario|remark/i.test(p);
            });
            if (ta) {
                ta.scrollIntoView({block: 'center', behavior: 'smooth'});
                ta.focus();
                const setter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
                setter.call(ta, val);
                ta.dispatchEvent(new Event('input', {bubbles: true}));
                ta.dispatchEvent(new Event('change', {bubbles: true}));
                try { if (window.getSelection) window.getSelection().removeAllRanges(); } catch(e){}
                return true;
            }
            return false;
        }""", COSCO_REMARK)

        if ok:
            reg.info(f"comentario: '{COSCO_REMARK}'")
            esperar(page, 0.8)
            return True

        # Fallback vía locator solo si JS no encontró el textarea
        ta = page.locator("textarea[placeholder*='facilítenos' i], .el-form-item:has-text('Comentarios') textarea").first
        if ta.count() and ta.is_visible():
            ta.scroll_into_view_if_needed(timeout=2500)
            ta.fill(COSCO_REMARK)
            try:
                page.evaluate("() => { if (window.getSelection) window.getSelection().removeAllRanges(); }")
            except Exception:
                pass
            reg.info(f"comentario (vía locator): '{COSCO_REMARK}'")
            esperar(page, 0.8)
            return True
        raise ObjetivoNoEncontrado("Comentarios de CMA", "el campo de comentarios (por su placeholder «facilítenos», "
                                                         "«comentario», «comment» o «remark», o su etiqueta «Comentarios» "
                                                         "o «remark»)")
    except Exception as e:
        reg.info(f"comentarios err: {str(e)[:45]}")
        return False


# El aviso de mantenimiento de CMA: con él, Click & Book no carga. Medido el 2026-09-26: «We are improving the
# eBusiness area», con la ventana anunciada, a la vista en la pantalla donde la reserva cortó (y, con OCR, en cma_final
# de las dos corridas); en ninguno de los otros 43 HTML de CMA de logs/, del 2026-09-24 al 26
# (CICLO-cierre-de-frenos.md). Sus filas quedan NO ENVIADA con CMA_MANTENIMIENTO (decisión de Marcelo). Hasta 4948e16
# la reserva cortaba en el Origen, con un motivo que hablaba de la sugerencia del puerto (CICLO-inicio-de-todas.md).
CMA_MANTENIMIENTO = "el portal de CMA está en mantenimiento"


def _cma_en_mantenimiento(page):
    """True si el texto a la vista de la página trae el aviso de mantenimiento de CMA («We are improving the eBusiness
    area»), sin distinguir mayúsculas ni saltos de línea. Solo lee: ni clics ni esperas. Si no puede leer la página,
    False."""
    return "we are improving the ebusiness area" in " ".join(texto_pagina(page).split())


@_con_la_nave_de_la_fila
@_con_la_ruta_de_la_fila
@_sin_clic_a_ciegas("cma")
def reservar_cma(page, reserva, creds, reg, on_pausa=None):
    """CMA-CGM (Click & Book): ruta + cotización, carga reefer, itinerario, ajustes
    reefer, comentarios y se DETIENE antes de emitir en Envío de la reserva."""
    f = reserva["fila"]
    dest_orig = (reserva.get("destino_orig") or "").strip()
    dest_fin = (reserva.get("destino_final") or "").strip()
    tiene_ramp_separado = bool(dest_orig and dest_fin and dest_orig.upper() not in dest_fin.upper() and dest_fin.upper() not in dest_orig.upper())

    dest_display = f"{dest_orig} / {dest_fin}" if tiene_ramp_separado else (dest_fin or dest_orig)
    reg.paso(f"[CMA fila {f}] {reserva['pol']} -> {dest_display} | NAVE: {reserva['nave']}")
    _avisar_dia_carga(reserva, reg)

    contrato = (str(reserva.get("cotizacion") or "").strip()
                or str(creds.get("contrato") or "").strip())
    fecha = _cma_fecha_txt(reserva.get("dia_carga", ""))

    def _ir_al_form():
        try:
            page.goto("https://www.cma-cgm.com/ebusiness/shipment/request",
                      wait_until="domcontentloaded")
            _cma_esperar_desafio(page, reg, on_pausa)
            esperar_hasta(page, "#pol", 8, reg, "cargar Click & Book", asentar=1.2)
        except Exception as e:
            reg.info(f"goto: {str(e)[:45]}")

    def _cotizacion():
        if not contrato:
            reg.info("sin 'contrato' en config.json; CMA lo exige"); return False
        try:
            page.keyboard.press("Escape")
            esperar(page, 0.4)
            q = page.locator("#quot").first
            q.scroll_into_view_if_needed(timeout=3000)
            try:
                q.click(timeout=3000)
            except Exception:
                page.keyboard.press("Escape")
                esperar(page, 0.3)
                q.click(timeout=2000, force=True)
            try: q.fill("", timeout=2000)
            except Exception: pass
            q.type(contrato, delay=60)
            page.keyboard.press("Tab"); esperar(page, 1.5)
            reg.info(f"cotizacion: {contrato}")
            return True
        except Exception as e:
            reg.info(f"cotizacion err: {str(e)[:40]}"); return False

    def _fecha():
        if not fecha:
            return
        try:
            d = page.locator("#fromDate").first
            d.click(timeout=4000)
            try: d.fill("", timeout=2000)
            except Exception: pass
            d.type(fecha, delay=70)
            d.press("Enter"); esperar(page, 0.8)
            page.keyboard.press("Tab")
            reg.info(f"fecha: {fecha}")
        except Exception as e:
            reg.info(f"fecha err: {str(e)[:40]}")

    def _validar():
        try:
            b = page.locator("#searchButton").first
            if b.is_disabled():
                return "deshabilitado"
            b.click(timeout=6000)
            reg.info("'Validar ruta'")
            return _cma_esperar_resultado(page, 12, reg)
        except Exception as e:
            reg.info(f"validar err: {str(e)[:45]}")
            return "error"

    if tiene_ramp_separado:
        intentos = [("ramp_separado", f"POD {dest_orig} y Ramp {dest_fin}"),
                    ("puerto", f"POD como puerto ({dest_fin})")]
    else:
        dest_p = dest_fin or dest_orig
        intentos = [("puerto", f"POD como puerto ({dest_p})"),
                    ("ramp", f"destino terrestre Ramp ({dest_p})")]

    ultimo_aviso = ""
    for modo, etiqueta in intentos:
        reg.paso(f"CMA · intento con {etiqueta}")
        _ir_al_form()
        if _cma_en_mantenimiento(page):
            reg.captura(page, f"cma_f{f}_mantenimiento")
            return _no_enviada(reg, CMA_MANTENIMIENTO)
        det = []
        # Antes de elegir cada sugerencia, la evidencia de la lista, con el modo (decisión de Marcelo,
        # CICLO-origen-y-destino.md). Sin una sugerencia elegida en el origen, el destino o el lugar de entrega, NO
        # ENVIADA, y no se prueba el modo siguiente: ninguna naviera sigue sin ellos (decisión de Marcelo, encargo 42,
        # CICLO-maersk-y-fila-sin-ruta.md). _cma_puerto corta por su cuenta si no elige, así que sus cortes de aquí no
        # se alcanzan hoy: cuidan que un cambio suyo no deje seguir sin el campo (hasta el encargo 42, un False suyo
        # habría dado REVISAR en el origen y seguido sin el destino). Sin el lugar de entrega, la reserva seguía.
        if not _cma_puerto(page, "#pol", reserva["pol"], reg, "Origen", evidencia=f"cma_f{f}_origen_{modo}"):
            raise ObjetivoNoEncontrado("Origen de CMA", _sugerencia_que_elegir(reserva["pol"]))
        det.append("POL")
        esperar(page, 0.8)

        if modo == "ramp_separado":
            if not _cma_puerto(page, "#pod", dest_orig, reg, "POD", evidencia=f"cma_f{f}_destino_{modo}"):
                raise ObjetivoNoEncontrado("POD de CMA", _sugerencia_que_elegir(dest_orig))
            det.append("POD=" + dest_orig)
            esperar(page, 0.8)
            ent = _cma_entrega(page, dest_fin, reg, evidencia=f"cma_f{f}_entrega_{modo}")
            if not ent:
                raise ObjetivoNoEncontrado("Lugar de entrega de CMA", _sugerencia_que_elegir(dest_fin))
            det.append("entrega=" + ent)
        elif modo == "puerto":
            dest_p = dest_fin or dest_orig
            if not _cma_puerto(page, "#pod", dest_p, reg, "POD", evidencia=f"cma_f{f}_destino_{modo}"):
                raise ObjetivoNoEncontrado("POD de CMA", _sugerencia_que_elegir(dest_p))
            det.append("POD=" + dest_p)
        elif modo == "ramp":
            dest_p = dest_fin or dest_orig
            if not _cma_puerto(page, "#pod", dest_p, reg, "POD", evidencia=f"cma_f{f}_destino_{modo}"):
                raise ObjetivoNoEncontrado("POD de CMA", _sugerencia_que_elegir(dest_p))
            det.append("POD=" + dest_p)
            esperar(page, 0.8)
            ent = _cma_entrega(page, dest_p, reg, evidencia=f"cma_f{f}_entrega_{modo}")
            if not ent:
                # El aviso con que CMA rechazó el modo puerto dice por qué se probó este (revisión de código del
                # encargo 42): sin él, el motivo hablaría solo de la sugerencia.
                aviso = f" (con el puerto, CMA avisó: «{ultimo_aviso}»)" if ultimo_aviso else ""
                raise ObjetivoNoEncontrado("Lugar de entrega de CMA", _sugerencia_que_elegir(dest_p) + aviso)
            det.append("entrega=" + ent)

        _fecha()
        if _cotizacion():
            det.append("cotiz=" + contrato)
        esperar(page, 1)
        reg.captura(page, f"cma_f{f}_2_ruta_{modo}", full=True)

        estado = _validar()
        if estado == "deshabilitado":
            reg.paso("'Validar ruta' quedo deshabilitado.")
            if modo in ("ramp", "ramp_separado"):
                return ("REVISAR", f"CMA: ruta incompleta ({', '.join(det)})")
            continue

        reg.captura(page, f"cma_f{f}_3_itinerarios_{modo}", full=True)
        ultimo_aviso = _cma_aviso(page)
        # Lo que dejó «Validar ruta» al terminar la espera que ya existe, respondiera o no el portal: la captura de la
        # ventana y el HTML, sin clics, teclas, esperas ni navegación. Va después de leer el aviso, para que esa lectura,
        # que decide el camino, siga en el mismo instante (decisión de Marcelo, CICLO-cola-tres-items.md).
        _evidencia_antes_de_la_guarda(page, reg, f"cma_f{f}_validar_{modo}", "tras «Validar ruta»", completa=False)
        if ultimo_aviso and "no matching" in ultimo_aviso.lower():
            reg.paso("CMA rechaza la combinacion: " + ultimo_aviso)
            if modo == "puerto":
                continue
            return ("REVISAR",
                    f"CMA: la cotizacion {contrato or '(sin contrato)'} no cubre "
                    f"{reserva['pol']} -> {dest_display}. Portal: {ultimo_aviso}")

        # RUTA ACEPTADA (o sin respuesta del portal): continuar con el flujo completo mapeado de la grabación
        _cma_anunciar_ruta(reg, estado)
        esperar(page, 2.5)

        # 1. Información extra si aparece el modal/formulario
        try:
            if page.locator("text=/extra information|Tamaño y tipo/i").count() or page.get_by_placeholder("Enter HS code").count():
                ok_info = _cma_completar_info_extra(page, reserva, reg)
                if not ok_info:
                    reg.info("reintentando información extra de carga...")
                    _cma_completar_info_extra(page, reserva, reg)
        except Exception as e:
            reg.info(f"info extra: {str(e)[:40]}")

        # 2. Selección de itinerario (Route choices)
        ok_itin, detalle_itin = _cma_seleccionar_itinerario(page, reserva, reg)
        reg.captura(page, f"cma_f{f}_4_itinerario", full=True)
        if not ok_itin:
            reg.paso(f"CMA · Itinerario no completado: {detalle_itin}")
            return ("REVISAR", detalle_itin)

        # 3. Ajustes Reefer (-20°C)
        _cma_ajustes_reefer(page, reserva, reg)

        # 4. Comentarios corporativos
        _cma_comentarios(page, reg)

        # 5. Llegar a la pantalla 'Envío de la reserva'
        reg.paso("Avanzando a la pantalla de revisión (Envío de la reserva)...")
        try:
            page.keyboard.press("Escape")
            esperar(page, 0.5)
            page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
            esperar(page, 1.5)
            _cma_marcar_i_agree(page, reg)
            esperar(page, 1.0)
        except Exception as e:
            reg.info(f"check agree err: {str(e)[:40]}")

        reg.captura(page, f"cma_f{f}_5_review", full=True)
        _evidencia_antes_de_la_guarda(page, reg, f"cma_f{f}_guarda")
        if not es_modo_emision():
            reg.paso("Me DETENGO en 'Envío de la reserva' antes de emitir (NO se pulsa Enviar el booking).")
            return ("OK-EJEMPLO", f"CMA armada hasta Envío de la reserva (nave: {reserva['nave']}); SIN emitir")
        else:
            # Modo emisión real
            reg.paso("EMISIÓN: Pulsando 'Enviar el booking'...")
            pulsado, error = None, None
            try:
                pulsado = _pulsar_boton(page, "button:has-text('Enviar el booking'), button:has-text('Send booking'), "
                                              "button:has-text('Submit booking')")
                if pulsado:
                    esperar(page, 4.0)
                esperar(page, 5.0)
            except Exception as e:
                error = e
            # CMA no tiene forma medida (sus capturas tras el envío no muestran confirmación): no
            # llega a EMITIDA hasta que se mida (CICLO-numero-booking.md).
            return _resultado_envio(page, reg, "cma", "CMA", f"cma_f{f}_6_confirmado", "Enviar el booking", pulsado,
                                    error)

    return ("REVISAR", f"CMA: no logre validar la ruta. Ultimo aviso: {ultimo_aviso or 'sin aviso'}")


RESERVADORES = {
    "one": reservar_one,
    "msc": reservar_msc,
    "cma": reservar_cma,
    "cosco": reservar_cosco,
    "hyundai": reservar_hyundai,
    "maersk": reservar_maersk,
}


# ============================================================
#  ORQUESTADOR
# ============================================================
def cargar_config():
    ruta = BASE / "config.json"
    if not ruta.exists():
        raise FileNotFoundError("No existe config.json (copia config.example.json y pon tus credenciales).")
    with open(ruta, encoding="utf-8") as f:
        return json.load(f)


def ejecutar_login(usuario, navieras, cfg=None, on_log=None, on_pausa=None,
                   on_listo=None, esperar_cierre=None):
    if cfg is None:
        cfg = cargar_config()
    opts = cfg.get("opciones", {})
    usuarios = cfg.get("usuarios", {})
    if usuario not in usuarios:
        raise ValueError(f"Usuario '{usuario}' no está en config.json.")

    carpeta = carpeta_corrida(usuario)
    reg = Registro(carpeta / "log.txt", on_log=on_log)
    reg.dir_capturas = carpeta

    headless = bool(opts.get("headless", False))
    canal = opts.get("navegador", "chrome")
    datos = usuarios[usuario]
    perfil_dir = PERFILES / usuario
    perfil_dir.mkdir(parents=True, exist_ok=True)

    reg.paso(f"INICIO · usuario={usuario} · navieras={','.join(navieras)}")
    reg.info(f"perfil: {perfil_dir}")
    reg.info(f"headless={headless} · navegador={canal} · modo sigiloso ON")

    resultados = {}
    with sync_playwright() as p:
        args = dict(
            user_data_dir=str(perfil_dir),
            headless=headless,
            no_viewport=True,
            args=_args_chrome(),
            ignore_default_args=["--enable-automation"],
        )
        try:
            ctx = p.chromium.launch_persistent_context(channel=canal, **args)
        except Exception as e:
            reg.info(f"no pude usar '{canal}' ({e}); uso chromium de playwright")
            ctx = p.chromium.launch_persistent_context(**args)

        try:
            ctx.add_init_script(STEALTH_JS)
        except Exception:
            pass

        page = ctx.pages[0] if ctx.pages else ctx.new_page()

        for clave in navieras:
            if clave not in NAVIERAS:
                reg.paso(f"[{clave}] naviera desconocida, se omite"); continue
            nombre, func = NAVIERAS[clave]
            creds = datos.get(clave, {})
            reg.paso(f"===== {nombre} =====")
            if not creds.get("usuario"):
                reg.info("sin credenciales en config.json, se omite"); resultados[clave] = None; continue
            t = time.time()
            try:
                ok = func(page, creds, reg, on_pausa=on_pausa)
            except Exception as e:
                reg.info(f"ERROR inesperado: {e}")
                try: reg.captura(page, f"{clave}_error")
                except Exception: pass
                ok = False
            reg.paso(f"[{nombre}] resultado={'OK' if ok else 'REVISAR'} (tardó {time.time()-t:.1f}s)")
            resultados[clave] = ok

        reg.paso("===== RESUMEN =====")
        for k, v in resultados.items():
            estado = "OK" if v else ("omitido" if v is None else "REVISAR")
            reg.info(f"{NAVIERAS[k][0]:10} {estado}")
        reg.paso(f"Log y capturas en: {carpeta}")
        reg.cerrar()

        if on_listo:
            try: on_listo(resultados, str(carpeta))
            except Exception: pass

        if esperar_cierre:
            try: esperar_cierre()
            except Exception: pass
        else:
            try: input("Presiona ENTER para cerrar el navegador... ")
            except Exception: pass

        try: ctx.close()
        except Exception: pass

    return resultados, str(carpeta)


def ejecutar_reservas(usuario, naviera_clave, cfg=None, on_log=None, on_pausa=None,
                      on_listo=None, esperar_cierre=None):
    """Inicia sesión en la naviera y arma cada reserva de la planilla (sin emitir)."""
    if cfg is None:
        cfg = cargar_config()
    opts = cfg.get("opciones", {})
    usuarios = cfg.get("usuarios", {})
    if usuario not in usuarios:
        raise ValueError(f"Usuario '{usuario}' no está en config.json.")
    if naviera_clave not in RESERVADORES:
        raise ValueError(f"Aún no está lista la reserva automática de '{naviera_clave}'.")

    ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")      # también arma la referencia de ejemplo
    carpeta = carpeta_corrida(f"reservas_{naviera_clave}_{usuario}")
    reg = Registro(carpeta / "log.txt", on_log=on_log)
    reg.dir_capturas = carpeta

    nombre, login_func = NAVIERAS[naviera_clave]
    reservador = RESERVADORES[naviera_clave]
    creds = usuarios[usuario].get(naviera_clave, {})
    headless = bool(opts.get("headless", False))
    canal = opts.get("navegador", "chrome")
    perfil_dir = PERFILES / usuario
    perfil_dir.mkdir(parents=True, exist_ok=True)

    reg.paso(f"INICIO RESERVAS · {nombre} · usuario={usuario}")
    _podar_html_viejo(reg)

    # Leer la planilla ANTES de abrir el navegador
    try:
        reservas = leer_reservas(naviera_clave)
    except Exception as e:
        reg.paso(f"No pude leer la planilla: {e}"); reg.cerrar()
        if on_listo: on_listo({}, str(carpeta))
        return {}, str(carpeta)
    reg.info(f"{len(reservas)} reserva(s) en la hoja {nombre}")
    if not reservas:
        reg.paso("No hay filas para procesar."); reg.cerrar()
        if on_listo: on_listo({}, str(carpeta))
        return {}, str(carpeta)

    resultados = {}
    sin_escribir = []       # filas cuyo resultado no quedó en la planilla (se cuentan en el resumen)
    # Copia de la planilla: una por corrida, justo antes de la primera escritura. Con «todas»
    # por consola las seis navieras comparten la de main() (hasta aaca5f1 dejaban una cada una).
    corrida = _CORRIDA_CONSOLA if _CORRIDA_CONSOLA is not None else {}
    respaldo_visto = False  # esta naviera ya pasó por la copia de la corrida

    def anotar(i, rsv, estado, detalle):
        """El resultado de la fila, en la planilla (con la copia de la corrida antes de la primera escritura) y en
        log.txt."""
        nonlocal respaldo_visto
        stamp = datetime.datetime.now().strftime("%d-%m %H:%M")
        refej = f"EJ{ts[-6:]}{i:02d}"
        # «SIN EMITIR» solo si la reserva volvió armada sin emitir (OK-EJEMPLO). Después
        # de la guarda vuelve EMITIDA, ENVIADA – REVISAR EN PORTAL o NO ENVIADA, y su
        # detalle dice qué pasó (_resultado_envio).
        cola = " · SIN EMITIR" if estado == "OK-EJEMPLO" else ""
        reporte = (f"SOLICITUD {i} · {estado} · nave: {rsv['nave']} · "
                   f"{rsv['pol']}→{rsv['destino_final']} · {stamp} · "
                   f"ref(ej) {refej} · {detalle}{cola}")
        try:
            if not respaldo_visto:
                _respaldo_de_la_corrida(corrida, reg)
                respaldo_visto = True
            escribir_estado(naviera_clave, rsv["fila"], reporte)
        except Exception as e:
            sin_escribir.append(rsv["fila"])
            reg.paso(f"⚠ No pude escribir el resultado de la fila {rsv['fila']} en la planilla: {e}. "
                     f"Anótalo a mano: {reporte}")
        resultados[rsv["fila"]] = estado
        reg.paso(f"fila {rsv['fila']}: {estado} ({detalle})")

    def resumen():
        orden = sorted(resultados.items())          # las filas sin nave se anotan primero; el resumen, en el de la hoja
        resultados.clear()
        resultados.update(orden)
        reg.paso("===== RESUMEN RESERVAS =====")
        for fila, est in resultados.items():
            reg.info(f"fila {fila}: {est}")
        if sin_escribir:
            reg.paso(f"⚠ {len(sin_escribir)} resultado(s) no quedaron en la planilla (filas "
                     f"{', '.join(map(str, sin_escribir))}); cada uno está arriba en este log.")
        reg.paso(f"Log y capturas en: {carpeta}")
        reg.cerrar()
        if on_listo:
            try: on_listo(resultados, str(carpeta))
            except Exception: pass

    # Una fila sin nave (vacía o con un comodín, _fila_sin_nave) no abre el portal: queda NO ENVIADA con el motivo, en
    # pantalla, en log.txt y en la planilla (decisión de Marcelo, CICLO-solo-la-nave-pedida.md). Si ninguna trae nave,
    # no se abre el navegador. Cada fila conserva su número de solicitud. Con AQUASHIELD_SOLO_PRIMERA, solo la primera
    # fila, traiga o no su nave y su ruta.
    numeradas = list(enumerate(reservas, start=1))
    if os.environ.get("AQUASHIELD_SOLO_PRIMERA"):
        reg.info("modo afinamiento: solo la primera fila")
        numeradas = numeradas[:1]
    for i, rsv in numeradas:
        if _fila_sin_nave(rsv["nave"]):
            anotar(i, rsv, *_sin_nave(reg, rsv["fila"], rsv["nave"]))
    con_nave = [(i, rsv) for i, rsv in numeradas if not _fila_sin_nave(rsv["nave"])]
    if not con_nave:
        reg.paso(f"Ninguna fila de {nombre} trae una nave para reservar: no abro el navegador ni entro al portal.")
        resumen()
        return resultados, str(carpeta)
    # Una fila con nave y sin puerto de carga o sin destino (_falta_en_la_fila) tampoco abre el portal: queda NO ENVIADA
    # con el motivo (decisión de Marcelo, encargo 42, CICLO-maersk-y-fila-sin-ruta.md).
    for i, rsv in con_nave:
        if _falta_en_la_fila(rsv):
            anotar(i, rsv, *_sin_ruta(reg, rsv["fila"], _falta_en_la_fila(rsv)))
    con_nave = [(i, rsv) for i, rsv in con_nave if not _falta_en_la_fila(rsv)]
    if not con_nave:
        reg.paso(f"Ninguna fila de {nombre} con nave trae el puerto de carga y el destino: no abro el navegador ni "
                 f"entro al portal.")
        resumen()
        return resultados, str(carpeta)

    with sync_playwright() as p:
        args = dict(user_data_dir=str(perfil_dir), headless=headless, no_viewport=True,
                    args=_args_chrome(),
                    ignore_default_args=["--enable-automation"])
        try:
            ctx = p.chromium.launch_persistent_context(channel=canal, **args)
        except Exception:
            ctx = p.chromium.launch_persistent_context(**args)
        try: ctx.add_init_script(STEALTH_JS)
        except Exception: pass
        # Traza de Playwright: graba pantalla, red y DOM paso a paso. Se abre con
        #   python -m playwright show-trace "<carpeta>\traza.zip"
        # Apagada por defecto (cuesta unos MB y algo de tiempo); se enciende con
        # la variable de entorno AQUASHIELD_TRAZA=1.
        trazando = bool(os.environ.get("AQUASHIELD_TRAZA"))
        if trazando:
            try:
                ctx.tracing.start(screenshots=True, snapshots=True, sources=True)
                reg.info("traza activada")
            except Exception as e:
                reg.info(f"no pude activar la traza: {str(e)[:60]}"); trazando = False
        page = ctx.pages[0] if ctx.pages else ctx.new_page()

        reg.paso(f"===== Login {nombre} =====")
        try:
            logueado = login_func(page, creds, reg, on_pausa=on_pausa)
        except Exception as e:
            reg.info(f"ERROR en login: {e}"); logueado = False

        if not logueado:
            reg.paso("No se pudo iniciar sesión; no proceso reservas.")
            # Sin la sesión de MSC, cada fila queda NO ENVIADA con su motivo, en la planilla y en log.txt (decisión de
            # Marcelo, encargo 45, CICLO-login-msc-y-maersk.md), el que dejó su login (_motivo_sin_sesion, encargo 50).
            # Con las otras navieras, como antes: no se toca.
            for i, rsv in (con_nave if naviera_clave in SIN_SESION else ()):
                anotar(i, rsv, NO_ENVIADA, _motivo_sin_sesion(reg, naviera_clave))
        else:
            for i, rsv in con_nave:
                reg.paso(f"----- Reserva {i}/{len(reservas)} -----")
                try:
                    estado, detalle = reservador(page, rsv, creds, reg, on_pausa=on_pausa)
                except Exception as e:
                    estado, detalle = "ERROR", str(e)[:120]
                    reg.info(f"ERROR: {e}")
                    try: reg.captura(page, f"error_fila_{rsv['fila']}")
                    except Exception: pass
                anotar(i, rsv, estado, detalle)

        resumen()
        if esperar_cierre:
            try: esperar_cierre()
            except Exception: pass
        else:
            try: input("Presiona ENTER para cerrar el navegador... ")
            except Exception: pass
        if trazando:
            try:
                ctx.tracing.stop(path=str(carpeta / "traza.zip"))
                reg.paso(f'Traza guardada. Ábrela con:  python -m playwright '
                         f'show-trace "{carpeta / "traza.zip"}"')
            except Exception as e:
                reg.info(f"no pude guardar la traza: {str(e)[:60]}")
        try: ctx.close()
        except Exception: pass

    return resultados, str(carpeta)


