def _familia(preferidas, defecto="TkDefaultFont"):
    """Primera tipografía disponible en el equipo, respetando el orden del manual."""
    try:
        from tkinter import font as tkfont
        disp = {f.lower() for f in tkfont.families()}
    except Exception:
        return defecto
    for f in preferidas:
        if f.lower() in disp:
            return f
    return defecto


def isotipo(canvas, x, y, alto, color, tags="iso"):
    """Dibuja el isotipo AquaChile: retícula de rombos que converge en una
    punta hacia la derecha. (x, y) es la esquina superior izquierda.
    Devuelve el ancho ocupado. No se rota, refleja ni deforma."""
    hh = alto / 8.0
    cols, hws, cxs = [4, 3, 2], [], []
    hw = hh * 0.62
    pos = hw
    for k in range(len(cols)):
        hws.append(hw); cxs.append(pos)
        nhw = hw * 1.30 if k < len(cols) - 1 else hh * 1.95
        pos += hw + nhw
        hw = nhw
    hw_cab = hh * 1.95
    pos -= hws[-1] * 0.6                      # la cabeza encaja en la V de la retícula
    cy0 = y + alto / 2.0
    for i, n in enumerate(cols):
        for j in range(n):
            cy = cy0 + (j - (n - 1) / 2.0) * 2 * hh
            px, hwp = x + cxs[i], hws[i]
            canvas.create_polygon(px, cy - hh, px + hwp, cy, px, cy + hh, px - hwp, cy,
                                  fill=color, outline="", tags=tags)
    px = x + pos
    canvas.create_polygon(px, cy0 - hh, px + hw_cab, cy0, px, cy0 + hh, px - hw_cab, cy0,
                          fill=color, outline="", tags=tags)
    return pos + hw_cab


def logotipo(canvas, x, y, alto, color, familia_serif, tags="logo"):
    """Logotipo completo: 'AquaChile' en serif con versalitas + isotipo a su
    derecha. (x, y) = extremo izquierdo, y centrado verticalmente."""
    from tkinter import font as tkfont
    f_may = tkfont.Font(family=familia_serif, size=-int(alto))
    f_ver = tkfont.Font(family=familia_serif, size=-int(alto * 0.74))
    cx = x
    for txt, f in (("A", f_may), ("QUA", f_ver), ("C", f_may), ("HILE", f_ver)):
        canvas.create_text(cx, y, text=txt, font=f, fill=color, anchor="w", tags=tags)
        cx += f.measure(txt)
    cx += alto * 0.42                                   # área de resguardo interna
    ancho_iso = isotipo(canvas, cx, y - alto * 0.42, alto * 0.84, color, tags=tags)
    return cx + ancho_iso - x


# ============================================================
#  PANEL GRÁFICO (Tkinter)
# ============================================================
def lanzar_panel():
    import tkinter as tk
    from tkinter import ttk, messagebox, simpledialog
    from tkinter import font as tkfont

    C = MARCA

    class Panel:
        def __init__(self, root):
            self.root = root
            root.title(f"AQUASHIELD · Reservas y Login · v{VERSION}")
            # la ventana se ajusta a la pantalla real (notebooks con escalado alto)
            try:
                sw, sh = root.winfo_screenwidth(), root.winfo_screenheight()
            except Exception:
                sw, sh = 1280, 800
            an = max(700, min(900, sw - 120))
            al = max(470, min(650, sh - 130))
            root.geometry(f"{an}x{al}+{max(0,(sw-an)//2)}+{max(0,(sh-al)//3)}")
            root.minsize(700, 470)
            root.configure(bg=C["gris_frio"])
            self.cola = queue.Queue()
            self.ev_pausa = threading.Event()
            self.ev_cierre = threading.Event()
            self.hilo = None
            self.ultima_carpeta = None

            # --- tipografías del manual (con los reemplazos autorizados) ---
            self.f_titular = _familia(["Quicksand Light", "Quicksand", "Century Gothic",
                                       "Corbel", "Segoe UI Light"], "Segoe UI")
            self.f_texto = _familia(["Dobra Book", "Dobra", "PT Sans", "Source Sans 3",
                                     "Segoe UI"], "Segoe UI")
            self.f_serif = _familia(["Charter", "Bitstream Charter", "ITC Charter",
                                     "Georgia", "Times New Roman"], "Georgia")
            self._estilos()

            try:
                self.cfg = cargar_config()
            except Exception as e:
                messagebox.showerror("config.json", str(e)); self.cfg = {"usuarios": {}, "opciones": {}}
            self.seg_visible = int(self.cfg.get("opciones", {}).get("segundos_visible", 6))
            usuarios = list(self.cfg.get("usuarios", {}).keys()) or ["(sin usuarios)"]

            self._cabecera(root)

            # la barra de estado se reserva antes que el cuerpo expansible
            pie = tk.Frame(root, bg=C["corp"], height=30); pie.pack(fill="x", side="bottom")
            self.lbl = tk.Label(pie, text="◆   Listo.", bg=C["corp"], fg=C["blanco"],
                                font=(self.f_serif, 9), anchor="w", padx=22, pady=6)
            self.lbl.pack(fill="x")

            cuerpo = ttk.Frame(root, style="Marca.TFrame", padding=(22, 16, 22, 0))
            cuerpo.pack(fill="both", expand=True)

            # --- fila de operador ---
            top = ttk.Frame(cuerpo, style="Marca.TFrame"); top.pack(fill="x")
            ttk.Label(top, text="OPERADOR", style="Rotulo.TLabel").pack(side="left", padx=(0, 8))
            self.cbo = ttk.Combobox(top, values=usuarios, state="readonly", width=20,
                                    style="Marca.TCombobox", font=(self.f_texto, 10))
            self.cbo.current(0); self.cbo.pack(side="left")
            self.modo_reservas = tk.BooleanVar(value=False)
            ttk.Checkbutton(top, text="Modo RESERVAS  (lee la planilla)",
                            variable=self.modo_reservas,
                            style="Marca.TCheckbutton").pack(side="left", padx=(18, 0))

            self._filete(cuerpo, C["borde"], (14, 10))

            # --- navieras ---
            ttk.Label(cuerpo, text="◆  NAVIERA", style="Rotulo.TLabel").pack(anchor="w")
            navf = ttk.Frame(cuerpo, style="Marca.TFrame", padding=(0, 8, 0, 0)); navf.pack(fill="x")
            self.botones = []
            navs = [("one", "ONE"), ("msc", "MSC"), ("cma", "CMA-CGM"), ("cosco", "COSCO"),
                    ("hyundai", "HYUNDAI"), ("maersk", "MAERSK"),
                    ("todas", "TODAS")]
            for i, (clave, texto) in enumerate(navs):
                estilo = "Acento.TButton" if clave == "todas" else "Nav.TButton"
                b = ttk.Button(navf, text=texto, width=8, style=estilo,
                               command=lambda c=clave: self.iniciar(c))
                b.grid(row=0, column=i, sticky="ew", padx=(0, 5))
                navf.columnconfigure(i, weight=1, uniform="nav")
                self.botones.append(b)

            # --- acciones ---
            acc = ttk.Frame(cuerpo, style="Marca.TFrame", padding=(0, 14, 0, 0)); acc.pack(fill="x")
            self.btn_manual = ttk.Button(acc, text="✔  Ya lo resolví (continuar)", style="Nav.TButton",
                                         state="disabled", command=self.continuar_manual)
            self.btn_manual.pack(side="left")
            self.btn_cerrar = ttk.Button(acc, text="Cerrar navegador ahora", style="Nav.TButton",
                                         state="disabled", command=self.cerrar_nav)
            self.btn_cerrar.pack(side="left", padx=8)
            ttk.Button(acc, text="Carpeta de logs", style="Plano.TButton",
                       command=self.abrir_logs).pack(side="right")
            ttk.Button(acc, text="Credenciales", style="Plano.TButton",
                       command=self.editar_credenciales).pack(side="right", padx=8)

            # --- bitácora ---
            ttk.Label(cuerpo, text="◆  BITÁCORA", style="Rotulo.TLabel").pack(anchor="w", pady=(16, 6))
            caja = tk.Frame(cuerpo, bg=C["borde"], bd=0, highlightthickness=0)
            caja.pack(fill="both", expand=True, pady=(0, 16))
            interior = tk.Frame(caja, bg=C["blanco"]); interior.pack(fill="both", expand=True, padx=1, pady=1)
            self.txt = tk.Text(interior, wrap="word", font=("Consolas", 9), bd=0,
                               bg=C["blanco"], fg=C["corp"], padx=12, pady=10,
                               highlightthickness=0, insertbackground=C["corp"], spacing1=1)
            sb = ttk.Scrollbar(interior, orient="vertical", command=self.txt.yview,
                               style="Marca.Vertical.TScrollbar")
            self.txt.configure(yscrollcommand=sb.set)
            sb.pack(side="right", fill="y"); self.txt.pack(side="left", fill="both", expand=True)
            self.txt.tag_configure("paso", foreground=C["corp"], font=("Consolas", 9, "bold"))
            self.txt.tag_configure("ok", foreground=C["ok"])
            self.txt.tag_configure("alerta", foreground=C["alerta"])
            self.txt.tag_configure("info", foreground=C["apagado"])
            self.txt.configure(state="disabled")

            self.root.after(100, self.procesar_cola)

        # ---------- identidad ----------
        def _estilos(self):
            st = ttk.Style()
            try: st.theme_use("clam")
            except Exception: pass
            g, corp, bl = C["gris_frio"], C["corp"], C["blanco"]
            st.configure("Marca.TFrame", background=g)
            st.configure("Marca.TLabel", background=g, foreground=corp, font=(self.f_texto, 10))
            st.configure("Rotulo.TLabel", background=g, foreground=C["apagado"],
                         font=(self.f_texto, 8, "bold"))
            st.configure("Nav.TButton", background=bl, foreground=corp, bordercolor=C["borde"],
                         lightcolor=bl, darkcolor=bl, relief="flat", padding=(8, 8),
                         font=(self.f_texto, 9), focuscolor=g)
            st.map("Nav.TButton",
                   background=[("disabled", "#E6E7E9"), ("pressed", C["corp_hover"]), ("active", corp)],
                   foreground=[("disabled", "#A9AFB4"), ("pressed", bl), ("active", bl)],
                   bordercolor=[("active", corp), ("disabled", C["borde"])])
            st.configure("Acento.TButton", background=corp, foreground=bl, bordercolor=corp,
                         lightcolor=corp, darkcolor=corp, relief="flat", padding=(8, 8),
                         font=(self.f_texto, 9, "bold"), focuscolor=corp)
            st.map("Acento.TButton",
                   background=[("disabled", "#B9C0C5"), ("active", C["naranja"])],
                   bordercolor=[("active", C["naranja"]), ("disabled", "#B9C0C5")],
                   lightcolor=[("active", C["naranja"])], darkcolor=[("active", C["naranja"])],
                   foreground=[("disabled", "#EDEFF0")])
            st.configure("Plano.TButton", background=g, foreground=C["apagado"], bordercolor=g,
                         lightcolor=g, darkcolor=g, relief="flat", padding=(6, 8),
                         font=(self.f_texto, 9), focuscolor=g)
            st.map("Plano.TButton", foreground=[("active", C["naranja"])],
                   background=[("active", g)], bordercolor=[("active", g)],
                   lightcolor=[("active", g)], darkcolor=[("active", g)])
            st.configure("Marca.TCheckbutton", background=g, foreground=corp,
                         font=(self.f_texto, 10), focuscolor=g, indicatorcolor=bl,
                         bordercolor=C["borde"], lightcolor=bl, darkcolor=bl)
            st.map("Marca.TCheckbutton", background=[("active", g)],
                   indicatorcolor=[("selected", C["naranja"])])
            st.configure("Marca.TCombobox", fieldbackground=bl, background=bl, foreground=corp,
                         bordercolor=C["borde"], lightcolor=bl, darkcolor=bl,
                         arrowcolor=corp, padding=5)
            st.map("Marca.TCombobox", fieldbackground=[("readonly", bl), ("disabled", "#E6E7E9")],
                   foreground=[("disabled", "#A9AFB4")], arrowcolor=[("disabled", "#A9AFB4")])
            st.configure("Marca.Vertical.TScrollbar", background=C["gris_calido"], troughcolor=bl,
                         bordercolor=bl, arrowcolor=C["apagado"], lightcolor=bl, darkcolor=bl)
            st.map("Marca.Vertical.TScrollbar", background=[("active", C["apagado"])])
            st.configure("Marca.TLabelframe", background=g, bordercolor=C["borde"],
                         lightcolor=g, darkcolor=g)
            st.configure("Marca.TLabelframe.Label", background=g, foreground=C["apagado"],
                         font=(self.f_texto, 8, "bold"))
            st.configure("Naviera.TLabel", background=g, foreground=corp,
                         font=(self.f_texto, 9, "bold"))
            st.configure("Marca.TEntry", fieldbackground=bl, bordercolor=C["borde"],
                         lightcolor=bl, darkcolor=bl, foreground=corp, padding=4)

        def _cabecera(self, root):
            """Banda corporativa: nombre del programa, versión y logotipo AquaChile.
            El isotipo va sobreimpreso tono sobre tono, sangrado por el borde inferior."""
            self.cab = tk.Canvas(root, height=92, bg=C["corp"], highlightthickness=0, bd=0)
            self.cab.pack(fill="x")
            self.cab.bind("<Configure>", self._pintar_cabecera)
            self._filete(root, C["naranja"], (0, 0), alto=3)

        def _pintar_cabecera(self, ev=None):
            c = self.cab
            c.delete("all")
            w = c.winfo_width() or 900
            # isotipo tono sobre tono, sangrado por abajo (recurso gráfico del manual)
            try:
                alto_ag = 210                       # sangrado por arriba y abajo
                isotipo(c, w * 0.44, 46 - alto_ag / 2, alto_ag, C["corp_agua"])
            except Exception:
                pass
            c.create_text(26, 34, text="A Q U A S H I E L D", anchor="w",
                          font=(self.f_titular, 20), fill=C["blanco"])
            c.create_text(28, 64, text=f"Reservas y Login  ·  versión {VERSION}", anchor="w",
                          font=(self.f_serif, 9, "italic"), fill="#B7C0C7")
            try:
                ancho = logotipo(c, 0, 0, 17, C["blanco"], self.f_serif)  # medir
                c.delete("logo")
                logotipo(c, w - 30 - ancho, 46, 17, C["blanco"], self.f_serif)
            except Exception:
                c.create_text(w - 30, 46, text="AquaChile", anchor="e",
                              font=(self.f_serif, 13), fill=C["blanco"])

        def _filete(self, padre, color, pady, alto=1):
            f = tk.Frame(padre, bg=color, height=alto)
            f.pack(fill="x", pady=pady)
            return f

        # ---------- lógica (sin cambios de comportamiento) ----------
        def iniciar(self, objetivo):
            if self.hilo and self.hilo.is_alive():
                messagebox.showinfo("En curso", "Ya hay una prueba corriendo. Espera a que termine."); return
            usuario = self.cbo.get()
            if usuario not in self.cfg.get("usuarios", {}):
                messagebox.showerror("Usuario", "Selecciona un usuario válido en config.json."); return

            reservas_mode = self.modo_reservas.get()
            if reservas_mode:
                if objetivo == "todas":
                    messagebox.showinfo("Reservas", "Elige UNA naviera (no 'TODAS') para armar reservas."); return
                if objetivo not in RESERVADORES:
                    disp = ", ".join(k.upper() for k in RESERVADORES)
                    messagebox.showinfo("Reservas",
                        f"La reserva automática de {objetivo.upper()} aún no está lista.\n"
                        f"Por ahora disponibles: {disp}.\n\n"
                        f"(Para {objetivo.upper()} puedes usar el modo LOGIN para entrar al portal "
                        f"y reservar a mano mientras construimos su flujo.)"); return
                self._log(f"\n════════  RESERVAS {objetivo.upper()} · {usuario}  ════════")
            else:
                navieras = list(NAVIERAS.keys()) if objetivo == "todas" else [objetivo]
                self._log(f"\n════════  LOGIN: {usuario} · {', '.join(navieras)}  ════════")

            self.estado_run(False); self.ev_pausa.clear(); self.ev_cierre.clear()
            self.btn_cerrar.configure(state="disabled"); self.btn_manual.configure(state="disabled")
            self.estado("Corriendo… se abrirá el navegador.")
            navieras = list(NAVIERAS.keys()) if (objetivo == "todas" and not reservas_mode) else [objetivo]
            self.hilo = threading.Thread(target=self._worker, args=(usuario, navieras, reservas_mode), daemon=True)
            self.hilo.start()

        def _worker(self, usuario, navieras, reservas_mode=False):
            cb_log = lambda l: self.cola.put(("log", l))
            cb_listo = lambda r, c: self.cola.put(("listo", (r, c)))
            try:
                if reservas_mode:
                    ejecutar_reservas(usuario, navieras[0], cfg=self.cfg, on_log=cb_log,
                                      on_pausa=self._pausa, on_listo=cb_listo,
                                      esperar_cierre=self._esperar_cierre)
                else:
                    ejecutar_login(usuario, navieras, cfg=self.cfg, on_log=cb_log,
                                   on_pausa=self._pausa, on_listo=cb_listo,
                                   esperar_cierre=self._esperar_cierre)
            except Exception:
                self.cola.put(("log", "ERROR en worker:\n" + traceback.format_exc()))
            finally:
                self.cola.put(("fin", None))

        def _pausa(self, mensaje):
            self.cola.put(("pausa", mensaje)); self.ev_pausa.wait()

        def _esperar_cierre(self):
            self.cola.put(("puede_cerrar", self.seg_visible))
            self.ev_cierre.wait(timeout=self.seg_visible)

        def continuar_manual(self):
            self.btn_manual.configure(state="disabled")
            self._log("▸ Continuando (paso manual resuelto)."); self.ev_pausa.set()

        def cerrar_nav(self):
            self.btn_cerrar.configure(state="disabled")
            self._log("▸ Cerrando navegador…"); self.ev_cierre.set()

        def abrir_logs(self):
            LOGS.mkdir(exist_ok=True)
            carpeta = self.ultima_carpeta or str(LOGS)
            try: os.startfile(carpeta)
            except Exception: messagebox.showinfo("Logs", f"Carpeta de logs:\n{carpeta}")

        def editar_credenciales(self):
            win = tk.Toplevel(self.root); win.title("Credenciales · AQUASHIELD")
            try:
                sw, sh = win.winfo_screenwidth(), win.winfo_screenheight()
            except Exception:
                sw, sh = 1280, 800
            an = max(680, min(780, sw - 140)); al = max(450, min(560, sh - 150))
            win.geometry(f"{an}x{al}+{max(0,(sw-an)//2)}+{max(0,(sh-al)//4)}")
            win.configure(bg=C["gris_frio"])
            win.transient(self.root); win.grab_set()

            cab = tk.Canvas(win, height=54, bg=C["corp"], highlightthickness=0, bd=0)
            cab.pack(fill="x")
            cab.create_text(22, 28, text="C R E D E N C I A L E S", anchor="w",
                            font=(self.f_titular, 13), fill=C["blanco"])
            tk.Frame(win, bg=C["naranja"], height=3).pack(fill="x")

            barra = ttk.Frame(win, style="Marca.TFrame", padding=(20, 14, 20, 0)); barra.pack(fill="x")
            ttk.Label(barra, text="OPERADOR", style="Rotulo.TLabel").pack(side="left", padx=(0, 8))
            users = list(self.cfg.get("usuarios", {}).keys())
            cbo = ttk.Combobox(barra, values=users, state="readonly", width=22,
                               style="Marca.TCombobox", font=(self.f_texto, 10))
            if users: cbo.current(0)
            cbo.pack(side="left")

            def nuevo_usuario():
                nombre = simpledialog.askstring("Nuevo operador",
                    "Nombre corto del operador (sin espacios), ej: usuario1, maria:", parent=win)
                if not nombre: return
                nombre = nombre.strip().lower().replace(" ", "_")
                vacia = lambda: {"usuario": "", "clave": "", "contrato": ""}
                self.cfg.setdefault("usuarios", {}).setdefault(nombre, {
                    "descripcion": nombre,
                    "cma": vacia(), "cosco": vacia(), "one": vacia(), "msc": vacia(),
                    "hyundai": vacia(), "maersk": vacia(),
                })
                cbo.configure(values=list(self.cfg["usuarios"].keys())); cbo.set(nombre); cargar()

            ttk.Button(barra, text="+  Nuevo operador", style="Plano.TButton",
                       command=nuevo_usuario).pack(side="left", padx=10)

            # el pie se reserva antes que el cuerpo, para que nunca quede fuera de la ventana
            pie = ttk.Frame(win, style="Marca.TFrame", padding=(20, 12, 20, 16))
            pie.pack(fill="x", side="bottom")

            cont = ttk.Frame(win, style="Marca.TFrame", padding=(20, 12, 20, 0))
            cont.pack(fill="both", expand=True)
            entries = {}
            NAV = [("one", "ONE"), ("msc", "MSC"), ("cma", "CMA-CGM"), ("cosco", "COSCO"),
                   ("hyundai", "HYUNDAI"), ("maersk", "MAERSK")]
            cab_campos = ttk.Frame(cont, style="Marca.TFrame"); cab_campos.pack(fill="x")
            for texto, ancho, exp in (("", 11, False), ("USUARIO", 26, True),
                                      ("CLAVE", 20, False), ("CONTRATO", 20, True)):
                ttk.Label(cab_campos, text=texto, width=ancho, anchor="w",
                          style="Rotulo.TLabel").pack(side="left", padx=(0, 6),
                                                      fill="x", expand=exp)
            for clave, titulo in NAV:
                fila = ttk.Frame(cont, style="Marca.TFrame"); fila.pack(fill="x", pady=3)
                ttk.Label(fila, text="◆  " + titulo, width=11,
                          style="Naviera.TLabel").pack(side="left", padx=(0, 6))
                for campo, ancho in (("usuario", 26), ("clave", 20), ("contrato", 20)):
                    e = ttk.Entry(fila, width=ancho, style="Marca.TEntry", font=(self.f_texto, 10),
                                  show=("•" if campo == "clave" else ""))
                    e.pack(side="left", padx=(0, 6), fill="x",
                           expand=(campo != "clave"))
                    entries[(clave, campo)] = e
                tk.Frame(cont, bg=C["borde"], height=1).pack(fill="x")

            estado = {"ver": False}
            def toggle_claves():
                estado["ver"] = not estado["ver"]
                for (c_, campo), e in entries.items():
                    if campo == "clave":
                        e.configure(show="" if estado["ver"] else "•")

            def cargar(*_):
                u = cbo.get(); datos = self.cfg.get("usuarios", {}).get(u, {})
                for (clave, campo), e in entries.items():
                    e.delete(0, "end")
                    e.insert(0, datos.get(clave, {}).get(campo, ""))

            def guardar():
                u = cbo.get()
                if not u:
                    messagebox.showwarning("Credenciales", "Crea o elige un operador primero.", parent=win); return
                d = self.cfg.setdefault("usuarios", {}).setdefault(u, {})
                d.setdefault("descripcion", u)
                for clave, _ in NAV:
                    d.setdefault(clave, {})
                    for campo in ("usuario", "clave", "contrato"):
                        d[clave][campo] = entries[(clave, campo)].get().strip()
                try:
                    # Escritura atómica, con el mismo ayudante que el panel web (CICLO-cola-siete-items.md).
                    _escribir_config(self.cfg, BASE / "config.json")
                    self.cbo.configure(values=list(self.cfg["usuarios"].keys()))
                    messagebox.showinfo("Credenciales", "Guardado correctamente.", parent=win)
                except Exception as e:
                    messagebox.showerror("Credenciales", f"No pude guardar:\n{e}", parent=win)

            cbo.bind("<<ComboboxSelected>>", cargar)
            if users: cargar()

            ttk.Button(pie, text="Mostrar / ocultar claves", style="Plano.TButton",
                       command=toggle_claves).pack(side="left")
            ttk.Button(pie, text="Guardar", style="Acento.TButton", command=guardar).pack(side="right")
            ttk.Button(pie, text="Cerrar", style="Nav.TButton",
                       command=win.destroy).pack(side="right", padx=8)

        def estado_run(self, on):
            e = "normal" if on else "disabled"
            for b in self.botones: b.configure(state=e)
            self.cbo.configure(state="readonly" if on else "disabled")

        def estado(self, texto):
            self.lbl.configure(text="◆   " + texto)

        def _etiqueta(self, linea):
            t = linea.strip()
            bajo = t.lower()
            if t.startswith("═") or t.startswith("###") or t.startswith("***"):
                return "paso"
            if any(k in bajo for k in ("ok", "listo", "reservado", "guardado", "correctamente")) \
               and not bajo.startswith("error"):
                return "ok"
            if any(k in bajo for k in ("error", "falló", "fallo", "no pude", "sin cupo",
                                       "bloquea", "timeout", "traceback")):
                return "alerta"
            if t.startswith("·") or t.startswith("-") or t.startswith("▸") or "esperando" in bajo:
                return "info"
            return ""

        def _log(self, texto):
            self.txt.configure(state="normal")
            for linea in str(texto).split("\n"):
                self.txt.insert("end", linea + "\n", self._etiqueta(linea))
            self.txt.see("end"); self.txt.configure(state="disabled")

        def procesar_cola(self):
            try:
                while True:
                    tipo, dato = self.cola.get_nowait()
                    if tipo == "log": self._log(dato)
                    elif tipo == "pausa":
                        self._log("\n***  ACCIÓN MANUAL REQUERIDA  ***"); self._log(dato)
                        self.btn_manual.configure(state="normal")
                        self.estado("Resuelve el paso en el navegador y pulsa «Ya lo resolví».")
                    elif tipo == "puede_cerrar":
                        self.btn_cerrar.configure(state="normal")
                        self.estado(f"Terminó. El navegador se cierra solo en {dato}s "
                                    f"(o «Cerrar navegador ahora»).")
                    elif tipo == "listo":
                        _, carpeta = dato; self.ultima_carpeta = carpeta
                    elif tipo == "fin":
                        self.estado_run(True); self.btn_manual.configure(state="disabled")
                        self.btn_cerrar.configure(state="disabled")
                        self.estado("Listo para la siguiente prueba.")
            except queue.Empty:
                pass
            self.root.after(100, self.procesar_cola)

    root = tk.Tk(); Panel(root); root.mainloop()




# -*- coding: utf-8 -*-
# ============================================================
#  INDEX WEB (servidor local)
#  Un HTML suelto no puede manejar Chrome: el navegador se lo prohibe.
#  Por eso el programa levanta un servidor en el propio equipo y abre
#  la pagina apuntando a el. Todo queda local; nada sale a internet.
# ============================================================
import json as _json
import threading as _th
import time as _time
import io as _io
import os as _os
import re as _re
import datetime as _dt

# Campos que se buscan en el encabezado. El orden importa: lo mas
# especifico primero, para que "Destino Final" no se lleve "Destino Original".
_CAMPOS = [
    ("naviera",       ("naviera", "linea", "carrier")),
    ("destino_final", ("destino final",)),
    ("destino_orig",  ("destino original", "puerto de descarga", "puerto descarga", "pto descarga", "pto. descarga", "pod", "descarga")),
    ("pol",           ("pto. embarque", "puerto de embarque", "embarque", "origen", "pol")),
    ("reserva_emitida", ("reserva emitida", "n° de reserva emitida", "nº de reserva emitida", "n° reserva", "booking emitido")),
    ("reserva",       ("reserva original", "reserva")),
    ("dia_retiro",    ("retiro",)),
    ("deposito",      ("deposito", "depósito")),
    ("dia_carga",     ("dia de carga", "día de carga", "carga")),
    ("nave",          ("nave",)),
    ("viaje",         ("viaje",)),
    ("contenedor",    ("tipo contenedor", "contenedor")),
    ("cant",          ("cant",)),
    ("estado",        ("estado",)),
    ("cotizacion",    ("cotiz", "contrato")),
    ("temp",          ("temperatura", "temp", "grados")),
]


def _txt(v):
    if v is None:
        return ""
    if isinstance(v, _dt.datetime):
        return v.strftime("%Y-%m-%d")
    if isinstance(v, _dt.date):
        return v.isoformat()
    return str(v).strip()


def _mapear(ws, tope=14):
    """Encuentra la fila de encabezado y en que columna esta cada campo.
    No se usan posiciones fijas: cada planilla acomoda las columnas a su gusto
    y la de COSCO, por ejemplo, parte en la columna B."""
    mejor, mejor_n, mejor_fila = {}, 0, 0
    for r in range(1, min(ws.max_row, tope) + 1):
        cabec = {}
        for c in range(1, min(ws.max_column, 40) + 1):
            h = _txt(ws.cell(r, c).value).lower()
            if not h:
                continue
            for campo, claves in _CAMPOS:
                if campo in cabec:
                    continue
                if any(k in h for k in claves):
                    cabec[campo] = c
                    break
        if len(cabec) > mejor_n:
            mejor, mejor_n, mejor_fila = cabec, len(cabec), r
    return mejor_fila, mejor


def leer_filas(ws):
    """Filas de reserva de una hoja ya abierta. Una fila = una reserva."""
    fila_enc, cols = _mapear(ws)
    if not fila_enc or "nave" not in cols and "pol" not in cols:
        return 0, {}, []
    filas = []
    for r in range(fila_enc + 1, ws.max_row + 1):
        val = lambda campo: _txt(ws.cell(r, cols[campo]).value) if campo in cols else ""
        pol, nave = val("pol"), val("nave")
        if not pol and not nave:
            continue
        if pol.lower().startswith("pto") or nave.lower() == "nave":
            continue                      # encabezado repetido
        try:
            cant = int(float(val("cant") or 1))
        except Exception:
            cant = 1
        filas.append({
            "fila": r,
            "naviera": val("naviera"),
            "pol": pol,
            "reserva": val("reserva"),
            "destino_orig": val("destino_orig"),
            "destino_final": _destino_final_de(val("destino_final")) or val("destino_orig"),
            "dia_retiro": val("dia_retiro"),
            "deposito": val("deposito"),
            "dia_carga": val("dia_carga"),
            "nave": "" if "completar" in nave.lower() else nave,
            "viaje": val("viaje"),
            "contenedor": val("contenedor") or "40 HC REEFER",
            "cant": cant,
            "cotizacion": val("cotizacion"),
            "temp": val("temp"),
        })
    return fila_enc, cols, filas


# ------------------------------------------------------------
#  Estado compartido entre el navegador y el proceso de reservas
# ------------------------------------------------------------
_SRV_ACTUAL = None
_WEB = {"ruta": None, "nombre": "", "hoja": "", "usuario": "",
        "log": [], "base": 0, "resultados": {}, "corriendo": False,
        "estado": "Listo.", "hilo": None, "detener": None, "carpeta": "",
        "pausa": None, "pausa_msg": "", "ultimo_latido": time.time()}
_LOCK = _th.Lock()


def _wlog(linea):
    with _LOCK:
        for l in str(linea).split("\n"):
            _WEB["log"].append(l)
        sobra = len(_WEB["log"]) - 4000
        if sobra > 0:                      # se recorta el inicio y se corre el origen
            del _WEB["log"][:sobra]
            _WEB["base"] += sobra


def _westado(t):
    with _LOCK:
        _WEB["estado"] = t


def _hojas_del_libro(ruta):
    import openpyxl
    wb = openpyxl.load_workbook(ruta, data_only=True)
    out = []
    for h in wb.sheetnames:
        try:
            _, _, filas = leer_filas(wb[h])
        except Exception:
            filas = []
        out.append({"hoja": h, "filas": len(filas),
                    "reservador": bool(_nav_de_hoja(h))})
    return out


def _filas_de_hoja(ruta, hoja):
    import openpyxl
    wb = openpyxl.load_workbook(ruta, data_only=True)
    if hoja not in wb.sheetnames:
        return []
    return leer_filas(wb[hoja])[2]


def _extraer_bkg_limpio(r):
    """Extrae el código limpio de la reserva emitida."""
    # Solo una EMITIDA tiene número: ENVIADA – REVISAR EN PORTAL, NO ENVIADA y los demás estados
    # van sin él aunque su detalle traiga un código (hasta f03bb75 se tomaba de cualquier estado).
    if str((r or {}).get("estado") or "") != "EMITIDA":
        return ""
    bkg = str((r or {}).get("booking") or "").strip()
    if bkg and bkg.upper() not in ("EN PROCESO", "COPYRIGHT", "CONSULTAR", "VER CAPTURA", "PENDIENTE", "NUMBER", "DETAILS", "SUMMARY", "REQUEST", "SERVICE"):
        return bkg
    det = str((r or {}).get("detalle") or "")
    # 1. ONE: SCLG...
    m = _re.search(r"\b(SCLG\d{6,10})\b", det)
    if m: return m.group(1).strip()
    # 2. HYUNDAI: SCLA...
    m = _re.search(r"\b(SCLA\d{6,10})\b", det)
    if m: return m.group(1).strip()
    # 3. MAERSK: 9 dígitos iniciando en 27
    m = _re.search(r"\b(27\d{7})\b", det)
    if m: return m.group(1).strip()
    # 4. MSC: EBKG...
    m = _re.search(r"\b(EBKG\d{7,10})\b", det)
    if m: return m.group(1).strip()
    # 5. MSC / CMA: Bkg: ... / Booking: ...
    m = _re.search(r"(?:Bkg|Booking|Reference(?:\s*No\.?)?)[:\s]+([A-Z0-9]{6,18})", det, _re.I)
    if m:
        c = m.group(1).strip()
        if c.upper() not in ("EN PROCESO", "COPYRIGHT", "CONSULTAR", "VER CAPTURA", "PENDIENTE", "NUMBER", "DETAILS", "SUMMARY", "REQUEST", "SERVICE"):
            return c
    return ""


# Lo que dice la columna «N° de reserva emitida», en el panel y en la planilla descargada: una sola fuente,
# _texto_n_reserva (el panel lo recibe hecho, en n_reserva de /api/estado). Con el candado cerrado, la reserva armada
# hasta la guarda (OK-EJEMPLO) no se emitió: queda lista para emitir. Hasta el encargo 34, el panel mostraba
# «✓ Confirmada» en esas filas, y la planilla dejaba la celda vacía (CICLO-one-y-maersk-eligen-la-nave.md).
LISTA_PARA_EMITIR = "lista para emitir"


def _texto_n_reserva(r):
    """El texto de la columna «N° de reserva emitida» para un resultado: el número de una EMITIDA (_extraer_bkg_limpio),
    LISTA_PARA_EMITIR si quedó en OK-EJEMPLO, y vacío en los demás estados. «Confirmada» no lo dice nunca: solo el
    número de una reserva real dice que se emitió."""
    bkg = _extraer_bkg_limpio(r)
    if bkg:
        return bkg
    return LISTA_PARA_EMITIR if str((r or {}).get("estado") or "") == "OK-EJEMPLO" else ""


def _planilla_con_resultados(ruta, hoja, resultados):
    """Devuelve el mismo archivo cargado, con la columna Estado y N° de reserva emitida completadas.
    Se conserva todo lo demás (formato, imágenes, otras hojas) porque se
    reescribe sobre el original, no se genera uno nuevo."""
    import openpyxl
    from copy import copy
    from openpyxl.styles import PatternFill, Font, Alignment, Border, Side
    wb = openpyxl.load_workbook(ruta)

    verde_fill = PatternFill(start_color="C6EFCE", end_color="C6EFCE", fill_type="solid")
    verde_font = Font(name="Segoe UI", size=10, bold=True, color="006100")
    align_center = Alignment(horizontal="center", vertical="center")
    align_left = Alignment(horizontal="left", vertical="center")
    thin_border = Border(
        left=Side(style="thin", color="D9D9D9"),
        right=Side(style="thin", color="D9D9D9"),
        top=Side(style="thin", color="D9D9D9"),
        bottom=Side(style="thin", color="D9D9D9")
    )

    # Solo la hoja que se corrió (decisión de Marcelo, opción C): los números de fila de
    # los resultados son de ESA hoja. Hasta 4f5f355 también se escribían en CONSOLIDADO,
    # donde esos números son otras reservas y ninguna columna las identifica, y si la hoja
    # no estaba, en la primera del libro (CICLO-escritura-planilla.md).
    hojas_a_procesar = [hoja] if hoja in wb.sheetnames else []
    # Lo que no se pudo escribir se avisa al final, igual que en la consola (hasta 0242321 se callaba).
    no_escritos = []                       # (fila, motivo, resultado)
    if resultados and not hojas_a_procesar:
        no_escritos += [(f, f"la planilla no tiene la hoja «{hoja}»", r) for f, r in resultados.items()]

    for h_nom in hojas_a_procesar:
        ws = wb[h_nom]
        fila_enc, cols = _mapear(ws)
        if not fila_enc:
            no_escritos += [(f, f"no encontré la fila de encabezados en la hoja «{h_nom}»", r)
                            for f, r in (resultados or {}).items()]
            continue
        col_est = cols.get("estado")
        if not col_est:
            col_est = (max(cols.values()) if cols else 1) + 1
            ws.cell(fila_enc, col_est, "Estado (Robot)")
        col_num = cols.get("reserva_emitida")
        if not col_num:
            col_num = col_est + 1
            c_hdr = ws.cell(fila_enc, col_num, "N° de reserva emitida")
            try:
                c_hdr.fill = copy(ws.cell(fila_enc, col_est).fill)
                c_hdr.font = copy(ws.cell(fila_enc, col_est).font)
            except Exception:
                pass
            c_hdr.alignment = align_center

        for fila_str, r in (resultados or {}).items():
            try:
                f_idx = int(fila_str)
                st = str(r.get("estado") or "")
                det = str(r.get("detalle") or "")
                bkg = _extraer_bkg_limpio(r)

                txt_est = "EMITIDA" if (st == "EMITIDA" and bkg) else (f"{st} · {det}"[:900] if det else st)
                c_e = ws.cell(f_idx, col_est, txt_est)
                c_e.border = thin_border
                c_e.alignment = align_left

                c_n = ws.cell(f_idx, col_num, _texto_n_reserva(r))
                c_n.border = thin_border
                c_n.alignment = align_center
                if bkg:
                    c_n.fill = verde_fill
                    c_n.font = verde_font
                    c_e.font = Font(name="Segoe UI", size=9, bold=True, color="006100")
            except Exception as e:
                no_escritos.append((fila_str, f"error inesperado ({type(e).__name__}: {e})", r))

        try:
            ws.column_dimensions[openpyxl.utils.get_column_letter(col_est)].width = 38
            ws.column_dimensions[openpyxl.utils.get_column_letter(col_num)].width = 22
        except Exception:
            pass

    if no_escritos:
        _avisar_descarga(no_escritos)
    buf = _io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


def _avisar_descarga(no_escritos):
    """Lo que la descarga del panel no pudo escribir, igual que la consola: en pantalla (el
    registro del panel) y en el log.txt de la última corrida, con el texto para anotarlo a mano."""
    lineas = []
    for fila, motivo, r in no_escritos:
        r = r if isinstance(r, dict) else {}
        texto = " · ".join(x for x in (str(r.get("estado") or ""), _extraer_bkg_limpio(r),
                                        str(r.get("detalle") or "")) if x)
        lineas.append(f"⚠ No pude escribir en la planilla descargada el resultado de la fila {fila}: "
                      f"{motivo}. Anótalo a mano: {texto[:300]}")
    lineas.append(f"⚠ {len(no_escritos)} resultado(s) no quedaron en la planilla descargada (filas "
                  f"{', '.join(str(f) for f, _, _ in no_escritos)}); cada uno está arriba en este log.")
    carpeta = _WEB.get("carpeta")
    if carpeta:
        reg = Registro(Path(carpeta) / "log.txt", on_log=_wlog)
        try:
            for linea in lineas:
                reg.paso(linea)
        finally:
            reg.cerrar()
    else:                                   # sin corrida no hay log.txt: consola y panel
        for linea in lineas:
            try:
                print(linea, flush=True)
            except Exception:
                pass
            _wlog(linea)


# ------------------------------------------------------------
#  Ejecucion: una reserva por fila marcada
# ------------------------------------------------------------
def _match_nav_key(texto):
    t = str(texto or '').strip().lower()
    if "one" in t: return "one"
    if "msc" in t: return "msc"
    if "cma" in t: return "cma"
    if "cosco" in t: return "cosco"
    if "hyundai" in t or "hmm" in t: return "hyundai"
    if "maersk" in t: return "maersk"
    return None


def _web_worker(hoja, usuario, filas_pedidas):
    nav_obj = _nav_de_hoja(hoja)
    reg = None
    try:
        cfg = cargar_config()
        opts = cfg.get("opciones", {})
        carpeta = carpeta_corrida(f"web_{nav_obj}_{usuario}")
        reg = Registro(carpeta / "log.txt", on_log=_wlog)
        reg.dir_capturas = carpeta
        with _LOCK:
            _WEB["carpeta"] = str(carpeta)

        todas = _filas_de_hoja(_WEB["ruta"], hoja)
        elegidas = [f for f in todas if f["fila"] in set(filas_pedidas)]
        reg.paso(f"INICIO · {hoja} · operador {usuario} · {len(elegidas)} reserva(s)")
        _podar_html_viejo(reg)
        if not elegidas:
            # Hasta 42247d4, con una sola naviera, abría el navegador y entraba al portal igual
            # (CICLO-cola-nueve-items.md).
            reg.paso("⚠ No hay filas elegidas: no abro el navegador ni entro a ningún portal. Elige al menos una "
                     "fila y vuelve a armar las reservas.")

        perfil = PERFILES / usuario
        perfil.mkdir(parents=True, exist_ok=True)
        headless = bool(opts.get("headless", False))
        canal = opts.get("navegador", "chrome")

        if nav_obj == "todas":
            navs_secuencia = ["one", "msc", "cma", "cosco", "hyundai", "maersk"]
        else:
            navs_secuencia = [nav_obj]

        for nav in navs_secuencia:
            if _WEB["detener"] and _WEB["detener"].is_set():
                reg.paso("Detenido por el operador."); break

            if nav_obj == "todas":
                sub_elegidas = [f for f in elegidas if _match_nav_key(f.get("naviera")) == nav]
            else:
                sub_elegidas = elegidas
            if not sub_elegidas:
                continue

            nombre, login_func = NAVIERAS[nav]
            reservador = RESERVADORES[nav]
            creds = cfg.get("usuarios", {}).get(usuario, {}).get(nav, {})

            # Una fila sin nave (vacía o con un comodín, _fila_sin_nave) no abre el portal: queda NO ENVIADA con el
            # motivo, en pantalla, en log.txt y en la planilla (decisión de Marcelo, CICLO-solo-la-nave-pedida.md). Si
            # ninguna fila de la naviera trae nave, no se abre el navegador.
            for rsv in [f for f in sub_elegidas if _fila_sin_nave(f.get("nave"))]:
                estado, detalle = _sin_nave(reg, rsv["fila"], rsv.get("nave"))
                with _LOCK:
                    _WEB["resultados"][str(rsv["fila"])] = {
                        "estado": estado, "detalle": detalle, "booking": "", "nave": rsv.get("nave", ""),
                        "hora": _dt.datetime.now().strftime("%H:%M")}
            sub_elegidas = [f for f in sub_elegidas if not _fila_sin_nave(f.get("nave"))]
            if not sub_elegidas:
                reg.paso(f"Ninguna fila de {nombre} trae una nave para reservar: no abro el navegador ni entro al "
                         f"portal.")
                continue
            # Una fila con nave y sin puerto de carga o sin destino (_falta_en_la_fila) tampoco abre el portal: queda NO
            # ENVIADA con el motivo (decisión de Marcelo, encargo 42, CICLO-maersk-y-fila-sin-ruta.md).
            for rsv in [f for f in sub_elegidas if _falta_en_la_fila(f)]:
                estado, detalle = _sin_ruta(reg, rsv["fila"], _falta_en_la_fila(rsv))
                with _LOCK:
                    _WEB["resultados"][str(rsv["fila"])] = {
                        "estado": estado, "detalle": detalle, "booking": "", "nave": rsv.get("nave", ""),
                        "hora": _dt.datetime.now().strftime("%H:%M")}
            sub_elegidas = [f for f in sub_elegidas if not _falta_en_la_fila(f)]
            if not sub_elegidas:
                reg.paso(f"Ninguna fila de {nombre} con nave trae el puerto de carga y el destino: no abro el "
                         f"navegador ni entro al portal.")
                continue

            reg.paso(f"===== INICIANDO {nombre.upper()} ({len(sub_elegidas)} reserva(s)) =====")
            _westado(f"Entrando a {nombre}…")

            with sync_playwright() as p:
                args = dict(user_data_dir=str(perfil), headless=headless,
                            no_viewport=True, args=_args_chrome(),
                            ignore_default_args=["--enable-automation"])
                try:
                    ctx = p.chromium.launch_persistent_context(channel=canal, **args)
                except Exception:
                    ctx = p.chromium.launch_persistent_context(**args)
                with _LOCK:
                    _WEB["ctx"] = ctx
                try: ctx.add_init_script(STEALTH_JS)
                except Exception: pass
                page = ctx.pages[0] if ctx.pages else ctx.new_page()

                reg.paso(f"===== Login {nombre} =====")
                try:
                    logueado = login_func(page, creds, reg, on_pausa=_web_pausa)
                except Exception as e:
                    reg.info(f"ERROR en login: {e}"); logueado = False

                if not logueado:
                    reg.paso(f"No se pudo iniciar sesión en {nombre}; no proceso sus reservas.")
                    # Sin la sesión de MSC, cada fila queda NO ENVIADA con su motivo (decisión de Marcelo, encargo 45,
                    # CICLO-login-msc-y-maersk.md), el que dejó su login: desde el encargo 50, tras el error después
                    # de la clave, con un solo intento más (_motivo_sin_sesion). Con las otras navieras, como antes:
                    # la fila queda sin estado.
                    for rsv in (sub_elegidas if nav in SIN_SESION else ()):
                        reg.paso(f"✗ fila {rsv['fila']}: {NO_ENVIADA} · {_motivo_sin_sesion(reg, nav)}")
                        with _LOCK:
                            _WEB["resultados"][str(rsv["fila"])] = {
                                "estado": NO_ENVIADA, "detalle": _motivo_sin_sesion(reg, nav), "booking": "",
                                "nave": rsv.get("nave", ""), "hora": _dt.datetime.now().strftime("%H:%M")}
                else:
                    for i, rsv in enumerate(sub_elegidas, start=1):
                        if _WEB["detener"] and _WEB["detener"].is_set():
                            reg.paso("Detenido por el operador."); break
                        f_idx = str(rsv["fila"])
                        with _LOCK:
                            _WEB["resultados"][f_idx] = {
                                "estado": "EN CURSO",
                                "detalle": f"Emitiendo en {nombre} (Reserva {i} de {len(sub_elegidas)})…",
                                "booking": "",
                                "nave": rsv.get("nave", ""),
                                "hora": _dt.datetime.now().strftime("%H:%M")
                            }
                        _westado(f"{nombre}: Reserva {i} de {len(sub_elegidas)} (en curso)")
                        reg.paso(f"----- [{nombre}] Reserva {i}/{len(sub_elegidas)} -----")
                        try:
                            estado, detalle = reservador(page, rsv, creds, reg, on_pausa=_web_pausa)
                        except Exception as e:
                            if _WEB.get("detener") and _WEB["detener"].is_set():
                                estado, detalle = "DETENIDO", "Cancelado por el operador"
                            else:
                                estado, detalle = "ERROR", str(e)[:160]
                                reg.info(f"ERROR: {e}")
                                try: reg.captura(page, f"error_{nav}_rsv_{i}")
                                except Exception: pass
                        bkg_limpio = _extraer_bkg_limpio({"estado": estado, "detalle": detalle})
                        with _LOCK:
                            _WEB["resultados"][f_idx] = {
                                "estado": estado, "detalle": detalle, "booking": bkg_limpio,
                                "nave": rsv.get("nave", ""), "hora": _dt.datetime.now().strftime("%H:%M")}
                        reg.paso(f"Reserva {i}: {estado} ({bkg_limpio or detalle})")

                try:
                    ctx.close()
                except Exception:
                    pass
                with _LOCK:
                    _WEB["ctx"] = None
                _time.sleep(0.3)

        reg.paso("===== FIN DE TODAS LAS RESERVAS =====")
        reg.cerrar()
    except Exception as e:
        _wlog(f"ERROR general: {e}")
        _westado("Terminó con error: " + str(e)[:90])
    finally:
        with _LOCK:
            _WEB["corriendo"] = False
            _WEB["ctx"] = None
        if _WEB.get("detener") and _WEB["detener"].is_set():
            _westado("Detenido.")
        elif not str(_WEB["estado"]).startswith("Terminó con error"):
            _westado("Terminado.")


def _web_worker_login(usuario, navieras):
    """Modo LOGIN: entra a los portales y deja el navegador abierto para que el
    operador trabaje a mano. Es lo mismo que hacia el boton de cada naviera en
    el panel de siempre."""
    try:
        _westado("Entrando a " + ", ".join(n.upper() for n in navieras) + "…")
        ejecutar_login(usuario, navieras, on_log=_wlog, on_pausa=_web_pausa,
                       esperar_cierre=lambda: _time.sleep(6))
    except Exception as e:
        _wlog(f"ERROR: {e}")
        _westado("Terminó con error: " + str(e)[:90])
    finally:
        with _LOCK:
            _WEB["corriendo"] = False
        if not str(_WEB["estado"]).startswith("Terminó con error"):
            _westado("Sesiones abiertas.")


def _web_pausa(mensaje):
    """Los portales que piden una accion manual (la validacion de COSCO) avisan
    por aca. La pagina muestra un boton 'Ya lo resolvi' y el proceso sigue en
    cuanto el operador lo pulsa; no se queda esperando un tiempo fijo."""
    ev = _th.Event()
    with _LOCK:
        _WEB["pausa"] = ev
        _WEB["pausa_msg"] = str(mensaje)[:300]
    _westado("Te toca a ti: resuelve el paso en el navegador")
    _wlog("*** ACCIÓN MANUAL REQUERIDA ***")
    _wlog(str(mensaje))
    for _ in range(300):                    # hasta 10 minutos de margen
        if ev.is_set():
            _wlog("▸ Continuando (paso manual resuelto).")
            break
        if _WEB["detener"] and _WEB["detener"].is_set():
            break
        _time.sleep(2)
    with _LOCK:
        _WEB["pausa"] = None
        _WEB["pausa_msg"] = ""


# ------------------------------------------------------------
#  Servidor HTTP (libreria estandar: el .exe sigue autocontenido)
# ------------------------------------------------------------
def _nav_de_hoja(hoja):
    h_clean = str(hoja).strip().lower()
    if h_clean in ("consolidado", "todas", "general"):
        return "todas"
    for clave, aliases in HOJA_ALIAS.items():
        if any(h_clean == str(a).strip().lower() for a in aliases):
            return clave if clave in RESERVADORES else None
    return None


def _reemplazar(tmp, destino, intentos=20, pausa=0.05):
    """os.replace con reintentos. En Windows, reemplazar un archivo falla con PermissionError (WinError 5, acceso
    denegado) si otro proceso lo tiene abierto un instante, como el antivirus al revisar el archivo recién escrito.
    Medido: 47 de 900 guardados seguidos de credenciales, y test_guardar_credenciales en 1 de 12 suites completas
    (CICLO-cola-cuatro-items.md). Reintenta hasta 'intentos' veces, con 'pausa' segundos entre una y otra, y devuelve
    cuántas veces tuvo que reintentar; si sigue negado, levanta el error. Cualquier otro error sube de inmediato."""
    for intento in range(intentos):
        try:
            _os.replace(tmp, destino)
            return intento
        except PermissionError:
            if intento == intentos - 1:
                raise
            _time.sleep(pausa)


def _escribir_config(cfg, ruta):
    """Escribe config.json de forma atómica, desde el panel web y desde el de escritorio: primero a '.json.tmp' y
    después _reemplazar, con sus reintentos. Si el disco falla a mitad, config.json no queda truncado, y con él las
    credenciales de los portales. Hasta 0af2d5b, el panel de escritorio lo abría con open(w), que lo trunca al abrir
    (CICLO-cola-siete-items.md). Devuelve cuántas veces tuvo que reintentar el reemplazo."""
    tmp = ruta.with_suffix(".json.tmp")
    with open(tmp, "w", encoding="utf-8") as f:
        _json.dump(cfg, f, ensure_ascii=False, indent=2)
    return _reemplazar(tmp, ruta)          # Windows lo niega a veces un instante (antivirus)


def lanzar_web(puerto=8765, abrir=True):
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
    from urllib.parse import urlparse, parse_qs
    import tempfile, webbrowser

    class H(BaseHTTPRequestHandler):
        def log_message(self, *a):
            pass                                   # sin ruido en la consola

        def _env(self, code, tipo, cuerpo, extra=None):
            if isinstance(cuerpo, str):
                cuerpo = cuerpo.encode("utf-8")
            self.send_response(code)
            self.send_header("Content-Type", tipo)
            self.send_header("Content-Length", str(len(cuerpo)))
            self.send_header("Cache-Control", "no-store")
            for k, v in (extra or {}).items():
                self.send_header(k, v)
            self.end_headers()
            try: self.wfile.write(cuerpo)
            except Exception: pass

        def _json(self, obj, code=200):
            self._env(code, "application/json; charset=utf-8",
                      _json.dumps(obj, ensure_ascii=False))

        # ---------------- GET ----------------
        def do_GET(self):
            u = urlparse(self.path)
            q = parse_qs(u.query)
            try:
                if u.path in ("/", "/index.html"):
                    return self._env(200, "text/html; charset=utf-8", HTML_INDEX)
                if u.path == "/app.js":
                    return self._env(200, "application/javascript; charset=utf-8", JS_INDEX)
                if u.path == "/estilo.css":
                    return self._env(200, "text/css; charset=utf-8", CSS_INDEX)
                if u.path == "/fuentes.css":
                    return self._env(200, "text/css; charset=utf-8", CSS_FUENTES)
                if u.path == "/api/config":
                    cfg = cargar_config()
                    return self._json({
                        "version": VERSION,
                        "modo_emision": es_modo_emision(),
                        "usuarios": list(cfg.get("usuarios", {}).keys()),
                        "navieras": [{"clave": k, "nombre": v[0],
                                      "reserva": k in RESERVADORES}
                                     for k, v in NAVIERAS.items()]})
                if u.path == "/api/credenciales":
                    cfg = cargar_config()
                    usuario = (q.get("usuario") or [""])[0]
                    datos = cfg.get("usuarios", {}).get(usuario, {})
                    # La clave NUNCA sale del proceso, ni por localhost: se informa
                    # solo si HAY una guardada. Para cambiarla se escribe una nueva;
                    # dejar el campo en blanco conserva la que ya estaba.
                    return self._json({
                        "usuario": usuario,
                        "descripcion": datos.get("descripcion", usuario),
                        "operadores": list(cfg.get("usuarios", {}).keys()),
                        "navieras": [{"clave": k, "nombre": v[0],
                                      "usuario": (datos.get(k) or {}).get("usuario", ""),
                                      "contrato": (datos.get(k) or {}).get("contrato", ""),
                                      "tiene_clave": bool((datos.get(k) or {}).get("clave"))}
                                     for k, v in NAVIERAS.items()]})
                if u.path == "/api/filas":
                    hoja = (q.get("hoja") or [""])[0]
                    if not _WEB["ruta"]:
                        return self._json({"filas": []})
                    # Cada fila dice si no trae una nave y si el operador la hace a mano (_con_su_marca).
                    return self._json({"filas": [_con_su_marca(f) for f in _filas_de_hoja(_WEB["ruta"], hoja)]})
                if u.path == "/api/estado":
                    with _LOCK:
                        _WEB["ultimo_latido"] = time.time()
                    desde = int((q.get("desde") or ["0"])[0])
                    with _LOCK:
                        base = _WEB["base"]
                        ini = max(desde - base, 0)
                        lineas = _WEB["log"][ini:]
                        return self._json({
                            "lineas": lineas,
                            "cursor": base + len(_WEB["log"]),
                            "corriendo": _WEB["corriendo"],
                            "estado": _WEB["estado"],
                            # Cada fila, con el texto de su «N° de reserva emitida», el mismo de la planilla.
                            "resultados": {f: dict(r, n_reserva=_texto_n_reserva(r)) if isinstance(r, dict) else r
                                           for f, r in _WEB["resultados"].items()},
                            "pausa": bool(_WEB["pausa"]),
                            "pausa_msg": _WEB["pausa_msg"],
                            "version": VERSION})
                if u.path == "/api/descargar":
                    if not _WEB["ruta"]:
                        return self._env(400, "text/plain; charset=utf-8", "No hay planilla cargada.")
                    datos = _planilla_con_resultados(_WEB["ruta"], _WEB["hoja"] or "", _WEB["resultados"])
                    nom = (_WEB["nombre"] or "planilla.xlsx").rsplit(".", 1)[0]
                    marca = _dt.datetime.now().strftime("%d-%m_%H%M")
                    return self._env(
                        200, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                        datos, {"Content-Disposition":
                                f'attachment; filename="{nom} - resultados {marca}.xlsx"'})
                if u.path in ("/api/apagar", "/api/shutdown", "/api/salir"):
                    def _apagar():
                        time.sleep(0.4)
                        if _SRV_ACTUAL:
                            try: _SRV_ACTUAL.shutdown()
                            except Exception: pass
                    _th.Thread(target=_apagar, daemon=True).start()
                    return self._json({"ok": True, "mensaje": "AQUASHIELD apagado."})
            except Exception as e:
                return self._env(500, "text/plain; charset=utf-8", str(e))
            self._env(404, "text/plain; charset=utf-8", "no existe")

        # ---------------- POST ----------------
        def do_POST(self):
            u = urlparse(self.path)
            q = parse_qs(u.query)
            largo = int(self.headers.get("Content-Length") or 0)
            cuerpo = self.rfile.read(largo) if largo else b""
            try:
                if u.path == "/api/planilla":
                    nombre = (q.get("nombre") or ["planilla.xlsx"])[0]
                    dest = _os.path.join(tempfile.gettempdir(), "aquashield_planilla.xlsx")
                    with open(dest, "wb") as f:
                        f.write(cuerpo)
                    hojas = _hojas_del_libro(dest)
                    with _LOCK:
                        _WEB.update({"ruta": dest, "nombre": nombre,
                                     "resultados": {}, "log": [], "base": 0})
                    return self._json({"nombre": nombre, "hojas": hojas})

                if u.path == "/api/credenciales":
                    d = _json.loads(cuerpo or b"{}")
                    usuario = (d.get("usuario") or "").strip()
                    if not usuario:
                        return self._json({"error": "falta el nombre del operador"}, 400)
                    cfg = cargar_config()
                    dest = cfg.setdefault("usuarios", {}).setdefault(usuario, {})
                    dest.setdefault("descripcion", usuario)
                    # Un operador nuevo nace con las SIETE navieras, igual que en el
                    # panel de escritorio: si nace solo con la que se escribio, el
                    # config.json queda distinto segun por donde se creo. setdefault
                    # no pisa nada, asi que tambien repara un config al que le falte
                    # una naviera.
                    for k in NAVIERAS:
                        dest.setdefault(k, {"usuario": "", "clave": "", "contrato": ""})
                    if d.get("descripcion"):
                        dest["descripcion"] = str(d["descripcion"]).strip()
                    for k in NAVIERAS:
                        entra = (d.get("navieras") or {}).get(k)
                        if entra is None:
                            continue
                        actual = dest.setdefault(k, {})
                        actual["usuario"] = str(entra.get("usuario") or "").strip()
                        actual["contrato"] = str(entra.get("contrato") or "").strip()
                        # clave: None/ausente = dejar la que hay; "" = borrarla.
                        nueva = entra.get("clave")
                        if nueva is not None:
                            actual["clave"] = str(nueva)
                        else:
                            actual.setdefault("clave", "")
                    # Escritura atomica, con el mismo ayudante que el panel de escritorio.
                    _escribir_config(cfg, BASE / "config.json")
                    return self._json({"ok": True, "operadores": list(cfg["usuarios"].keys())})

                if u.path == "/api/correr":
                    d = _json.loads(cuerpo or b"{}")
                    if _WEB["corriendo"]:
                        return self._json({"error": "ya hay una corrida en curso"}, 409)
                    hoja = d.get("hoja") or ""
                    if not _nav_de_hoja(hoja):
                        return self._json({"error": f"'{hoja}' no tiene automatización"}, 400)
                    with _LOCK:
                        _WEB.update({"hoja": hoja, "usuario": d.get("usuario") or "",
                                     "resultados": {}, "log": [], "base": 0,
                                     "corriendo": True, "estado": "Abriendo el navegador…",
                                     "detener": _th.Event()})
                    h = _th.Thread(target=_web_worker,
                                   args=(hoja, d.get("usuario") or "", d.get("filas") or []),
                                   daemon=True)
                    _WEB["hilo"] = h
                    h.start()
                    return self._json({"ok": True})

                if u.path == "/api/login":
                    d = _json.loads(cuerpo or b"{}")
                    if _WEB["corriendo"]:
                        return self._json({"error": "ya hay algo en curso"}, 409)
                    navs = [n for n in (d.get("navieras") or []) if n in NAVIERAS]
                    if not navs:
                        return self._json({"error": "elige al menos una naviera"}, 400)
                    with _LOCK:
                        _WEB.update({"log": [], "base": 0, "corriendo": True,
                                     "estado": "Abriendo el navegador…",
                                     "detener": _th.Event()})
                    h = _th.Thread(target=_web_worker_login,
                                   args=(d.get("usuario") or "", navs), daemon=True)
                    _WEB["hilo"] = h
                    h.start()
                    return self._json({"ok": True})

                if u.path == "/api/continuar":
                    if _WEB["pausa"]:
                        _WEB["pausa"].set()
                    return self._json({"ok": True})

                if u.path == "/api/detener":
                    if _WEB.get("detener"):
                        _WEB["detener"].set()
                    if _WEB.get("pausa"):
                        _WEB["pausa"].set()
                    _westado("Deteniendo…")
                    ctx_act = _WEB.get("ctx")
                    if ctx_act:
                        def _cerrar_ctx(c):
                            try: c.close()
                            except Exception: pass
                        _th.Thread(target=_cerrar_ctx, args=(ctx_act,), daemon=True).start()
                    return self._json({"ok": True})

                if u.path in ("/api/apagar", "/api/shutdown", "/api/salir"):
                    def _apagar():
                        time.sleep(0.4)
                        if _SRV_ACTUAL:
                            try: _SRV_ACTUAL.shutdown()
                            except Exception: pass
                    _th.Thread(target=_apagar, daemon=True).start()
                    return self._json({"ok": True, "mensaje": "AQUASHIELD apagado."})
            except Exception as e:
                return self._env(500, "text/plain; charset=utf-8", str(e))
            self._env(404, "text/plain; charset=utf-8", "no existe")

    global _SRV_ACTUAL

    # 1. Comprobar si ya hay una instancia de AQUASHIELD en el puerto base (8765)
    try:
        import urllib.request
        with urllib.request.urlopen(f"http://127.0.0.1:{puerto}/api/estado", timeout=1.0) as resp:
            d = _json.loads(resp.read().decode("utf-8"))
            if "corriendo" in d:
                if d.get("corriendo"):
                    # Ya hay una reserva en ejecución: simplemente abrimos el navegador
                    url = f"http://127.0.0.1:{puerto}/"
                    if abrir:
                        try: webbrowser.open(url)
                        except Exception: pass
                    print(f"AQUASHIELD ya está activo ejecutando tareas en {url}")
                    return
                else:
                    # Instancia ociosa anterior: pedirle que se apague para renovar
                    try:
                        req = urllib.request.Request(f"http://127.0.0.1:{puerto}/api/apagar", data=b"{}", method="POST")
                        urllib.request.urlopen(req, timeout=1.0)
                        time.sleep(0.6)
                    except Exception:
                        pass
    except Exception:
        pass

    def _liberar_puerto(p):
        try:
            import subprocess
            cmd = f'netstat -ano -p tcp | findstr /R /C:":{p} .*LISTENING"'
            out = subprocess.check_output(cmd, shell=True).decode(errors="ignore")
            for linea in out.strip().splitlines():
                partes = linea.split()
                if len(partes) >= 5 and f":{p}" in partes[1] and partes[3].upper() == "LISTENING":
                    pid = partes[4]
                    if pid and pid != "0":
                        subprocess.call(f"taskkill /F /PID {pid}", shell=True)
                        time.sleep(0.5)
        except Exception:
            pass

    class _Srv(ThreadingHTTPServer):
        # En Windows, allow_reuse_address deja que un segundo proceso tome el puerto.
        allow_reuse_address = False
        daemon_threads = True

    srv = None
    for intento in range(4):
        p = puerto + intento
        try:
            srv = _Srv(("127.0.0.1", p), H)
            puerto = p
            break
        except OSError:
            if intento == 0:
                _liberar_puerto(p)
                try:
                    srv = _Srv(("127.0.0.1", p), H)
                    puerto = p
                    break
                except OSError:
                    continue
            continue

    if srv is None:
        raise RuntimeError(f"no encontré un puerto libre para AQUASHIELD cerca de {puerto}")

    _SRV_ACTUAL = srv

    # Watchdog de inactividad: si el usuario cerró el navegador y no hay reservas corriendo,
    # apaga el servidor en segundo plano tras 90 segundos para no dejar procesos huérfanos.
    def _inactividad_watchdog():
        time.sleep(60)
        while True:
            time.sleep(15)
            with _LOCK:
                corriendo = _WEB.get("corriendo", False)
                ultimo = _WEB.get("ultimo_latido", time.time())
            if not corriendo and (time.time() - ultimo) > 90:
                if _SRV_ACTUAL:
                    try:
                        _SRV_ACTUAL.shutdown()
                    except Exception:
                        pass
                break
    _th.Thread(target=_inactividad_watchdog, daemon=True).start()

    url = f"http://127.0.0.1:{puerto}/"
    if abrir:
        try: webbrowser.open(url)
        except Exception: pass
    print(f"AQUASHIELD web en {url}  (Ctrl+C para salir)")
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        _SRV_ACTUAL = None


